package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import java.nio.file.Files;
import java.util.HashSet;
import java.util.Random;
import java.util.Set;
import javax.imageio.ImageIO;
import org.junit.Before;
import org.junit.Test;

/**
 * Verifies that weighted variants re-roll on each loop boundary (not only on
 * state entry) and that a variant stays fixed for the duration of a single loop.
 */
public class AnimationControllerRerollTest
{
	private File dir;

	@Before
	public void setUp() throws Exception
	{
		dir = Files.createTempDirectory("if-reroll").toFile();
		// Multi-frame "active" variants (128x64 -> 2 frames each), distinct colours.
		// The bundled resources ship active_loop_2.png AND active_loop_3.png, and
		// variant discovery intentionally MERGES bundled variants with the external
		// drop-in (see AnimationController.discoverVariants / the
		// externalPrimaryDoesNotHideBundledVariants test). So to keep this test's
		// "active" variant set fully under its own control, override every bundled
		// active_loop_N here — otherwise a bundled sheet (whose corner is transparent)
		// can be picked and the colour assertion below would see neither test colour.
		writeSheet("active_loop.png", Color.RED);
		writeSheet("active_loop_2.png", Color.BLUE);
		writeSheet("active_loop_3.png", Color.GREEN);
		// Equal odds so the variants surface quickly.
		Files.write(new File(dir, "weights.json").toPath(),
			"{\"active_loop\":1,\"active_loop_2\":1,\"active_loop_3\":1}".getBytes());
	}

	private void writeSheet(String name, Color color) throws Exception
	{
		BufferedImage sheet = new BufferedImage(128, 64, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = sheet.createGraphics();
		g.setColor(color);
		g.fillRect(0, 0, 128, 64);
		g.dispose();
		ImageIO.write(sheet, "png", new File(dir, name));
	}

	private AnimationController controller(long seed)
	{
		AnimationController controller = new AnimationController(new Random(seed));
		controller.setExternalAssetDir(dir);
		controller.loadDefaultAnimations();
		return controller;
	}

	@Test
	public void variantStaysFixedWithinASingleLoop()
	{
		AnimationController controller = controller(1);

		// Two 64-base frames: 300ms + 600ms (last frame doubled) = 900ms loop.
		controller.getFrameAt(AvatarState.PLAYER_ACTIVE, "", 1000L);
		String first = controller.currentVariantName();
		controller.getFrameAt(AvatarState.PLAYER_ACTIVE, "", 1300L); // still < 900ms in
		controller.getFrameAt(AvatarState.PLAYER_ACTIVE, "", 1800L);
		assertEquals("variant must not re-roll mid-loop", first, controller.currentVariantName());
	}

	@Test
	public void variantRerollsAcrossLoopBoundaries()
	{
		AnimationController controller = controller(1);

		Set<String> seen = new HashSet<>();
		long now = 1000L;
		for (int i = 0; i < 100; i++)
		{
			controller.getFrameAt(AvatarState.PLAYER_ACTIVE, "", now);
			seen.add(controller.currentVariantName());
			now += 2000L; // > one 900ms loop, so a re-roll is eligible every step
		}

		assertTrue("expected both variants to appear across loops, saw " + seen, seen.size() >= 2);
	}

	@Test
	public void switchingStateReAnchorsAndRendersOneOfItsVariants()
	{
		AnimationController controller = controller(7);

		// active -> logged_out -> active exercises state-entry re-anchoring.
		controller.getFrameAt(AvatarState.PLAYER_ACTIVE, "", 1000L);
		controller.getFrameAt(AvatarState.LOGGED_OUT, "", 1100L);
		BufferedImage frame = controller.getFrameAt(AvatarState.PLAYER_ACTIVE, "", 1200L);

		int rgb = frame.getRGB(0, 0);
		assertTrue("active frame must be one of its variants",
			rgb == Color.RED.getRGB() || rgb == Color.BLUE.getRGB() || rgb == Color.GREEN.getRGB());
		String variant = controller.currentVariantName();
		assertTrue("variant must be one of the active sheets",
			"active_loop".equals(variant) || "active_loop_2".equals(variant) || "active_loop_3".equals(variant));
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import net.runelite.api.ChatMessageType;
import org.junit.Test;

public class ChatSoundFilterTest
{
	@Test
	public void allowsPlayerAndSocialChatTypes()
	{
		assertTrue(ChatSoundFilter.isAudible(ChatMessageType.PUBLICCHAT, "hello"));
		assertTrue(ChatSoundFilter.isAudible(ChatMessageType.MODCHAT, "hello"));
		assertTrue(ChatSoundFilter.isAudible(ChatMessageType.PRIVATECHAT, "hello"));
		assertTrue(ChatSoundFilter.isAudible(ChatMessageType.FRIENDSCHAT, "hello"));
		assertTrue(ChatSoundFilter.isAudible(ChatMessageType.CLAN_MESSAGE, "hello"));
		assertTrue(ChatSoundFilter.isAudible(ChatMessageType.TRADE, "hello"));
	}

	@Test
	public void suppressesNoisySystemAndPluginMessages()
	{
		assertFalse(ChatSoundFilter.isAudible(ChatMessageType.GAMEMESSAGE, "You swing your axe."));
		assertFalse(ChatSoundFilter.isAudible(ChatMessageType.SPAM, "Filtered spam"));
		assertFalse(ChatSoundFilter.isAudible(ChatMessageType.PUBLICCHAT, "Idle Familiar: animations look good."));
	}

	@Test
	public void filteredTriggersCanMatchGameMessages()
	{
		assertEquals("cave begin to", ChatSoundFilter.matchedTriggerFilter(
			ChatMessageType.GAMEMESSAGE,
			"Some cracks around the cave begin to ooze water.",
			ChatMessageMatcher.compile("cave begin to")));
	}

	@Test
	public void filteredTriggersRejectPluginAndSpamMessages()
	{
		assertNull(ChatSoundFilter.matchedTriggerFilter(
			ChatMessageType.PUBLICCHAT,
			"Idle Familiar: animations look good.",
			ChatMessageMatcher.compile("animations look good")));
		assertNull(ChatSoundFilter.matchedTriggerFilter(
			ChatMessageType.SPAM,
			"Some cracks around the cave begin to ooze water.",
			ChatMessageMatcher.compile("cave begin to")));
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/** Source-pinned chart and cascade fixtures for V1 fishing profiles. */
public class FishingCatalogTest
{
	@Test
	public void smallNetShrimpAnchovyGatesAnchoviesThenUsesTheSourceCascade()
	{
		GatheringProfile profile = FishingCatalog.smallNetShrimpAnchovyProfile();

		assertProfile(profile, 1, 5, 1, 0, 49);
		assertProfile(profile, 50, 5, 1, 77, 153);
		assertProfile(profile, 99, 5, 1, 129, 257);
		assertEquals(47099d / 65536d, profile.expectedSlotsPerRollAt(50), 0d);
	}

	@Test
	public void monkfishAndRainbowFishUseTheirSeparateSourceRows()
	{
		assertProfile(FishingCatalog.smallNetMonkfishProfile(), 62, 5, 62, 75);
		assertProfile(FishingCatalog.smallNetMonkfishProfile(), 99, 5, 62, 91);
		assertProfile(FishingCatalog.flyRainbowFishProfile(), 38, 5, 38, 30);
		assertProfile(FishingCatalog.flyRainbowFishProfile(), 99, 5, 38, 65);
	}

	@Test
	public void cageLobsterUsesItsPinnedFiveTickSingleRoll()
	{
		GatheringProfile profile = FishingCatalog.cageLobsterProfile();

		assertProfile(profile, 40, 5, 40, 42);
		assertProfile(profile, 70, 5, 40, 70);
		assertProfile(profile, 99, 5, 40, 96);
	}

	@Test
	public void harpoonTunaSwordfishGatesSwordfishBeforeLevelFifty()
	{
		GatheringProfile profile = FishingCatalog.harpoonTunaSwordfishProfile();

		assertProfile(profile, 35, 5, 35, 0, 28);
		assertProfile(profile, 50, 5, 35, 27, 37);
		assertProfile(profile, 99, 5, 35, 49, 65);
		assertEquals(15385d / 65536d, profile.expectedSlotsPerRollAt(50), 0d);
	}

	@Test
	public void dragonAndCrystalHarpoonsUseTheirOwnPinnedTunaSwordfishRows()
	{
		GatheringProfile dragon = FishingCatalog.harpoonTunaSwordfishProfile(
			FishingCatalog.HarpoonTier.DRAGON);
		GatheringProfile crystal = FishingCatalog.harpoonTunaSwordfishProfile(
			FishingCatalog.HarpoonTier.CRYSTAL);

		assertProfile(dragon, 50, 5, 35, 32, 44);
		assertProfile(dragon, 99, 5, 35, 58, 77);
		assertProfile(crystal, 50, 5, 35, 36, 49);
		assertProfile(crystal, 99, 5, 35, 65, 87);
	}

	@Test
	public void harpoonSharkUsesTheCorrectToolTierRow()
	{
		assertProfile(FishingCatalog.harpoonSharkProfile(FishingCatalog.HarpoonTier.NORMAL),
			76, 5, 76, 32);
		assertProfile(FishingCatalog.harpoonSharkProfile(FishingCatalog.HarpoonTier.DRAGON),
			76, 5, 76, 38);
		assertProfile(FishingCatalog.harpoonSharkProfile(FishingCatalog.HarpoonTier.CRYSTAL),
			76, 5, 76, 43);
	}

	@Test
	public void bareHandedFishingUsesTheNormalHarpoonRowsWithoutAHarpoonToolBonus()
	{
		assertProfile(FishingCatalog.barehandedTunaSwordfishProfile(), 55, 5, 55, 0, 40);
		assertProfile(FishingCatalog.barehandedTunaSwordfishProfile(), 70, 5, 55, 36, 48);
		assertProfile(FishingCatalog.barehandedSharkProfile(), 96, 5, 96, 40);
	}

	@Test
	public void barbarianRodUsesItsPinnedThreeFishCascade()
	{
		GatheringProfile profile = FishingCatalog.barbarianRodProfile();

		assertProfile(profile, 48, 5, 48, 0, 0, 110);
		assertProfile(profile, 58, 5, 48, 0, 64, 126);
		assertProfile(profile, 99, 5, 48, 65, 97, 193);
	}

	@Test
	public void flyFishingTroutSalmonGatesSalmonBeforeLevelThirty()
	{
		GatheringProfile profile = FishingCatalog.flyTroutSalmonProfile();

		assertProfile(profile, 20, 5, 20, 0, 64);
		assertProfile(profile, 50, 5, 20, 57, 113);
		assertProfile(profile, 99, 5, 20, 97, 193);
		assertEquals(37079d / 65536d, profile.expectedSlotsPerRollAt(50), 0d);
	}

	@Test
	public void ordinaryRodSardineHerringGatesHerringBeforeLevelTen()
	{
		GatheringProfile profile = FishingCatalog.rodSardineHerringProfile();

		assertProfile(profile, 5, 5, 5, 0, 40);
		assertProfile(profile, 50, 5, 5, 77, 113);
		assertProfile(profile, 99, 5, 5, 129, 193);
		assertEquals(39939d / 65536d, profile.expectedSlotsPerRollAt(50), 0d);
	}

	@Test
	public void ordinaryRodPikeUsesItsOwnSourceRow()
	{
		GatheringProfile profile = FishingCatalog.rodPikeProfile();

		assertProfile(profile, 25, 5, 25, 37);
		assertProfile(profile, 50, 5, 25, 57);
		assertProfile(profile, 99, 5, 25, 97);
	}

	@Test
	public void sourceCataloguedEelsAndAnglerfishKeepDistinctToolAndBaitProfiles()
	{
		assertProfile(FishingCatalog.rodSlimyCaveEelProfile(), 28, 5, 28, 0, 30);
		assertProfile(FishingCatalog.rodSlimyCaveEelProfile(), 38, 5, 28, 37, 37);
		assertProfile(FishingCatalog.rodSlimyCaveEelProfile(), 99, 5, 28, 81, 81);
		assertProfile(FishingCatalog.oilyRodLavaEelProfile(), 53, 5, 53, 59);
		assertProfile(FishingCatalog.oilyRodLavaEelProfile(), 99, 5, 53, 97);
		assertProfile(FishingCatalog.oilyRodInfernalEelProfile(), 80, 5, 80, 82);
		assertProfile(FishingCatalog.oilyRodInfernalEelProfile(), 99, 5, 80, 94);
		assertProfile(FishingCatalog.rodAnglerfishProfile(false), 82, 5, 82, 31);
		assertProfile(FishingCatalog.rodAnglerfishProfile(false), 99, 5, 82, 37);
		assertProfile(FishingCatalog.rodAnglerfishProfile(true), 82, 5, 82, 86);
		assertProfile(FishingCatalog.rodAnglerfishProfile(true), 99, 5, 82, 101);
	}

	@Test
	public void karambwanVesselPinsRequirementCadenceAndChartFixtures()
	{
		GatheringProfile profile = FishingCatalog.karambwanVesselProfile();
		OutcomeRoll karambwan = profile.getOutcomeRolls().get(0);

		assertEquals(65, profile.getRequiredLevel());
		assertEquals(4, profile.getRollTicks());
		assertEquals(GatheringProfile.YieldMode.SINGLE, profile.getYieldMode());
		assertEquals(107, karambwan.successRollAt(65));
		assertEquals(134, karambwan.successRollAt(82));
		assertEquals(161, karambwan.successRollAt(99));
		assertEquals(28672d / 107d, profile.expectedTicksToFill(28, 65), 0d);
	}

	@Test
	public void conventionalProfilesAreWhitelistedButKarambwanIsHandledSeparately()
	{
		assertTrue(FishingCatalog.isConventionalV1Profile(FishingCatalog.cageLobsterProfile()));
		assertTrue(FishingCatalog.isConventionalV1Profile(FishingCatalog.rodPikeProfile()));
		assertFalse(FishingCatalog.isConventionalV1Profile(FishingCatalog.karambwanVesselProfile()));
		assertTrue(FishingCatalog.isFishingProfileLabel(
			FishingCatalog.smallNetMonkfishProfile().getLabel()));
		assertTrue(FishingCatalog.isFishingProfileLabel(
			FishingCatalog.flyRainbowFishProfile().getLabel()));
		assertTrue(FishingCatalog.isFishingProfileLabel(
			FishingCatalog.oilyRodInfernalEelProfile().getLabel()));
		assertTrue(FishingCatalog.isFishingProfileLabel(
			FishingCatalog.rodAnglerfishProfile(true).getLabel()));
		assertTrue(FishingCatalog.isFishingProfileLabel(
			FishingCatalog.karambwanVesselProfile().getLabel()));
		assertFalse(FishingCatalog.isFishingProfileLabel("Maple"));
	}

	@Test
	public void fishBarrelCompatibilityIncludesLeapingFishButExcludesInfernalEels()
	{
		assertTrue(FishingCatalog.isFishBarrelCompatible(
			FishingCatalog.barbarianRodProfile()));
		assertTrue(FishingCatalog.isFishBarrelCompatible(
			FishingCatalog.flyTroutSalmonProfile()));
		assertFalse(FishingCatalog.isFishBarrelCompatible(
			FishingCatalog.oilyRodInfernalEelProfile()));
		assertFalse(FishingCatalog.isFishBarrelCompatible(
			FishingCatalog.karambwanVesselProfile()));
	}

	private static void assertProfile(GatheringProfile profile, int level, int rollTicks,
		int requiredLevel, int... expectedRolls)
	{
		assertEquals(rollTicks, profile.getRollTicks());
		assertEquals(requiredLevel, profile.getRequiredLevel());
		assertEquals(expectedRolls.length, profile.getOutcomeRolls().size());
		for (int index = 0; index < expectedRolls.length; index++)
		{
			assertEquals(expectedRolls[index], profile.getOutcomeRolls().get(index).successRollAt(level));
		}
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertEquals;

import java.util.Map;
import net.runelite.api.ItemID;
import net.runelite.api.gameval.AnimationID;
import org.junit.Test;

public class ActivityDetectorArbitrationTest
{
	@Test
	public void oneTransitionHasOneOwningRecognizer()
	{
		ActivityDetector detector = new ActivityDetector(
			ActivityAnimationRegistry.build(), new GatheringResourceTracker());
		InventoryState before = InventoryState.of(Map.of(
			ItemID.FLY_FISHING_ROD, 1, ItemID.FEATHER, 20), 2);
		InventoryState after = InventoryState.of(Map.of(
			ItemID.FLY_FISHING_ROD, 1, ItemID.FEATHER, 19, ItemID.RAW_TROUT, 1), 3);

		ActivityDetector.InventoryDetection result = detector.detectInventory(
			new InventoryChange(before, after), InventoryState.empty(), true,
			AnimationID.HUMAN_FISH_ONSPOT, 99, 99, 100, 4, 6);

		assertEquals(ActivityDetector.Kind.FISHING, result.kind());
		assertEquals(null, result.woodcutting());
		assertEquals(null, result.processing());
	}

	@Test
	public void exactSmithingIsReachedOnlyAfterGatheringRejectsTheDelta()
	{
		ActivityDetector detector = new ActivityDetector(
			ActivityAnimationRegistry.build(), new GatheringResourceTracker());
		InventoryState before = InventoryState.of(Map.of(ItemID.BRONZE_BAR, 10), 10);
		InventoryState after = InventoryState.of(Map.of(
			ItemID.BRONZE_BAR, 5, ItemID.BRONZE_PLATEBODY, 1), 6);

		ActivityDetector.InventoryDetection result = detector.detectInventory(
			new InventoryChange(before, after), InventoryState.empty(), true,
			AnimationID.HUMAN_SMITHING, 99, 99, 100, 4, 6);

		assertEquals(ActivityDetector.Kind.PROCESSING, result.kind());
	}

	@Test
	public void unrelatedDeltaReturnsNoClaimAndCanReachGenericProcessing()
	{
		ActivityDetector detector = new ActivityDetector(
			ActivityAnimationRegistry.build(), new GatheringResourceTracker());
		InventoryState before = InventoryState.of(Map.of(100, 3), 1);
		InventoryState after = InventoryState.of(Map.of(100, 2, 200, 1), 2);

		assertEquals(ActivityDetector.Kind.NONE, detector.detectInventory(
			new InventoryChange(before, after), InventoryState.empty(), true,
			-1, 99, 99, 100, 4, 6).kind());
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/** Exercises client-free shimmer arming and clearing. */
public class ShimmerControllerTest
{
	@Test
	public void unexpectedDisconnectSurvivesLoginScreenUntilLoginOrHopReset()
	{
		ShimmerController controller = new ShimmerController();
		controller.onConnectionLost();
		controller.maintainLoggedOut();
		assertEquals(AttentionReason.DISCONNECTED, controller.attentionReason());

		controller.onLoggedIn();
		assertEquals(AttentionReason.NONE, controller.attentionReason());
		controller.onConnectionLost();
		controller.reset();
		controller.maintainLoggedOut();
		assertEquals(AttentionReason.NONE, controller.attentionReason());
	}

	/** A tick with every trigger false and safe vitals, in the given state. */
	private static void quietTick(ShimmerController c, AvatarState state)
	{
		c.tick(state, false, false, false, false, false, false, true, true);
	}

	// --- Arming on each trigger edge ---------------------------------------

	@Test
	public void armsOnInventoryFullEdge()
	{
		ShimmerController c = new ShimmerController();
		quietTick(c, AvatarState.SKILLING);
		c.tick(AvatarState.PLAYER_IDLE, true, false, false, false, false, false, true, true);
		assertTrue(c.isActive());
	}

	@Test
	public void armsOnAfkWarningEdge()
	{
		ShimmerController c = new ShimmerController();
		quietTick(c, AvatarState.PLAYER_IDLE);
		c.tick(AvatarState.AFK_WARNING, false, false, false, true, false, false, true, true);
		assertTrue(c.isActive());
	}

	@Test
	public void armsOnLowHpEdge()
	{
		ShimmerController c = new ShimmerController();
		quietTick(c, AvatarState.PLAYER_IDLE);
		c.tick(AvatarState.LOW_HEALTH, false, true, false, false, false, false, false, true);
		assertTrue(c.isActive());
	}

	@Test
	public void armsOnLowPrayerEdge()
	{
		ShimmerController c = new ShimmerController();
		quietTick(c, AvatarState.PLAYER_IDLE);
		c.tick(AvatarState.LOW_PRAYER, false, false, true, false, false, false, true, false);
		assertTrue(c.isActive());
	}

	@Test
	public void armsOnDeathEdge()
	{
		ShimmerController c = new ShimmerController();
		quietTick(c, AvatarState.PLAYER_IDLE);
		c.tick(AvatarState.DEATH, false, false, false, false, true, false, false, true);
		assertTrue(c.isActive());
	}

	@Test
	public void armsOnLevelUpEdge()
	{
		ShimmerController c = new ShimmerController();
		quietTick(c, AvatarState.SKILLING);
		c.tick(AvatarState.LEVEL_UP, false, false, false, false, false, true, true, true);
		assertTrue(c.isActive());
	}

	@Test
	public void doesNotArmWithoutAnEdge()
	{
		ShimmerController c = new ShimmerController();
		quietTick(c, AvatarState.PLAYER_IDLE);
		quietTick(c, AvatarState.PLAYER_IDLE);
		assertFalse(c.isActive());
	}

	// --- Normal-arm clearing ------------------------------------------------

	@Test
	public void normalArmClearsOnActiveState()
	{
		ShimmerController c = new ShimmerController();
		c.tick(AvatarState.PLAYER_IDLE, true, false, false, false, false, false, true, true);
		assertTrue(c.isActive());
		// Inventory still full, but the player is skilling again: clear.
		c.tick(AvatarState.SKILLING, true, false, false, false, false, false, true, true);
		assertFalse(c.isActive());
	}

	@Test
	public void normalArmClearsOnCombat()
	{
		ShimmerController c = new ShimmerController();
		c.tick(AvatarState.AFK_WARNING, false, false, false, true, false, false, true, true);
		assertTrue(c.isActive());
		c.tick(AvatarState.COMBAT, false, false, false, false, false, false, true, true);
		assertFalse(c.isActive());
	}

	@Test
	public void normalArmSurvivesNonActiveStates()
	{
		ShimmerController c = new ShimmerController();
		c.tick(AvatarState.PLAYER_IDLE, true, false, false, false, false, false, true, true);
		quietTick(c, AvatarState.PLAYER_IDLE);
		quietTick(c, AvatarState.DEFAULT);
		c.tick(AvatarState.INVENTORY_FULL, true, false, false, false, false, false, true, true);
		assertTrue(c.isActive());
	}

	// --- Danger-arm clearing (the key regression) ----------------------------

	@Test
	public void dangerArmIsNotClearedByCombat()
	{
		ShimmerController c = new ShimmerController();
		// Low HP arms while idle; auto-retaliate then drags the player into combat.
		c.tick(AvatarState.LOW_HEALTH, false, true, false, false, false, false, false, true);
		assertTrue(c.isActive());
		c.tick(AvatarState.COMBAT, false, true, false, false, false, false, false, true);
		assertTrue("COMBAT must not clear a danger arm (auto-retaliate)", c.isActive());
	}

	@Test
	public void dangerArmClearsOnActiveNonCombatState()
	{
		ShimmerController c = new ShimmerController();
		c.tick(AvatarState.LOW_HEALTH, false, true, false, false, false, false, false, true);
		c.tick(AvatarState.WALKING, false, true, false, false, false, false, false, true);
		assertFalse(c.isActive());
	}

	@Test
	public void dangerArmClearsWhenVitalRecovers()
	{
		ShimmerController c = new ShimmerController();
		c.tick(AvatarState.LOW_HEALTH, false, true, false, false, false, false, false, true);
		assertTrue(c.isActive());
		// HP back above the threshold, still no input: clear.
		c.tick(AvatarState.PLAYER_IDLE, false, false, false, false, false, false, true, true);
		assertFalse(c.isActive());
	}

	@Test
	public void lowPrayerDangerArmNeedsPrayerRecoveryNotHp()
	{
		ShimmerController c = new ShimmerController();
		c.tick(AvatarState.LOW_PRAYER, false, false, true, false, false, false, true, false);
		assertTrue(c.isActive());
		// HP is safe throughout; prayer still low — must stay armed.
		c.tick(AvatarState.COMBAT, false, false, true, false, false, false, true, false);
		assertTrue(c.isActive());
		// Prayer recovers: clear.
		c.tick(AvatarState.PLAYER_IDLE, false, false, false, false, false, false, true, true);
		assertFalse(c.isActive());
	}

	@Test
	public void doubleDangerArmNeedsBothVitalsToRecover()
	{
		ShimmerController c = new ShimmerController();
		c.tick(AvatarState.LOW_HEALTH, false, true, false, false, false, false, false, true);
		c.tick(AvatarState.LOW_PRAYER, false, true, true, false, false, false, false, false);
		// Only HP recovers; prayer still low — stays armed.
		c.tick(AvatarState.PLAYER_IDLE, false, false, true, false, false, false, true, false);
		assertTrue(c.isActive());
		// Prayer recovers too: clear.
		c.tick(AvatarState.PLAYER_IDLE, false, false, false, false, false, false, true, true);
		assertFalse(c.isActive());
	}

	@Test
	public void dangerTriggerUpgradesAnExistingNormalArm()
	{
		ShimmerController c = new ShimmerController();
		c.tick(AvatarState.PLAYER_IDLE, true, false, false, false, false, false, true, true);
		assertTrue(c.isActive());
		// Low HP fires while armed: upgrade to danger; combat must no longer clear it.
		c.tick(AvatarState.PLAYER_IDLE, true, true, false, false, false, false, false, true);
		c.tick(AvatarState.COMBAT, true, true, false, false, false, false, false, true);
		assertTrue(c.isActive());
	}

	@Test
	public void etaExpirySurvivesContinuedSkillingUntilClientInteraction()
	{
		ShimmerController c = new ShimmerController();
		c.armEtaExpired();
		assertTrue(c.isActive());

		quietTick(c, AvatarState.SKILLING);
		quietTick(c, AvatarState.WALKING);
		assertTrue("activity animation is not proof of a new client interaction", c.isActive());

		c.onClientInteraction();
		assertFalse(c.isActive());
	}

	@Test
	public void clientInteractionDoesNotSilenceAnUnrecoveredDangerArm()
	{
		ShimmerController c = new ShimmerController();
		c.tick(AvatarState.LOW_HEALTH, false, true, false, false, false, false, false, true);
		c.armEtaExpired();
		c.onClientInteraction();

		assertTrue(c.isActive());
		quietTick(c, AvatarState.PLAYER_IDLE);
		assertFalse(c.isActive());
	}

	// --- Re-arm behaviour -----------------------------------------------------

	@Test
	public void doesNotRearmWhileConditionStaysTrue()
	{
		ShimmerController c = new ShimmerController();
		c.tick(AvatarState.PLAYER_IDLE, true, false, false, false, false, false, true, true);
		// Skilling with a full inventory (e.g. power-mining) clears it...
		c.tick(AvatarState.SKILLING, true, false, false, false, false, false, true, true);
		assertFalse(c.isActive());
		// ...and it must NOT re-arm while the inventory simply stays full.
		c.tick(AvatarState.PLAYER_IDLE, true, false, false, false, false, false, true, true);
		c.tick(AvatarState.PLAYER_IDLE, true, false, false, false, false, false, true, true);
		assertFalse(c.isActive());
	}

	@Test
	public void rearmsOnAFreshEdge()
	{
		ShimmerController c = new ShimmerController();
		c.tick(AvatarState.PLAYER_IDLE, true, false, false, false, false, false, true, true);
		c.tick(AvatarState.SKILLING, true, false, false, false, false, false, true, true);
		assertFalse(c.isActive());
		// Inventory drops an item (goes false) then fills again: fresh edge, re-arm.
		c.tick(AvatarState.PLAYER_IDLE, false, false, false, false, false, false, true, true);
		c.tick(AvatarState.PLAYER_IDLE, true, false, false, false, false, false, true, true);
		assertTrue(c.isActive());
	}

	// --- Reset ----------------------------------------------------------------

	@Test
	public void resetClearsEverything()
	{
		ShimmerController c = new ShimmerController();
		c.tick(AvatarState.LOW_HEALTH, true, true, false, false, false, false, false, true);
		assertTrue(c.isActive());
		c.reset();
		assertFalse(c.isActive());
		// Edge trackers are cleared too: a still-true condition after reset is a
		// fresh edge on the next tick (login with a full inventory should shimmer).
		c.tick(AvatarState.PLAYER_IDLE, true, false, false, false, false, false, true, true);
		assertTrue(c.isActive());
	}

	@Test
	public void publishesTheHighestPriorityExactReasonWithoutLosingLowerLatches()
	{
		ShimmerController c = new ShimmerController();
		c.armEtaExpired();
		assertEquals(AttentionReason.ETA_REACHED, c.attentionReason());

		c.tick(AvatarState.LOW_PRAYER, false, false, true,
			false, false, false, true, false);
		assertEquals(AttentionReason.LOW_PRAYER, c.attentionReason());

		// Recovery reveals the still-latched ETA instead of dropping all context.
		quietTick(c, AvatarState.PLAYER_IDLE);
		assertEquals(AttentionReason.ETA_REACHED, c.attentionReason());
	}

	@Test
	public void disconnectedReasonSurvivesActivityUntilConnectionLifecycleClearsIt()
	{
		ShimmerController c = new ShimmerController();
		c.armEtaExpired();
		c.armDisconnected();
		assertEquals(AttentionReason.DISCONNECTED, c.attentionReason());

		quietTick(c, AvatarState.WALKING);
		c.onClientInteraction();
		assertEquals(AttentionReason.DISCONNECTED, c.attentionReason());

		c.clearDisconnected();
		assertEquals(AttentionReason.NONE, c.attentionReason());
		assertFalse(c.isActive());
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class PlayerActivityServiceTest
{
	@Test
	public void oneLingerImplementationOwnsTransientDurationsAndMirroredFlags()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.arm(PlayerActivityService.Linger.CHAT_MESSAGE);

		assertTrue(service.isLingering(PlayerActivityService.Linger.CHAT_MESSAGE));
		assertEquals(AvatarState.CUSTOM_EVENT, service.resolveState(false, false));
		for (int tick = 0; tick < 4; tick++)
		{
			service.advanceLingers();
		}

		assertFalse(service.isLingering(PlayerActivityService.Linger.CHAT_MESSAGE));
		assertEquals(AvatarState.PLAYER_ACTIVE, service.resolveState(false, false));
	}

	@Test
	public void loggedOutHasHighestPriority()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(false);
		service.setLowHitpoints(true);

		assertEquals(AvatarState.LOGGED_OUT, service.resolveState(false, false));
	}

	@Test
	public void resolvesUrgentStatesBeforeActivityStates()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.setInCombat(true);
		service.setLowPrayer(true);

		assertEquals(AvatarState.LOW_PRAYER, service.resolveState(false, false));
	}

	@Test
	public void resolvesAfkBeforeInventoryAndCombat()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.setInventoryFull(true);
		service.setInCombat(true);

		assertEquals(AvatarState.AFK_WARNING, service.resolveState(true, true));
	}

	@Test
	public void customEventResolvesAboveAfkButBelowLevelUp()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.arm(PlayerActivityService.Linger.CHAT_MESSAGE);

		assertEquals(AvatarState.CUSTOM_EVENT, service.resolveState(true, true));
		service.arm(PlayerActivityService.Linger.LEVEL_UP);
		assertEquals(AvatarState.LEVEL_UP, service.resolveState(true, true));
	}

	@Test
	public void resolvesSkillingBeforeInventoryFull()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.setInventoryFull(true);
		service.setSkilling(true);

		assertEquals(AvatarState.SKILLING, service.resolveState(false, false));
	}

	@Test
	public void resolvesIdleWhenNoHigherPriorityStateApplies()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);

		assertEquals(AvatarState.PLAYER_IDLE, service.resolveState(true, false));
		assertEquals(AvatarState.PLAYER_ACTIVE, service.resolveState(false, false));
	}

	@Test
	public void inventoryFullResolvesAboveGrandExchange()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.setInventoryFull(true);
		service.arm(PlayerActivityService.Linger.GRAND_EXCHANGE);

		assertEquals(AvatarState.INVENTORY_FULL, service.resolveState(false, false));
	}

	@Test
	public void grandExchangeResolvesAboveLocomotion()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.setWalking(true);
		service.arm(PlayerActivityService.Linger.GRAND_EXCHANGE);

		assertEquals(AvatarState.GRAND_EXCHANGE, service.resolveState(false, false));
	}

	@Test
	public void bankingResolvesAboveCombat()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.setBanking(true);
		service.setInCombat(true);

		// Opening a bank involves interacting with a banker NPC/booth; it must never
		// be misread as combat, so BANKING outranks COMBAT.
		assertEquals(AvatarState.BANKING, service.resolveState(false, false));
	}

	@Test
	public void teleportingResolvesAboveSkilling()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.setSkilling(true);
		service.arm(PlayerActivityService.Linger.TELEPORTING);

		// A teleport cast also drops Magic XP (which marks skilling); the teleport
		// must win so it isn't masked as "skilling Magic".
		assertEquals(AvatarState.TELEPORTING, service.resolveState(false, false));
	}

	@Test
	public void teleportingResolvesAboveInventoryFull()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.setInventoryFull(true);
		service.arm(PlayerActivityService.Linger.TELEPORTING);

		// Teleporting is a momentary committed action, shown above standing conditions.
		assertEquals(AvatarState.TELEPORTING, service.resolveState(false, false));
	}

	@Test
	public void teleportingResolvesAboveWalking()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.setWalking(true);
		service.arm(PlayerActivityService.Linger.TELEPORTING);

		assertEquals(AvatarState.TELEPORTING, service.resolveState(false, false));
	}

	@Test
	public void walkingResolvesAboveIdleAndActive()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.setWalking(true);

		// Walking outranks both idle and active.
		assertEquals(AvatarState.WALKING, service.resolveState(true, false));
		assertEquals(AvatarState.WALKING, service.resolveState(false, false));
	}

	@Test
	public void runningResolvesAboveIdleButBelowWalking()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.setRunning(true);

		assertEquals(AvatarState.RUNNING, service.resolveState(false, false));
	}

	@Test
	public void skillingResolvesAboveGrandExchangeAndLocomotion()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.setSkilling(true);
		service.arm(PlayerActivityService.Linger.GRAND_EXCHANGE);
		service.setRunning(true);

		assertEquals(AvatarState.SKILLING, service.resolveState(false, false));
	}

	@Test
	public void deathResolvesAboveLowHealth()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.setLowHitpoints(true);
		service.arm(PlayerActivityService.Linger.DEATH);

		// Hitpoints hitting 0 also trips LOW_HEALTH; DEATH sits at the top of the
		// logged-in ladder so it must win.
		assertEquals(AvatarState.DEATH, service.resolveState(false, false));
	}

	@Test
	public void levelUpResolvesAboveAfkButBelowLowVitals()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.arm(PlayerActivityService.Linger.LEVEL_UP);

		// The flourish interrupts ordinary activity (here AFK).
		assertEquals(AvatarState.LEVEL_UP, service.resolveState(true, true));

		// ...but a low-vitals warning still outranks it.
		service.setLowPrayer(true);
		assertEquals(AvatarState.LOW_PRAYER, service.resolveState(true, true));
	}

	@Test
	public void resetClearsDeathAndLevelUp()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.arm(PlayerActivityService.Linger.DEATH);
		service.arm(PlayerActivityService.Linger.LEVEL_UP);
		service.reset();
		service.setLoggedIn(true);

		assertEquals(AvatarState.PLAYER_ACTIVE, service.resolveState(false, false));
	}

	@Test
	public void resetClearsNewFlags()
	{
		PlayerActivityService service = new PlayerActivityService();
		service.setLoggedIn(true);
		service.setWalking(true);
		service.setRunning(true);
		service.arm(PlayerActivityService.Linger.TELEPORTING);
		service.arm(PlayerActivityService.Linger.GRAND_EXCHANGE);
		service.arm(PlayerActivityService.Linger.CHAT_MESSAGE);
		service.reset();
		service.setLoggedIn(true);

		assertEquals(AvatarState.PLAYER_ACTIVE, service.resolveState(false, false));
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class SkillingActivityTrackerTest
{
	private static final int LINGER = 10;

	@Test
	public void skillingDoesNotFlickerToIdleBetweenSignals()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();

		// First skilling signal at tick 0.
		assertTrue(tracker.recordSkillSignal("Fishing", 0));
		assertTrue(tracker.isSkilling(0, LINGER));

		// Four ticks later, still within the linger window, no new signal yet.
		// The avatar must NOT flicker to idle during this gap.
		assertTrue(tracker.isSkilling(4, LINGER));

		// A second signal arrives at tick 5 and keeps it alive.
		assertTrue(tracker.recordSkillSignal("Fishing", 5));
		assertTrue(tracker.isSkilling(5, LINGER));
	}

	@Test
	public void skillingExpiresAfterLingerWindow()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.recordSkillSignal("Fishing", 0);

		// Just inside the window: still skilling.
		assertTrue(tracker.isSkilling(LINGER - 1, LINGER));
		// At and beyond the window with no new signals: no longer skilling.
		assertFalse(tracker.isSkilling(LINGER, LINGER));
		assertFalse(tracker.isSkilling(LINGER + 5, LINGER));
		assertNull(tracker.getConfirmedSkill(LINGER, LINGER));
	}

	@Test
	public void passiveSkillsDoNotStartOrExtendLinger()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();

		// Player fishes at tick 0, then stops.
		tracker.recordSkillSignal("Fishing", 0);

		// A passive prayer-drain stat change arrives near the end of the window.
		assertFalse(tracker.recordSkillSignal("Prayer", 9));
		// And a hitpoints-regen stat change too.
		assertFalse(tracker.recordSkillSignal("Hitpoints", 9));

		// Neither passive source extended the fishing linger: it still expires
		// LINGER ticks after the original fishing signal, not the passive ones.
		assertFalse(tracker.isSkilling(LINGER, LINGER));
		// And the confirmed skill was never overwritten to a passive skill.
		assertEquals("Fishing", tracker.getConfirmedSkill(LINGER - 1, LINGER));
	}

	@Test
	public void passiveSkillAloneNeverCountsAsSkilling()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		assertFalse(tracker.recordSkillSignal("Hitpoints", 0));
		assertFalse(tracker.isSkilling(0, LINGER));
		assertNull(tracker.getConfirmedSkill(0, LINGER));
	}

	@Test
	public void confirmedPrayerXpCountsAsSkilling()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();

		assertTrue(tracker.recordXpSkillSignal("Prayer", 0));
		assertTrue(tracker.isSkilling(0, LINGER));
		assertEquals("Prayer", tracker.getConfirmedSkill(0, LINGER));
	}

	@Test
	public void activitySignalRefreshesLingerWithoutChangingSkill()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.recordSkillSignal("Woodcutting", 0);

		// An ongoing tool animation refreshes the window at tick 8.
		tracker.recordActivitySignal(8);

		// Still skilling at tick 17 (8 + LINGER - 1), thanks to the refresh.
		assertTrue(tracker.isSkilling(17, LINGER));
		// The confirmed skill label is unchanged.
		assertEquals("Woodcutting", tracker.getConfirmedSkill(17, LINGER));
	}

	@Test
	public void targetSustainBridgesAnimationGapsBeyondLinger()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		int spot = 0xF15; // opaque fishing-spot identity token

		// Tick 0: a confirmed fishing animation while interacting with the spot.
		assertTrue(tracker.recordSkillSignal("Fishing", 0));
		assertTrue(tracker.recordInteractionTarget(spot, 0));

		// Far past the linger window with NO new animation signal, but still
		// interacting with the same spot: skilling stays alive and labelled.
		int tick = LINGER + 50;
		assertTrue(tracker.recordInteractionTarget(spot, tick));
		assertTrue(tracker.isSkilling(tick, LINGER));
		assertEquals("Fishing", tracker.getConfirmedSkill(tick, LINGER));
	}

	@Test
	public void targetSustainDropsInstantlyWhenInteractionEnds()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		int spot = 0xF15;
		tracker.recordSkillSignal("Fishing", 0);
		tracker.recordInteractionTarget(spot, 0);
		assertTrue(tracker.isSkilling(5, LINGER));

		// Spot depletes / player walks away: the target clears this tick and the
		// bridge ends immediately (only the short linger could now apply).
		assertFalse(tracker.recordInteractionTarget(SkillingActivityTracker.NO_TARGET, 6));
		assertFalse(tracker.isSustainedByTarget());
	}

	@Test
	public void targetSustainRequiresAConfirmedSkillingSignal()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		int npc = 0xC0B;

		// Interacting with an NPC but no skilling animation was ever confirmed
		// (e.g. plain combat): target-based sustain must NOT engage, or combat
		// would be misread as skilling.
		assertFalse(tracker.recordInteractionTarget(npc, 0));
		assertFalse(tracker.isSustainedByTarget());
		assertFalse(tracker.isSkilling(0, LINGER));
	}

	@Test
	public void cancelLingerEndsTargetSustain()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		int spot = 0xF15;
		tracker.recordSkillSignal("Fishing", 0);
		tracker.recordInteractionTarget(spot, 0);
		assertTrue(tracker.isSustainedByTarget());

		// Movement cancels the linger; target sustain must end on the same tick so
		// walking away from a fishing spot drops skilling immediately.
		tracker.cancelLinger();
		assertFalse(tracker.isSustainedByTarget());
		assertFalse(tracker.isSkilling(0, LINGER));
	}

	@Test
	public void cancelLingerImmediatelyStopsSkillingAndClearsLabel()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.recordSkillSignal("Fishing", 0);
		assertTrue(tracker.isSkilling(0, LINGER));

		// Player moves: the linger must be cancelled this very tick, not allowed
		// to ride out the remaining window (the fishing-walk-to-bank false positive).
		tracker.cancelLinger();

		assertFalse(tracker.isSkilling(0, LINGER));
		assertNull(tracker.getConfirmedSkill(0, LINGER));
	}

	@Test
	public void cancelLingerClearsStaleSkillSoItCannotReattach()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.recordSkillSignal("Fishing", 0);
		tracker.cancelLinger();

		// A later, unrelated activity signal (e.g. an animation) must not resurrect
		// the old "Fishing" label — the confirmed skill was cleared on cancel.
		tracker.recordActivitySignal(20);
		assertNull(tracker.getConfirmedSkill(20, LINGER));
	}

	@Test
	public void resetClearsAllState()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.recordSkillSignal("Fishing", 0);
		tracker.reset();

		// After a reset (logout / plugin start) nothing is skilling and no label
		// or sustained target survives.
		assertFalse(tracker.isSkilling(0, LINGER));
		assertFalse(tracker.isSustainedByTarget());
		assertNull(tracker.getConfirmedSkill(0, LINGER));
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import org.junit.Test;

public class ThemeDecorationRendererTest
{
	@Test
	public void perimeterArtDecoratesWithoutPaintingThePanelCenter()
	{
		BufferedImage output = new BufferedImage(240, 160, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = output.createGraphics();
		Rectangle panel = new Rectangle(40, 32, 160, 96);
		ThemeDecorationRenderer.draw(graphics,
			ThemeAssets.forTheme(WidgetTheme.ARCANE).panelDecorations(), panel, 1.0d);
		graphics.dispose();

		assertEquals(0, output.getRGB(panel.x + panel.width / 2,
			panel.y + panel.height / 2) >>> 24);
		assertTrue(visiblePixels(output) > 40);
	}

	@Test
	public void missingOrMalformedAtlasesAreIgnored()
	{
		BufferedImage output = new BufferedImage(80, 80, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = output.createGraphics();
		ThemeDecorationRenderer.draw(graphics, null, new Rectangle(10, 10, 60, 60), 1.0d);
		ThemeDecorationRenderer.draw(graphics,
			new BufferedImage(191, 192, BufferedImage.TYPE_INT_ARGB),
			new Rectangle(10, 10, 60, 60), 1.0d);
		graphics.dispose();
		assertEquals(0, visiblePixels(output));
	}

	@Test
	public void everyThemeDecoratesAtBothSupportedWidgetScales()
	{
		for (WidgetTheme theme : WidgetTheme.values())
		{
			for (double scale : new double[]{1.0d, 1.5d})
			{
				BufferedImage output = new BufferedImage(360, 240, BufferedImage.TYPE_INT_ARGB);
				Graphics2D graphics = output.createGraphics();
				Rectangle panel = new Rectangle(70, 50, 220, 140);
				ThemeDecorationRenderer.draw(graphics,
					ThemeAssets.forTheme(theme).panelDecorations(), panel, scale);
				graphics.dispose();

				assertEquals(theme + " center", 0, output.getRGB(
					panel.x + panel.width / 2, panel.y + panel.height / 2) >>> 24);
				assertTrue(theme + " " + scale, visiblePixels(output) > 40);
			}
		}
	}

	private static int visiblePixels(BufferedImage image)
	{
		int visible = 0;
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) >>> 24) != 0)
				{
					visible++;
				}
			}
		}
		return visible;
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class GatheringEtaEngineTest
{
	@Test
	public void modelledRunUsesCapacityHorizonAndLocalCadence()
	{
		GatheringEtaEngine engine = new GatheringEtaEngine();
		GatheringProfile lobster = FishingCatalog.cageLobsterProfile();

		assertEquals(GatheringEtaEngine.Disposition.ACTIVE,
			engine.onConventionalFishingCatch(lobster, 40, 2, 1, 1d, true, 36, 100));
		assertEquals(36, engine.snapshot().getRemainingTicks());

		engine.onConventionalFishingCatch(lobster, 40, 3, 1, 1d, true, 31, 105);
		engine.onConventionalFishingCatch(lobster, 40, 4, 1, 1d, true, 26, 110);
		engine.onConventionalFishingCatch(lobster, 40, 5, 1, 1d, true, 21, 115);
		assertEquals(TaskEtaSnapshot.Confidence.HIGH, engine.snapshot().getConfidence());
		assertEquals(21, engine.snapshot().getRemainingTicks());
	}

	@Test
	public void storageCapacityCanCollapseWithoutRebasingInitialTotal()
	{
		GatheringEtaEngine engine = new GatheringEtaEngine();
		engine.onWoodcuttingStorageStart(WoodcuttingCatalog.Tree.MAPLE,
			WoodcuttingCatalog.AxeTier.DRAGON, 99, 2, 28, true, 100, 10);
		assertEquals(54, engine.snapshot().getInitialUnits());

		engine.onWoodcuttingLog(WoodcuttingCatalog.Tree.MAPLE,
			WoodcuttingCatalog.AxeTier.DRAGON, 99, 3, 1, true, 96, 14);
		assertEquals(54, engine.snapshot().getInitialUnits());
		assertEquals(25, engine.snapshot().getRemainingUnits());
	}

	@Test
	public void observedRunCalibratesAfterThreeCompleteIntervals()
	{
		GatheringEtaEngine engine = new GatheringEtaEngine();
		engine.startObserved("Mining", 1, true, 100);
		engine.onObservedYield("Mining", 2, 1, true, 105);
		engine.onObservedYield("Mining", 3, 1, true, 110);
		engine.onObservedYield("Mining", 4, 1, true, 115);

		assertTrue(engine.snapshot().isActive());
		assertEquals(TaskEtaSnapshot.Confidence.HIGH, engine.snapshot().getConfidence());
