import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.awt.AlphaComposite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.function.IntUnaryOperator;
import org.junit.Test;

public class InventoryGridRendererTest
{
	@Test
	public void x1AndX2ViewerGeometryMatchesThePaintedGridContract()
	{
		assertEquals(new Dimension(134, 246), size(InventoryDensity.MINI_GRID, AvatarScale.X2));
		assertEquals(new Dimension(134, 66), size(InventoryDensity.STRIP, AvatarScale.X2));
		assertEquals(new Dimension(202, 370), size(InventoryDensity.MINI_GRID, AvatarScale.X3));
		assertEquals(new Dimension(202, 100), size(InventoryDensity.STRIP, AvatarScale.X3));
		assertEquals(new Dimension(0, 0), size(InventoryDensity.OFF, AvatarScale.X2));
	}

	@Test
	public void everyThemePaintsBothViewerModesAtBothScalesAndOpacityExtremes()
	{
		for (AvatarScale scale : AvatarScale.values())
		{
			IntUnaryOperator ui = value -> DesktopPetWindow.scaledUiMetric(value, scale);
			for (InventoryDensity density : new InventoryDensity[]{InventoryDensity.STRIP,
				InventoryDensity.MINI_GRID})
			{
				Dimension size = InventoryGridRenderer.viewerSize(density, ui);
				for (WidgetTheme theme : WidgetTheme.values())
				{
					for (float opacity : new float[]{0.2f, 1.0f})
					{
						BufferedImage output = new BufferedImage(size.width, size.height,
							BufferedImage.TYPE_INT_ARGB);
						Graphics2D graphics = output.createGraphics();
						graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER,
							DesktopPetWindow.clampAlpha(opacity)));
						new InventoryGridRenderer().paint(graphics, InventorySnapshot.empty(), 0,
							density, 0, 0, size.width, size.height, theme,
							scale.widgetMultiplier(), ui, 0L);
						graphics.dispose();
						assertTrue(theme + " " + scale + " " + density + " " + opacity,
							visiblePixels(output) > 0);
					}
				}
			}
		}
	}

	private static Dimension size(InventoryDensity density, AvatarScale scale)
	{
		return InventoryGridRenderer.viewerSize(density,
			value -> DesktopPetWindow.scaledUiMetric(value, scale));
	}

	private static int visiblePixels(BufferedImage image)
	{
		int visible = 0;
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) >>> 24) != 0)
				{
					visible++;
				}
			}
		}
		return visible;
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertEquals;

import java.lang.reflect.Proxy;
import net.runelite.api.NPC;
import net.runelite.client.game.FishingSpot;
import org.junit.Test;

public class FishingSpotMovementTrackerTest
{
	@Test
	public void observedOrdinarySpotCountsDownToItsEarliestPossibleMove()
	{
		FishingSpotMovementTracker tracker = new FishingSpotMovementTracker();
		NPC monkfish = npc(FishingSpot.MONKFISH.getIds()[0]);
		tracker.onSpawned(monkfish, 100);

		assertEquals(250, tracker.earliestMoveRemainingTicks(monkfish,
			FishingCatalog.smallNetMonkfishProfile(), 100));
		assertEquals(150, tracker.earliestMoveRemainingTicks(monkfish,
			FishingCatalog.smallNetMonkfishProfile(), 200));
		assertEquals(0, tracker.earliestMoveRemainingTicks(monkfish,
			FishingCatalog.smallNetMonkfishProfile(), 400));
	}

	@Test
	public void unobservedAndSourceExcludedSpotsDoNotInventAHorizon()
	{
		FishingSpotMovementTracker tracker = new FishingSpotMovementTracker();
		NPC monkfish = npc(FishingSpot.MONKFISH.getIds()[0]);
		assertEquals(FishingCatalog.NO_SPOT_MOVEMENT_HORIZON,
			tracker.earliestMoveRemainingTicks(monkfish,
				FishingCatalog.smallNetMonkfishProfile(), 100));

		NPC anglerfish = npc(FishingSpot.ANGLERFISH.getIds()[0]);
		tracker.onSpawned(anglerfish, 100);
		assertEquals(FishingCatalog.NO_SPOT_MOVEMENT_HORIZON,
			tracker.earliestMoveRemainingTicks(anglerfish,
				FishingCatalog.rodAnglerfishProfile(false), 100));

		NPC karambwan = npc(FishingSpot.KARAMBWAN.getIds()[0]);
		tracker.onSpawned(karambwan, 100);
		assertEquals(FishingCatalog.NO_SPOT_MOVEMENT_HORIZON,
			tracker.earliestMoveRemainingTicks(karambwan,
				FishingCatalog.karambwanVesselProfile(), 100));
	}

	@Test
	public void infernalEelsUseTheirSourceSpecificEarliestMove()
	{
		FishingSpotMovementTracker tracker = new FishingSpotMovementTracker();
		NPC infernal = npc(FishingSpot.INFERNAL_EEL.getIds()[0]);
		tracker.onSpawned(infernal, 50);

		assertEquals(100, tracker.earliestMoveRemainingTicks(infernal,
			FishingCatalog.oilyRodInfernalEelProfile(), 50));
		assertEquals(75, tracker.earliestMoveRemainingTicks(infernal,
			FishingCatalog.oilyRodInfernalEelProfile(), 75));
	}

	private static NPC npc(int id)
	{
		return (NPC) Proxy.newProxyInstance(NPC.class.getClassLoader(), new Class<?>[]{NPC.class},
			(proxy, method, args) -> "getId".equals(method.getName()) ? id
				: defaultValue(method.getReturnType()));
	}

	private static Object defaultValue(Class<?> type)
	{
		if (!type.isPrimitive())
		{
			return null;
		}
		if (type == boolean.class)
		{
			return false;
		}
		if (type == char.class)
		{
			return '\0';
		}
		if (type == long.class)
		{
			return 0L;
		}
		if (type == float.class)
		{
			return 0f;
		}
		if (type == double.class)
		{
			return 0d;
		}
		return 0;
	}
}

