	{
		assertRolls(WoodcuttingCatalog.Tree.OAK, new int[]{15, 57, 99}, new int[]{157, 267, 376});
		assertRolls(WoodcuttingCatalog.Tree.WILLOW, new int[]{30, 64, 99}, new int[]{99, 143, 188});
