		assertRolls(WoodcuttingCatalog.Tree.CAMPHOR, new int[]{66, 82, 99}, new int[]{71, 80, 90});
	}

	@Test
	public void oakPinsEveryAxeInputAtBothEndsOfTheChart()
	{
		int[] levelOneRolls = new int[WoodcuttingCatalog.AxeTier.values().length];
		int[] levelNinetyNineRolls = new int[levelOneRolls.length];
		for (WoodcuttingCatalog.AxeTier axe : WoodcuttingCatalog.AxeTier.values())
		{
			OutcomeRoll roll = WoodcuttingCatalog.profile(WoodcuttingCatalog.Tree.OAK, axe)
				.getOutcomeRolls().get(0);
			levelOneRolls[axe.ordinal()] = roll.successRollAt(1);
			levelNinetyNineRolls[axe.ordinal()] = roll.successRollAt(99);
		}

		assertArrayEquals(new int[]{33, 49, 65, 73, 81, 97, 113, 121, 126}, levelOneRolls);
		assertArrayEquals(new int[]{101, 151, 201, 226, 251, 301, 351, 376, 401}, levelNinetyNineRolls);
	}

	@Test
	public void expectedInventoryTicksUseTheClampedEngineChance()
	{
		GatheringProfile oak = WoodcuttingCatalog.profile(WoodcuttingCatalog.Tree.OAK, DRAGON);
		assertEquals(1d, oak.expectedSlotsPerRollAt(99), 0d);
		assertEquals(112d, oak.expectedTicksToFill(28, 99), 0d);

		GatheringProfile maple = WoodcuttingCatalog.profile(WoodcuttingCatalog.Tree.MAPLE, DRAGON);
		assertEquals(94d / 256d, maple.expectedSlotsPerRollAt(99), 0d);
		assertEquals(305.02127659574467d, maple.expectedTicksToFill(28, 99), 0.0000000001d);
	}

	@Test
	public void activeAndRespawnTimersArePinnedForEveryShippingTree()
	{
		assertSpotTimers(WoodcuttingCatalog.Tree.OAK, 45, 14);
		assertSpotTimers(WoodcuttingCatalog.Tree.WILLOW, 50, 14);
		assertSpotTimers(WoodcuttingCatalog.Tree.TEAK, 50, 15);
		assertSpotTimers(WoodcuttingCatalog.Tree.MAPLE, 100, 59);
		assertSpotTimers(WoodcuttingCatalog.Tree.MAHOGANY, 100, 14);
		assertSpotTimers(WoodcuttingCatalog.Tree.YEW, 190, 99);
		assertSpotTimers(WoodcuttingCatalog.Tree.MAGIC, 390, 199);
		assertSpotTimers(WoodcuttingCatalog.Tree.REDWOOD, 440, 199);
		assertSpotTimers(WoodcuttingCatalog.Tree.CAMPHOR, 200, 99);
	}

	@Test
	public void levelsAreCappedAtNinetyNineBeforeSnapshotResolution()
	{
		GatheringProfile yew = WoodcuttingCatalog.profile(WoodcuttingCatalog.Tree.YEW, DRAGON);
		assertEquals(yew.expectedSlotsPerRollAt(99), yew.expectedSlotsPerRollAt(120), 0d);
	}

	private static void assertRolls(WoodcuttingCatalog.Tree tree, int[] levels, int[] expectedRolls)
	{
		GatheringProfile profile = WoodcuttingCatalog.profile(tree, DRAGON);
		int[] actualRolls = new int[levels.length];
		for (int index = 0; index < levels.length; index++)
		{
			actualRolls[index] = profile.getOutcomeRolls().get(0).successRollAt(levels[index]);
		}
		assertArrayEquals(expectedRolls, actualRolls);
	}

	private static void assertSpotTimers(WoodcuttingCatalog.Tree tree, int activeTicks, int respawnTicks)
	{
		GatheringProfile profile = WoodcuttingCatalog.profile(tree, DRAGON);
		assertEquals(activeTicks, profile.getActiveSpotTicks());
		assertEquals(respawnTicks, profile.getRespawnTicks());
	}
}

