public class ExtendedInventoryTrackerTest
{
	@Test
	public void fullEvidenceIsScopedToItsContainerAndCanBeCleared()
	{
		ExtendedInventoryTracker tracker = new ExtendedInventoryTracker();
		assertFalse(tracker.isKnownFull(ExtendedInventoryTracker.Container.FISH_BARREL));
		assertFalse(tracker.isKnownFull(ExtendedInventoryTracker.Container.LOG_BASKET));

		tracker.markFull(ExtendedInventoryTracker.Container.FISH_BARREL);
		assertTrue(tracker.isKnownFull(ExtendedInventoryTracker.Container.FISH_BARREL));
		assertFalse(tracker.isKnownFull(ExtendedInventoryTracker.Container.LOG_BASKET));

		tracker.markFull(ExtendedInventoryTracker.Container.LOG_BASKET);
		tracker.markEmptyOrUnknown(ExtendedInventoryTracker.Container.FISH_BARREL);
		assertFalse(tracker.isKnownFull(ExtendedInventoryTracker.Container.FISH_BARREL));
		assertTrue(tracker.isKnownFull(ExtendedInventoryTracker.Container.LOG_BASKET));

		tracker.reset();
		assertFalse(tracker.isKnownFull(ExtendedInventoryTracker.Container.LOG_BASKET));
	}

	@Test
	public void assumedCapacityIsAddedOnlyUntilFullIsProved()
	{
		ExtendedInventoryTracker tracker = new ExtendedInventoryTracker();
		assertEquals(35, tracker.effectiveFreeSlots(
			ExtendedInventoryTracker.Container.FISH_BARREL, true, 7));

		tracker.markFull(ExtendedInventoryTracker.Container.FISH_BARREL);
		assertEquals(7, tracker.effectiveFreeSlots(
			ExtendedInventoryTracker.Container.FISH_BARREL, true, 7));
		assertEquals(7, tracker.effectiveFreeSlots(
			ExtendedInventoryTracker.Container.LOG_BASKET, false, 7));
	}

	@Test
	public void ownsPresenceAndServerEvidenceTransitions()
	{
		ExtendedInventoryTracker tracker = new ExtendedInventoryTracker();
		assertTrue(tracker.hasOpenFishBarrel(InventoryState.of(
			Map.of(ItemID.OPEN_FISH_BARREL, 1), 1), InventoryState.empty()));
		assertTrue(tracker.hasOpenLogBasket(InventoryState.empty(), InventoryState.of(
			Map.of(ItemID.OPEN_LOG_BASKET, 1), 1)));

		tracker.onChatMessage("your barrel is full; empty at a bank");
		assertTrue(tracker.isKnownFull(ExtendedInventoryTracker.Container.FISH_BARREL));
		tracker.onMenuAction("empty", "fish barrel");
		assertFalse(tracker.isKnownFull(ExtendedInventoryTracker.Container.FISH_BARREL));
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Map;
import org.junit.Test;

public class FullInventoryActivityTrackerTest
{
	@Test
	public void verifiedProcessingAlwaysCountsAsWorkingAtFull()
	{
		FullInventoryActivityTracker tracker = new FullInventoryActivityTracker();
		assertTrue(tracker.isWorkingAtFull(true, true, false, 500));
		assertFalse(tracker.isWorkingAtFull(false, true, true, 500));
	}

	@Test
	public void changedFullInventoryNeedsLiveSkillingAndExpiresAfterGrace()
	{
		FullInventoryActivityTracker tracker = new FullInventoryActivityTracker();
		tracker.onInventoryChanged(Map.of(1, 10), Map.of(1, 9, 2, 1), 28, 100);

		assertTrue(tracker.isWorkingAtFull(true, false, true, 100));
		assertTrue(tracker.isWorkingAtFull(true, false, true,
			100 + FullInventoryActivityTracker.PROGRESS_GRACE_TICKS));
		assertFalse(tracker.isWorkingAtFull(true, false, false, 100));
		assertFalse(tracker.isWorkingAtFull(true, false, true,
			101 + FullInventoryActivityTracker.PROGRESS_GRACE_TICKS));
	}

	@Test
	public void initialSeedAndNonFullChangesDoNotSuppressAttention()
	{
		FullInventoryActivityTracker tracker = new FullInventoryActivityTracker();
		tracker.onInventoryChanged(Map.of(), Map.of(1, 10), 28, 10);
		assertFalse(tracker.isWorkingAtFull(true, false, true, 10));

		tracker.markProgress(11);
		tracker.onInventoryChanged(Map.of(1, 10), Map.of(1, 9), 27, 12);
		assertFalse(tracker.isWorkingAtFull(true, false, true, 12));
	}

	@Test
	public void nonCombatXpCanRefreshTheWorkingGrace()
	{
		FullInventoryActivityTracker tracker = new FullInventoryActivityTracker();
		tracker.markProgress(40);
		assertTrue(tracker.isWorkingAtFull(true, false, true, 40));
		tracker.reset();
		assertFalse(tracker.isWorkingAtFull(true, false, true, 40));
	}
}

