package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.awt.Dimension;
import java.awt.Point;
import java.awt.Rectangle;
import org.junit.Test;

public class WidgetPositioningTest
{
	private static final Rectangle WORK = new Rectangle(100, 50, 1000, 700);

	@Test
	public void anchorsRespectSafeMarginAndOffsets()
	{
		Dimension size = new Dimension(200, 100);
		assertEquals(new Rectangle(112, 62, 200, 100),
			WidgetPositioning.anchoredBounds(WORK, size, WidgetAnchor.TOP_LEFT, 0, 0, 12));
		assertEquals(new Rectangle(883, 65, 200, 100),
			WidgetPositioning.anchoredBounds(WORK, size, WidgetAnchor.TOP_RIGHT, 5, 3, 12));
		assertEquals(new Rectangle(112, 638, 200, 100),
			WidgetPositioning.anchoredBounds(WORK, size, WidgetAnchor.BOTTOM_LEFT, 0, 0, 12));
		assertEquals(new Rectangle(888, 638, 200, 100),
			WidgetPositioning.anchoredBounds(WORK, size, WidgetAnchor.BOTTOM_RIGHT, 0, 0, 12));
	}

	@Test
	public void freePositionIsRecoveredInsideUsableDisplay()
	{
		assertEquals(new Rectangle(112, 62, 200, 100),
			WidgetPositioning.anchoredBounds(WORK, new Dimension(200, 100), WidgetAnchor.FREE,
				-5000, -5000, 12));
		assertEquals(new Rectangle(888, 638, 200, 100),
			WidgetPositioning.anchoredBounds(WORK, new Dimension(200, 100), WidgetAnchor.FREE,
				5000, 5000, 12));
	}

	@Test
	public void onlyCornersCreatePersistentAnchors()
	{
		assertEquals(WidgetAnchor.TOP_LEFT,
			WidgetPositioning.cornerAnchor(new Rectangle(116, 65, 200, 100), WORK, 12, 8));
		assertEquals(WidgetAnchor.BOTTOM_RIGHT,
			WidgetPositioning.cornerAnchor(new Rectangle(885, 635, 200, 100), WORK, 12, 8));
		assertEquals(WidgetAnchor.FREE,
			WidgetPositioning.cornerAnchor(new Rectangle(400, 65, 200, 100), WORK, 12, 8));
	}

	@Test
	public void anchorOffsetsRoundTrip()
	{
		Rectangle bounds = new Rectangle(863, 628, 200, 100);
		Point offsets = WidgetPositioning.offsetsFor(bounds, WORK, WidgetAnchor.BOTTOM_RIGHT, 12);
		assertEquals(new Point(25, 10), offsets);
		assertEquals(bounds, WidgetPositioning.anchoredBounds(WORK, bounds.getSize(),
			WidgetAnchor.BOTTOM_RIGHT, offsets.x, offsets.y, 12));
	}

	@Test
	public void inventoryViewerGrowsAwayFromAnchoredScreenEdge()
	{
		Rectangle widget = new Rectangle(400, 300, 200, 100);
		assertFalse(WidgetPositioning.inventoryExpandsUp(widget, WORK, WidgetAnchor.TOP_LEFT));
		assertFalse(WidgetPositioning.inventoryExpandsUp(widget, WORK, WidgetAnchor.TOP_RIGHT));
		assertTrue(WidgetPositioning.inventoryExpandsUp(widget, WORK, WidgetAnchor.BOTTOM_LEFT));
		assertTrue(WidgetPositioning.inventoryExpandsUp(widget, WORK, WidgetAnchor.BOTTOM_RIGHT));
	}

	@Test
	public void freeInventoryViewerUsesWidgetScreenHalf()
	{
		assertFalse(WidgetPositioning.inventoryExpandsUp(
			new Rectangle(400, 100, 200, 100), WORK, WidgetAnchor.FREE));
		assertTrue(WidgetPositioning.inventoryExpandsUp(
			new Rectangle(400, 600, 200, 100), WORK, WidgetAnchor.FREE));
	}

	@Test
	public void hoverExpansionKeepsTheNearScreenEdgeStableAtBothScales()
	{
		for (AvatarScale scale : AvatarScale.values())
		{
			int viewerHeight = InventoryGridRenderer.viewerSize(InventoryDensity.MINI_GRID,
				value -> DesktopPetWindow.scaledUiMetric(value, scale)).height;
			Dimension expanded = new Dimension(220, 100 + viewerHeight);

			Rectangle top = new Rectangle(300, 62, 220, 100);
			Rectangle below = WidgetPositioning.resizedFreeBounds(top, expanded, WORK, 12, false);
			assertEquals(top.y, below.y);

			Rectangle bottom = new Rectangle(300, 638, 220, 100);
			Rectangle above = WidgetPositioning.resizedFreeBounds(bottom, expanded, WORK, 12, true);
			assertEquals(bottom.y + bottom.height, above.y + above.height);
		}
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import java.util.Map;
import net.runelite.api.ItemID;
import net.runelite.api.MenuAction;
import net.runelite.api.gameval.AnimationID;
import org.junit.Test;

public class ProcessingActivityDetectorTest
{
	private final ActivityEvidenceTracker evidence = new ActivityEvidenceTracker();
	private final ProcessingActivityDetector detector = new ProcessingActivityDetector(
		ActivityAnimationRegistry.build(), evidence);

	@Test
	public void recognisesAnvilDeltaWithOffhandHammer()
	{
		InventoryChange change = change(
			Map.of(ItemID.BRONZE_BAR, 10), 10,
			Map.of(ItemID.BRONZE_BAR, 5, ItemID.BRONZE_PLATEBODY, 1), 6);
		ProcessingActivityDetector.Result result = detector.detect(change,
			InventoryState.of(Map.of(ItemID.IMCANDO_HAMMER_OFFHAND, 1), 1),
			AnimationID.HUMAN_SMITHING, 100, 4);

		assertNotNull(result);
		assertEquals(ProcessingContext.Kind.ANVIL_SMITHING, result.context().kind());
		assertEquals(true, result.context().hasOffhandHammer());
	}

	@Test
	public void recognisesRegularFurnaceDelta()
	{
		InventoryChange change = change(
			Map.of(ItemID.IRON_ORE, 4, ItemID.COAL, 8), 2,
			Map.of(ItemID.IRON_ORE, 3, ItemID.COAL, 6, ItemID.STEEL_BAR, 1), 3);
		ProcessingActivityDetector.Result result = detector.detect(change,
			InventoryState.empty(), AnimationID.HUMAN_FURNACE, 100, 4);

		assertNotNull(result);
		assertEquals(ProcessingContext.Kind.FURNACE_SMELTING, result.context().kind());
	}

	@Test
	public void rejectsExactDeltaWithoutMatchingActivityEvidence()
	{
		InventoryChange change = change(
			Map.of(ItemID.IRON_ORE, 4, ItemID.COAL, 8), 2,
			Map.of(ItemID.IRON_ORE, 3, ItemID.COAL, 6, ItemID.STEEL_BAR, 1), 3);
		assertNull(detector.detect(change, InventoryState.empty(), -1, 100, 4));
	}

	@Test
	public void menuIntentIsCapturedWithoutOwningTheEta()
	{
		assertEquals(ProcessingContext.Kind.FLETCHING_KNIFE,
			detector.contextForMenu(-1, ItemID.FLETCHING_KNIFE,
				MenuAction.WIDGET_TARGET_ON_WIDGET, "use", "logs",
				InventoryState.empty()).kind());
		assertEquals(ProcessingContext.Kind.FORESTERS_CAMPFIRE,
			detector.contextForMenu(-1, -1, MenuAction.GAME_OBJECT_FIRST_OPTION,
				"add logs", "forester's campfire", InventoryState.empty()).kind());
		assertEquals(ProcessingContext.Kind.FORESTERS_CAMPFIRE,
			detector.contextForMenu(-1, -1, MenuAction.GAME_OBJECT_FIRST_OPTION,
				"tend-to", "campfire", InventoryState.empty()).kind());
		assertEquals(ProcessingContext.Kind.FORESTERS_CAMPFIRE,
			detector.contextForMenu(-1, ItemID.MAPLE_LOGS,
				MenuAction.WIDGET_TARGET_ON_GAME_OBJECT, "use", "forester's campfire",
				InventoryState.empty()).kind());
		assertEquals(ProcessingContext.Kind.COOKING,
			detector.contextForMenu(-1, ItemID.RAW_SHARK,
				MenuAction.WIDGET_TARGET_ON_GAME_OBJECT, "use", "forester's campfire",
				InventoryState.empty()).kind());
	}

	@Test
	public void potionSavingEquipmentSuppressesExactFinishedPotionContext()
	{
		assertEquals(ProcessingContext.Kind.NONE,
			detector.contextForMenu(-1, -1, MenuAction.WIDGET_TARGET_ON_WIDGET,
				"use", "potion", InventoryState.of(
					Map.of(ItemID.PRESCRIPTION_GOGGLES, 1), 1)).kind());
	}

	private static InventoryChange change(Map<Integer, Integer> before, int beforeSlots,
		Map<Integer, Integer> after, int afterSlots)
	{
		return new InventoryChange(InventoryState.of(before, beforeSlots),
			InventoryState.of(after, afterSlots));
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.awt.Component;
import java.awt.Container;
import java.awt.GridLayout;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.JComboBox;
import javax.swing.JCheckBox;
import javax.swing.SwingUtilities;
import org.junit.Test;

/** Headless checks for the refreshable sidebar's component ownership and vertical layout. */
public class IdleFamiliarPanelTest
{
	@Test
	public void repeatedPresetStyleRefreshesKeepRowsOrderedAndExposeGridDensity() throws Exception
	{
		AtomicReference<IdleFamiliarPanel> reference = new AtomicReference<>();
		SwingUtilities.invokeAndWait(() ->
		{
			IdleFamiliarPanel panel = new IdleFamiliarPanel(content(), new IdleFamiliarConfig() { }, null);
			panel.setSize(PluginPanelDimensions.WIDTH, 1400);
			for (int index = 0; index < 20; index++)
			{
				panel.refreshFromConfig();
			}
			panel.doLayout();
			reference.set(panel);
		});

		IdleFamiliarPanel panel = reference.get();
		List<Class<?>> comboTypes = new ArrayList<>();
		collectComboTypes(panel, comboTypes);
		assertTrue(comboTypes.contains(InventoryDensity.class));

		Component previous = null;
		for (Component component : panel.getComponents())
		{
			if (!component.isVisible() || component.getHeight() <= 0)
			{
				continue;
			}
			if (previous != null)
			{
				Rectangle before = previous.getBounds();
				Rectangle current = component.getBounds();
				assertTrue("Sidebar rows overlap: " + previous.getClass().getSimpleName()
					+ " and " + component.getClass().getSimpleName(),
					before.y + before.height <= current.y);
			}
			previous = component;
		}
		SwingUtilities.invokeAndWait(panel::shutDown);
	}

	@Test
	public void constrainedSidebarControlsUseSeparateShortLabelsAndTooltips() throws Exception
	{
		AtomicReference<IdleFamiliarPanel> reference = new AtomicReference<>();
		SwingUtilities.invokeAndWait(() -> reference.set(new IdleFamiliarPanel(
			content(), new IdleFamiliarConfig() { }, null)));

		List<JCheckBox> checkBoxes = new ArrayList<>();
		collectCheckBoxes(reference.get(), checkBoxes);
		List<String> labels = new ArrayList<>();
		for (JCheckBox checkBox : checkBoxes)
		{
			labels.add(checkBox.getText());
			assertFalse("Sidebar labels must not contain rendered ellipses",
				checkBox.getText().contains("..."));
		}

		assertTrue(labels.contains("Shimmer"));
		assertTrue(labels.contains("Reason"));
		assertTrue(labels.contains("Frame"));
		assertFalse(labels.contains("Speech bubble"));
		assertTrue(labels.contains("RL notify"));
		assertTrue(labels.stream().filter("ETA"::equals).count() == 2);
		assertTrue(labels.contains("Inv"));
		assertFalse(labels.contains("Shimmer + reason"));
		assertFalse(labels.contains("RuneLite notifications"));
		assertFalse(labels.contains("Keep inventory grid open"));

		assertToolTip(checkBoxes, "Inv");
		assertToolTip(checkBoxes, "RL notify");
		assertTrue(checkBoxes.stream().anyMatch(checkBox ->
			"ETA finished sound".equals(checkBox.getToolTipText())));
		assertThreeColumnLabelsFit(reference.get());
		SwingUtilities.invokeAndWait(reference.get()::shutDown);
	}

	private static void collectComboTypes(Container container, List<Class<?>> types)
	{
		for (Component component : container.getComponents())
		{
			if (component instanceof JComboBox<?>)
			{
				JComboBox<?> box = (JComboBox<?>) component;
				if (box.getItemCount() > 0 && box.getItemAt(0) != null)
				{
					types.add(box.getItemAt(0).getClass());
				}
			}
			if (component instanceof Container)
			{
				collectComboTypes((Container) component, types);
			}
		}
	}

	private static void collectCheckBoxes(Container container, List<JCheckBox> checkBoxes)
	{
		for (Component component : container.getComponents())
		{
			if (component instanceof JCheckBox)
			{
				checkBoxes.add((JCheckBox) component);
			}
			if (component instanceof Container)
			{
				collectCheckBoxes((Container) component, checkBoxes);
			}
		}
	}

	private static void assertToolTip(List<JCheckBox> checkBoxes, String label)
	{
		for (JCheckBox checkBox : checkBoxes)
		{
			if (label.equals(checkBox.getText()))
			{
				assertTrue(label + " should preserve its full meaning in a tooltip",
					checkBox.getToolTipText() != null && !checkBox.getToolTipText().isEmpty());
				return;
			}
		}
		assertTrue("Missing sidebar control " + label, false);
	}

	private static void assertThreeColumnLabelsFit(Container container)
	{
		if (container.getLayout() instanceof GridLayout)
		{
			GridLayout layout = (GridLayout) container.getLayout();
			if (layout.getColumns() == 3)
			{
				int cellWidth = (PluginPanelDimensions.WIDTH - layout.getHgap() * 2) / 3;
				for (Component component : container.getComponents())
				{
					if (component instanceof JCheckBox)
					{
						assertTrue(((JCheckBox) component).getText() + " is too wide for its sidebar cell",
							component.getPreferredSize().width <= cellWidth);
					}
				}
			}
		}
		for (Component component : container.getComponents())
		{
			if (component instanceof Container)
			{
				assertThreeColumnLabelsFit((Container) component);
			}
		}
	}

	private static WidgetContentSource content()
	{
		return new WidgetContentSource()
		{
			@Override
			public BufferedImage getCurrentFrame()
			{
				return null;
			}

			@Override
			public Rectangle getCurrentFrameVisualBounds()
			{
				return null;
			}

			@Override
			public AvatarPackManifest getAvatarPackManifest()
			{
				return null;
			}

			@Override
			public WidgetSnapshot getWidgetSnapshot()
			{
				return WidgetSnapshot.loggedOut();
			}
		};
	}

	/** Avoid importing the protected PluginPanel width constant into production code. */
	private static final class PluginPanelDimensions
	{
		private static final int WIDTH = 225;
	}
}

