	public void exactConfigEventValueControlsCollapsedState()
	{
		DesktopPetWindow widget = new DesktopPetWindow(null, null, null);
		widget.applyCollapsed("true");
		assertTrue(widget.isCollapsed());
		widget.applyCollapsed("false");
		assertFalse(widget.isCollapsed());
	}

	@Test
	public void configBackedPaintStateIsSafelyPublishedToSwing() throws Exception
	{
		assertTrue(Modifier.isVolatile(DesktopPetWindow.class
			.getDeclaredField("collapsed").getModifiers()));
		assertTrue(Modifier.isVolatile(DesktopPetWindow.class
			.getDeclaredField("selectedTheme").getModifiers()));
