			avatar, DesktopPetWindow.CARROT_SIZE, 6);
		Rectangle collapsed = DesktopPetWindow.standaloneControlBounds(48, 40, 48,
			null, DesktopPetWindow.CARROT_SIZE, 6);

		assertEquals(42, expanded.x + expanded.width);
		assertEquals(42, collapsed.x + collapsed.width);
