package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class ObservedProcessingTrackerTest
{
	private static final int INPUT = 10;
	private static final int OUTPUT = 20;

	@Test
	public void requiresThreeIdenticalCyclesBeforePublishingATime()
	{
		ObservedProcessingTracker tracker = new ObservedProcessingTracker();
		TaskEtaSnapshot first = observe(tracker, inventory(INPUT, 10), inventory(INPUT, 9, OUTPUT, 1), 10, true);
		assertTrue(first.isCalibrating());
		assertEquals("Cal 1/3", first.getDisplayText());

		TaskEtaSnapshot second = observe(tracker, inventory(INPUT, 9, OUTPUT, 1),
			inventory(INPUT, 8, OUTPUT, 2), 14, true);
		assertTrue(second.isCalibrating());
		assertEquals("Cal 2/3", second.getDisplayText());

		TaskEtaSnapshot third = observe(tracker, inventory(INPUT, 8, OUTPUT, 2),
			inventory(INPUT, 7, OUTPUT, 3), 18, true);
		assertFalse(third.isCalibrating());
		assertTrue(third.isApproximate());
		assertEquals(TaskEtaSnapshot.Confidence.HIGH, third.getConfidence());
		assertEquals(28, third.getRemainingTicks());
	}

	@Test
	public void supportsTwoInputsAndOneToManyOutput()
	{
		ObservedProcessingTracker tracker = new ObservedProcessingTracker();
		observe(tracker, inventory(10, 8, 11, 4), inventory(10, 6, 11, 3, 20, 15), 10, true);
		observe(tracker, inventory(10, 6, 11, 3, 20, 15), inventory(10, 4, 11, 2, 20, 30), 13, true);
		TaskEtaSnapshot snapshot = observe(tracker, inventory(10, 4, 11, 2, 20, 30),
			inventory(10, 2, 11, 1, 20, 45), 16, true);
		assertTrue(snapshot.isActive());
		assertEquals(1, snapshot.getRemainingUnits());
		assertEquals(3, snapshot.getRemainingTicks());
	}

	@Test
	public void supportsThreeInputAutomaticMagicTransformationsAfterCalibration()
	{
		ObservedProcessingTracker tracker = new ObservedProcessingTracker();
		observe(tracker, inventory(10, 6, 11, 12, 12, 420, 20, 0),
			inventory(10, 5, 11, 10, 12, 350, 20, 1), 10, true);
		observe(tracker, inventory(10, 5, 11, 10, 12, 350, 20, 1),
			inventory(10, 4, 11, 8, 12, 280, 20, 2), 16, true);
		TaskEtaSnapshot snapshot = observe(tracker,
			inventory(10, 4, 11, 8, 12, 280, 20, 2),
			inventory(10, 3, 11, 6, 12, 210, 20, 3), 22, true);

		assertTrue(snapshot.isActive());
		assertEquals(TaskEtaSnapshot.Confidence.HIGH, snapshot.getConfidence());
		assertEquals(3, snapshot.getRemainingUnits());
		assertEquals(18, snapshot.getRemainingTicks());
	}

	@Test
	public void rejectsChangedRecipesBankLikeDeltasAndUnverifiedActivity()
	{
		ObservedProcessingTracker tracker = new ObservedProcessingTracker();
		observe(tracker, inventory(INPUT, 10), inventory(INPUT, 9, OUTPUT, 1), 10, true);
		TaskEtaSnapshot changed = observe(tracker, inventory(INPUT, 9, OUTPUT, 1),
			inventory(INPUT, 7, OUTPUT, 2), 14, true);
		assertTrue(changed.isCalibrating());
		assertEquals("Cal 1/3", changed.getDisplayText());

		TaskEtaSnapshot bank = observe(tracker, inventory(1, 10, 2, 10, 3, 10),
			inventory(4, 10, 5, 10, 6, 10), 20, true);
		assertFalse(bank.isActive());

		TaskEtaSnapshot unverified = observe(tracker, inventory(INPUT, 8), inventory(INPUT, 7, OUTPUT, 1), 24, false);
		assertFalse(unverified.isActive());
	}

	private static TaskEtaSnapshot observe(ObservedProcessingTracker tracker, Map<Integer, Integer> before,
		Map<Integer, Integer> after, int tick, boolean eligible)
	{
		return tracker.observe(new InventoryDelta(before, after), before, after, "Crafting", eligible, tick);
	}

	private static Map<Integer, Integer> inventory(int... pairs)
	{
		Map<Integer, Integer> inventory = new HashMap<>();
		for (int index = 0; index < pairs.length; index += 2)
		{
			inventory.put(pairs[index], pairs[index + 1]);
		}
		return inventory;
	}
}

