	@Test
	public void everyReviewedStackablePotionUpgradeUsesItsExactLimitingIngredient()
	{
		// Four-dose recipes pinned in the Wiki experience table: four shards or
		// scales per potion, one crushed bone, and 80 ancient essence.
		int[][] recipes = {
			{ItemID.ANTIFIRE_POTION4, ItemID.LAVA_SCALE_SHARD, 4,
				ItemID.EXTENDED_ANTIFIRE4},
			{ItemID.ANTIFIRE_POTION4, ItemID.CRUSHED_SUPERIOR_DRAGON_BONES, 1,
				ItemID.SUPER_ANTIFIRE_POTION4},
