		controller.setProcessingContext(ProcessingContext.finishedPotionWithoutSavingEffect());
		controller.seedInventory(inventory(ItemID.ANTIVENOM4_12913, 4,
			ItemID.ARAXYTE_VENOM_SAC, 16));
		controller.onInventoryChanged(inventory(ItemID.ANTIVENOM4_12913, 3,
			ItemID.ARAXYTE_VENOM_SAC, 12, ItemID.EXTENDED_ANTIVENOM4, 1), 160);

		assertTrue(controller.snapshot().isActive());
		assertFalse(controller.snapshot().isCalibrating());
		assertEquals(3, controller.snapshot().getRemainingUnits());
		assertEquals(9, controller.snapshot().getRemainingTicks());
