import java.util.Collections;
import net.runelite.api.ItemID;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class SessionLifecycleCoordinatorTest
{
	@Test
	public void resetClearsSharedSessionEvidenceAndAdvancesEpoch()
	{
		Fixture fixture = new Fixture();
		int firstEpoch = fixture.lifecycle.reset();
		InventoryState inventory = InventoryState.of(
			Collections.singletonMap(ItemID.RAW_SHARK, 4), 4);
		assertTrue(fixture.lifecycle.seedIfCurrent(firstEpoch, inventory, InventoryState.empty()));

		fixture.eta.onVerifiedFixedAttentionHorizon(EtaActivity.STYMPHIKE,
			"Test", 20, true, 10);
		fixture.evidence.mark(ActivityEvidenceTracker.Signal.FISHING, 10);
		fixture.extendedInventory.markFull(ExtendedInventoryTracker.Container.FISH_BARREL);
		fixture.fullInventory.markProgress(10);
		fixture.skillProgress.record(net.runelite.api.Skill.FISHING, 1_000, 50, 0L);
		assertTrue(fixture.skillProgress.record(
			net.runelite.api.Skill.FISHING, 1_100, 50, 1_000L).activeXpGain());
		fixture.resources.recordWoodcuttingInteraction(WoodcuttingCatalog.Tree.MAPLE,
			10832, new WorldPoint(3200, 3200, 0), 10);

		int secondEpoch = fixture.lifecycle.reset();

		assertEquals(firstEpoch + 1, secondEpoch);
		assertFalse(fixture.eta.snapshot().isActive());
		assertFalse(fixture.inventoryHistory.isSeeded());
		assertFalse(fixture.inventoryHistory.isEquipmentSeeded());
		assertFalse(fixture.evidence.isRecent(ActivityEvidenceTracker.Signal.FISHING, 10, 4));
		assertFalse(fixture.extendedInventory.isKnownFull(
			ExtendedInventoryTracker.Container.FISH_BARREL));
		assertFalse(fixture.fullInventory.isWorkingAtFull(true, false, true, 10));
		assertFalse(fixture.skillProgress.record(
			net.runelite.api.Skill.FISHING, 1_200, 50, 2_000L).activeXpGain());
		assertEquals(GatheringResourceTracker.NO_HORIZON,
			fixture.resources.remainingWoodcuttingHorizon(WoodcuttingCatalog.Tree.MAPLE, 10));
	}

	@Test
	public void staleQueuedSeedCannotOverwriteANewerSession()
	{
		Fixture fixture = new Fixture();
		int staleEpoch = fixture.lifecycle.reset();
		int currentEpoch = fixture.lifecycle.reset();
		InventoryState stale = InventoryState.of(
			Collections.singletonMap(ItemID.RAW_SHARK, 20), 20);
		InventoryState current = InventoryState.of(
			Collections.singletonMap(ItemID.RAW_LOBSTER, 7), 7);

		assertFalse(fixture.lifecycle.isCurrent(staleEpoch));
		assertTrue(fixture.lifecycle.isCurrent(currentEpoch));
		assertFalse(fixture.lifecycle.seedIfCurrent(staleEpoch, stale, InventoryState.empty()));
		assertFalse(fixture.inventoryHistory.isSeeded());
		assertTrue(fixture.lifecycle.seedIfCurrent(currentEpoch, current, InventoryState.empty()));
		assertEquals(7, fixture.inventoryHistory.current().quantity(ItemID.RAW_LOBSTER));
		assertEquals(0, fixture.inventoryHistory.current().quantity(ItemID.RAW_SHARK));
	}

	@Test
	public void resetAfterSchedulingInvalidatesThatSeed()
	{
		Fixture fixture = new Fixture();
		int scheduledEpoch = fixture.lifecycle.reset();
		fixture.lifecycle.reset();

		assertFalse(fixture.lifecycle.seedIfCurrent(scheduledEpoch,
			InventoryState.empty(), InventoryState.empty()));
		assertFalse(fixture.inventoryHistory.isSeeded());
	}

	private static final class Fixture
	{
		private final EtaSessionManager eta = new EtaSessionManager();
		private final InventoryHistory inventoryHistory = new InventoryHistory();
		private final GatheringResourceTracker resources = eta.gatheringResourcesForRecognition();
		private final FullInventoryActivityTracker fullInventory = new FullInventoryActivityTracker();
		private final ActivityDetector activityDetector = new ActivityDetector(
			ActivityAnimationRegistry.build(), resources);
		private final ActivityEvidenceTracker evidence = activityDetector.evidence();
		private final ExtendedInventoryTracker extendedInventory =
			activityDetector.extendedInventory();
		private final SkillProgressTracker skillProgress = new SkillProgressTracker(null, null);
		private final SessionLifecycleCoordinator lifecycle = new SessionLifecycleCoordinator(
			eta, inventoryHistory, fullInventory, activityDetector, skillProgress);
	}
}

