package com.idlefamiliar;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.InputStream;
import java.lang.reflect.Constructor;
import javax.imageio.ImageIO;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;

/**
 * Reproducible README artwork rendered by the production widget painter.
 * Sample values are deliberately synthetic; geometry, themes, typography,
 * avatar placement, and inventory slots are the real implementation.
 */
public final class DocumentationPreviewRenderer
{
	private static final int CANVAS_WIDTH = 520;
	private static final int CANVAS_HEIGHT = 520;

	private DocumentationPreviewRenderer()
	{
	}

	public static void main(String[] args) throws Exception
	{
		if (args.length != 1)
		{
			throw new IllegalArgumentException("Expected the documentation image directory");
		}
		File outputDirectory = new File(args[0]);
		if (!outputDirectory.isDirectory() && !outputDirectory.mkdirs())
		{
			throw new IllegalStateException("Could not create " + outputDirectory);
		}

		AvatarAnimation animation;
		try (InputStream stream = DocumentationPreviewRenderer.class.getResourceAsStream(
			"/com/idlefamiliar/avatar/default/woodcutting_loop.png"))
		{
			animation = new SpriteSheetLoader().load(stream, "woodcutting_loop.png", 140L);
		}
		BufferedImage frame = animation.getFrame(0L);
		Rectangle visualBounds = animation.getVisualBounds();

		render(new File(outputDirectory, "widget-compact-preview.png"), frame, visualBounds,
			InventoryDensity.OFF, false, 17);
		render(new File(outputDirectory, "widget-inventory-preview.png"), frame, visualBounds,
			InventoryDensity.MINI_GRID, true, 0);
	}

	private static void render(File output, BufferedImage frame, Rectangle visualBounds,
		InventoryDensity density, boolean inventoryOpen, int inventoryCount) throws Exception
	{
		BufferedImage[] result = new BufferedImage[1];
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				WidgetSnapshot snapshot = new WidgetSnapshot(
					AvatarState.SKILLING, "Woodcutting", 71, 99, 42, 77,
					inventoryCount, "64.3k", "Cutting maple", null, false,
					AttentionReason.NONE,
					TaskEtaSnapshot.gathering("Maple tree", 23, 11, 90, 180, 78, 102),
					InventorySnapshot.empty());
				WidgetContentSource source = new PreviewContentSource(frame, visualBounds, snapshot);
				DesktopPetWindow desktopWindow = new DesktopPetWindow(
					source, new PreviewConfig(density, inventoryOpen), null);
				JComponent component = createPetComponent(desktopWindow);
				component.setSize(CANVAS_WIDTH, CANVAS_HEIGHT);

				BufferedImage canvas = new BufferedImage(
					CANVAS_WIDTH, CANVAS_HEIGHT, BufferedImage.TYPE_INT_ARGB);
				Graphics2D graphics = canvas.createGraphics();
				try
				{
					component.paint(graphics);
				}
				finally
				{
					graphics.dispose();
				}
				result[0] = cropVisible(canvas, 4);
			}
			catch (ReflectiveOperationException ex)
			{
				throw new IllegalStateException(ex);
			}
		});

		if (result[0] == null || result[0].getWidth() < 100 || result[0].getHeight() < 60)
		{
			throw new IllegalStateException("Documentation preview rendered empty: " + output);
		}
		if (!ImageIO.write(result[0], "png", output))
		{
			throw new IllegalStateException("PNG writer unavailable");
		}
	}

	private static JComponent createPetComponent(DesktopPetWindow desktopWindow)
		throws ReflectiveOperationException
	{
		Class<?> componentType = Class.forName("com.idlefamiliar.DesktopPetWindow$PetComponent");
		Constructor<?> constructor = componentType.getDeclaredConstructor(DesktopPetWindow.class);
		constructor.setAccessible(true);
		return (JComponent) constructor.newInstance(desktopWindow);
	}

	private static BufferedImage cropVisible(BufferedImage source, int padding)
	{
		int minX = source.getWidth();
		int minY = source.getHeight();
		int maxX = -1;
		int maxY = -1;
		for (int y = 0; y < source.getHeight(); y++)
		{
			for (int x = 0; x < source.getWidth(); x++)
			{
				if ((source.getRGB(x, y) >>> 24) != 0)
				{
					minX = Math.min(minX, x);
					minY = Math.min(minY, y);
					maxX = Math.max(maxX, x);
					maxY = Math.max(maxY, y);
				}
			}
		}
		if (maxX < minX || maxY < minY)
		{
			return null;
		}
		int left = Math.max(0, minX - padding);
		int top = Math.max(0, minY - padding);
		int right = Math.min(source.getWidth(), maxX + padding + 1);
		int bottom = Math.min(source.getHeight(), maxY + padding + 1);
		BufferedImage copy = new BufferedImage(right - left, bottom - top,
			BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = copy.createGraphics();
		try
		{
			graphics.drawImage(source, -left, -top, null);
		}
		finally
		{
			graphics.dispose();
		}
		return copy;
	}

	private static final class PreviewContentSource implements WidgetContentSource
	{
		private final BufferedImage frame;
		private final Rectangle visualBounds;
		private final WidgetSnapshot snapshot;

		private PreviewContentSource(BufferedImage frame, Rectangle visualBounds,
			WidgetSnapshot snapshot)
		{
			this.frame = frame;
			this.visualBounds = new Rectangle(visualBounds);
			this.snapshot = snapshot;
		}

		@Override
		public BufferedImage getCurrentFrame()
		{
			return frame;
		}

		@Override
		public Rectangle getCurrentFrameVisualBounds()
		{
			return new Rectangle(visualBounds);
		}

		@Override
		public AvatarPackManifest getAvatarPackManifest()
		{
			return AvatarPackManifest.goldenToad();
		}

		@Override
		public WidgetSnapshot getWidgetSnapshot()
		{
			return snapshot;
		}
	}

	private static final class PreviewConfig implements IdleFamiliarConfig
	{
		private final InventoryDensity density;
		private final boolean inventoryOpen;

		private PreviewConfig(InventoryDensity density, boolean inventoryOpen)
		{
			this.density = density;
			this.inventoryOpen = inventoryOpen;
		}

		@Override
		public AvatarScale avatarScale()
		{
			return AvatarScale.X2;
		}

		@Override
		public WidgetTheme widgetTheme()
		{
			return WidgetTheme.SWAMP;
		}

		@Override
		public boolean showAdvancedInfo()
		{
			return true;
		}

		@Override
		public boolean showTaskEta()
		{
			return true;
		}

		@Override
		public boolean showAttentionReason()
		{
			return true;
		}

		@Override
		public InventoryDensity inventoryDensity()
		{
			return density;
		}

		@Override
		public boolean inventoryViewerAlwaysVisible()
		{
			return inventoryOpen;
		}
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.lang.reflect.Proxy;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import org.junit.Test;

public class InventorySnapshotTest
{
	@Test
	public void captureKeepsTheNativeFourBySevenSlotLayoutAndExactQuantities()
	{
		Item[] items = new Item[28];
		items[0] = new Item(ItemID.LOGS, 1);
		items[3] = new Item(ItemID.COAL, 123_456_789);
		items[27] = new Item(ItemID.RAW_SHARK, 2);

		InventorySnapshot snapshot = InventorySnapshot.capture(inventory(items), null, null);
		assertEquals(4, InventorySnapshot.COLUMNS);
		assertEquals(7, InventorySnapshot.ROWS);
		assertEquals(ItemID.LOGS, snapshot.getSlot(0).getItemId());
		assertEquals(123_456_789, snapshot.getSlot(3).getQuantity());
		assertTrue(snapshot.getSlot(1).isEmpty());
		assertEquals(ItemID.RAW_SHARK, snapshot.getSlot(27).getItemId());
		assertEquals(2, snapshot.getSlot(27).getQuantity());
	}

	@Test
	public void unchangedInventoryReusesItsPublishedSnapshot()
	{
		Item[] items = new Item[28];
		items[5] = new Item(ItemID.MAPLE_LOGS, 1);
		ItemContainer inventory = inventory(items);

		InventorySnapshot first = InventorySnapshot.capture(inventory, null, null);
		assertSame(first, InventorySnapshot.capture(inventory, first, null));

		items[5] = new Item(ItemID.MAPLE_LOGS, 2);
		InventorySnapshot changed = InventorySnapshot.capture(inventory, first, null);
		assertEquals(2, changed.getSlot(5).getQuantity());
	}

	private static ItemContainer inventory(Item[] items)
	{
		return (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),
			new Class<?>[]{ItemContainer.class}, (proxy, method, args) ->
				"getItems".equals(method.getName()) ? items : defaultValue(method.getReturnType()));
	}

	private static Object defaultValue(Class<?> type)
	{
		if (!type.isPrimitive())
		{
			return null;
		}
		if (type == boolean.class)
		{
			return false;
		}
		if (type == char.class)
		{
			return '\0';
		}
		if (type == long.class)
		{
			return 0L;
		}
		if (type == float.class)
		{
			return 0f;
		}
		if (type == double.class)
		{
			return 0d;
		}
		return 0;
	}
}

package com.idlefamiliar;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/** Records release diagnostics without imposing machine-specific timing thresholds. */
public final class ReleasePerformanceProbe
{
	private static final int PAINT_ITERATIONS = 1_000;
	private static final String[] REPRESENTATIVE_SKILLS = {
		"Agility", "Cooking", "Crafting", "Firemaking", "Fishing", "Fletching",
		"Herblore", "Hunter", "Mining", "Prayer", "Sailing", "Smithing",
		"Thieving", "Woodcutting"
	};

	private ReleasePerformanceProbe()
	{
	}

	public static void main(String[] args) throws IOException
	{
		if (args.length != 1)
		{
			throw new IllegalArgumentException("Expected one report path");
		}

		forceGc();
		long heapBefore = usedHeap();
		AnimationController controller = new AnimationController();
		long startupStart = System.nanoTime();
		controller.loadDefaultAnimations();
		long startupNanos = System.nanoTime() - startupStart;

		long warmStart = System.nanoTime();
		for (AvatarState state : AvatarState.values())
		{
			controller.getFrame(state, "");
		}
		for (String skill : REPRESENTATIVE_SKILLS)
		{
			controller.getFrame(AvatarState.SKILLING, skill);
		}
		long warmNanos = System.nanoTime() - warmStart;
		forceGc();
		long retainedHeap = Math.max(0L, usedHeap() - heapBefore);

		long reloadStart = System.nanoTime();
		controller.reloadAnimations();
		long reloadNanos = System.nanoTime() - reloadStart;

		Dimension gridSize = InventoryGridRenderer.viewerSize(
			InventoryDensity.MINI_GRID, value -> value);
		BufferedImage canvas = new BufferedImage(gridSize.width, gridSize.height,
			BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = canvas.createGraphics();
		InventoryGridRenderer renderer = new InventoryGridRenderer();
		long paintStart = System.nanoTime();
		try
		{
			for (int iteration = 0; iteration < PAINT_ITERATIONS; iteration++)
			{
				renderer.paint(graphics, InventorySnapshot.empty(), 0,
					InventoryDensity.MINI_GRID, 0, 0, gridSize.width, gridSize.height,
					WidgetTheme.CLASSIC_RUNESCAPE, 1d, value -> value, iteration * 100L);
			}
		}
		finally
		{
			graphics.dispose();
		}
		long paintNanos = System.nanoTime() - paintStart;

		List<String> report = new ArrayList<>();
		report.add("javaVersion=" + System.getProperty("java.version"));
		report.add("javaVendor=" + System.getProperty("java.vendor"));
		report.add("avatarStartupLoadMs=" + millis(startupNanos));
		report.add("representativeAssetWarmupMs=" + millis(warmNanos));
		report.add("avatarReloadMs=" + millis(reloadNanos));
		report.add("representativeRetainedHeapBytes=" + retainedHeap);
		report.add("inventoryPaintIterations=" + PAINT_ITERATIONS);
		report.add("inventoryPaintAverageMicros="
			+ String.format(java.util.Locale.ROOT, "%.3f",
				paintNanos / 1_000d / PAINT_ITERATIONS));
		report.add("animatedRepaintIntervalMs="
			+ DesktopPetWindow.ANIMATED_REPAINT_INTERVAL_MS);
		report.add("animatedRepaintsPerSecond="
			+ (1_000 / DesktopPetWindow.ANIMATED_REPAINT_INTERVAL_MS));
		report.add("staticCompactRepaintIntervalMs="
			+ DesktopPetWindow.STATIC_REPAINT_INTERVAL_MS);
		report.add("staticCompactRepaintsPerSecond="
			+ (1_000 / DesktopPetWindow.STATIC_REPAINT_INTERVAL_MS));
		report.add("loggedOutCompactRepaintIntervalMs="
			+ DesktopPetWindow.LOGGED_OUT_REPAINT_INTERVAL_MS);
		report.add("loggedOutCompactRepaintsPerSecond="
			+ (1_000 / DesktopPetWindow.LOGGED_OUT_REPAINT_INTERVAL_MS));

		Path reportPath = Path.of(args[0]);
		Files.createDirectories(reportPath.getParent());
		Files.write(reportPath, report, StandardCharsets.UTF_8);
	}

	private static long millis(long nanos)
	{
		return Math.round(nanos / 1_000_000d);
	}

	private static long usedHeap()
	{
		Runtime runtime = Runtime.getRuntime();
		return runtime.totalMemory() - runtime.freeMemory();
	}

	private static void forceGc()
	{
		System.gc();
		System.runFinalization();
		System.gc();
	}
}

