public class SalvageSessionCoordinatorTest
{
	@Test
	public void playerInventoryOwnsProgressionAndChatCannotDoubleDecrement()
	{
		Fixture fixture = new Fixture();
		InventoryState before = InventoryState.of(
			Map.of(ItemID.SMALL_SALVAGE, 4), 4);
		InventoryState after = InventoryState.of(
			Map.of(ItemID.SMALL_SALVAGE, 3), 3);

		assertTrue(fixture.coordinator.onMenuInteraction("sort-salvage",
			"salvaging station", 100, false, () -> before));
		assertEquals(EtaActivity.SALVAGE_SORTING, fixture.eta.activeActivity());
		assertEquals(4, fixture.eta.snapshot().getRemainingUnits());

		fixture.coordinator.onPlayerInventoryChanged(
			new InventoryChange(before, after), 103, true, false, 4);
		assertEquals(3, fixture.eta.snapshot().getRemainingUnits());

		fixture.coordinator.onChatMessage(
			"you sort through the fishy salvage and find: coins.",
			103, false, () -> after);
		assertEquals(3, fixture.eta.snapshot().getRemainingUnits());

		fixture.coordinator.onChatMessage("you have no more salvage to sort.",
			106, false, () -> after);
		assertEquals(EtaActivity.NONE, fixture.eta.activeActivity());
		assertTrue(fixture.eta.consumeExpiry());
		assertFalse(fixture.eta.consumeExpiry());
	}

	@Test
	public void onboardStationAnimationAlsoUsesPlayerInventory()
	{
		Fixture fixture = new Fixture();
		InventoryState playerInventory = InventoryState.of(
			Map.of(ItemID.FISHY_SALVAGE, 5), 5);

		fixture.coordinator.onAnimation(
			AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_INTERACT01,
			200, false, false, () -> playerInventory);

		assertEquals(EtaActivity.SALVAGE_SORTING, fixture.eta.activeActivity());
		assertEquals(5, fixture.eta.snapshot().getRemainingUnits());
	}

	@Test
	public void playerInventoryDecreaseAdvancesSortingQueue()
	{
		Fixture fixture = new Fixture();
		InventoryState before = InventoryState.of(
			Map.of(ItemID.SMALL_SALVAGE, 4), 4);
		InventoryState after = InventoryState.of(
			Map.of(ItemID.SMALL_SALVAGE, 3), 3);
		fixture.coordinator.onMenuInteraction("sort-salvage",
			"salvaging station", 250, false, () -> before);

		fixture.coordinator.onPlayerInventoryChanged(
			new InventoryChange(before, after), 253, true, false, 4);

		assertEquals(EtaActivity.SALVAGE_SORTING, fixture.eta.activeActivity());
		assertEquals(3, fixture.eta.snapshot().getRemainingUnits());
	}

	@Test
	public void verifiedSortingPreventsHookPoseFromReclaimingEta()
	{
		Fixture fixture = new Fixture();
		InventoryState playerInventory = InventoryState.of(
			Map.of(ItemID.SMALL_SALVAGE, 4), 4);
		fixture.coordinator.onMenuInteraction("sort-salvage",
			"salvaging station", 300, false, () -> playerInventory);

		int hookAnimation =
			AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_IDLE01;
		fixture.coordinator.onAnimation(hookAnimation, 301,
			true, false, () -> playerInventory);

		assertEquals(EtaActivity.SALVAGE_SORTING, fixture.eta.activeActivity());
		assertTrue(fixture.coordinator.isSortingEngaged(hookAnimation, 301));
	}

	@Test
	public void hookPoseStartsOnlyTheObservedGatheringCalibration()
	{
		Fixture fixture = new Fixture();
		InventoryState playerInventory = InventoryState.of(
			Map.of(ItemID.COINS_995, 1), 1);

		fixture.coordinator.onAnimation(
			AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_PULL01,
			400, false, false, () -> playerInventory);

		assertEquals(EtaActivity.SALVAGE_GATHERING, fixture.eta.activeActivity());
		assertTrue(fixture.eta.snapshot().isCalibrating());
		assertFalse(fixture.coordinator.isSortingEngaged(-1, 400));
	}

	@Test
	public void hookPoseWaitsForTheNativeInventoryContainer()
	{
		Fixture fixture = new Fixture();

		fixture.coordinator.onAnimation(
			AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_PULL01,
			450, false, false, null);

		assertEquals(EtaActivity.NONE, fixture.eta.activeActivity());
	}

	@Test
	public void unrelatedEventsDoNotReadThePlayerInventory()
	{
		Fixture fixture = new Fixture();
		AtomicInteger reads = new AtomicInteger();
		Supplier<InventoryState> inventory = () ->
		{
			reads.incrementAndGet();
			return InventoryState.empty();
		};

		fixture.coordinator.onAnimation(-1, 500, false, false, inventory);
		assertFalse(fixture.coordinator.onMenuInteraction("walk here", "",
			500, false, inventory));
		fixture.coordinator.onChatMessage("nothing about salvage", 500,
			false, inventory);

		assertEquals(0, reads.get());
	}

	private static final class Fixture
	{
		private final ActivityEvidenceTracker evidence = new ActivityEvidenceTracker();
		private final EtaSessionManager eta = new EtaSessionManager();
		private final SalvageSessionCoordinator coordinator =
			new SalvageSessionCoordinator(evidence, eta);
	}
}

