	@Test
	public void genericInventorySyncPreservesFixedQueueIdentity()
	{
		EtaSessionManager manager = new EtaSessionManager();
		manager.seedInventory(Map.of(ItemID.SMALL_SALVAGE, 4));
		manager.onVerifiedFixedProcessingQueue(EtaActivity.SALVAGE_SORTING,
			SalvageSortingCatalog.LABEL, 4, 3, true, 100);

		manager.onInventoryChanged(Map.of(ItemID.SMALL_SALVAGE, 3), 101);

		assertEquals(EtaActivity.SALVAGE_SORTING, manager.activeActivity());
		assertTrue(manager.snapshot().isActive());
	}

	@Test
	public void replacingAProcessingFamilyCannotResurrectItsOldRun()
	{
		EtaSessionManager manager = new EtaSessionManager();
		manager.onVerifiedFixedProcessingQueue(EtaActivity.SALVAGE_SORTING,
			"Old processing label", 10, 3, true, 100);
		assertEquals(EtaActivity.SALVAGE_SORTING, manager.activeActivity());

		manager.onVerifiedFixedAttentionHorizon(EtaActivity.STYMPHIKE,
			"New attention label", 65, true, 101);
		manager.onGameTick(player(StymphikeCatalog.WAITING_IDLE_ANIMATION), 102, false,
			ActivityAnimationRegistry.build(), new ActivityEvidenceTracker(), 4, 6);

		assertTrue(manager.snapshot().isActive());
		assertEquals("New attention label", manager.snapshot().getProfileLabel());
		assertEquals(EtaActivity.STYMPHIKE, manager.activeActivity());
	}

	@Test
	public void woodcuttingLifecycleUsesStableActivityOwnership()
	{
		EtaSessionManager manager = new EtaSessionManager();
		manager.onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree.MAPLE,
			WoodcuttingCatalog.AxeTier.RUNE, 80, 2, 1, true,
			GatheringResourceTracker.NO_HORIZON, 100);
		ActivityEvidenceTracker evidence = new ActivityEvidenceTracker();
		evidence.mark(ActivityEvidenceTracker.Signal.WOODCUTTING, 100);

		manager.onGameTick(player(-1), 104, false, ActivityAnimationRegistry.build(),
			evidence, 4, 6);
		assertTrue(manager.snapshot().isActive());

		manager.onGameTick(player(-1), 105, false, ActivityAnimationRegistry.build(),
			evidence, 4, 6);
		assertFalse(manager.snapshot().isActive());
		assertEquals(EtaActivity.NONE, manager.activeActivity());
	}

