	@Test
	public void stymphikeMovementCannotRestartAnAlreadyObservedEntryAnimation()
	{
		EtaSessionManager manager = new EtaSessionManager();
		ActivityEvidenceTracker evidence = new ActivityEvidenceTracker();

		manager.onGameTick(player(StymphikeCatalog.WAITING_IDLE_START_ANIMATION),
			100, true, ActivityAnimationRegistry.build(), evidence, 4, 6);
		assertTrue(manager.snapshot().isActive());

		// The plugin's movement stage cancels before ETA continuation. If the
		// one-shot entry animation is still visible, it must not be mistaken for
		// a second entry transition and recreate the cancelled horizon.
		manager.cancel();
		manager.onGameTick(player(StymphikeCatalog.WAITING_IDLE_START_ANIMATION),
			101, true, ActivityAnimationRegistry.build(), evidence, 4, 6);

		assertFalse(manager.snapshot().isActive());
		assertEquals(EtaActivity.NONE, manager.activeActivity());
	}

