		assertEquals(StymphikeCatalog.WAIT_TICKS - 10,
			manager.snapshot().getRemainingTicks());
	}

	@Test
	public void daeyaltOffsetClickStartsFromTheSoleObservedRockCycle()
	{
		EtaSessionManager manager = new EtaSessionManager();
		WorldPoint anchor = new WorldPoint(3600, 3300, 0);
		manager.onGameObjectDespawned(39094, anchor, 100);
		manager.onGameObjectSpawned(39095, anchor, 100);

		assertTrue(manager.armDaeyalt(new WorldPoint(3601, 3302, 0),
			DaeyaltCatalog.PickaxeTier.DRAGON, 102));
		manager.startPendingDaeyalt(103, 12);

		assertTrue(manager.snapshot().isActive());
		assertEquals(EtaActivity.DAEYALT, manager.activeActivity());
		assertEquals(DaeyaltCatalog.LABEL, manager.snapshot().getProfileLabel());
		assertEquals(89, manager.snapshot().getRemainingTicks());
	}

	private static Player player(int animation)
	{
		return (Player) Proxy.newProxyInstance(Player.class.getClassLoader(),
			new Class<?>[]{Player.class}, (proxy, method, args) ->
				"getAnimation".equals(method.getName()) ? animation
					: defaultValue(method.getReturnType()));
	}

	private static Object defaultValue(Class<?> type)
	{
		if (!type.isPrimitive())
		{
			return null;
		}
		if (type == boolean.class)
		{
			return false;
		}
		if (type == char.class)
		{
			return '\0';
		}
		if (type == long.class)
		{
			return 0L;
		}
		if (type == float.class)
		{
			return 0f;
		}
		if (type == double.class)
		{
			return 0d;
		}
		return 0;
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Map;
import org.junit.Test;

public class InventoryHistoryTest
{
	@Test
	public void commitsOneSharedBeforeAndAfterTransition()
	{
		InventoryHistory history = new InventoryHistory();
		history.seed(InventoryState.of(Map.of(1, 4), 4), InventoryState.empty());

		InventoryChange change = history.observe(InventoryState.of(Map.of(1, 3, 2, 1), 4));

		assertTrue(change.hasBaseline());
		assertEquals(4, change.before().quantity(1));
		assertEquals(3, change.after().quantity(1));
		assertEquals(1, change.delta().consumed(1));
		assertEquals(1, change.delta().produced(2));
		assertEquals(change.after(), history.current());
	}

	@Test
	public void preservesOccupiedSlotsSeparatelyFromStackCounts()
	{
		InventoryHistory history = new InventoryHistory();
		history.seed(InventoryState.of(Map.of(100, 2), 2), InventoryState.empty());
		InventoryChange change = history.observe(InventoryState.of(Map.of(100, 3), 3));

		assertEquals(2, change.before().occupiedSlots());
		assertEquals(3, change.after().occupiedSlots());
		assertEquals(1, change.delta().produced(100));
	}

	@Test
	public void reportsMissingBaselineAfterReset()
	{
		InventoryHistory history = new InventoryHistory();
		history.seed(InventoryState.of(Map.of(1, 1), 1), InventoryState.empty());
		history.reset();

		assertFalse(history.observe(InventoryState.of(Map.of(2, 1), 1)).hasBaseline());
	}
}

