public class AttentionHorizonEtaEngineTest
{
	@Test
	public void fixedAndApproximateHorizonsKeepTheirPresentationSemantics()
	{
		AttentionHorizonEtaEngine engine = new AttentionHorizonEtaEngine();
		assertTrue(engine.start("Stymphike hunt", 65, true, false, 100));
		engine.onGameTick(105);
		assertEquals(60, engine.snapshot().getRemainingTicks());
		assertFalse(engine.snapshot().isApproximate());

		assertTrue(engine.start("Daeyalt rock moves", 40, true, true, 200));
		assertTrue(engine.snapshot().isApproximate());
		assertEquals(40, engine.snapshot().getRemainingTicks());
	}

	@Test
	public void invalidEvidenceClearsTheEngine()
	{
		AttentionHorizonEtaEngine engine = new AttentionHorizonEtaEngine();
		engine.start("Stymphike hunt", 65, true, false, 100);
		assertFalse(engine.start("Stymphike hunt", -1, true, false, 101));
		assertFalse(engine.isActive());
	}
}

