 * for the sequence that previously made Cook-all disappear on a burn.
 */
public class IdleFamiliarPluginEtaPipelineTest
{
	@Test
	public void cookingBurnsAndSuccessfulCooksStayInTheSameLiveEtaQueue() throws Exception
	{
		IdleFamiliarPlugin plugin = configuredPlugin(AnimationID.HUMAN_COOKING);
		IdleStateTracker stateTracker = (IdleStateTracker) getField(plugin, "idleStateTracker");

		// First inventory callback establishes the plugin's real event baseline.
		stateTracker.setCurrentTick(100);
		plugin.onItemContainerChanged(inventoryEvent(ItemID.RAW_SHARK, 4));

		// First native cook is only a candidate; the four-tick repeat proves Cook-all.
		plugin.onItemContainerChanged(inventoryEvent(ItemID.RAW_SHARK, 3, ItemID.SHARK, 1));
		Supplier<TaskEtaSnapshot> etaSnapshots = plugin::taskEtaSnapshotForTesting;
		assertFalse(etaSnapshots.get().isActive());

		stateTracker.setCurrentTick(104);
		plugin.onItemContainerChanged(inventoryEvent(ItemID.RAW_SHARK, 2, ItemID.SHARK, 1,
			ItemID.BURNT_SHARK, 1));
		assertTrue(etaSnapshots.get().isActive());
		assertEquals("Cooking", etaSnapshots.get().getProfileLabel());
		assertEquals(2, etaSnapshots.get().getRemainingUnits());

		stateTracker.setCurrentTick(108);
		plugin.onItemContainerChanged(inventoryEvent(ItemID.RAW_SHARK, 1, ItemID.SHARK, 2,
			ItemID.BURNT_SHARK, 1));
		assertTrue(etaSnapshots.get().isActive());
		assertEquals(1, etaSnapshots.get().getRemainingUnits());
	}

