	@Test
	public void aFullFishBarrelNeverRestartsTheKarambwanEta() throws Exception
	{
		// 1193 is the client animation for fishing a Karambwan vessel.
		IdleFamiliarPlugin plugin = configuredPlugin(1193);
		IdleStateTracker stateTracker = (IdleStateTracker) getField(plugin, "idleStateTracker");
		Supplier<TaskEtaSnapshot> etaSnapshots = plugin::taskEtaSnapshotForTesting;

		stateTracker.setCurrentTick(500);
		plugin.onItemContainerChanged(inventoryEvent(ItemID.KARAMBWAN_VESSEL, 1,
			ItemID.RAW_KARAMBWANJI, 80, ItemID.OPEN_FISH_BARREL, 1));
		// The first attempted catch assumes the barrel is empty.
		plugin.onItemContainerChanged(inventoryEvent(ItemID.KARAMBWAN_VESSEL, 1,
			ItemID.RAW_KARAMBWANJI, 79, ItemID.OPEN_FISH_BARREL, 1));
		assertEquals(53, etaSnapshots.get().getInitialUnits());

		stateTracker.setCurrentTick(504);
		// A raw Karambwan entering normal inventory proves the barrel is full.
		plugin.onItemContainerChanged(inventoryEvent(ItemID.KARAMBWAN_VESSEL, 1,
			ItemID.RAW_KARAMBWANJI, 78, ItemID.OPEN_FISH_BARREL, 1,
			ItemID.RAW_KARAMBWAN, 1));
		assertEquals(53, etaSnapshots.get().getInitialUnits());
		assertEquals(24, etaSnapshots.get().getRemainingUnits());

		stateTracker.setCurrentTick(508);
		// A later failed roll must stay in normal-inventory mode; it must not add
		// the barrel's 28 spaces and rebase the timer upward.
		plugin.onItemContainerChanged(inventoryEvent(ItemID.KARAMBWAN_VESSEL, 1,
			ItemID.RAW_KARAMBWANJI, 77, ItemID.OPEN_FISH_BARREL, 1,
			ItemID.RAW_KARAMBWAN, 1));
		assertEquals(53, etaSnapshots.get().getInitialUnits());
		assertEquals(24, etaSnapshots.get().getRemainingUnits());
	}

