	@Test
	public void movingShipCoordinatesDoNotEraseAnExactSortingQueue() throws Exception
	{
		AtomicReference<ItemContainer> liveInventory = new AtomicReference<>(
			inventory(ItemID.SMALL_SALVAGE, 4));
		AtomicReference<WorldPoint> location = new AtomicReference<>(
			new WorldPoint(3200, 3200, 0));
		IdleFamiliarPlugin plugin = new IdleFamiliarPlugin();
		setField(plugin, "client", clientWithStationInventoryAndLocation(
			liveInventory, location));
		setField(plugin, "config", defaultProxy(IdleFamiliarConfig.class));

		plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV,
			liveInventory.get()));
		plugin.onGameTick(new GameTick());
		assertTrue(plugin.taskEtaSnapshotForTesting().isActive());

		// Sailing movement cancels stale activity first. The still-visible exact
		// station pose must reclaim the queue later in the same game tick.
		location.set(new WorldPoint(3201, 3200, 0));
		plugin.onGameTick(new GameTick());

		TaskEtaSnapshot eta = plugin.taskEtaSnapshotForTesting();
		assertTrue(eta.isActive());
		assertEquals(SalvageSortingCatalog.LABEL, eta.getProfileLabel());
		assertEquals(4, eta.getRemainingUnits());
		assertEquals(11, eta.getRemainingTicks());

		liveInventory.set(inventory(ItemID.SMALL_SALVAGE, 3));
		plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV,
			liveInventory.get()));
		assertEquals(3, plugin.taskEtaSnapshotForTesting().getRemainingUnits());
		assertEquals(9, plugin.taskEtaSnapshotForTesting().getRemainingTicks());

		location.set(new WorldPoint(3202, 3200, 0));
		plugin.onGameTick(new GameTick());
		assertEquals(8, plugin.taskEtaSnapshotForTesting().getRemainingTicks());
	}

