		stateTracker.setCurrentTick(100);
		plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, liveInventory.get()));
		AnimationChanged hookStarted = new AnimationChanged();
		hookStarted.setActor(((Client) getField(plugin, "client")).getLocalPlayer());
		plugin.onAnimationChanged(hookStarted);
		assertTrue(etaSnapshots.get().isCalibrating());
		assertEquals(TaskEtaSnapshot.Mode.GATHERING, etaSnapshots.get().getMode());

