		assertEquals(SalvageSortingCatalog.GATHERING_LABEL, etaSnapshots.get().getProfileLabel());
		assertEquals(TaskEtaSnapshot.Confidence.HIGH, etaSnapshots.get().getConfidence());
		assertEquals(25, etaSnapshots.get().getRemainingUnits());
		assertEquals(100, etaSnapshots.get().getRemainingTicks());
	}

