	private static ItemContainer inventory(int... itemQuantityPairs)
	{
		Item[] items = new Item[28];
		for (int index = 0; index < itemQuantityPairs.length; index += 2)
		{
			items[index / 2] = new Item(itemQuantityPairs[index], itemQuantityPairs[index + 1]);
		}
		return (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),
			new Class<?>[]{ItemContainer.class}, (proxy, method, args) ->
				"getItems".equals(method.getName()) ? items : defaultValue(method.getReturnType()));
	}

	private static ItemContainer inventorySlots(int... itemIds)
	{
		Item[] items = new Item[28];
		for (int index = 0; index < itemIds.length; index++)
		{
			items[index] = new Item(itemIds[index], 1);
		}
		return (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),
			new Class<?>[]{ItemContainer.class}, (proxy, method, args) ->
				"getItems".equals(method.getName()) ? items : defaultValue(method.getReturnType()));
	}

