	{
		return new ItemContainerChanged(InventoryID.INV, inventory(itemQuantityPairs));
	}

	private static MenuOptionClicked menuClick(String option, String target, MenuAction action)
	{
		return menuClick(option, target, action, -1);
	}

	private static MenuOptionClicked menuClick(String option, String target, MenuAction action,
		int itemId)
	{
		return menuClick(option, target, action, itemId, 0);
	}

	private static MenuOptionClicked menuClick(String option, String target, MenuAction action,
		int itemId, int identifier)
	{
		MenuEntry entry = (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
			new Class<?>[]{MenuEntry.class}, (proxy, method, args) -> {
				switch (method.getName())
				{
					case "getOption":
						return option;
					case "getTarget":
						return target;
					case "getType":
						return action;
					case "getItemId":
						return itemId;
					case "getIdentifier":
						return identifier;
					default:
						return defaultValue(method.getReturnType());
				}
			});
		return new MenuOptionClicked(entry);
	}

	@SuppressWarnings("unchecked")
	private static <T> T defaultProxy(Class<T> type)
	{
		return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type},
			(proxy, method, args) -> defaultValue(method.getReturnType()));
	}

	private static Object defaultValue(Class<?> type)
	{
		if (!type.isPrimitive())
		{
			return null;
		}
		if (type == boolean.class)
		{
			return false;
		}
		if (type == char.class)
		{
			return '\0';
		}
		if (type == long.class)
		{
			return 0L;
		}
		if (type == float.class)
		{
			return 0f;
		}
		if (type == double.class)
		{
			return 0d;
		}
		return 0;
	}

	private static Object getField(Object target, String name) throws Exception
	{
		Field field = target.getClass().getDeclaredField(name);
		field.setAccessible(true);
		return field.get(target);
	}

	private static void setField(Object target, String name, Object value) throws Exception
	{
		Field field = target.getClass().getDeclaredField(name);
		field.setAccessible(true);
		field.set(target, value);
	}

	private static final class RecordingSoundController extends SoundController
	{
		private int etaCompletionCount;

		@Override
		public void playGameEvent(GameSoundEvent event)
		{
			if (event == GameSoundEvent.ETA_COMPLETE)
			{
				etaCompletionCount++;
			}
		}
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Map;
import net.runelite.api.ItemID;
import net.runelite.api.gameval.AnimationID;
import net.runelite.client.game.FishingSpot;
import org.junit.Test;

public class FishingActivityDetectorTest
{
	private final ExtendedInventoryTracker storage = new ExtendedInventoryTracker();
	private final FishingActivityDetector detector = new FishingActivityDetector(
		ActivityAnimationRegistry.build(), new ActivityEvidenceTracker(), storage);

	@Test
	public void flyFishingReturnsTypedCatchEvidence()
	{
		InventoryState before = InventoryState.of(
			Map.of(ItemID.FLY_FISHING_ROD, 1, ItemID.FEATHER, 30), 2);
		InventoryState after = InventoryState.of(
			Map.of(ItemID.FLY_FISHING_ROD, 1, ItemID.FEATHER, 29, ItemID.RAW_TROUT, 1), 3);

		FishingActivityDetector.Detection detection = detector.detect(
			new InventoryChange(before, after), after, InventoryState.empty(),
			AnimationID.HUMAN_FISH_ONSPOT, 100, 99, 6);

		assertTrue(detection instanceof FishingActivityDetector.ConventionalCatch);
		FishingActivityDetector.ConventionalCatch catchEvidence =
			(FishingActivityDetector.ConventionalCatch) detection;
		assertEquals(FishingCatalog.flyTroutSalmonProfile(), catchEvidence.profile);
		assertTrue(catchEvidence.eligible);
		assertEquals(3, catchEvidence.occupiedSlots);
	}

	@Test
	public void karambwanAttemptUsesAssumedBarrelCapacityUntilCatchProvesFull()
	{
		InventoryState before = InventoryState.of(Map.of(
			ItemID.KARAMBWAN_VESSEL, 1, ItemID.RAW_KARAMBWANJI, 80,
			ItemID.OPEN_FISH_BARREL, 1), 3);
		InventoryState failed = InventoryState.of(Map.of(
			ItemID.KARAMBWAN_VESSEL, 1, ItemID.RAW_KARAMBWANJI, 79,
			ItemID.OPEN_FISH_BARREL, 1), 3);

		FishingActivityDetector.KarambwanAttempt first =
			(FishingActivityDetector.KarambwanAttempt) detector.detect(
				new InventoryChange(before, failed), failed, InventoryState.empty(),
				1193, 100, 99, 6);
		assertNotNull(first);
		assertTrue(first.usesFishBarrel);

		InventoryState caught = InventoryState.of(Map.of(
			ItemID.KARAMBWAN_VESSEL, 1, ItemID.RAW_KARAMBWANJI, 78,
			ItemID.OPEN_FISH_BARREL, 1, ItemID.RAW_KARAMBWAN, 1), 4);
		FishingActivityDetector.KarambwanAttempt second =
			(FishingActivityDetector.KarambwanAttempt) detector.detect(
				new InventoryChange(failed, caught), caught, InventoryState.empty(),
				1193, 104, 99, 6);
		assertFalse(second.usesFishBarrel);
		assertTrue(storage.isKnownFull(ExtendedInventoryTracker.Container.FISH_BARREL));
	}

	@Test
	public void exactCatchWithoutFishingAnimationIsRejected()
	{
		InventoryState before = InventoryState.of(
			Map.of(ItemID.FLY_FISHING_ROD, 1, ItemID.FEATHER, 30), 2);
		InventoryState after = InventoryState.of(
			Map.of(ItemID.FLY_FISHING_ROD, 1, ItemID.FEATHER, 29, ItemID.RAW_TROUT, 1), 3);

		assertNull(detector.detect(new InventoryChange(before, after), after,
			InventoryState.empty(), -1, 100, 99, 6));
	}

	@Test
	public void barrelPrestartRequiresAnUnambiguousSpotAndInputs()
	{
		InventoryState monkfish = InventoryState.of(Map.of(
			ItemID.SMALL_FISHING_NET, 1, ItemID.OPEN_FISH_BARREL, 1), 2);
		FishingActivityDetector.BarrelStart start = detector.detectBarrelStart(
			FishingSpot.MONKFISH, monkfish, InventoryState.empty(),
			AnimationID.HUMAN_FISH_ONSPOT, 99);

		assertNotNull(start);
		assertEquals(FishingCatalog.smallNetMonkfishProfile(), start.profile);
		assertEquals(54, start.ordinaryFreeSlots
			+ ExtendedInventoryTracker.Container.FISH_BARREL.capacity());
		assertTrue(start.eligible);
		FishingActivityDetector.BarrelStart shrimpStart = detector.detectBarrelStart(
			FishingSpot.SHRIMP, monkfish, InventoryState.empty(),
			AnimationID.HUMAN_FISH_ONSPOT, 99);
		assertNotNull(shrimpStart);
		assertEquals(FishingCatalog.smallNetShrimpAnchovyProfile(), shrimpStart.profile);
	}

	@Test
	public void openBarrelPrestartResolvesFlyAndBarbarianFishing()
	{
		InventoryState fly = InventoryState.of(Map.of(
			ItemID.FLY_FISHING_ROD, 1, ItemID.FEATHER, 100,
			ItemID.OPEN_FISH_BARREL, 1), 3);
		FishingActivityDetector.BarrelStart flyStart = detector.detectBarrelStart(
			FishingSpot.SALMON, fly, InventoryState.empty(),
			AnimationID.HUMAN_FISH_ONSPOT, 99);
		assertNotNull(flyStart);
		assertEquals(FishingCatalog.flyTroutSalmonProfile(), flyStart.profile);
		assertEquals(25, flyStart.ordinaryFreeSlots);
		assertTrue(flyStart.eligible);

		InventoryState barbarian = InventoryState.of(Map.of(
			ItemID.BARBARIAN_ROD, 1, ItemID.FEATHER, 100,
			ItemID.OPEN_FISH_BARREL, 1), 3);
		FishingActivityDetector.BarrelStart barbarianStart = detector.detectBarrelStart(
			FishingSpot.BARB_FISH, barbarian, InventoryState.empty(), 9350, 99);
		assertNotNull(barbarianStart);
		assertEquals(FishingCatalog.barbarianRodProfile(), barbarianStart.profile);
		assertTrue(barbarianStart.eligible);
	}

	@Test
	public void ordinarySpotWithTwoPossibleMethodsStaysSilent()
	{
		InventoryState ambiguous = InventoryState.of(Map.of(
			ItemID.FLY_FISHING_ROD, 1, ItemID.FEATHER, 100,
			ItemID.FISHING_ROD, 1, ItemID.FISHING_BAIT, 100,
			ItemID.OPEN_FISH_BARREL, 1), 5);

		assertNull(detector.detectBarrelStart(FishingSpot.SALMON, ambiguous,
			InventoryState.empty(), AnimationID.HUMAN_FISH_ONSPOT, 99));
	}

	@Test
	public void barbarianFishEnteringInventoryProvesBarrelFullWithoutRejectingCatch()
	{
		InventoryState before = InventoryState.of(Map.of(
			ItemID.BARBARIAN_ROD, 1, ItemID.FEATHER, 100,
			ItemID.OPEN_FISH_BARREL, 1), 3);
		FishingActivityDetector.BarrelStart start = detector.detectBarrelStart(
			FishingSpot.BARB_FISH, before, InventoryState.empty(), 9350, 99);
		assertNotNull(start);
		assertFalse(storage.isKnownFull(ExtendedInventoryTracker.Container.FISH_BARREL));

		InventoryState after = InventoryState.of(Map.of(
			ItemID.BARBARIAN_ROD, 1, ItemID.FEATHER, 99,
			ItemID.OPEN_FISH_BARREL, 1, ItemID.LEAPING_TROUT, 1), 4);
		FishingActivityDetector.ConventionalCatch result =
			(FishingActivityDetector.ConventionalCatch) detector.detect(
				new InventoryChange(before, after), after, InventoryState.empty(),
				9350, 100, 99, 6);

		assertNotNull(result);
		assertEquals(FishingCatalog.barbarianRodProfile(), result.profile);
		assertTrue(result.eligible);
		assertTrue(storage.isKnownFull(ExtendedInventoryTracker.Container.FISH_BARREL));
	}

	@Test
	public void anglerfishBarrelPrestartKeepsBaitVariantsDistinct()
	{
		InventoryState sandworms = InventoryState.of(Map.of(
			ItemID.FISHING_ROD, 1, ItemID.SANDWORMS, 100,
			ItemID.OPEN_FISH_BARREL, 1), 3);
		FishingActivityDetector.BarrelStart sandwormStart = detector.detectBarrelStart(
			FishingSpot.ANGLERFISH, sandworms, InventoryState.empty(),
			AnimationID.HUMAN_FISH_ONSPOT, 99);
		assertNotNull(sandwormStart);
		assertEquals(FishingCatalog.rodAnglerfishProfile(false), sandwormStart.profile);

		InventoryState both = InventoryState.of(Map.of(
			ItemID.FISHING_ROD, 1, ItemID.SANDWORMS, 100,
			ItemID.DIABOLIC_WORMS, 100, ItemID.OPEN_FISH_BARREL, 1), 4);
		assertNull(detector.detectBarrelStart(FishingSpot.ANGLERFISH, both,
			InventoryState.empty(), AnimationID.HUMAN_FISH_ONSPOT, 99));
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class SoundActivationTest
{
	@Test
	public void defaultSoundTriggersMatchSimplifiedConfig()
	{
		IdleFamiliarConfig config = new IdleFamiliarConfig()
		{
		};

		assertTrue(SoundActivation.animationStart(config, AvatarState.PLAYER_IDLE));
		assertTrue(SoundActivation.animationStart(config, AvatarState.AFK_WARNING));
		assertFalse(SoundActivation.animationStart(config, AvatarState.SKILLING));
		assertFalse(SoundActivation.animationStart(config, AvatarState.GRAND_EXCHANGE));

		assertTrue(SoundActivation.gameEvent(config, GameSoundEvent.INVENTORY_FULL));
		assertTrue(SoundActivation.gameEvent(config, GameSoundEvent.LOW_HEALTH));
		assertTrue(SoundActivation.gameEvent(config, GameSoundEvent.LOW_PRAYER));
		assertTrue(SoundActivation.gameEvent(config, GameSoundEvent.ETA_COMPLETE));
		assertFalse(SoundActivation.chatMessage(config));
	}

	@Test
	public void triggerTogglesDisableMatchingAnimationAndGameEventSounds()
	{
		IdleFamiliarConfig config = disabledRequestedTriggers();

		assertFalse(SoundActivation.animationStart(config, AvatarState.PLAYER_IDLE));
		assertFalse(SoundActivation.animationStart(config, AvatarState.AFK_WARNING));
		assertFalse(SoundActivation.animationStart(config, AvatarState.SKILLING));
		assertFalse(SoundActivation.animationStart(config, AvatarState.INVENTORY_FULL));
		assertFalse(SoundActivation.animationStart(config, AvatarState.GRAND_EXCHANGE));
		assertFalse(SoundActivation.animationStart(config, AvatarState.LOW_HEALTH));
		assertFalse(SoundActivation.animationStart(config, AvatarState.LOW_PRAYER));
		assertFalse(SoundActivation.animationStart(config, AvatarState.CUSTOM_EVENT));

		assertFalse(SoundActivation.gameEvent(config, GameSoundEvent.INVENTORY_FULL));
		assertFalse(SoundActivation.gameEvent(config, GameSoundEvent.LOW_HEALTH));
		assertFalse(SoundActivation.gameEvent(config, GameSoundEvent.LOW_PRAYER));
		assertFalse(SoundActivation.gameEvent(config, GameSoundEvent.ETA_COMPLETE));
		assertFalse(SoundActivation.chatMessage(config));

		// States with no dedicated toggle (combat / skilling / GE / ...) are
		// opt-in and stay silent, rather than falling through to a default-on cue.
		assertFalse(SoundActivation.animationStart(config, AvatarState.SKILLING));
		assertFalse(SoundActivation.animationStart(config, AvatarState.GRAND_EXCHANGE));
	}

