import java.awt.Point;
import java.awt.image.BufferedImage;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.imageio.ImageIO;
import org.junit.Test;

public class AvatarPackManifestTest
{
	@Test
	public void goldenToadManifestDeclaresStablePackMetadata()
	{
		AvatarPackManifest manifest = AvatarPackManifest.goldenToad();
		assertEquals("golden-toad", manifest.getIdentifier());
		assertEquals("Golden Toad", manifest.getDisplayName());
		assertEquals(64, manifest.getNativeSize());
		assertEquals(128, manifest.getSourceFrameSize());
		assertEquals(1_048_576L, manifest.getMaximumDecodedPixels());
		assertEquals(54, manifest.getBundledSpriteSheets().size());
		assertFalse(manifest.getBundledSpriteSheets().contains("walking_loop.png"));
		assertEquals(AvatarState.DEFAULT, manifest.getFallbackState());
		assertTrue(manifest.getSupportedStates().contains(AvatarState.SKILLING));
	}

	@Test
	public void everyManifestedBundledSheetExistsAndMatchesItsDecodeContract() throws Exception
	{
		AvatarPackManifest manifest = AvatarPackManifest.goldenToad();
		String root = "/com/idlefamiliar/avatar/default/";
		for (String sheetName : manifest.getBundledSpriteSheets())
		{
			try (InputStream stream = AvatarPackManifestTest.class.getResourceAsStream(root + sheetName))
			{
				assertNotNull(sheetName, stream);
				BufferedImage sheet = ImageIO.read(stream);
				assertNotNull(sheetName, sheet);
				assertEquals(sheetName, manifest.getSourceFrameSize(), sheet.getHeight());
				assertEquals(sheetName, 0, sheet.getWidth() % sheet.getHeight());
				assertTrue(sheetName, (long) sheet.getWidth() * sheet.getHeight()
					<= manifest.getMaximumDecodedPixels());
			}
		}
	}

	@Test
	public void everyBundledWeightTargetsAManifestedSheet() throws Exception
	{
		AvatarPackManifest manifest = AvatarPackManifest.goldenToad();
		try (InputStream stream = AvatarPackManifestTest.class.getResourceAsStream(
			"/com/idlefamiliar/avatar/default/weights.json"))
		{
			assertNotNull(stream);
			String weights = new String(stream.readAllBytes(), StandardCharsets.UTF_8);
			Matcher keys = Pattern.compile("\\\"([^\\\"]+)\\\"\\s*:").matcher(weights);
			int count = 0;
			while (keys.find())
			{
				count++;
				assertTrue(keys.group(1),
					manifest.getBundledSpriteSheets().contains(keys.group(1) + ".png"));
			}
			assertTrue("weights.json should declare at least one weighted sheet", count > 0);
		}
	}

	@Test
