package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Map;
import net.runelite.api.ItemID;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

public class WoodcuttingRecognizerTest
{
	private static final int RUNE_CHOP_ANIMATION = 867;

	private ActivityEvidenceTracker evidence;
	private GatheringResourceTracker resources;
	private ExtendedInventoryTracker storage;
	private WoodcuttingRecognizer recognizer;

	@Before
	public void setUp()
	{
		evidence = new ActivityEvidenceTracker();
		resources = new GatheringResourceTracker();
		storage = new ExtendedInventoryTracker();
		recognizer = new WoodcuttingRecognizer(ActivityAnimationRegistry.build(), evidence,
			resources, storage);
	}

	@Test
	public void emitsTypedLogEvidenceWithBestVisibleAxeAndClickHorizon()
	{
		recognizer.onTreeInteraction(MenuAction.GAME_OBJECT_FIRST_OPTION, "chop down",
			"maple tree", 10832, new WorldPoint(3200, 3200, 0), 100,
			state(Map.of(ItemID.BRONZE_AXE, 1), 1),
			state(Map.of(ItemID.RUNE_AXE, 1), 1));

		WoodcuttingRecognizer.LogResult result = recognizer.detectLog(
			change(Map.of(ItemID.BRONZE_AXE, 1), 1,
				Map.of(ItemID.BRONZE_AXE, 1, ItemID.MAPLE_LOGS, 1), 2),
			state(Map.of(ItemID.RUNE_AXE, 1), 1), true,
			RUNE_CHOP_ANIMATION, 81, 104, 4);

		assertEquals(WoodcuttingCatalog.Tree.MAPLE, result.tree());
		assertEquals(WoodcuttingCatalog.AxeTier.RUNE, result.axeTier());
		assertEquals(81, result.effectiveLevel());
		assertEquals(2, result.occupiedSlots());
		assertEquals(1, result.producedSlots());
		assertTrue(result.eligible());
		assertEquals(96, result.despawnRemainingTicks());
	}

	@Test
	public void rejectsAResultWithAnyAdditionalInventoryChange()
	{
		WoodcuttingRecognizer.LogResult result = recognizer.detectLog(
			change(Map.of(ItemID.RUNE_AXE, 1), 1,
				Map.of(ItemID.RUNE_AXE, 1, ItemID.OAK_LOGS, 1,
					995, 1), 3),
			InventoryState.empty(), true, RUNE_CHOP_ANIMATION, 70, 20, 4);

		assertNull(result);
	}

	@Test
	public void graceEvidenceStillRequiresALocalPlayer()
	{
		assertTrue(recognizer.onAnimation(RUNE_CHOP_ANIMATION, 50));
		InventoryChange log = change(Map.of(ItemID.RUNE_AXE, 1), 1,
			Map.of(ItemID.RUNE_AXE, 1, ItemID.YEW_LOGS, 1), 2);

		assertTrue(recognizer.detectLog(log, InventoryState.empty(), true,
			-1, 80, 54, 4) != null);
		assertNull(recognizer.detectLog(log, InventoryState.empty(), false,
			-1, 80, 54, 4));
	}

	@Test
	public void unsupportedEquipmentProducesIneligibleEvidence()
	{
		WoodcuttingRecognizer.LogResult result = recognizer.detectLog(
			change(Map.of(ItemID.RUNE_AXE, 1), 1,
				Map.of(ItemID.RUNE_AXE, 1, ItemID.YEW_LOGS, 1), 2),
			state(Map.of(ItemID.KANDARIN_HEADGEAR_4, 1), 1), true,
			RUNE_CHOP_ANIMATION, 90, 30, 4);

		assertFalse(result.eligible());
	}

	@Test
	public void ordinaryLogInInventoryMarksAnOpenBasketFull()
	{
		InventoryState equipment = state(Map.of(
			ItemID.RUNE_AXE, 1,
			ItemID.OPEN_FORESTRY_BASKET, 1), 2);
		WoodcuttingRecognizer.LogResult result = recognizer.detectLog(
			change(Map.of(), 0, Map.of(ItemID.OAK_LOGS, 1), 1),
			equipment, true, RUNE_CHOP_ANIMATION, 70, 40, 4);

		assertTrue(result != null);
		assertTrue(storage.isKnownFull(ExtendedInventoryTracker.Container.LOG_BASKET));
	}

	@Test
	public void openBasketClickEmitsOneStorageStartAfterAnimation()
	{
		InventoryState inventory = state(Map.of(ItemID.OPEN_LOG_BASKET, 1), 1);
		InventoryState equipment = state(Map.of(ItemID.RUNE_AXE, 1), 1);
		recognizer.onTreeInteraction(MenuAction.GAME_OBJECT_FIRST_OPTION, "chop down",
			"oak tree", 10820, new WorldPoint(3210, 3210, 0), 10,
			inventory, equipment);

		WoodcuttingRecognizer.StorageStart start = recognizer.detectPendingStorageStart(
			inventory, equipment, 70, 12, 20);

		assertEquals(WoodcuttingCatalog.Tree.OAK, start.tree());
		assertEquals(WoodcuttingCatalog.AxeTier.RUNE, start.axeTier());
		assertEquals(1, start.occupiedSlots());
		assertEquals(28, start.extraCapacity());
		assertTrue(start.eligible());
		assertEquals(43, start.despawnRemainingTicks());
		assertNull(recognizer.detectPendingStorageStart(
			inventory, equipment, 70, 13, 20));
	}

	@Test
	public void closedFullExpiredAndResetBasketClicksCannotStart()
	{
		InventoryState openBasket = state(Map.of(ItemID.OPEN_LOG_BASKET, 1), 1);
		InventoryState runeAxe = state(Map.of(ItemID.RUNE_AXE, 1), 1);

		recognizer.onTreeInteraction(MenuAction.GAME_OBJECT_FIRST_OPTION, "chop",
			"willow tree", 10829, null, 10, InventoryState.empty(), runeAxe);
		assertNull(recognizer.detectPendingStorageStart(
			InventoryState.empty(), runeAxe, 70, 11, 20));

		storage.markFull(ExtendedInventoryTracker.Container.LOG_BASKET);
		recognizer.onTreeInteraction(MenuAction.GAME_OBJECT_FIRST_OPTION, "chop",
			"willow tree", 10829, null, 20, openBasket, runeAxe);
		assertNull(recognizer.detectPendingStorageStart(openBasket, runeAxe, 70, 21, 20));

		storage.markEmptyOrUnknown(ExtendedInventoryTracker.Container.LOG_BASKET);
		recognizer.onTreeInteraction(MenuAction.GAME_OBJECT_FIRST_OPTION, "chop",
			"willow tree", 10829, null, 30, openBasket, runeAxe);
		assertNull(recognizer.detectPendingStorageStart(openBasket, runeAxe, 70, 51, 20));

		recognizer.onTreeInteraction(MenuAction.GAME_OBJECT_FIRST_OPTION, "chop",
			"willow tree", 10829, null, 60, openBasket, runeAxe);
		recognizer.reset();
		assertNull(recognizer.detectPendingStorageStart(openBasket, runeAxe, 70, 61, 20));
	}

	@Test
	public void etaLabelRecognitionRemainsCatalogueComplete()
	{
		assertTrue(WoodcuttingRecognizer.isWoodcuttingEtaLabel("Camphor (rune axe)"));
		assertFalse(WoodcuttingRecognizer.isWoodcuttingEtaLabel("Small net (monkfish)"));
	}

	private static InventoryState state(Map<Integer, Integer> counts, int slots)
	{
		return InventoryState.of(counts, slots);
	}

	private static InventoryChange change(Map<Integer, Integer> before, int beforeSlots,
		Map<Integer, Integer> after, int afterSlots)
	{
		return new InventoryChange(state(before, beforeSlots), state(after, afterSlots));
	}
}

