		GatheringResourceTracker.ResourceDespawn despawn = tracker.onGameObjectDespawned(39095, DAEYALT, 105);
		assertTrue(despawn.endedDaeyaltActiveRock());
		assertNull(tracker.consumePendingDaeyalt(105, 12));
