		tracker.onGameObjectDespawned(39094, DAEYALT, 100);
		tracker.onGameObjectSpawned(39095, DAEYALT, 100);

		WorldPoint clickedTile = new WorldPoint(DAEYALT.getX() + 1, DAEYALT.getY() + 2,
			DAEYALT.getPlane());
		assertTrue(tracker.armDaeyalt(clickedTile,
			DaeyaltCatalog.PickaxeTier.DRAGON, 102));

		GatheringResourceTracker.DaeyaltStart start =
			tracker.consumePendingDaeyalt(103, 12);
		assertNotNull(start);
		assertEquals(89, start.earliestMoveRemainingTicks());
	}

	@Test
	public void daeyaltOffsetClickDoesNotGuessBetweenMultipleTrackedRocks()
	{
		GatheringResourceTracker tracker = new GatheringResourceTracker();
		WorldPoint other = new WorldPoint(3610, 3310, 0);
		tracker.onGameObjectDespawned(39094, DAEYALT, 100);
		tracker.onGameObjectSpawned(39095, DAEYALT, 100);
		tracker.onGameObjectDespawned(39094, other, 100);
		tracker.onGameObjectSpawned(39095, other, 100);

		assertFalse(tracker.armDaeyalt(new WorldPoint(3601, 3301, 0),
			DaeyaltCatalog.PickaxeTier.DRAGON, 102));
