		assertTrue(theme.name(), image.getColorModel().hasAlpha());
		assertTrue(theme.name(), hasVisiblePixel(image));
	}

	private static boolean hasVisiblePixel(BufferedImage image)
	{
		for (int y = 0; y < image.getHeight(); y += 4)
