			{
				if ((image.getRGB(x, y) >>> 24) != 0)
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;
import java.util.function.Function;
import org.junit.Test;

public class DisplayPresetControllerTest
{
	@Test
	public void headlessPresetWritesEverySettingAndRefreshesOnce()
	{
		AtomicReference<DisplayPreset> active = new AtomicReference<>(DisplayPreset.CUSTOM);
		Map<String, Object> writes = new LinkedHashMap<>();
		List<DisplayPreset> refreshed = new ArrayList<>();
		DisplayPresetController controller = controller(active, writes, refreshed,
			true, (preset, completion) -> { });

		controller.onConfigChanged("displayPreset", "AFK_SKILLING");

		assertEquals(DisplayPreset.AFK_SKILLING.settings(), writes);
		assertEquals(1, refreshed.size());
		assertEquals(DisplayPreset.AFK_SKILLING, refreshed.get(0));
	}

	@Test
	public void manualControlledChangeSelectsCustomButMatchingPresetWriteDoesNot()
	{
		AtomicReference<DisplayPreset> active = new AtomicReference<>(DisplayPreset.AFK_SKILLING);
		Map<String, Object> writes = new LinkedHashMap<>();
		DisplayPresetController controller = controller(active, writes, new ArrayList<>(),
			true, (preset, completion) -> { });

		controller.onConfigChanged("showTaskEta", "true");
		assertTrue(writes.isEmpty());

		controller.onConfigChanged("showTaskEta", "false");
		assertEquals(DisplayPreset.CUSTOM, writes.get("displayPreset"));
	}

	@Test
	public void cancelledOrReplacedConfirmationCannotApplyAStalePreset()
	{
		AtomicReference<DisplayPreset> active = new AtomicReference<>(DisplayPreset.CUSTOM);
		Map<String, Object> writes = new LinkedHashMap<>();
		List<Consumer<Boolean>> completions = new ArrayList<>();
		DisplayPresetController controller = controller(active, writes, new ArrayList<>(),
			false, (preset, completion) -> completions.add(completion));

		controller.onConfigChanged("displayPreset", "COMBAT_WATCH");
		assertEquals(1, completions.size());
		controller.onConfigChanged("displayPreset", "CUSTOM");
		completions.get(0).accept(true);

		assertFalse(writes.containsKey("showTaskEta"));
		assertFalse(writes.containsKey("enableSounds"));
	}

	@Test
	public void shutdownOfPendingConfirmationPersistsCustom()
	{
		AtomicReference<DisplayPreset> active = new AtomicReference<>(DisplayPreset.CUSTOM);
		Map<String, Object> writes = new LinkedHashMap<>();
		DisplayPresetController controller = controller(active, writes, new ArrayList<>(),
			false, (preset, completion) -> { });

		controller.onConfigChanged("displayPreset", "COMBAT_WATCH");
		controller.cancelPending();

		assertEquals(DisplayPreset.CUSTOM, writes.get("displayPreset"));
	}

	@Test
	public void startupDowngradesAnIncompleteSavedPresetToCustom()
	{
		AtomicReference<DisplayPreset> active = new AtomicReference<>(DisplayPreset.AFK_SKILLING);
		Map<String, Object> writes = new LinkedHashMap<>();
		Map<String, String> persisted = new LinkedHashMap<>();
		DisplayPreset.AFK_SKILLING.settings().forEach((key, value) ->
			persisted.put(key, String.valueOf(value)));
		persisted.put("showTaskEta", "false");
		DisplayPresetController controller = controller(active, writes, new ArrayList<>(),
			true, (preset, completion) -> { }, persisted::get);

		controller.reconcileSavedSelection();

		assertEquals(DisplayPreset.CUSTOM, writes.get("displayPreset"));
	}

	@Test
	public void startupKeepsACompletelyAppliedSavedPreset()
	{
		AtomicReference<DisplayPreset> active = new AtomicReference<>(DisplayPreset.AFK_SKILLING);
		Map<String, Object> writes = new LinkedHashMap<>();
		Map<String, String> persisted = new LinkedHashMap<>();
		DisplayPreset.AFK_SKILLING.settings().forEach((key, value) ->
			persisted.put(key, String.valueOf(value)));
		DisplayPresetController controller = controller(active, writes, new ArrayList<>(),
			true, (preset, completion) -> { }, persisted::get);

		controller.reconcileSavedSelection();

		assertTrue(writes.isEmpty());
	}

	private static DisplayPresetController controller(
		AtomicReference<DisplayPreset> active,
		Map<String, Object> writes,
		List<DisplayPreset> refreshed,
		boolean headless,
		DisplayPresetController.ConfirmationRequester confirmationRequester)
	{
		return controller(active, writes, refreshed, headless,
			confirmationRequester, key -> null);
	}

	private static DisplayPresetController controller(
		AtomicReference<DisplayPreset> active,
		Map<String, Object> writes,
		List<DisplayPreset> refreshed,
		boolean headless,
		DisplayPresetController.ConfirmationRequester confirmationRequester,
		Function<String, String> configurationReader)
	{
		IdleFamiliarConfig config = (IdleFamiliarConfig) Proxy.newProxyInstance(
			IdleFamiliarConfig.class.getClassLoader(),
			new Class<?>[]{IdleFamiliarConfig.class},
			(proxy, method, args) -> "displayPreset".equals(method.getName())
				? active.get() : defaultValue(method.getReturnType()));
		return new DisplayPresetController(config, (key, value) ->
		{
			writes.put(key, value);
			if ("displayPreset".equals(key) && value instanceof DisplayPreset)
			{
				active.set((DisplayPreset) value);
			}
		}, refreshed::add, () -> headless, confirmationRequester,
			configurationReader);
	}

	private static Object defaultValue(Class<?> type)
	{
		if (!type.isPrimitive())
		{
			return null;
		}
		if (type == boolean.class)
		{
			return false;
		}
		if (type == char.class)
		{
			return '\0';
		}
		if (type == long.class)
		{
			return 0L;
		}
		if (type == float.class)
		{
			return 0f;
		}
		if (type == double.class)
		{
			return 0d;
		}
		return 0;
	}
}

