	@Test
	public void learnedFallbackCalibratesOnlyWhenCallerVerifiesProcessingSkill()
	{
		TaskEtaController controller = new TaskEtaController();
		controller.seedInventory(inventory(100, 6));
		controller.setObservedProcessingContext("Magic", true);
		controller.onInventoryChanged(inventory(100, 5, 200, 1), 10);
		assertEquals("Cal 1/3", controller.snapshot().getDisplayText());
		controller.onInventoryChanged(inventory(100, 4, 200, 2), 15);
		assertEquals("Cal 2/3", controller.snapshot().getDisplayText());
		controller.onInventoryChanged(inventory(100, 3, 200, 3), 20);
		assertTrue(controller.snapshot().isActive());
		assertEquals(TaskEtaSnapshot.Confidence.HIGH, controller.snapshot().getConfidence());
	}

	private static final int CHISEL = 1755;
	private static final int UNCUT_SAPPHIRE = 1623;
	private static final int SAPPHIRE = 1607;
	private static final int UNCUT_OPAL = 1625;
	private static final int CRUSHED_GEM = 1633;

	@Test
	public void startsFromAConfirmedGemTransformationAndCountsTwoTicksPerRemainingGem()
	{
		TaskEtaController controller = new TaskEtaController();
		controller.seedInventory(inventory(CHISEL, 1, UNCUT_SAPPHIRE, 5));

		controller.onInventoryChanged(inventory(CHISEL, 1, UNCUT_SAPPHIRE, 4, SAPPHIRE, 1), 100);

		TaskEtaSnapshot snapshot = controller.snapshot();
		assertTrue(snapshot.isActive());
		assertEquals(TaskEtaSnapshot.Mode.PROCESSING, snapshot.getMode());
		assertEquals("Gem cutting", snapshot.getProfileLabel());
		assertEquals(5, snapshot.getInitialUnits());
		assertEquals(4, snapshot.getRemainingUnits());
		assertEquals(8, snapshot.getRemainingTicks());
		assertEquals(0.8d, snapshot.getProgress(), 0.0001d);
		assertEquals("0:05", snapshot.getDisplayText());

		controller.onGameTick(101);
		assertEquals(7, controller.snapshot().getRemainingTicks());

		controller.onInventoryChanged(inventory(CHISEL, 1, UNCUT_SAPPHIRE, 3, SAPPHIRE, 2), 102);
		assertEquals(3, controller.snapshot().getRemainingUnits());
		assertEquals(6, controller.snapshot().getRemainingTicks());
	}

