	@Test
	public void startsAnApproximateWoodcuttingEtaOnlyFromACallerVerifiedLogDelta()
	{
		TaskEtaController controller = new TaskEtaController();

		controller.onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree.MAPLE,
			WoodcuttingCatalog.AxeTier.DRAGON, 99, 1, 1, true, 100);

		TaskEtaSnapshot snapshot = controller.snapshot();
		assertTrue(snapshot.isActive());
		assertEquals(TaskEtaSnapshot.Mode.GATHERING, snapshot.getMode());
		assertEquals("Maple (dragon axe)", snapshot.getProfileLabel());
		assertEquals(28, snapshot.getInitialUnits());
		assertEquals(27, snapshot.getRemainingUnits());
		// The capacity-only estimate is ~2:57, but a maple tree's 100-tick
		// lifetime is the earlier attention horizon.
		assertEquals(100, snapshot.getRemainingTicks());
		assertEquals("~1:00", snapshot.getDisplayText());

		controller.onGameTick(102);
		assertEquals(98, controller.snapshot().getRemainingTicks());

		controller.onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree.MAPLE,
			WoodcuttingCatalog.AxeTier.DRAGON, 99, 2, 1, true, 104);
		assertEquals(28, controller.snapshot().getInitialUnits());
		assertEquals(26, controller.snapshot().getRemainingUnits());
		assertEquals(96, controller.snapshot().getRemainingTicks());
	}

