	@Test
	public void mapleTreeHorizonCorrectlyWinsUntilOnlyEightSlotsRemain()
	{
		// At level 99 with a dragon axe, maples succeed 94/256 per four-tick
		// roll. Ten free slots still take about 109 ticks on average, which is
		// longer than a maple's observed 100-tick active lifetime. Therefore an
		// ETA should remain the tree-end countdown at both 5 and 17 occupied
		// inventory slots; it is not an ignored inventory update.
		TaskEtaController fiveOccupied = new TaskEtaController();
		fiveOccupied.onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree.MAPLE,
			WoodcuttingCatalog.AxeTier.DRAGON, 99, 6, 1, true, 100, 10);
		assertEquals(100, fiveOccupied.snapshot().getRemainingTicks());

		TaskEtaController seventeenOccupied = new TaskEtaController();
		seventeenOccupied.onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree.MAPLE,
			WoodcuttingCatalog.AxeTier.DRAGON, 99, 18, 1, true, 100, 10);
		assertEquals(100, seventeenOccupied.snapshot().getRemainingTicks());

		TaskEtaController nineteenOccupied = new TaskEtaController();
		nineteenOccupied.onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree.MAPLE,
			WoodcuttingCatalog.AxeTier.DRAGON, 99, 20, 1, true, 100, 10);
		assertEquals(88, nineteenOccupied.snapshot().getRemainingTicks());
	}

	@Test
	public void unclassifiedInventoryRefreshDoesNotFlickerAwayVerifiedGathering()
	{
		TaskEtaController controller = new TaskEtaController();
		controller.seedInventory(inventory(1517, 1));
		controller.onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree.MAPLE,
			WoodcuttingCatalog.AxeTier.DRAGON, 99, 1, 1, true, 100);
		assertTrue(controller.snapshot().isActive());

		// RuneLite can publish an inventory refresh at the one-tick animation
		// reset where the integration cannot prove a new log delta. The caller's
		// explicit stop/despawn path owns invalidation, not this raw refresh.
		controller.onInventoryChanged(inventory(1517, 1), 101);
		assertTrue(controller.snapshot().isActive());

		// The next caller-verified log re-synchronises the current free capacity;
		// it need not be exactly one slot lower than the last verified snapshot.
		controller.onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree.MAPLE,
			WoodcuttingCatalog.AxeTier.DRAGON, 99, 3, 1, true, 98, 104);
		assertTrue(controller.snapshot().isActive());
		assertEquals(25, controller.snapshot().getRemainingUnits());
	}

	@Test
	public void logBasketCapacityCorrectsDownwardWithoutStartingANewRun()
	{
		TaskEtaController controller = new TaskEtaController();
		// An open log basket is assumed empty at the chop animation. Two ordinary
		// slots are occupied, so the ETA begins with 26 + 28 available log slots.
		controller.onVerifiedWoodcuttingStorageStart(WoodcuttingCatalog.Tree.MAPLE,
			WoodcuttingCatalog.AxeTier.DRAGON, 99, 2, 28, true, 100, 10);

		assertTrue(controller.snapshot().isActive());
		assertEquals(54, controller.snapshot().getInitialUnits());
		assertEquals(54, controller.snapshot().getRemainingUnits());

		// A regular inventory log proves that the basket cannot accept further
		// logs. Reconcile to ordinary capacity only, but retain the original run
		// rather than creating a fresh 25-slot ETA.
		controller.onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree.MAPLE,
			WoodcuttingCatalog.AxeTier.DRAGON, 99, 3, 1, true, 96, 14);
		assertTrue(controller.snapshot().isActive());
		assertEquals(54, controller.snapshot().getInitialUnits());
		assertEquals(25, controller.snapshot().getRemainingUnits());

		controller.onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree.MAPLE,
			WoodcuttingCatalog.AxeTier.DRAGON, 99, 4, 1, true, 92, 18);
		assertEquals(54, controller.snapshot().getInitialUnits());
		assertEquals(24, controller.snapshot().getRemainingUnits());
	}

