	@Test
	public void karambwanFailureStartsAndRefreshesTheSameVerifiedProfile()
	{
		TaskEtaController controller = new TaskEtaController();
		controller.onVerifiedKarambwanAttempt(99, 1, 80, false, true, 20);
		assertTrue(controller.snapshot().isActive());
		assertEquals(27, controller.snapshot().getInitialUnits());
		assertEquals(27, controller.snapshot().getRemainingUnits());
		assertEquals(172, controller.snapshot().getRemainingTicks());

		// The next verified failed attempt consumes another bait but does not use
		// an inventory slot, so the current capacity remains unchanged.
		controller.onVerifiedKarambwanAttempt(99, 1, 79, false, true, 24);
		assertTrue(controller.snapshot().isActive());
		// A failed roll conditions on no new fish, so the expected time from this
		// point to fill the same capacity remains unchanged; only the bait
		// horizon advances.
		assertEquals(172, controller.snapshot().getRemainingTicks());
	}

