	@Test
	public void fullFishBarrelReconcilesToOrdinaryCapacityWithoutAnUpwardReset()
	{
		TaskEtaController controller = new TaskEtaController();
		controller.onVerifiedKarambwanBarrelAttempt(99, 25, 100, 1d, true, 20);
		assertEquals(53, controller.snapshot().getInitialUnits());

		// The first raw Karambwan in normal inventory proves the barrel is full.
		// Its normal-capacity confirmation keeps the original run's initial
		// baseline, so a later bait-only attempt cannot make the ETA jump upward.
		controller.onVerifiedKarambwanAttempt(99, 4, 99, true, true, 24);
		assertTrue(controller.snapshot().isActive());
		assertEquals(53, controller.snapshot().getInitialUnits());
		assertEquals(24, controller.snapshot().getRemainingUnits());

		controller.onVerifiedKarambwanAttempt(99, 4, 98, false, true, 28);
		assertTrue(controller.snapshot().isActive());
		assertEquals(53, controller.snapshot().getInitialUnits());
		assertEquals(24, controller.snapshot().getRemainingUnits());
	}

	@Test
	public void conventionalFishingStartsOnlyFromACallerVerifiedNonStackableCatch()
	{
		TaskEtaController controller = new TaskEtaController();
		GatheringProfile lobster = FishingCatalog.cageLobsterProfile();

		// Post-catch state: one raw lobster was added to a two-occupied-slot
		// inventory. The controller only owns the source-pinned ETA after the
		// integration verified the spot, animation, cage and exact delta.
		controller.onVerifiedConventionalFishingCatch(lobster, 99, 2, 1, true, 100);

		TaskEtaSnapshot snapshot = controller.snapshot();
		assertTrue(snapshot.isActive());
		assertEquals(TaskEtaSnapshot.Mode.GATHERING, snapshot.getMode());
		assertEquals("Cage (lobster)", snapshot.getProfileLabel());
		assertEquals(27, snapshot.getInitialUnits());
		assertEquals(26, snapshot.getRemainingUnits());
		assertEquals((int) Math.ceil(lobster.expectedTicksToFill(26, 99)), snapshot.getRemainingTicks());

		controller.onGameTick(105);
		assertEquals((int) Math.ceil(lobster.expectedTicksToFill(26, 99)) - 5,
			controller.snapshot().getRemainingTicks());

		controller.onVerifiedConventionalFishingCatch(lobster, 99, 3, 1, true, 105);
		assertEquals(25, controller.snapshot().getRemainingUnits());
		assertEquals((int) Math.ceil(lobster.expectedTicksToFill(25, 99)),
			controller.snapshot().getRemainingTicks());
	}

