	@Test
	public void suppressesIneligibleOrAmbiguousWoodcuttingContexts()
	{
		TaskEtaController controller = new TaskEtaController();
		controller.onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree.OAK,
			WoodcuttingCatalog.AxeTier.DRAGON, 99, 1, 1, false, 10);
		assertFalse(controller.snapshot().isActive());

		controller.onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree.OAK,
			WoodcuttingCatalog.AxeTier.DRAGON, 99, 1, 1, true, 20);
		assertTrue(controller.snapshot().isActive());

		// A second claimed log without consuming a new inventory slot is not a
		// valid non-stackable log delta, so the estimate must not survive it.
		controller.onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree.OAK,
			WoodcuttingCatalog.AxeTier.DRAGON, 99, 1, 1, true, 24);
		assertFalse(controller.snapshot().isActive());

		// Filling the final slot is a resolved capacity event, not a stale ~0:00.
		controller.onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree.OAK,
