	@Test
	public void everyEtaEngineFamilyAtomicallyOwnsEveryPairwiseTransition()
	{
		for (EtaFamily source : EtaFamily.values())
		{
			for (EtaFamily target : EtaFamily.values())
			{
				String transition = source + " -> " + target;
				TaskEtaController controller = new TaskEtaController();
				source.activate(controller, 100);
				assertOwned(transition + " source", source, controller);

				target.activate(controller, 120);
				assertOwned(transition + " target", target, controller);
				controller.onGameTick(121);
				assertOwned(transition + " advanced", target, controller);

				// Deterministic and fixed queues cancel themselves when their
				// confirmation cadence is lost. A formerly active engine must not
				// reappear on the following tick. Gathering and attention horizons
				// intentionally remain published at zero pending external proof.
				controller.onGameTick(1000);
				controller.onGameTick(1001);
				if (target.selfCancelsWithoutEvidence)
				{
					assertFalse(transition + " resurrected a former owner",
						controller.snapshot().isActive());
				}
				else
				{
					assertOwned(transition + " zero horizon", target, controller);
					assertEquals(0, controller.snapshot().getRemainingTicks());
				}
			}
		}
	}

	private static void assertOwned(String message, EtaFamily expected,
		TaskEtaController controller)
	{
		assertTrue(message, controller.snapshot().isActive());
		assertEquals(message, expected.label, controller.snapshot().getProfileLabel());
	}

	private enum EtaFamily
	{
		DETERMINISTIC_PROCESSING("Gem cutting", true)
		{
			@Override
			void activate(TaskEtaController controller, int tick)
			{
				controller.seedInventory(inventory(CHISEL, 1, UNCUT_SAPPHIRE, 6));
				controller.onInventoryChanged(
					inventory(CHISEL, 1, UNCUT_SAPPHIRE, 5, SAPPHIRE, 1), tick);
			}
		},
		FIXED_PROCESSING("Matrix fixed queue", true)
		{
			@Override
			void activate(TaskEtaController controller, int tick)
			{
				controller.onVerifiedFixedProcessingQueue("Matrix fixed queue", 20, 4, true, tick);
			}
		},
		GATHERING("Maple (dragon axe)", false)
		{
			@Override
			void activate(TaskEtaController controller, int tick)
			{
				int occupiedSlots = tick <= 100 ? 1 : 2;
				controller.onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree.MAPLE,
					WoodcuttingCatalog.AxeTier.DRAGON, 99, occupiedSlots, 1, true, 200, tick);
			}
		},
		ATTENTION_HORIZON("Matrix attention horizon", false)
		{
			@Override
			void activate(TaskEtaController controller, int tick)
			{
				controller.onVerifiedFixedAttentionHorizon(
					"Matrix attention horizon", 200, true, tick);
			}
		};

		private final String label;
		private final boolean selfCancelsWithoutEvidence;

		EtaFamily(String label, boolean selfCancelsWithoutEvidence)
		{
			this.label = label;
			this.selfCancelsWithoutEvidence = selfCancelsWithoutEvidence;
		}

		abstract void activate(TaskEtaController controller, int tick);
	}

	private static Map<Integer, Integer> inventory(int... idQuantityPairs)
	{
		Map<Integer, Integer> inventory = new HashMap<>();
		for (int index = 0; index < idQuantityPairs.length; index += 2)
		{
			inventory.put(idQuantityPairs[index], idQuantityPairs[index + 1]);
		}
		return inventory;
	}
}

