		for (GameSoundEvent event : GameSoundEvent.values())
		{
			assertNotNull("Missing mapping for " + event, controller.soundForGameEvent(event));
		}
		assertEquals(SoundEffect.COIN_CHIME,
			controller.soundForGameEvent(GameSoundEvent.ETA_COMPLETE));
	}

	@Test
	public void onlyConfiguredAnimationStartsUseBundledSounds()
	{
