		controller.setEnabled(false);
		controller.setVolumePercent(70);

		controller.applyConfigurationChange("enableSounds", "true");
		assertTrue(controller.isEnabledForTesting());
		assertEquals(70, controller.volumePercentForTesting());

		controller.applyConfigurationChange("soundVolumePercent", "35");
		assertTrue(controller.isEnabledForTesting());
		assertEquals(35, controller.volumePercentForTesting());

		controller.applyConfigurationChange("showTaskEta", "false");
		assertTrue(controller.isEnabledForTesting());
