package com.idlefamiliar;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.lang.reflect.Proxy;
import net.runelite.api.Player;
import org.junit.Test;

public class GatheringEtaLifecycleTest
{
	@Test
	public void fishingUsesItsSixTickResultGraceThenCancels()
	{
		TaskEtaController controller = new TaskEtaController();
		controller.onVerifiedConventionalFishingCatch(FishingCatalog.smallNetMonkfishProfile(),
			99, 2, 1, true, 100);
		ActivityEvidenceTracker evidence = new ActivityEvidenceTracker();
		evidence.mark(ActivityEvidenceTracker.Signal.FISHING, 100);
		GatheringEtaLifecycle lifecycle = new GatheringEtaLifecycle();

		lifecycle.cancelIfStale(controller, EtaActivity.FISHING, player(-1), 106, false,
			ActivityAnimationRegistry.build(), evidence, 4, 6);
		assertTrue(controller.snapshot().isActive());

		lifecycle.cancelIfStale(controller, EtaActivity.FISHING, player(-1), 107, false,
			ActivityAnimationRegistry.build(), evidence, 4, 6);
		assertFalse(controller.snapshot().isActive());
	}

	@Test
	public void stymphikeFixedHorizonSurvivesIntermediateAnimationGap()
	{
		TaskEtaController controller = new TaskEtaController();
		controller.onVerifiedFixedAttentionHorizon(StymphikeCatalog.LABEL,
			StymphikeCatalog.WAIT_TICKS, true, 100);
		ActivityEvidenceTracker evidence = new ActivityEvidenceTracker();
		evidence.mark(ActivityEvidenceTracker.Signal.STYMPHIKE, 100);
		GatheringEtaLifecycle lifecycle = new GatheringEtaLifecycle();

		// Live Hunter progress can temporarily reset the waiting animation well
		// beyond ordinary animation grace. Exact entry already proved this fixed
		// autonomous wait, so that gap must not erase the horizon.
		lifecycle.cancelIfStale(controller, EtaActivity.STYMPHIKE, player(-1), 110,
			false, ActivityAnimationRegistry.build(), evidence, 4, 6);

		assertTrue(controller.snapshot().isActive());
	}

	@Test
	public void stymphikeMovementAwayStillCancelsTheFixedHorizon()
	{
		TaskEtaController controller = new TaskEtaController();
		controller.onVerifiedFixedAttentionHorizon(StymphikeCatalog.LABEL,
			StymphikeCatalog.WAIT_TICKS, true, 100);
		GatheringEtaLifecycle lifecycle = new GatheringEtaLifecycle();

		lifecycle.cancelIfStale(controller, EtaActivity.STYMPHIKE, player(-1), 110,
			true, ActivityAnimationRegistry.build(), new ActivityEvidenceTracker(), 4, 6);

		assertFalse(controller.snapshot().isActive());
	}

	private static Player player(int animation)
	{
		return (Player) Proxy.newProxyInstance(Player.class.getClassLoader(),
			new Class<?>[]{Player.class}, (proxy, method, args) ->
				"getAnimation".equals(method.getName()) ? animation
					: defaultValue(method.getReturnType()));
	}

	private static Object defaultValue(Class<?> type)
	{
		if (!type.isPrimitive())
		{
			return null;
		}
		if (type == boolean.class)
		{
			return false;
		}
		if (type == char.class)
		{
			return '\0';
		}
		if (type == long.class)
		{
			return 0L;
		}
		if (type == float.class)
		{
			return 0f;
		}
		if (type == double.class)
		{
			return 0d;
		}
		return 0;
	}
}

package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
