public class SkillProgressTrackerTest
{
	@Test
	public void loginBaselineIsSilentAndLaterIncreasesAreReported()
	{
		SkillProgressTracker tracker = new SkillProgressTracker(null, null);

		SkillProgressTracker.SkillChange baseline =
			tracker.record(Skill.FISHING, 1_000, 50, 0L);
		SkillProgressTracker.SkillChange gain =
			tracker.record(Skill.FISHING, 1_100, 51, 1_000L);

		assertFalse(baseline.activeXpGain());
		assertFalse(baseline.levelUp());
		assertTrue(gain.activeXpGain());
		assertTrue(gain.levelUp());
	}

	@Test
	public void fallbackRateAndVisibilityRemainSessionScoped()
	{
		SkillProgressTracker tracker = new SkillProgressTracker(null, null);
		tracker.record(Skill.FISHING, 1_000, 50, 0L);
		tracker.record(Skill.FISHING, 1_100, 50, 1_000L);
		tracker.record(Skill.FISHING, 1_200, 50, 7_000L);

		tracker.updatePublishedValues("Fishing", true, 0, 7_000L);
		assertEquals("120k/hr", tracker.cachedXpHr());

		tracker.updatePublishedValues("Fishing", false, 0, 8_000L);
		assertNull(tracker.cachedXpHr());
		tracker.reset();
		assertFalse(tracker.record(Skill.FISHING, 1_300, 51, 9_000L).activeXpGain());
	}

	@Test
	public void combatClassificationAndStylesStayCentralized()
	{
		assertTrue(SkillProgressTracker.isLikelyCombatStat(Skill.HITPOINTS));
		assertEquals("melee", SkillProgressTracker.combatStyle(Skill.STRENGTH));
		assertEquals("ranged", SkillProgressTracker.combatStyle(Skill.RANGED));
		assertEquals("magic", SkillProgressTracker.combatStyle(Skill.MAGIC));
		assertNull(SkillProgressTracker.combatStyle(Skill.HITPOINTS));
		assertFalse(SkillProgressTracker.isLikelyCombatStat(Skill.FISHING));
	}
