		assertEquals("Farming",
			registry.activityForAnimation(AnimationID.HUMAN_FARMING));
	}

	@Test
	public void mapsAllFishingMethodsToFishing()
	{
		// Rod casting, harpoon, small-net, and bare-handed fishing all resolve to a
		// single Fishing label.
		assertEquals("Fishing",
			registry.activityForAnimation(AnimationID.HUMAN_FISHING_CASTING));
		assertEquals("Fishing",
			registry.activityForAnimation(AnimationID.HUMAN_HARPOON));
		assertEquals("Fishing",
