package com.idlefamiliar;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.Random;
import javax.imageio.ImageIO;
import org.junit.Test;

/** Verifies latched one-shots with synthetic drop-in sprite sheets. */
public class AnimationControllerOneShotTest
{
	private File externalDirWithTeleportSheet() throws IOException
	{
		return externalDirWithSheets("teleporting.png");
	}

	private File externalDirWithSheets(String... fileNames) throws IOException
	{
		File dir = Files.createTempDirectory("if-oneshot").toFile();
		dir.deleteOnExit();
		BufferedImage sheet = new BufferedImage(256, 64, BufferedImage.TYPE_INT_ARGB);
		for (String fileName : fileNames)
		{
			ImageIO.write(sheet, "png", new File(dir, fileName));
		}
		return dir;
	}

	@Test
	public void oneShotPlaysFullCycleEvenAfterStateChanges() throws IOException
	{
		AnimationController controller = new AnimationController(new Random(1));
		controller.setExternalAssetDir(externalDirWithTeleportSheet());
		controller.loadDefaultAnimations();
		controller.setPlayFullCycleOneShots(true);

		long t = 1_000_000L;

		// Entering TELEPORTING arms the one-shot latch.
		assertNotNull(controller.getFrameAt(AvatarState.TELEPORTING, "", t));
		assertEquals("teleporting", controller.activeOneShotKey());

		// The state immediately drops back to idle, but the one-shot keeps playing
		// (a 4-frame sheet runs ~1.5s, so 100ms in it is still mid-cycle).
		controller.getFrameAt(AvatarState.PLAYER_IDLE, "", t + 100);
		assertEquals("teleporting", controller.activeOneShotKey());

		// Well past the cycle length, the latch releases and idle resumes.
		controller.getFrameAt(AvatarState.PLAYER_IDLE, "", t + 100_000);
		assertNull(controller.activeOneShotKey());
	}

	@Test
	public void oneShotDisabledNeverLatches() throws IOException
	{
		AnimationController controller = new AnimationController(new Random(1));
		controller.setExternalAssetDir(externalDirWithTeleportSheet());
		controller.loadDefaultAnimations();
		controller.setPlayFullCycleOneShots(false);

		controller.getFrameAt(AvatarState.TELEPORTING, "", 2_000_000L);
		assertNull(controller.activeOneShotKey());
	}

	@Test
	public void nonOneShotStatesNeverLatch() throws IOException
	{
		AnimationController controller = new AnimationController(new Random(1));
		controller.setExternalAssetDir(externalDirWithTeleportSheet());
		controller.loadDefaultAnimations();
		controller.setPlayFullCycleOneShots(true);

		controller.getFrameAt(AvatarState.PLAYER_IDLE, "", 3_000_000L);
		assertNull(controller.activeOneShotKey());
		controller.getFrameAt(AvatarState.SKILLING, "Fishing", 3_000_100L);
		assertNull(controller.activeOneShotKey());
	}

	@Test
	public void agilityObstacleLatchesAsAOneShot() throws IOException
	{
		AnimationController controller = new AnimationController(new Random(1));
		controller.setExternalAssetDir(externalDirWithSheets("agility_loop.png"));
		controller.loadDefaultAnimations();
		controller.setPlayFullCycleOneShots(true);

		long t = 1_000_000L;

		// Agility is XP-detected and surfaces as SKILLING "Agility" -> asset key
		// agility_loop, a one-shot. It must latch so the obstacle plays its full cycle
		// even though the player is already walking again before it would end.
		assertNotNull(controller.getFrameAt(AvatarState.SKILLING, "Agility", t));
		assertEquals("agility_loop", controller.activeOneShotKey());

		controller.getFrameAt(AvatarState.WALKING, "", t + 100);
		assertEquals("agility_loop", controller.activeOneShotKey());

		controller.getFrameAt(AvatarState.WALKING, "", t + 100_000);
		assertNull(controller.activeOneShotKey());
	}

	@Test
	public void hunterEntryLatchesAsAOneShot() throws IOException
	{
		AnimationController controller = new AnimationController(new Random(1));
		controller.setExternalAssetDir(externalDirWithSheets("hunter_loop.png"));
		controller.loadDefaultAnimations();
		controller.setPlayFullCycleOneShots(true);

		long t = 4_000_000L;
		assertNotNull(controller.getFrameAt(AvatarState.SKILLING, "Hunter", t));
		assertEquals("hunter_loop", controller.activeOneShotKey());

		// The Stymphike entry animation can end before the familiar sheet. The
		// avatar must finish the selected cycle instead of snapping back to idle.
		controller.getFrameAt(AvatarState.PLAYER_IDLE, "", t + 100);
		assertEquals("hunter_loop", controller.activeOneShotKey());

		controller.getFrameAt(AvatarState.PLAYER_IDLE, "", t + 100_000);
		assertNull(controller.activeOneShotKey());
	}

	@Test
	public void grandExchangeAndLevelUpLatchAsOneShots() throws IOException
	{
		AnimationController controller = new AnimationController(new Random(1));
		controller.setExternalAssetDir(externalDirWithSheets("grand_exchange.png", "level_up.png"));
		controller.loadDefaultAnimations();
		controller.setPlayFullCycleOneShots(true);

		// A filled GE offer latches its one-shot.
		assertNotNull(controller.getFrameAt(AvatarState.GRAND_EXCHANGE, "", 5_000_000L));
		assertEquals("grand_exchange", controller.activeOneShotKey());

		// Let it finish, then a real level-up latches its own one-shot.
		controller.getFrameAt(AvatarState.PLAYER_IDLE, "", 5_100_000L);
		assertNull(controller.activeOneShotKey());
		assertNotNull(controller.getFrameAt(AvatarState.LEVEL_UP, "", 5_200_000L));
		assertEquals("level_up", controller.activeOneShotKey());
	}
}

package com.idlefamiliar;

import net.runelite.api.ItemID;
import net.runelite.api.MenuAction;
import net.runelite.api.gameval.AnimationID;

/** Emits processing evidence without owning ETA lifecycle. */
final class ProcessingActivityDetector
{
	private final ActivityAnimationRegistry animationRegistry;
	private final ActivityEvidenceTracker evidence;

	ProcessingActivityDetector(ActivityAnimationRegistry animationRegistry,
		ActivityEvidenceTracker evidence)
	{
		this.animationRegistry = animationRegistry;
		this.evidence = evidence;
	}

	ProcessingContext contextForMenu(int itemId, int selectedWidgetItemId,
		MenuAction action, String normalizedOption, String normalizedTarget,
		InventoryState equipment)
	{
		if (itemId == ItemID.FLETCHING_KNIFE || selectedWidgetItemId == ItemID.FLETCHING_KNIFE)
		{
			return ProcessingContext.fletchingKnife();
		}
		if (isForestersCampfireAction(normalizedOption, normalizedTarget))
		{
			return ProcessingContext.forestersCampfire();
		}
		int selectedItem = selectedWidgetItemId >= 0 ? selectedWidgetItemId : itemId;
		if (isUseOnCampfire(normalizedOption, normalizedTarget))
		{
			if (ProcessingCatalog.isReviewedCampfireLog(selectedItem))
			{
				return ProcessingContext.forestersCampfire();
			}
			if (ProcessingCatalog.isReviewedRawFood(selectedItem))
			{
				return ProcessingContext.cooking();
			}
		}
		if (action == MenuAction.WIDGET_TARGET_ON_WIDGET
			&& hasNoKnownPotionSavingEffect(equipment))
		{
			return ProcessingContext.finishedPotionWithoutSavingEffect();
		}
		return ProcessingContext.none();
	}

	Result detect(InventoryChange change, InventoryState equipment,
		int animationId, int tick, int graceTicks)
	{
		if (change == null || !change.hasBaseline())
		{
			return null;
		}

		boolean smithingRecent = isSmithingAnimation(animationId)
			|| evidence.isRecent(ActivityEvidenceTracker.Signal.SMITHING, tick, graceTicks);
		if (smithingRecent)
		{
			Result result = detectAnvilSmithing(change, equipment, tick);
			if (result != null)
			{
				return result;
			}
		}

		boolean furnaceRecent = isFurnaceAnimation(animationId)
			|| evidence.isRecent(ActivityEvidenceTracker.Signal.FURNACE, tick, graceTicks);
		return furnaceRecent ? detectFurnaceSmelting(change, tick) : null;
	}

	String observedProcessingSkill(String animationLabel, String confirmedSkill)
	{
		String label = animationLabel == null || animationLabel.isEmpty()
			? confirmedSkill : animationLabel;
		if ("Crafting".equals(label) || "Fletching".equals(label)
			|| "Herblore".equals(label) || "Cooking".equals(label)
			|| "Smithing".equals(label) || "Magic".equals(label))
		{
			return label;
		}
		return null;
	}

	boolean isSmithingAnimation(int animationId)
	{
		return "Smithing".equals(
			animationRegistry.activityForAnimation(animationId));
	}

	static boolean isFurnaceAnimation(int animationId)
	{
		return animationId == AnimationID.HUMAN_FURNACE
			|| animationId == AnimationID.HUMAN_FURNACE_NOSTALL;
	}

	private Result detectAnvilSmithing(InventoryChange change,
		InventoryState equipment, int tick)
	{
		boolean fullUniform = hasFullSmithsUniform(equipment);
		ProcessingContext context = ProcessingContext.anvilSmithing(
			equipment.containsAny(ItemID.IMCANDO_HAMMER_OFFHAND), fullUniform);
		ProcessingProfile profile = ProcessingCatalog.matchAnvilCandidate(
			change.delta(), change.after().itemCounts(), context);
		if (profile == null)
		{
			return null;
		}

		evidence.mark(ActivityEvidenceTracker.Signal.SMITHING, tick);
		if (hasAnySmithsUniformPiece(equipment) && !fullUniform)
		{
			return new Result(ProcessingContext.none());
		}
		return new Result(profile.matches(change.delta(), change.after().itemCounts(), context)
			? context : ProcessingContext.none());
	}

	private Result detectFurnaceSmelting(InventoryChange change, int tick)
	{
		if (ProcessingCatalog.matchFurnaceCandidate(
			change.delta(), change.after().itemCounts()) == null)
		{
			return null;
		}
		evidence.mark(ActivityEvidenceTracker.Signal.FURNACE, tick);
		return new Result(ProcessingContext.furnaceSmelting());
	}

	private static boolean isForestersCampfireAction(String option, String target)
	{
		// The live object exposes "Tend-to"; older/menu-entry variants used
		// "Add-logs". The target name has also appeared as both "Campfire" and
		// "Forester's Campfire", so the action is the discriminating evidence.
		boolean startsQueue = "tend-to".equals(option) || "tend to".equals(option)
			|| "add-logs".equals(option) || "add logs".equals(option);
		return startsQueue && target != null && target.contains("campfire");
	}

	private static boolean isUseOnCampfire(String option, String target)
	{
		return ("use".equals(option) || "cook".equals(option))
			&& target != null && target.contains("campfire");
	}

	private static boolean hasNoKnownPotionSavingEffect(InventoryState equipment)
	{
		return !equipment.containsAny(ItemID.AMULET_OF_CHEMISTRY,
			ItemID.PRESCRIPTION_GOGGLES, ItemID.PRESCRIPTION_GOGGLES_29976);
	}

	private static boolean hasFullSmithsUniform(InventoryState equipment)
	{
		return equipment.containsAny(ItemID.SMITHS_TUNIC)
			&& equipment.containsAny(ItemID.SMITHS_TROUSERS)
			&& equipment.containsAny(ItemID.SMITHS_BOOTS)
			&& equipment.containsAny(ItemID.SMITHS_GLOVES, ItemID.SMITHS_GLOVES_I);
	}

	private static boolean hasAnySmithsUniformPiece(InventoryState equipment)
	{
		return equipment.containsAny(ItemID.SMITHS_TUNIC, ItemID.SMITHS_TROUSERS,
			ItemID.SMITHS_BOOTS, ItemID.SMITHS_GLOVES, ItemID.SMITHS_GLOVES_I);
	}

	static final class Result
	{
		private final ProcessingContext context;

		private Result(ProcessingContext context)
		{
			this.context = context == null ? ProcessingContext.none() : context;
		}

		ProcessingContext context()
		{
			return context;
		}
	}
}

package com.idlefamiliar;

import net.runelite.api.Player;

/**
 * Owns the per-tick continuation and cancellation rules for gathering ETAs.
 * Recognition remains with the activity-specific integrations; once a run is
 * active, this component applies one consistent bounded-animation policy.
 */
final class GatheringEtaLifecycle
{
	void cancelIfStale(TaskEtaController controller, EtaActivity activity, Player localPlayer, int tick,
		boolean movedThisTick, ActivityAnimationRegistry registry,
		ActivityEvidenceTracker evidence, int normalGraceTicks, int fishingGraceTicks)
	{
		TaskEtaSnapshot eta = controller.snapshot();
		if (!eta.isActive() || eta.getMode() != TaskEtaSnapshot.Mode.GATHERING)
		{
			return;
		}

		int animation = localPlayer == null ? -1 : localPlayer.getAnimation();
		if (activity == EtaActivity.SALVAGE_GATHERING)
		{
			continueOrCancel(controller, SalvageSortingCatalog.isHookAnimation(animation), tick,
				evidence, ActivityEvidenceTracker.Signal.SALVAGE_GATHERING, normalGraceTicks);
			return;
		}
		if (activity == EtaActivity.FISHING)
		{
			continueOrCancel(controller, isActivity(registry, animation, "Fishing"), tick,
				evidence, ActivityEvidenceTracker.Signal.FISHING, fishingGraceTicks);
			return;
		}
		if (activity == EtaActivity.DAEYALT)
		{
			continueOrCancel(controller, isActivity(registry, animation, "Mining"), tick,
				evidence, ActivityEvidenceTracker.Signal.MINING, normalGraceTicks);
			return;
		}
		if (activity == EtaActivity.STYMPHIKE)
		{
			boolean waitingAnimation = StymphikeCatalog.isWaitingAnimation(animation);
			// Exact bush entry starts one bounded autonomous wait. Intermediate
			// Hunter events can briefly replace/reset the waiting animation before
			// the bird arrives, so animation loss is not proof that the wait ended.
			// Movement away, session boundaries and natural expiry remain explicit
			// cancellation inputs. Entry movement is accepted while its exact
			// hide/idle-start animation is still visible.
			if (eta.getRemainingTicks() <= 0 || (movedThisTick && !waitingAnimation))
			{
				controller.cancel();
				return;
			}
			if (waitingAnimation)
			{
				evidence.mark(ActivityEvidenceTracker.Signal.STYMPHIKE, tick);
			}
			return;
		}

		if (activity == EtaActivity.WOODCUTTING)
		{
			continueOrCancel(controller, isActivity(registry, animation, "Woodcutting"), tick,
				evidence, ActivityEvidenceTracker.Signal.WOODCUTTING, normalGraceTicks);
		}
	}

	private static void continueOrCancel(TaskEtaController controller, boolean animationActive,
		int tick, ActivityEvidenceTracker evidence, ActivityEvidenceTracker.Signal signal,
		int graceTicks)
	{
		if (animationActive)
		{
			evidence.mark(signal, tick);
			return;
		}
		if (!evidence.isRecent(signal, tick, graceTicks))
		{
			controller.cancel();
		}
	}

	private static boolean isActivity(ActivityAnimationRegistry registry, int animation,
		String activity)
	{
		return activity.equals(registry.activityForAnimation(animation));
	}
}

package com.idlefamiliar;

import java.awt.Rectangle;
import java.awt.image.BufferedImage;

/** Read-only presentation boundary consumed by both Swing views. */
interface WidgetContentSource
{
	BufferedImage getCurrentFrame();

	Rectangle getCurrentFrameVisualBounds();

	AvatarPackManifest getAvatarPackManifest();

	WidgetSnapshot getWidgetSnapshot();
}

package com.idlefamiliar;

import java.awt.Dimension;
import java.awt.GraphicsConfiguration;
import java.awt.GraphicsDevice;
import java.awt.GraphicsEnvironment;
import java.awt.Insets;
import java.awt.MouseInfo;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.Toolkit;
import javax.swing.JWindow;
import javax.swing.SwingUtilities;
import net.runelite.client.config.ConfigManager;

/** Owns desktop-display discovery, anchor persistence, snapping and resize recovery. */
final class DesktopWindowPositionController
{
	private static final int DEFAULT_SAFE_MARGIN = 12;
	private static final int POSITION_SNAP_DISTANCE = 20;

	private final IdleFamiliarConfig config;
	private final ConfigManager configManager;
	private JWindow window;
	private volatile boolean writingConfiguration;

	DesktopWindowPositionController(IdleFamiliarConfig config, ConfigManager configManager)
	{
		this.config = config;
		this.configManager = configManager;
	}

	void attach(JWindow window)
	{
		this.window = window;
	}

	boolean isWritingConfiguration()
	{
		return writingConfiguration;
	}

	void restore()
	{
		if (window == null)
		{
			return;
		}
		GraphicsConfiguration display = configurationForDisplayId(
			config == null ? "" : config.widgetDisplayId());
		Rectangle workArea = workArea(display);
		int margin = safeMargin();
		int storedX = config == null ? Integer.MIN_VALUE : config.widgetPositionX();
		int storedY = config == null ? Integer.MIN_VALUE : config.widgetPositionY();
		if (storedX == Integer.MIN_VALUE || storedY == Integer.MIN_VALUE)
		{
			int x = workArea.x + (workArea.width - window.getWidth()) / 2;
			int y = workArea.y + (workArea.height - window.getHeight()) / 2;
			window.setBounds(WidgetPositioning.clampToWorkArea(
				new Rectangle(x, y, window.getWidth(), window.getHeight()), workArea, margin));
			return;
		}
		WidgetAnchor anchor = selectedAnchor();
		window.setBounds(WidgetPositioning.anchoredBounds(workArea, window.getSize(), anchor,
			storedX, storedY, margin));
	}

	void applySelectedAnchor()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (window == null || config == null)
			{
				return;
			}
			Rectangle workArea = workAreaFor(window.getBounds());
			WidgetAnchor anchor = selectedAnchor();
			Rectangle target = anchor == WidgetAnchor.FREE
				? WidgetPositioning.clampToWorkArea(window.getBounds(), workArea, safeMargin())
				: WidgetPositioning.anchoredBounds(workArea, window.getSize(), anchor, 0, 0,
					safeMargin());
			window.setBounds(target);
			persist(target, workArea, anchor);
		});
	}

	void resetPosition()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (window == null)
			{
				return;
			}
			GraphicsConfiguration primary = GraphicsEnvironment.getLocalGraphicsEnvironment()
				.getDefaultScreenDevice().getDefaultConfiguration();
			Rectangle workArea = workArea(primary);
			Rectangle target = WidgetPositioning.anchoredBounds(workArea, window.getSize(),
				WidgetAnchor.TOP_RIGHT, 0, 0, safeMargin());
			window.setBounds(target);
			persist(target, workArea, WidgetAnchor.TOP_RIGHT);
		});
	}

	void moveToPointerDisplay()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (window == null)
			{
				return;
			}
			Point pointer = MouseInfo.getPointerInfo() == null
				? null : MouseInfo.getPointerInfo().getLocation();
			Rectangle workArea = workArea(configurationFor(pointer));
			WidgetAnchor anchor = selectedAnchor();
			Rectangle target;
			if (anchor == WidgetAnchor.FREE)
			{
				int x = workArea.x + (workArea.width - window.getWidth()) / 2;
				int y = workArea.y + (workArea.height - window.getHeight()) / 2;
				target = WidgetPositioning.clampToWorkArea(
					new Rectangle(x, y, window.getWidth(), window.getHeight()), workArea, safeMargin());
			}
			else
			{
				target = WidgetPositioning.anchoredBounds(workArea, window.getSize(), anchor,
					0, 0, safeMargin());
			}
			window.setBounds(target);
			persist(target, workArea, anchor);
		});
	}

	Rectangle workAreaFor(Rectangle bounds)
	{
		GraphicsConfiguration best = null;
		long bestIntersection = -1L;
		for (GraphicsDevice device : GraphicsEnvironment.getLocalGraphicsEnvironment().getScreenDevices())
		{
			GraphicsConfiguration candidate = device.getDefaultConfiguration();
			Rectangle intersection = candidate.getBounds().intersection(bounds);
			long area = intersection.isEmpty() ? 0L : (long) intersection.width * intersection.height;
			if (area > bestIntersection)
			{
				best = candidate;
				bestIntersection = area;
			}
		}
		if (best == null || bestIntersection == 0L)
		{
			best = configurationForDisplayId(config == null ? "" : config.widgetDisplayId());
		}
		return workArea(best);
	}

	void resize(int targetWidth, int targetHeight, boolean preserveBottomEdge, boolean dragging)
	{
		if (window == null || (window.getWidth() == targetWidth && window.getHeight() == targetHeight))
		{
			return;
		}
		SwingUtilities.invokeLater(() ->
		{
			if (window == null)
			{
				return;
			}
			Dimension targetSize = new Dimension(targetWidth, targetHeight);
			Rectangle workArea = workAreaFor(window.getBounds());
			WidgetAnchor anchor = selectedAnchor();
			Rectangle target;
			if (!dragging && anchor != WidgetAnchor.FREE
				&& config.widgetPositionX() != Integer.MIN_VALUE
				&& config.widgetPositionY() != Integer.MIN_VALUE)
			{
				target = WidgetPositioning.anchoredBounds(workArea, targetSize, anchor,
					config.widgetPositionX(), config.widgetPositionY(), safeMargin());
			}
			else
			{
				target = WidgetPositioning.resizedFreeBounds(window.getBounds(), targetSize,
					workArea, safeMargin(), !dragging && preserveBottomEdge);
			}
			window.setBounds(target);
		});
	}

	void persistDraggedPosition()
	{
		if (window == null)
		{
			return;
		}
		Rectangle workArea = workAreaFor(window.getBounds());
		Rectangle bounds = WidgetPositioning.clampToWorkArea(
			window.getBounds(), workArea, safeMargin());
		WidgetAnchor anchor = config != null && config.widgetEdgeSnapping()
			? WidgetPositioning.cornerAnchor(bounds, workArea, safeMargin(), POSITION_SNAP_DISTANCE)
			: WidgetAnchor.FREE;
		if (anchor != WidgetAnchor.FREE)
		{
			bounds = WidgetPositioning.anchoredBounds(workArea, window.getSize(), anchor,
				0, 0, safeMargin());
		}
		window.setBounds(bounds);
		persist(bounds, workArea, anchor);
	}

	private void persist(Rectangle bounds, Rectangle workArea, WidgetAnchor anchor)
	{
		if (configManager == null)
		{
			return;
		}
		Point offsets = WidgetPositioning.offsetsFor(bounds, workArea, anchor, safeMargin());
		writingConfiguration = true;
		try
		{
			configManager.setConfiguration(IdleFamiliarConfig.GROUP, "widgetPositionX", offsets.x);
			configManager.setConfiguration(IdleFamiliarConfig.GROUP, "widgetPositionY", offsets.y);
			configManager.setConfiguration(IdleFamiliarConfig.GROUP, "widgetDisplayId", displayIdFor(workArea));
			configManager.setConfiguration(IdleFamiliarConfig.GROUP, "widgetAnchor", anchor);
		}
		finally
		{
			writingConfiguration = false;
		}
	}

	private WidgetAnchor selectedAnchor()
	{
		return config == null || config.widgetAnchor() == null
			? WidgetAnchor.FREE : config.widgetAnchor();
	}

	private int safeMargin()
	{
		return config == null ? DEFAULT_SAFE_MARGIN : config.widgetSafeMargin();
	}

	private GraphicsConfiguration configurationFor(Point point)
	{
		if (point != null)
		{
			for (GraphicsDevice device : GraphicsEnvironment.getLocalGraphicsEnvironment().getScreenDevices())
			{
				GraphicsConfiguration candidate = device.getDefaultConfiguration();
				if (candidate.getBounds().contains(point))
				{
					return candidate;
				}
			}
		}
		return GraphicsEnvironment.getLocalGraphicsEnvironment()
			.getDefaultScreenDevice().getDefaultConfiguration();
	}

	private GraphicsConfiguration configurationForDisplayId(String displayId)
	{
		if (displayId != null && !displayId.isEmpty())
		{
			for (GraphicsDevice device : GraphicsEnvironment.getLocalGraphicsEnvironment().getScreenDevices())
			{
				if (displayId.equals(device.getIDstring()))
				{
					return device.getDefaultConfiguration();
				}
			}
		}
		return GraphicsEnvironment.getLocalGraphicsEnvironment()
			.getDefaultScreenDevice().getDefaultConfiguration();
	}

	private String displayIdFor(Rectangle workArea)
	{
		for (GraphicsDevice device : GraphicsEnvironment.getLocalGraphicsEnvironment().getScreenDevices())
		{
			if (workArea(device.getDefaultConfiguration()).equals(workArea))
			{
				return device.getIDstring();
			}
		}
		return GraphicsEnvironment.getLocalGraphicsEnvironment()
			.getDefaultScreenDevice().getIDstring();
	}

	private Rectangle workArea(GraphicsConfiguration configuration)
	{
		GraphicsConfiguration safeConfiguration = configuration == null
			? GraphicsEnvironment.getLocalGraphicsEnvironment()
				.getDefaultScreenDevice().getDefaultConfiguration()
			: configuration;
		Rectangle bounds = safeConfiguration.getBounds();
		Insets insets = Toolkit.getDefaultToolkit().getScreenInsets(safeConfiguration);
		return new Rectangle(bounds.x + insets.left, bounds.y + insets.top,
			Math.max(1, bounds.width - insets.left - insets.right),
			Math.max(1, bounds.height - insets.top - insets.bottom));
	}
}

