package com.idlefamiliar;

/**
 * Client-free skilling-success interpolation. Source: OSRS Wiki
 * {@code Module:Skilling_success_chart}, revision 15084668 (2026-07-21).
 */
final class GatheringSuccessChance
{
	static final int MIN_LEVEL = 1;
	static final int MAX_LEVEL = 99;
	private static final double DENOMINATOR = 256d;

	private GatheringSuccessChance()
	{
	}

	/**
	 * Returns the game's integer success roll for a captured effective level.
	 * Levels above 99 use the game's level-99 cap.
	 */
	static int roll(int low, int high, int effectiveLevel)
	{
		if (low < 0 || high < low)
		{
			throw new IllegalArgumentException("Invalid success-chart inputs");
		}

		int level = capLevel(effectiveLevel);
		double interpolated = low * (MAX_LEVEL - level) / 98d
			+ high * (level - MIN_LEVEL) / 98d;
		return (int) Math.floor(interpolated + 0.5d) + 1;
	}

	static double chance(int low, int high, int effectiveLevel)
	{
		return Math.max(0d, Math.min(1d, roll(low, high, effectiveLevel) / DENOMINATOR));
	}

	static int capLevel(int effectiveLevel)
	{
		return Math.max(MIN_LEVEL, Math.min(MAX_LEVEL, effectiveLevel));
	}
}

package com.idlefamiliar;

import java.util.function.Supplier;

/** Owns shipwreck-hook and salvage-sorting session coordination. */
final class SalvageSessionCoordinator
{
	/** Covers one complete three-tick station cycle plus event-order jitter. */
	private static final int SORTING_EVIDENCE_GRACE_TICKS =
		SalvageSortingCatalog.TICKS_PER_ITEM + 1;

	private final ActivityEvidenceTracker evidence;
	private final SalvageActivityDetector detector;
	private final EtaSessionManager etaSessionManager;

	SalvageSessionCoordinator(ActivityEvidenceTracker evidence,
		EtaSessionManager etaSessionManager)
	{
		this.evidence = evidence;
		this.detector = new SalvageActivityDetector(evidence);
		this.etaSessionManager = etaSessionManager;
	}

	void onAnimation(int animationId, int tick, boolean moved, boolean banking,
		Supplier<InventoryState> playerInventory)
	{
		if (SalvageSortingCatalog.isStationAnimation(animationId))
		{
			evidence.mark(ActivityEvidenceTracker.Signal.SALVAGE_SORTING, tick);
			startSorting(tick, banking, playerInventory);
		}
		if (SalvageSortingCatalog.isHookAnimation(animationId)
			&& !isSortingEngaged(animationId, tick))
		{
			evidence.mark(ActivityEvidenceTracker.Signal.SALVAGE_GATHERING, tick);
			startGathering(tick, moved, banking, playerInventory);
		}
	}

	boolean onMenuInteraction(String normalizedOption, String normalizedTarget,
		int tick, boolean banking, Supplier<InventoryState> playerInventory)
	{
		if (!SalvageSortingCatalog.isSortingInteraction(
			normalizedOption, normalizedTarget))
		{
			return false;
		}
		evidence.mark(ActivityEvidenceTracker.Signal.SALVAGE_SORTING, tick);
		startSorting(tick, banking, playerInventory);
		return true;
	}

	void onChatMessage(String normalizedMessage, int tick, boolean banking,
		Supplier<InventoryState> playerInventory)
	{
		if (SalvageSortingCatalog.isSortingStartMessage(normalizedMessage))
		{
			evidence.mark(ActivityEvidenceTracker.Signal.SALVAGE_SORTING, tick);
			startSorting(tick, banking, playerInventory);
			return;
		}
		if (SalvageSortingCatalog.isSortingResultMessage(normalizedMessage))
		{
			// Player-inventory deltas are the sole quantity authority. The chat and
			// inventory events can arrive in either order, so decrementing here as
			// well would sometimes count one cleaned salvage twice.
			evidence.mark(ActivityEvidenceTracker.Signal.SALVAGE_SORTING, tick);
			return;
		}
		if (SalvageSortingCatalog.isSortingEndMessage(normalizedMessage)
			&& etaSessionManager.activeActivity() == EtaActivity.SALVAGE_SORTING)
		{
			etaSessionManager.complete();
		}
	}

	void onPlayerInventoryChanged(InventoryChange inventoryChange, int tick,
		boolean moved, boolean banking, int animationGraceTicks)
	{
		SalvageActivityDetector.InventoryEvidence result = detector.detectInventory(
			inventoryChange, etaSessionManager.activeActivity(), tick, moved,
			banking, animationGraceTicks);
		if (result.sorting != null)
		{
			updateSortingQueue(result.sorting.remainingUnits,
				result.sorting.eligible, tick);
		}
		if (result.yield != null)
		{
			etaSessionManager.onVerifiedObservedGatheringYield(
				EtaActivity.SALVAGE_GATHERING,
				SalvageSortingCatalog.GATHERING_LABEL,
				result.yield.occupiedSlots,
				result.yield.producedSlots,
				result.yield.eligible,
				tick);
		}
		if (result.cancelGathering)
		{
			etaSessionManager.cancel();
		}
	}

	boolean isSortingEngaged(int animationId, int tick)
	{
		return etaSessionManager.activeActivity() == EtaActivity.SALVAGE_SORTING
			&& (SalvageSortingCatalog.isStationAnimation(animationId)
				|| evidence.isRecent(ActivityEvidenceTracker.Signal.SALVAGE_SORTING,
					tick, SORTING_EVIDENCE_GRACE_TICKS));
	}

	private void startSorting(int tick, boolean banking,
		Supplier<InventoryState> playerInventorySupplier)
	{
		if (etaSessionManager.activeActivity() == EtaActivity.SALVAGE_SORTING)
		{
			TaskEtaSnapshot current = etaSessionManager.snapshot();
			updateSortingQueue(current.getRemainingUnits(), !banking, tick);
			return;
		}
		InventoryState playerInventory = currentInventory(playerInventorySupplier);
		if (playerInventory == null)
		{
			return;
		}
		SalvageActivityDetector.SortingQueue queue =
			detector.sortingStart(playerInventory, banking);
		updateSortingQueue(queue.remainingUnits, queue.eligible, tick);
	}

	private void startGathering(int tick, boolean moved, boolean banking,
		Supplier<InventoryState> playerInventorySupplier)
	{
		InventoryState playerInventory = currentInventory(playerInventorySupplier);
		if (playerInventory == null)
		{
			return;
		}
		SalvageActivityDetector.GatheringStart start =
			detector.gatheringStart(playerInventory, moved, banking);
		etaSessionManager.onObservedGatheringStart(EtaActivity.SALVAGE_GATHERING,
			SalvageSortingCatalog.GATHERING_LABEL, start.occupiedSlots,
			start.eligible, tick);
	}

	private void updateSortingQueue(int remainingUnits, boolean eligible, int tick)
	{
		etaSessionManager.onVerifiedFixedProcessingQueue(
			EtaActivity.SALVAGE_SORTING,
			SalvageSortingCatalog.LABEL,
			remainingUnits,
			SalvageSortingCatalog.TICKS_PER_ITEM,
			eligible,
			tick);
	}

	private static InventoryState currentInventory(
		Supplier<InventoryState> playerInventory)
	{
		return playerInventory == null ? null : playerInventory.get();
	}
}

