import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * Reviewed Woodcutting mechanics. Source: OSRS Wiki {@code Woodcutting}
 * revision 15263858 and tree revisions below (2026-07-21).
 */
final class WoodcuttingCatalog
{
	enum Tree
	{
		OAK("oak", "Oak", 15, 45, 14, "15264017"),
		WILLOW("willow", "Willow", 30, 50, 14, "15264018"),
		TEAK("teak", "Teak", 35, 50, 15, "15254477"),
		MAPLE("maple", "Maple", 45, 100, 59, "15264019"),
		MAHOGANY("mahogany", "Mahogany", 50, 100, 14, "15254480"),
		YEW("yew", "Yew", 60, 190, 99, "15264021"),
		MAGIC("magic", "Magic", 75, 390, 199, "15264023"),
		REDWOOD("redwood", "Redwood", 90, 440, 199, "15229691"),
		CAMPHOR("camphor", "Camphor", 66, 200, 99, "15264047");

		private final String key;
		private final String label;
		private final int requirement;
		private final int activeSpotTicks;
		private final int respawnTicks;
		private final String sourceRevision;

		Tree(String key, String label, int requirement, int activeSpotTicks,
			int respawnTicks, String sourceRevision)
		{
			this.key = key;
			this.label = label;
			this.requirement = requirement;
			this.activeSpotTicks = activeSpotTicks;
			this.respawnTicks = respawnTicks;
			this.sourceRevision = sourceRevision;
		}
	}

	enum AxeTier
	{
		BRONZE,
		IRON,
		STEEL,
		BLACK,
		MITHRIL,
		ADAMANT,
		RUNE,
		DRAGON,
		CRYSTAL
	}

	private static final int ROLL_TICKS = 4;
	private static final Map<Tree, Map<AxeTier, GatheringProfile>> PROFILES = createProfiles();

	private WoodcuttingCatalog()
	{
	}

	static GatheringProfile profile(Tree tree, AxeTier axeTier)
	{
		if (tree == null || axeTier == null)
		{
			throw new IllegalArgumentException("Tree and axe tier are required");
		}
		return PROFILES.get(tree).get(axeTier);
	}

	static String sourceRevision(Tree tree)
	{
		if (tree == null)
		{
			throw new IllegalArgumentException("Tree is required");
		}
		return tree.sourceRevision;
	}

	/** Static upper bound from the first interaction, used when no tighter observed horizon is available. */
	static int activeSpotTicks(Tree tree)
	{
		if (tree == null)
		{
			throw new IllegalArgumentException("Tree is required");
		}
		return tree.activeSpotTicks;
	}

	private static Map<Tree, Map<AxeTier, GatheringProfile>> createProfiles()
	{
		Map<Tree, Map<AxeTier, GatheringProfile>> allProfiles = new EnumMap<>(Tree.class);
		add(allProfiles, Tree.OAK, new int[][]{
			{32, 100}, {48, 150}, {64, 200}, {72, 225}, {80, 250}, {96, 300}, {112, 350}, {120, 375}, {125, 400}});
		add(allProfiles, Tree.WILLOW, new int[][]{
			{16, 50}, {24, 75}, {32, 100}, {36, 112}, {40, 125}, {48, 150}, {56, 175}, {60, 187}, {64, 195}});
		add(allProfiles, Tree.TEAK, new int[][]{
			{15, 46}, {23, 70}, {31, 93}, {35, 102}, {39, 117}, {47, 140}, {55, 164}, {60, 190}, {60, 200}});
		add(allProfiles, Tree.MAPLE, new int[][]{
			{8, 25}, {12, 37}, {16, 50}, {18, 56}, {20, 62}, {24, 75}, {28, 87}, {30, 93}, {32, 100}});
		add(allProfiles, Tree.MAHOGANY, new int[][]{
			{8, 25}, {12, 38}, {16, 50}, {18, 54}, {20, 63}, {25, 75}, {29, 88}, {34, 94}, {36, 97}});
		add(allProfiles, Tree.YEW, new int[][]{
			{4, 12}, {6, 19}, {8, 25}, {9, 28}, {10, 31}, {12, 37}, {14, 44}, {15, 47}, {16, 50}});
		add(allProfiles, Tree.MAGIC, new int[][]{
			{2, 6}, {3, 9}, {4, 12}, {5, 13}, {5, 15}, {6, 18}, {7, 21}, {7, 22}, {8, 23}});
		add(allProfiles, Tree.REDWOOD, new int[][]{
			{2, 6}, {3, 9}, {4, 12}, {4, 14}, {5, 15}, {6, 18}, {7, 21}, {7, 30}, {8, 35}});
		add(allProfiles, Tree.CAMPHOR, new int[][]{
			{8, 23}, {11, 36}, {15, 47}, {17, 71}, {19, 59}, {23, 71}, {27, 83}, {32, 89}, {34, 93}});
		return Collections.unmodifiableMap(allProfiles);
	}

	private static void add(Map<Tree, Map<AxeTier, GatheringProfile>> allProfiles, Tree tree,
		int[][] chanceRows)
	{
		if (chanceRows.length != AxeTier.values().length)
		{
			throw new IllegalArgumentException("Each tree needs one row per axe tier");
		}

		Map<AxeTier, GatheringProfile> byAxe = new EnumMap<>(AxeTier.class);
		for (AxeTier axeTier : AxeTier.values())
		{
			int[] chanceRow = chanceRows[axeTier.ordinal()];
			OutcomeRoll logRoll = new OutcomeRoll(tree.label + " logs", chanceRow[0], chanceRow[1]);
			GatheringProfile profile = new GatheringProfile(
				"woodcutting." + tree.key + "." + axeTier.name().toLowerCase(),
				tree.label + " (" + axeTier.name().toLowerCase() + " axe)",
				tree.requirement, ROLL_TICKS, tree.activeSpotTicks, tree.respawnTicks,
				GatheringProfile.YieldMode.SINGLE, List.of(logRoll));
			byAxe.put(axeTier, profile);
		}
		allProfiles.put(tree, Collections.unmodifiableMap(byAxe));
	}
}

