/** Owns ETA state, target horizons, and continuation on the client thread. */
final class EtaSessionManager
{
	private final TaskEtaController controller = new TaskEtaController();
	private final GatheringEtaLifecycle gatheringLifecycle = new GatheringEtaLifecycle();
	private final GatheringResourceTracker gatheringResources = new GatheringResourceTracker();
	private final FishingSpotMovementTracker fishingSpots = new FishingSpotMovementTracker();
	private EtaActivity activeActivity = EtaActivity.NONE;
	private int lastStymphikeAnimation = -1;

	void reset()
	{
		controller.reset();
		gatheringResources.reset();
		fishingSpots.reset();
		activeActivity = EtaActivity.NONE;
		lastStymphikeAnimation = -1;
	}

	void seedInventory(Map<Integer, Integer> inventory)
	{
		controller.seedInventory(inventory);
	}

	void seedInventory(InventoryState inventory)
	{
		controller.seedInventory(inventory == null ? null : inventory.itemCounts());
	}

	/**
	 * Keep deterministic-processing history aligned after a gathering recognizer
	 * owns an inventory event. The same immutable event state is used; no second
	 * client read and no ETA lifecycle transition occurs.
	 */
	void syncInventoryBaseline(InventoryState inventory)
	{
		seedInventory(inventory);
	}

	void armProcessingContext(ProcessingContext context, int tick)
	{
		// Menu intent is recognition context, not proof that the former activity
		// ended. A complete inventory transformation claims PROCESSING later.
		controller.armProcessingContext(context, tick);
		syncProcessingActivity();
	}

	void setObservedProcessingContext(String activityLabel, boolean eligible)
	{
		controller.setObservedProcessingContext(activityLabel, eligible);
	}

	void onInventoryChanged(Map<Integer, Integer> inventory, int tick)
	{
		controller.onInventoryChanged(inventory, tick);
		syncProcessingActivity();
	}

	void onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree tree,
		WoodcuttingCatalog.AxeTier axeTier, int effectiveLevel, int occupiedInventorySlots,
		int producedLogSlots, boolean eligible, int despawnRemainingTicks, int tick)
	{
		prepareFor(EtaActivity.WOODCUTTING);
		controller.onVerifiedWoodcuttingLogDelta(tree, axeTier, effectiveLevel,
			occupiedInventorySlots, producedLogSlots, eligible, despawnRemainingTicks, tick);
		claimIfActive(EtaActivity.WOODCUTTING);
