	void onVerifiedWoodcuttingStorageStart(WoodcuttingCatalog.Tree tree,
		WoodcuttingCatalog.AxeTier axeTier, int effectiveLevel, int occupiedInventorySlots,
		int storageCapacity, boolean eligible, int despawnRemainingTicks, int tick)
