		prepareFor(EtaActivity.WOODCUTTING);
		controller.onVerifiedWoodcuttingStorageStart(tree, axeTier, effectiveLevel,
			occupiedInventorySlots, storageCapacity, eligible, despawnRemainingTicks, tick);
		claimIfActive(EtaActivity.WOODCUTTING);
	}

	void onVerifiedConventionalFishingCatch(GatheringProfile profile, int effectiveLevel,
