package com.idlefamiliar;

import java.io.IOException;
import java.io.InputStream;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.client.audio.AudioPlayer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Small local-only sound layer for Idle Familiar. It maps high-level plugin
 * events to bundled WAV resources and plays them as short, fire-and-forget cues
 * through RuneLite's {@link AudioPlayer}.
 */
public class SoundController
{
	private static final Logger log = LoggerFactory.getLogger(SoundController.class);
	static final String RESOURCE_DIR = "/com/idlefamiliar/sounds/";

	private final Map<AvatarState, SoundEffect> animationStartSounds = new EnumMap<>(AvatarState.class);
	private final Map<GameSoundEvent, SoundEffect> gameEventSounds = new EnumMap<>(GameSoundEvent.class);

	private volatile boolean enabled = true;
	private volatile int volumePercent = 70;

	/** Supplied by the plugin once Guice has injected it; until then playback is a no-op. */
	private volatile AudioPlayer audioPlayer;

	public SoundController()
	{
		registerDefaults();
	}

	private void registerDefaults()
	{
		// Logical cues may share a bundled sample; add a distinct SoundEffect resource
		// only when an event has distinct audio.
		animationStartSounds.put(AvatarState.PLAYER_IDLE, SoundEffect.PRAYER_CHIME);
		animationStartSounds.put(AvatarState.AFK_WARNING, SoundEffect.FROG_CROAK);

		gameEventSounds.put(GameSoundEvent.INVENTORY_FULL, SoundEffect.INVENTORY_POP);
		gameEventSounds.put(GameSoundEvent.LOW_HEALTH, SoundEffect.LOW_HP_ALARM);
		gameEventSounds.put(GameSoundEvent.LOW_PRAYER, SoundEffect.PRAYER_CHIME);
		gameEventSounds.put(GameSoundEvent.ETA_COMPLETE, SoundEffect.COIN_CHIME);
	}

	public void setAudioPlayer(AudioPlayer audioPlayer)
	{
		this.audioPlayer = audioPlayer;
	}

	public void setEnabled(boolean enabled)
	{
		this.enabled = enabled;
	}

	public void setVolumePercent(int volumePercent)
	{
		this.volumePercent = Math.max(0, Math.min(100, volumePercent));
	}

	/** Apply only the exact event-backed setting that changed; config proxies can lag bulk writes. */
	void applyConfigurationChange(String key, String serializedValue)
	{
		if ("enableSounds".equals(key))
		{
			setEnabled(Boolean.parseBoolean(serializedValue));
		}
		else if ("soundVolumePercent".equals(key))
		{
			try
			{
				setVolumePercent(Integer.parseInt(serializedValue));
			}
			catch (NumberFormatException ignored)
			{
				// Keep the last valid value when an externally edited profile is malformed.
			}
		}
	}

	boolean isEnabledForTesting()
	{
		return enabled;
	}

	int volumePercentForTesting()
	{
		return volumePercent;
	}

	public void playAnimationStart(AvatarState state)
	{
		play(soundForAnimationStart(state));
	}

	public void playGameEvent(GameSoundEvent event)
	{
		play(soundForGameEvent(event));
	}

	public void playChatMessage()
	{
		play(SoundEffect.INVENTORY_POP);
	}

	boolean hasSoundResource(SoundEffect effect)
	{
		if (effect == null)
		{
			return false;
		}
		try (InputStream stream = openSound(effect))
		{
			return stream != null;
		}
		catch (IOException ex)
		{
			return false;
		}
	}

	SoundEffect soundForAnimationStart(AvatarState state)
	{
		return animationStartSounds.get(state);
	}

	SoundEffect soundForGameEvent(GameSoundEvent event)
	{
		return gameEventSounds.get(event);
	}

	private void play(SoundEffect effect)
	{
		final AudioPlayer player = audioPlayer;
		if (!enabled || volumePercent <= 0 || effect == null || player == null)
		{
			return;
		}

		try
		{
			// Catch broad Exception on purpose: AudioPlayer#play declares the
			// javax.sound checked exceptions, and referencing those types here is
			// disallowed on the Plugin Hub. Exception covers them without naming them.
			player.play(SoundController.class, RESOURCE_DIR + effect.fileName(), gainDecibels());
		}
		catch (Exception ex)
		{
			log.debug("Unable to play Idle Familiar sound {}", effect.fileName(), ex);
		}
	}

	/** Convert the 0-100 volume into a dB gain (0 dB at 100%, quieter below). */
	private float gainDecibels()
	{
		float normalized = Math.max(0.0001f, volumePercent / 100.0f);
		return (float) (20.0 * Math.log10(normalized));
	}

	private InputStream openSound(SoundEffect effect)
	{
		return SoundController.class.getResourceAsStream(RESOURCE_DIR + effect.fileName());
	}
}

package com.idlefamiliar;

import java.util.EnumSet;
import net.runelite.api.ItemID;

/**
 * Tracks unreadable container capacity. Evidence may reduce capacity but never
 * restore it within the same session.
 */
final class ExtendedInventoryTracker
{
	enum Container
	{
		FISH_BARREL(28),
		LOG_BASKET(28);

		private final int capacity;

		Container(int capacity)
		{
			this.capacity = capacity;
		}

		int capacity()
		{
			return capacity;
		}
	}

	private final EnumSet<Container> knownFull = EnumSet.noneOf(Container.class);

	void reset()
	{
		knownFull.clear();
	}

	void markFull(Container container)
	{
		if (container != null)
		{
			knownFull.add(container);
		}
	}

	void markEmptyOrUnknown(Container container)
	{
		if (container != null)
		{
			knownFull.remove(container);
		}
	}

	boolean isKnownFull(Container container)
	{
		return container != null && knownFull.contains(container);
	}

	int assumedExtraCapacity(Container container, boolean present)
	{
		return present && !isKnownFull(container) ? container.capacity() : 0;
	}

	int effectiveFreeSlots(Container container, boolean present, int ordinaryFreeSlots)
	{
		return Math.max(0, ordinaryFreeSlots) + assumedExtraCapacity(container, present);
	}

	boolean hasOpenFishBarrel(InventoryState inventory, InventoryState equipment)
	{
		return contains(inventory, equipment, ItemID.OPEN_FISH_BARREL,
			ItemID.OPEN_FISH_SACK_BARREL);
	}

	boolean hasOpenLogBasket(InventoryState inventory, InventoryState equipment)
	{
		return contains(inventory, equipment, ItemID.OPEN_LOG_BASKET,
			ItemID.OPEN_FORESTRY_BASKET);
	}

	void onMenuAction(String normalizedOption, String normalizedTarget)
	{
		if (!"empty".equals(normalizedOption))
		{
			return;
		}
		String target = normalizedTarget == null ? "" : normalizedTarget;
		if (target.contains("fish barrel") || target.contains("fish sack barrel"))
		{
			markEmptyOrUnknown(Container.FISH_BARREL);
		}
		if (target.contains("log basket") || target.contains("forestry basket"))
		{
			markEmptyOrUnknown(Container.LOG_BASKET);
		}
	}

	void onChatMessage(String normalizedMessage)
	{
		String message = normalizedMessage == null ? "" : normalizedMessage;
		if (message.contains("barrel is full") && message.contains("empty at a bank"))
		{
			markFull(Container.FISH_BARREL);
		}
		else if (message.contains("empty all of your containers into the bank")
			|| message.contains("containers are already empty"))
		{
			markEmptyOrUnknown(Container.FISH_BARREL);
			markEmptyOrUnknown(Container.LOG_BASKET);
		}
	}

	private static boolean contains(InventoryState inventory, InventoryState equipment,
		int... itemIds)
	{
		InventoryState safeInventory = inventory == null ? InventoryState.empty() : inventory;
		InventoryState safeEquipment = equipment == null ? InventoryState.empty() : equipment;
		return safeInventory.containsAny(itemIds) || safeEquipment.containsAny(itemIds);
	}
}

