package com.idlefamiliar;

/**
 * One source-defined success roll.  The low and high inputs are the values
 * exposed by the OSRS game-script chart, before conversion to the engine's
 * denominator of 256.
 */
final class OutcomeRoll
{
	private final String label;
	private final int low;
	private final int high;
	private final int requiredLevel;

	OutcomeRoll(String label, int low, int high)
	{
		this(label, low, high, GatheringSuccessChance.MIN_LEVEL);
	}

	/** Creates one independently unlocked roll in a mixed fishing cascade. */
	OutcomeRoll(String label, int low, int high, int requiredLevel)
	{
		if (label == null || label.isEmpty())
		{
			throw new IllegalArgumentException("A roll label is required");
		}
		if (low < 0 || high < low || requiredLevel < GatheringSuccessChance.MIN_LEVEL
			|| requiredLevel > GatheringSuccessChance.MAX_LEVEL)
		{
			throw new IllegalArgumentException("Invalid success-chart inputs");
		}
		this.label = label;
		this.low = low;
		this.high = high;
		this.requiredLevel = requiredLevel;
	}

	String getLabel()
	{
		return label;
	}

	int getLow()
	{
		return low;
	}

	int getHigh()
	{
		return high;
	}

	int getRequiredLevel()
	{
		return requiredLevel;
	}

	int successRollAt(int effectiveLevel)
	{
		return GatheringSuccessChance.capLevel(effectiveLevel) < requiredLevel
			? 0 : GatheringSuccessChance.roll(low, high, effectiveLevel);
	}

	double successChanceAt(int effectiveLevel)
	{
		return GatheringSuccessChance.capLevel(effectiveLevel) < requiredLevel
			? 0d : GatheringSuccessChance.chance(low, high, effectiveLevel);
	}
}

package com.idlefamiliar;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.stream.ImageInputStream;

/**
 * Validates sprite geometry, variants, weights, references, and size limits in
 * an avatar override folder.
 */
public final class AvatarAssetValidator
{
	/** A variant file base ends in one of these once its primary base is stripped. */
	private static final Pattern VARIANT_SUFFIX = Pattern.compile("^(.*)_(uncommon|rare|[2-9])$");

	private AvatarAssetValidator()
	{
	}

	/**
	 * @param dir the avatar folder to validate (typically the external drop-in dir)
	 * @return a list of human-readable issues; empty means the folder is clean (or
	 *         absent - there is nothing to validate)
	 */
	public static List<String> validate(File dir)
	{
		return validate(dir, null);
	}

	/** Validates a folder and optionally flags unreferenced primary sheets. */
	public static List<String> validate(File dir, Set<String> referencedBases)
	{
		List<String> issues = new ArrayList<>();
		if (dir == null || !dir.isDirectory())
		{
			return issues;
		}

		File[] files = dir.listFiles((d, name) -> name.toLowerCase(Locale.ROOT).endsWith(".png"));
		if (files == null)
		{
			return issues;
		}

		Set<String> bases = new LinkedHashSet<>();
		for (File file : files)
		{
			bases.add(stripPng(file.getName()));
		}

		for (File file : files)
		{
			checkDimensions(file, issues);
		}

		for (String base : bases)
		{
			Matcher matcher = VARIANT_SUFFIX.matcher(base);
			if (matcher.matches() && !bases.contains(matcher.group(1)))
			{
				issues.add("Orphaned variant: " + base + ".png has no primary " + matcher.group(1) + ".png");
			}
		}

		if (referencedBases != null)
		{
			for (String base : bases)
			{
				checkUnreferenced(base, bases, referencedBases, issues);
			}
		}

		checkWeights(new File(dir, "weights.json"), bases, issues);
		return issues;
	}

	/** Flags a primary sheet that no state, skill, or variant can resolve. */
	private static void checkUnreferenced(String base, Set<String> bases, Set<String> referencedBases, List<String> issues)
	{
		if (referencedBases.contains(base))
		{
			return;
		}
		Matcher matcher = VARIANT_SUFFIX.matcher(base);
		if (matcher.matches() && bases.contains(matcher.group(1)))
		{
			return;
		}
		issues.add("Unreferenced sheet: " + base + ".png maps to no known state, skill, or variant");
	}

	private static void checkDimensions(File file, List<String> issues)
	{
		try (ImageInputStream imageInput = ImageIO.createImageInputStream(file))
		{
			if (imageInput == null)
			{
				issues.add("Unreadable sheet: " + file.getName() + " is not a valid image");
				return;
			}
			Iterator<ImageReader> readers = ImageIO.getImageReaders(imageInput);
			if (!readers.hasNext())
			{
				issues.add("Unreadable sheet: " + file.getName() + " is not a valid image");
				return;
			}
			ImageReader reader = readers.next();
			try
			{
				reader.setInput(imageInput, true, true);
				int width = reader.getWidth(0);
				int height = reader.getHeight(0);
				long decodedPixels = (long) width * height;
				if (decodedPixels > SpriteSheetLoader.DEFAULT_MAX_DECODED_PIXELS)
				{
					issues.add("Oversized sheet: " + file.getName() + " is " + width + "x" + height
						+ " (decoded pixels " + decodedPixels + " exceed "
						+ SpriteSheetLoader.DEFAULT_MAX_DECODED_PIXELS + ")");
				}
				else if (height <= 0 || width % height != 0)
				{
					issues.add("Malformed sheet: " + file.getName() + " is " + width + "x" + height
						+ " (width must be a whole multiple of height; frames = width / height)");
				}
			}
			finally
			{
				reader.dispose();
			}
		}
		catch (IOException ex)
		{
			issues.add("Unreadable sheet: " + file.getName() + " (" + ex.getMessage() + ")");
		}
	}

	private static void checkWeights(File weightsFile, Set<String> bases, List<String> issues)
	{
		if (!weightsFile.isFile())
		{
			return;
		}
		String raw;
		try
		{
			raw = new String(Files.readAllBytes(weightsFile.toPath()), StandardCharsets.UTF_8);
		}
		catch (IOException ex)
		{
			issues.add("weights.json: unreadable (" + ex.getMessage() + ")");
			return;
		}
		String stripped = raw.replaceAll("[{}\"\\s]", "");
		for (String pair : stripped.split(","))
		{
			if (pair.isEmpty())
			{
				continue;
			}
			String key = pair.split(":")[0];
			if (!key.isEmpty() && !bases.contains(key))
			{
				issues.add("Dangling weight: weights.json key '" + key + "' has no " + key + ".png");
			}
		}
	}

	private static String stripPng(String fileName)
	{
		int dot = fileName.toLowerCase(Locale.ROOT).lastIndexOf(".png");
		return dot >= 0 ? fileName.substring(0, dot) : fileName;
	}
}

package com.idlefamiliar;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.ItemID;

/**
 * Source-reviewed deterministic transformations. Timing sources and profile
 * boundaries are recorded in the mechanics catalog and tests.
 */
@SuppressWarnings("deprecation") // RuneLite retains the stable ItemID table for plugin item matching.
final class ProcessingCatalog
{
	private static final int[] REVIEWED_CAMPFIRE_LOGS = {
		ItemID.ACHEY_TREE_LOGS, ItemID.LOGS, ItemID.OAK_LOGS, ItemID.WILLOW_LOGS,
		ItemID.TEAK_LOGS, ItemID.ARCTIC_PINE_LOGS, ItemID.MAPLE_LOGS, ItemID.MAHOGANY_LOGS,
		ItemID.YEW_LOGS, ItemID.BLISTERWOOD_LOGS, ItemID.MAGIC_LOGS, ItemID.REDWOOD_LOGS,
		ItemID.CAMPHOR_LOGS, ItemID.IRONWOOD_LOGS, ItemID.ROSEWOOD_LOGS
	};
	private static final int[] REVIEWED_RAW_FOODS = {
		ItemID.RAW_SHRIMPS, ItemID.RAW_ANCHOVIES, ItemID.RAW_SARDINE, ItemID.RAW_HERRING,
		ItemID.RAW_MACKEREL, ItemID.RAW_COD, ItemID.RAW_TROUT, ItemID.RAW_PIKE, ItemID.RAW_SALMON,
		ItemID.RAW_TUNA, ItemID.RAW_BASS, ItemID.RAW_LOBSTER, ItemID.RAW_SWORDFISH,
		ItemID.RAW_MONKFISH, ItemID.RAW_SHARK, ItemID.RAW_SEA_TURTLE, ItemID.RAW_MANTA_RAY,
		ItemID.RAW_CAVE_EEL, ItemID.RAW_SLIMY_EEL, ItemID.RAW_DARK_CRAB, ItemID.RAW_ANGLERFISH,
		ItemID.RAW_BEEF, ItemID.RAW_CHICKEN, ItemID.RAW_RABBIT, ItemID.RAW_CHOMPY
	};
	private static final List<ProcessingProfile> PROFILES = profiles();

	private ProcessingCatalog()
	{
	}

	static ProcessingProfile match(InventoryDelta delta, Map<Integer, Integer> inventoryAfter)
	{
		return match(delta, inventoryAfter, ProcessingContext.none());
	}

	static ProcessingProfile match(InventoryDelta delta, Map<Integer, Integer> inventoryAfter,
		ProcessingContext context)
	{
		ProcessingProfile contextual = contextualMatch(delta, inventoryAfter,
			context == null ? ProcessingContext.none() : context);
		if (contextual != null)
		{
			return contextual;
		}
		if (context == null || context.kind() != ProcessingContext.Kind.FLETCHING_KNIFE)
		{
			ProcessingProfile cooking = matchCookAll(delta, ProcessingContext.Kind.NONE);
			if (cooking != null)
			{
				return cooking;
			}
		}
		ProcessingProfile fletchingBatch = matchArrowOrBoltBatch(delta,
			context == null ? ProcessingContext.none() : context);
		if (fletchingBatch != null)
		{
			return fletchingBatch;
		}
		for (ProcessingProfile profile : PROFILES)
		{
			if (profile.matches(delta, inventoryAfter, context))
			{
				return profile;
			}
		}
		return null;
	}

