	private static void addGem(List<ProcessingProfile> profiles, int input, int output, int... failureOutputs)
	{
		Set<Integer> outputs = new java.util.HashSet<>();
		outputs.add(output);
		for (int failureOutput : failureOutputs)
		{
			outputs.add(failureOutput);
		}
		profiles.add(new ProcessingProfile("gem." + input, "Gem cutting", 2, input,
			Map.of(input, 1), outputs, Collections.emptyMap(), Set.of(ItemID.CHISEL),
			Collections.emptySet(), ProcessingProfile.CapacityModel.PRIMARY_INPUT));
	}

