	private static ProcessingProfile contextualMatch(InventoryDelta delta, Map<Integer, Integer> inventory,
		ProcessingContext context)
	{
		switch (context.kind())
		{
			case ANVIL_SMITHING:
				return matchAnvil(delta, inventory, context);
			case FURNACE_SMELTING:
				return matchFurnaceSmelting(delta, inventory);
			case FORESTERS_CAMPFIRE:
				return matchForestersCampfire(delta);
			case COOKING:
				return matchCookAll(delta, ProcessingContext.Kind.COOKING);
			case FINISHED_POTION:
				return matchFinishedPotion(delta);
			default:
				return null;
		}
	}

	private static ProcessingProfile matchAnvil(InventoryDelta delta, Map<Integer, Integer> inventory,
		ProcessingContext context)
	{
		int bar = onlyConsumedItem(delta, ItemID.BRONZE_BAR, ItemID.IRON_BAR, ItemID.STEEL_BAR,
			ItemID.SILVER_BAR, ItemID.GOLD_BAR, ItemID.MITHRIL_BAR, ItemID.ADAMANTITE_BAR, ItemID.RUNITE_BAR);
		if (bar < 0)
		{
			return null;
		}
		int barsPerOutput = delta.consumed(bar);
		if (barsPerOutput < 1 || barsPerOutput > 5)
		{
			return null;
		}
		int output = onlyProducedItem(delta, bar);
		int outputQuantity = output < 0 ? 0 : delta.produced(output);
		return output < 0 || outputQuantity < 1 || outputQuantity > 15 ? null
			: ProcessingProfile.anvilSmithing(bar, barsPerOutput, output, outputQuantity, context);
	}

	/** Package-visible for plugin-side verification of a live smithing animation. */
	static ProcessingProfile matchAnvilCandidate(InventoryDelta delta, Map<Integer, Integer> inventory,
		ProcessingContext context)
	{
		return matchAnvil(delta, inventory, context);
	}

	/** Matches ordinary furnaces; failed iron still consumes one queue action. */
	static ProcessingProfile matchFurnaceCandidate(InventoryDelta delta, Map<Integer, Integer> inventory)
	{
		ProcessingProfile match;
		match = furnaceRecipe(delta, inventory, "furnace.bronze",
			Map.of(ItemID.COPPER_ORE, 1, ItemID.TIN_ORE, 1), ItemID.BRONZE_BAR, false);
		if (match != null)
		{
			return match;
		}
		match = furnaceRecipe(delta, inventory, "furnace.iron", Map.of(ItemID.IRON_ORE, 1),
			ItemID.IRON_BAR, true);
		if (match != null)
		{
			return match;
		}
		match = furnaceRecipe(delta, inventory, "furnace.silver", Map.of(ItemID.SILVER_ORE, 1),
			ItemID.SILVER_BAR, false);
		if (match != null)
		{
			return match;
		}
		match = furnaceRecipe(delta, inventory, "furnace.gold", Map.of(ItemID.GOLD_ORE, 1),
			ItemID.GOLD_BAR, false);
		if (match != null)
		{
			return match;
		}
		match = furnaceRecipe(delta, inventory, "furnace.steel",
			Map.of(ItemID.IRON_ORE, 1, ItemID.COAL, 2), ItemID.STEEL_BAR, false);
		if (match != null)
		{
			return match;
		}
		match = furnaceRecipe(delta, inventory, "furnace.mithril",
			Map.of(ItemID.MITHRIL_ORE, 1, ItemID.COAL, 4), ItemID.MITHRIL_BAR, false);
		if (match != null)
		{
			return match;
		}
		match = furnaceRecipe(delta, inventory, "furnace.adamantite",
			Map.of(ItemID.ADAMANTITE_ORE, 1, ItemID.COAL, 6), ItemID.ADAMANTITE_BAR, false);
		if (match != null)
		{
			return match;
		}
		return furnaceRecipe(delta, inventory, "furnace.runite",
			Map.of(ItemID.RUNITE_ORE, 1, ItemID.COAL, 8), ItemID.RUNITE_BAR, false);
	}

	private static ProcessingProfile matchFurnaceSmelting(InventoryDelta delta,
		Map<Integer, Integer> inventory)
	{
		return matchFurnaceCandidate(delta, inventory);
	}

	private static ProcessingProfile furnaceRecipe(InventoryDelta delta, Map<Integer, Integer> inventory,
		String key, Map<Integer, Integer> inputs, int output, boolean outputMayBeAbsent)
	{
		ProcessingProfile profile = ProcessingProfile.furnaceSmelting(key, inputs, output,
			outputMayBeAbsent);
		return profile.matches(delta, inventory, ProcessingContext.furnaceSmelting()) ? profile : null;
	}

	private static ProcessingProfile matchForestersCampfire(InventoryDelta delta)
	{
		int log = onlyConsumedItem(delta, REVIEWED_CAMPFIRE_LOGS);
		return log >= 0 && delta.consumed(log) == 1 && onlyProducedItem(delta, log) < 0
			? ProcessingProfile.forestersCampfire(log) : null;
	}

	private static ProcessingProfile matchFinishedPotion(InventoryDelta delta)
	{
		Map<Integer, Integer> consumed = changedConsumedItems(delta);
		if (consumed.size() < 2 || consumed.size() > 4
			|| (!containsUnfinishedPotion(consumed.keySet())
				&& !containsReviewedStackablePotionSecondary(consumed.keySet())))
		{
			return null;
		}
		int output = onlyProducedItem(delta, consumed.keySet().toArray(new Integer[0]));
		return output >= 0 && delta.produced(output) == 1
			? ProcessingProfile.finishedPotion(consumed, output,
				containsAraxyteVenomSac(consumed.keySet()) ? 3 : 2) : null;
	}

	/** Finished-potion bases require item-on-item context and a complete delta. */
	private static boolean containsReviewedStackablePotionSecondary(Set<Integer> itemIds)
	{
		return itemIds.contains(ItemID.AMYLASE_CRYSTAL)
			|| itemIds.contains(ItemID.LAVA_SCALE_SHARD)
			|| itemIds.contains(ItemID.ZULRAHS_SCALES)
			|| itemIds.contains(ItemID.CRUSHED_SUPERIOR_DRAGON_BONES)
			|| itemIds.contains(ItemID.ANCIENT_ESSENCE)
			|| itemIds.contains(ItemID.ARAXYTE_VENOM_SAC)
			|| itemIds.contains(ItemID.MARLIN_SCALES);
	}

	private static boolean containsAraxyteVenomSac(Set<Integer> itemIds)
	{
		return itemIds.contains(ItemID.ARAXYTE_VENOM_SAC);
	}

	private static boolean containsUnfinishedPotion(Set<Integer> itemIds)
	{
		for (Integer itemId : itemIds)
		{
			if (itemId != null && (itemId == ItemID.GUAM_POTION_UNF || itemId == ItemID.MARRENTILL_POTION_UNF
				|| itemId == ItemID.TARROMIN_POTION_UNF || itemId == ItemID.HARRALANDER_POTION_UNF
				|| itemId == ItemID.RANARR_POTION_UNF || itemId == ItemID.TOADFLAX_POTION_UNF
				|| itemId == ItemID.IRIT_POTION_UNF || itemId == ItemID.AVANTOE_POTION_UNF
				|| itemId == ItemID.KWUARM_POTION_UNF || itemId == ItemID.SNAPDRAGON_POTION_UNF
				|| itemId == ItemID.CADANTINE_POTION_UNF || itemId == ItemID.LANTADYME_POTION_UNF
				|| itemId == ItemID.DWARF_WEED_POTION_UNF || itemId == ItemID.TORSTOL_POTION_UNF
				|| itemId == ItemID.HUASCA_POTION_UNF))
			{
				return true;
			}
		}
		return false;
	}

	private static int onlyConsumedItem(InventoryDelta delta, int... allowed)
	{
		Map<Integer, Integer> consumed = changedConsumedItems(delta);
		if (consumed.size() != 1)
		{
			return -1;
		}
		int consumedId = consumed.keySet().iterator().next();
		return contains(allowed, consumedId) ? consumedId : -1;
	}

	private static Map<Integer, Integer> changedConsumedItems(InventoryDelta delta)
	{
		Map<Integer, Integer> consumed = new java.util.HashMap<>();
		for (Integer itemId : delta.itemIds())
		{
			int quantity = delta.consumed(itemId);
			if (quantity > 0)
			{
				consumed.put(itemId, quantity);
			}
		}
		return consumed;
	}

	private static ProcessingProfile matchCookAll(InventoryDelta delta,
		ProcessingContext.Kind requiredContext)
	{
		int raw = onlyConsumedItem(delta, REVIEWED_RAW_FOODS);
		if (raw < 0 || delta.consumed(raw) != 1)
		{
			return null;
		}
		int output = onlyProducedItem(delta, raw);
		return output >= 0 && delta.produced(output) == 1
			? ProcessingProfile.cookAll(raw, output, requiredContext) : null;
	}

	static boolean isReviewedCampfireLog(int itemId)
	{
		return contains(REVIEWED_CAMPFIRE_LOGS, itemId);
	}

	static boolean isReviewedRawFood(int itemId)
	{
		return contains(REVIEWED_RAW_FOODS, itemId);
	}

	private static boolean contains(int[] itemIds, int itemId)
	{
		for (int candidate : itemIds)
		{
			if (candidate == itemId)
			{
				return true;
			}
		}
		return false;
	}

	/** Matches complete native batches: 15 arrows or 10 bolts. */
	private static ProcessingProfile matchArrowOrBoltBatch(InventoryDelta delta,
		ProcessingContext context)
	{
		ProcessingContext.Kind kind = context == null ? ProcessingContext.Kind.NONE : context.kind();
		if (kind != ProcessingContext.Kind.NONE && kind != ProcessingContext.Kind.FLETCHING_KNIFE)
		{
			return null;
		}

		Map<Integer, Integer> consumed = changedConsumedItems(delta);
		int output = onlyProducedItem(delta, consumed.keySet().toArray(new Integer[0]));
		if (output < 0)
		{
			return null;
		}
		if (isArrowBatchInputs(consumed) && delta.produced(output) == 15)
		{
			return ProcessingProfile.fletchingBatch(consumed, output, 15, kind);
		}
		if (isBoltBatchInputs(consumed) && delta.produced(output) == 10)
		{
			return ProcessingProfile.fletchingBatch(consumed, output, 10, kind);
		}
		return null;
	}

	private static boolean isArrowBatchInputs(Map<Integer, Integer> consumed)
	{
		return hasExactBatchInputs(consumed, ItemID.ARROW_SHAFT, ItemID.FEATHER, 15)
			|| hasExactBatchInputsFromSet(consumed, ItemID.HEADLESS_ARROW, 15,
				ItemID.BRONZE_ARROWTIPS, ItemID.IRON_ARROWTIPS, ItemID.STEEL_ARROWTIPS,
				ItemID.MITHRIL_ARROWTIPS, ItemID.ADAMANT_ARROWTIPS, ItemID.RUNE_ARROWTIPS,
				ItemID.DRAGON_ARROWTIPS, ItemID.BROAD_ARROWHEADS, ItemID.AMETHYST_ARROWTIPS);
	}

	private static boolean isBoltBatchInputs(Map<Integer, Integer> consumed)
	{
		return hasExactBatchInputsFromSet(consumed, ItemID.FEATHER, 10,
			ItemID.BRONZE_BOLTS_UNF, ItemID.BLURITE_BOLTS_UNF, ItemID.IRON_BOLTS_UNF,
			ItemID.STEEL_BOLTS_UNF, ItemID.MITHRIL_BOLTS_UNF, ItemID.ADAMANT_BOLTSUNF,
			ItemID.RUNITE_BOLTS_UNF, ItemID.SILVER_BOLTS_UNF, ItemID.UNFINISHED_BROAD_BOLTS,
			ItemID.DRAGON_BOLTS_UNF);
	}

	private static boolean hasExactBatchInputs(Map<Integer, Integer> consumed, int first, int second,
		int quantity)
	{
		return consumed.size() == 2 && consumed.getOrDefault(first, 0) == quantity
			&& consumed.getOrDefault(second, 0) == quantity;
	}

	private static boolean hasExactBatchInputsFromSet(Map<Integer, Integer> consumed, int fixedInput,
		int quantity, int... variableInputs)
	{
		if (consumed.size() != 2 || consumed.getOrDefault(fixedInput, 0) != quantity)
		{
			return false;
		}
		for (int variable : variableInputs)
		{
			if (consumed.getOrDefault(variable, 0) == quantity)
			{
				return true;
			}
		}
		return false;
	}

	private static int onlyProducedItem(InventoryDelta delta, Integer... excluded)
	{
		Integer result = null;
		for (Integer itemId : delta.itemIds())
		{
			if (delta.produced(itemId) > 0 && !contains(excluded, itemId))
			{
				if (result != null)
				{
					return -1;
				}
				result = itemId;
			}
		}
		return result == null ? -1 : result;
	}

	private static boolean contains(Integer[] itemIds, int itemId)
	{
		for (Integer candidate : itemIds)
		{
			if (candidate != null && candidate == itemId)
			{
				return true;
			}
		}
		return false;
	}
}

