package com.idlefamiliar;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/** Paints the eight perimeter cells of a fixed 3x3 theme-decoration atlas. */
final class ThemeDecorationRenderer
{
	private static final int ATLAS_COLUMNS = 3;
	private static final int CORNER_SIZE = 28;
	private static final int EDGE_WIDTH = 40;
	private static final int EDGE_HEIGHT = 28;
	private static final int CORNER_OVERHANG = 10;
	private static final int EDGE_OVERHANG = 12;

	private ThemeDecorationRenderer()
	{
	}

	static void draw(Graphics2D graphics, BufferedImage atlas, Rectangle bounds, double scale)
	{
		if (graphics == null || atlas == null || bounds == null || bounds.width <= 0 || bounds.height <= 0
			|| atlas.getWidth() % ATLAS_COLUMNS != 0 || atlas.getHeight() % ATLAS_COLUMNS != 0)
		{
			return;
		}

		double safeScale = Math.max(0.5d, scale);
		int corner = scaled(CORNER_SIZE, safeScale);
		int edgeWidth = scaled(EDGE_WIDTH, safeScale);
		int edgeHeight = scaled(EDGE_HEIGHT, safeScale);
		int cornerOverhang = scaled(CORNER_OVERHANG, safeScale);
		int edgeOverhang = scaled(EDGE_OVERHANG, safeScale);

		Object oldInterpolation = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		try
		{
			drawCell(graphics, atlas, 0, 0,
				bounds.x - cornerOverhang, bounds.y - cornerOverhang, corner, corner);
			drawCell(graphics, atlas, 2, 0,
				bounds.x + bounds.width - corner + cornerOverhang,
				bounds.y - cornerOverhang, corner, corner);
			drawCell(graphics, atlas, 0, 2,
				bounds.x - cornerOverhang,
				bounds.y + bounds.height - corner + cornerOverhang, corner, corner);
			drawCell(graphics, atlas, 2, 2,
				bounds.x + bounds.width - corner + cornerOverhang,
				bounds.y + bounds.height - corner + cornerOverhang, corner, corner);

			if (bounds.width >= scaled(72, safeScale))
			{
				int centerX = bounds.x + (bounds.width - edgeWidth) / 2;
				drawCell(graphics, atlas, 1, 0,
					centerX, bounds.y - edgeOverhang, edgeWidth, edgeHeight);
				drawCell(graphics, atlas, 1, 2,
					centerX, bounds.y + bounds.height - edgeHeight + edgeOverhang,
					edgeWidth, edgeHeight);
			}

			if (bounds.height >= scaled(48, safeScale))
			{
				int centerY = bounds.y + (bounds.height - edgeHeight) / 2;
				drawCell(graphics, atlas, 0, 1,
					bounds.x - edgeOverhang, centerY, edgeHeight, edgeHeight);
				drawCell(graphics, atlas, 2, 1,
					bounds.x + bounds.width - edgeHeight + edgeOverhang,
					centerY, edgeHeight, edgeHeight);
			}
		}
		finally
		{
			graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				oldInterpolation == null ? RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR
					: oldInterpolation);
		}
	}

	private static void drawCell(Graphics2D graphics, BufferedImage atlas, int column, int row,
		int x, int y, int width, int height)
	{
		int cellWidth = atlas.getWidth() / ATLAS_COLUMNS;
		int cellHeight = atlas.getHeight() / ATLAS_COLUMNS;
		int sourceX = column * cellWidth;
		int sourceY = row * cellHeight;
		graphics.drawImage(atlas,
			x, y, x + width, y + height,
			sourceX, sourceY, sourceX + cellWidth, sourceY + cellHeight, null);
	}

	private static int scaled(int pixels, double scale)
	{
		return Math.max(1, (int) Math.round(pixels * scale));
	}
}

