package com.idlefamiliar;

import com.google.inject.Injector;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.xptracker.XpTrackerPlugin;
import net.runelite.client.plugins.xptracker.XpTrackerService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Owns per-login skill XP/level baselines and the skill icon/XP-rate values
 * published to the widget. RuneLite events remain in the plugin; it supplies
 * primitive observations in their original order.
 */
final class SkillProgressTracker
{
	private static final Logger log = LoggerFactory.getLogger(SkillProgressTracker.class);
	private static final int XP_TRACKER_LOOKUP_RETRY_TICKS = 50;

	private PluginManager pluginManager;
	private SpriteManager spriteManager;
	private final XpRateTracker xpRateTracker = new XpRateTracker();
	private final Map<Skill, Integer> lastSkillLevels = new HashMap<>();
	private final Map<Skill, Integer> lastSkillXp = new HashMap<>();

	private XpTrackerService xpTrackerService;
	private boolean xpTrackerLogged;
	private int nextXpTrackerLookupTick;
	private Integer cachedSkillSpriteId;
	private BufferedImage confirmedSkillIcon;
	private String cachedXpHr;

	SkillProgressTracker(PluginManager pluginManager, SpriteManager spriteManager)
	{
		this.pluginManager = pluginManager;
		this.spriteManager = spriteManager;
	}

	void configure(PluginManager pluginManager, SpriteManager spriteManager)
	{
		this.pluginManager = pluginManager;
		this.spriteManager = spriteManager;
	}

	void reset()
	{
		xpRateTracker.reset();
		xpTrackerService = null;
		xpTrackerLogged = false;
		nextXpTrackerLookupTick = 0;
		lastSkillLevels.clear();
		lastSkillXp.clear();
		cachedSkillSpriteId = null;
		confirmedSkillIcon = null;
		cachedXpHr = null;
	}

	void primeXpCache(Client client)
	{
		if (client == null || !lastSkillXp.isEmpty())
		{
			return;
		}
		for (Skill skill : Skill.values())
		{
			try
			{
				lastSkillXp.put(skill, client.getSkillExperience(skill));
			}
			catch (RuntimeException ignored)
			{
				// Synthetic enum values, if present, may have no client XP value.
			}
		}
	}

	SkillChange record(Skill skill, int xp, int level, long nowMillis)
	{
		Integer previousLevel = lastSkillLevels.put(skill, level);
		boolean levelUp = previousLevel != null && level > previousLevel;

		Integer previousXp = lastSkillXp.put(skill, xp);
		boolean activeXpGain = previousXp != null && xp > previousXp;
		String skillName = skill.getName();
		if (!SkillingActivityTracker.isPassiveSkill(skillName) || activeXpGain)
		{
			xpRateTracker.record(skillName, xp, nowMillis);
		}
		return new SkillChange(activeXpGain, levelUp);
	}

	/** Refresh both widget values from one confirmed-skill observation. */
	void updatePublishedValues(String confirmedSkill, boolean showXpRate,
		int currentTick, long nowMillis)
	{
		updateConfirmedSkillIcon(confirmedSkill);
		if (!showXpRate)
		{
			cachedXpHr = null;
			return;
		}
		cachedXpHr = confirmedSkill == null ? null
			: XpRateTracker.formatRate(xpHrFor(confirmedSkill, currentTick, nowMillis));
	}

	BufferedImage confirmedSkillIcon()
	{
		return confirmedSkillIcon;
	}

	String cachedXpHr()
	{
		return cachedXpHr;
	}

	private long xpHrFor(String skill, int currentTick, long nowMillis)
	{
		Skill resolved = resolveSkill(skill);
		XpTrackerService service = resolveXpTracker(currentTick);
		if (service != null && resolved != null)
		{
			int rate = service.getXpHr(resolved);
			if (rate > 0)
			{
				return rate;
			}
		}
		return xpRateTracker.ratePerHour(skill, nowMillis);
	}

	private XpTrackerService resolveXpTracker(int currentTick)
	{
		if (xpTrackerService != null)
		{
			return xpTrackerService;
		}
		if (pluginManager == null || currentTick < nextXpTrackerLookupTick)
		{
			return null;
		}
		nextXpTrackerLookupTick = currentTick + XP_TRACKER_LOOKUP_RETRY_TICKS;
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (plugin instanceof XpTrackerPlugin)
			{
				Injector injector = plugin.getInjector();
				if (injector != null)
				{
					try
					{
						xpTrackerService = injector.getInstance(XpTrackerService.class);
					}
					catch (RuntimeException ex)
					{
						log.debug("XpTrackerService not available from the XP Tracker plugin injector", ex);
					}
				}
				break;
			}
		}
		if (xpTrackerService != null && !xpTrackerLogged)
		{
			xpTrackerLogged = true;
			log.info("[idle-familiar] XP/hr now sourced from the XP Tracker plugin");
		}
		return xpTrackerService;
	}

	private void updateConfirmedSkillIcon(String confirmedSkill)
	{
		Integer spriteId = SkillIcons.spriteId(confirmedSkill);
		if (spriteId == null)
		{
			cachedSkillSpriteId = null;
			confirmedSkillIcon = null;
			return;
		}
		if (!spriteId.equals(cachedSkillSpriteId))
		{
			cachedSkillSpriteId = spriteId;
			confirmedSkillIcon = null;
		}
		if (confirmedSkillIcon == null && spriteManager != null)
		{
			confirmedSkillIcon = spriteManager.getSprite(spriteId, 0);
		}
	}

	static boolean isLikelyCombatStat(Skill skill)
	{
		return skill == Skill.ATTACK || skill == Skill.STRENGTH
			|| skill == Skill.DEFENCE || skill == Skill.RANGED
			|| skill == Skill.MAGIC || skill == Skill.HITPOINTS;
	}

	static String combatStyle(Skill skill)
	{
		if (skill == Skill.ATTACK || skill == Skill.STRENGTH || skill == Skill.DEFENCE)
		{
			return "melee";
		}
		if (skill == Skill.RANGED)
		{
			return "ranged";
		}
		if (skill == Skill.MAGIC)
		{
			return "magic";
		}
		return null;
	}

	private static Skill resolveSkill(String name)
	{
		if (name == null)
		{
			return null;
		}
		try
		{
			return Skill.valueOf(name.toUpperCase(Locale.ROOT).replace(' ', '_'));
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
	}

	static final class SkillChange
	{
		private final boolean activeXpGain;
		private final boolean levelUp;

		private SkillChange(boolean activeXpGain, boolean levelUp)
		{
			this.activeXpGain = activeXpGain;
			this.levelUp = levelUp;
		}

		boolean activeXpGain()
		{
			return activeXpGain;
		}

		boolean levelUp()
		{
			return levelUp;
		}
	}
}

package com.idlefamiliar;

import java.awt.GraphicsEnvironment;
import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.Function;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import net.runelite.client.config.ConfigManager;

/** Owns display-preset confirmation, bulk writes and Custom-transition policy. */
final class DisplayPresetController
{
	@FunctionalInterface
	interface ConfigurationWriter
	{
		void set(String key, Object value);
	}

	@FunctionalInterface
	interface ConfirmationRequester
	{
		void request(DisplayPreset preset, Consumer<Boolean> completion);
	}

	private final IdleFamiliarConfig config;
	private final ConfigurationWriter configurationWriter;
	private final Consumer<DisplayPreset> afterPresetApplied;
	private final BooleanSupplier headless;
	private final ConfirmationRequester confirmationRequester;
	private final Function<String, String> configurationReader;

	private volatile boolean applyingPreset;
	private volatile DisplayPreset pendingConfirmation;

	DisplayPresetController(IdleFamiliarConfig config, ConfigManager configManager,
		DesktopUiCoordinator desktopUi)
	{
		this(config,
			(key, value) -> configManager.setConfiguration(
				IdleFamiliarConfig.GROUP, key, value),
			desktopUi::refreshAfterPreset,
			GraphicsEnvironment::isHeadless,
			DisplayPresetController::showConfirmation,
			key -> configManager.getConfiguration(IdleFamiliarConfig.GROUP, key));
	}

	DisplayPresetController(IdleFamiliarConfig config,
		ConfigurationWriter configurationWriter,
		Consumer<DisplayPreset> afterPresetApplied,
		BooleanSupplier headless,
		ConfirmationRequester confirmationRequester)
	{
		this(config, configurationWriter, afterPresetApplied, headless,
			confirmationRequester, key -> null);
	}

	DisplayPresetController(IdleFamiliarConfig config,
		ConfigurationWriter configurationWriter,
		Consumer<DisplayPreset> afterPresetApplied,
		BooleanSupplier headless,
		ConfirmationRequester confirmationRequester,
		Function<String, String> configurationReader)
	{
		this.config = config;
		this.configurationWriter = configurationWriter;
		this.afterPresetApplied = afterPresetApplied;
		this.headless = headless;
		this.confirmationRequester = confirmationRequester;
		this.configurationReader = configurationReader;
	}

	/**
	 * A preset selection is persisted before its asynchronous confirmation can
	 * finish. On startup, retain that name only when every owned value was
	 * committed; otherwise the honest persisted state is Custom.
	 */
	void reconcileSavedSelection()
	{
		DisplayPreset preset = config == null ? null : config.displayPreset();
		if (preset == null || preset == DisplayPreset.CUSTOM)
		{
			return;
		}
		for (String key : preset.settings().keySet())
		{
			if (!preset.matchesSetting(key, configurationReader.apply(key)))
			{
				configurationWriter.set("displayPreset", DisplayPreset.CUSTOM);
				return;
			}
		}
	}

	void onConfigChanged(String key, String newValue)
	{
		if ("displayPreset".equals(key) && !applyingPreset)
		{
			request(DisplayPreset.fromConfigValue(newValue));
			return;
		}

		DisplayPreset activePreset = config.displayPreset();
		if (!applyingPreset && DisplayPreset.controls(key)
			&& activePreset != null && activePreset != DisplayPreset.CUSTOM
			// Delivery can occur after the synchronous bulk-write guard. Matching
			// values still belong to the preset, not a manual customization.
			&& !activePreset.matchesSetting(key, newValue))
		{
			pendingConfirmation = null;
			configurationWriter.set("displayPreset", DisplayPreset.CUSTOM);
		}
	}

	void cancelPending()
	{
		DisplayPreset cancelled = pendingConfirmation;
		pendingConfirmation = null;
		if (cancelled != null)
		{
			configurationWriter.set("displayPreset", DisplayPreset.CUSTOM);
		}
	}

	void apply(DisplayPreset preset)
	{
		if (preset == null || preset == DisplayPreset.CUSTOM)
		{
			return;
		}

		applyingPreset = true;
		try
		{
			for (Map.Entry<String, Object> setting : preset.settings().entrySet())
			{
				configurationWriter.set(setting.getKey(), setting.getValue());
			}
		}
		finally
		{
			applyingPreset = false;
		}
		afterPresetApplied.accept(preset);
	}

	private void request(DisplayPreset preset)
	{
		if (preset == null || preset == DisplayPreset.CUSTOM)
		{
			pendingConfirmation = null;
			return;
		}
		if (!preset.changesAlertOrSoundIntensity(config) || headless.getAsBoolean())
		{
			pendingConfirmation = null;
			apply(preset);
			return;
		}

		pendingConfirmation = preset;
		confirmationRequester.request(preset, confirmed ->
		{
			if (pendingConfirmation != preset)
			{
				return;
			}
			pendingConfirmation = null;
			if (confirmed)
			{
				apply(preset);
			}
			else
			{
				configurationWriter.set("displayPreset", DisplayPreset.CUSTOM);
			}
		});
	}

	private static void showConfirmation(DisplayPreset preset,
		Consumer<Boolean> completion)
	{
		SwingUtilities.invokeLater(() ->
		{
			int result = JOptionPane.showConfirmDialog(null,
				preset + " will update the widget layout, visual alerts, and sound preferences.\n"
					+ "Window position and personal chat phrases will be preserved.\n\nApply this preset?",
				"Apply Idle Familiar preset", JOptionPane.YES_NO_OPTION,
				JOptionPane.QUESTION_MESSAGE);
			completion.accept(result == JOptionPane.YES_OPTION);
		});
	}
}

package com.idlefamiliar;

public class IdleStateTracker
{
	private int currentTick;
	private int lastActivityTick;
	private ActivityType lastActivityType = ActivityType.UNKNOWN;

	public void reset(int tick)
	{
		currentTick = tick;
		lastActivityTick = tick;
		lastActivityType = ActivityType.UNKNOWN;
	}

	public void setCurrentTick(int currentTick)
	{
		this.currentTick = currentTick;
	}

	public void markActivity(ActivityType activityType)
	{
		lastActivityTick = currentTick;
		lastActivityType = activityType;
	}

	public int getCurrentTick()
	{
		return currentTick;
	}

	public int getTicksSinceActivity()
	{
		return Math.max(0, currentTick - lastActivityTick);
	}

	public ActivityType getLastActivityType()
	{
		return lastActivityType;
	}

	public boolean isIdle(int idleThresholdTicks)
	{
		return getTicksSinceActivity() >= idleThresholdTicks;
	}

	public boolean isAfkWarning(int afkWarningThresholdTicks)
	{
		return getTicksSinceActivity() >= afkWarningThresholdTicks;
	}
}

