package com.idlefamiliar;

import net.runelite.api.ChatMessageType;

public final class ChatSoundFilter
{
	private ChatSoundFilter()
	{
	}

	public static boolean isAudible(ChatMessageType type, String message)
	{
		if (message != null && message.startsWith("Idle Familiar:"))
		{
			return false;
		}
		return type == ChatMessageType.PUBLICCHAT
			|| type == ChatMessageType.MODCHAT
			|| type == ChatMessageType.PRIVATECHAT
			|| type == ChatMessageType.MODPRIVATECHAT
			|| type == ChatMessageType.FRIENDSCHAT
			|| type == ChatMessageType.CLAN_CHAT
			|| type == ChatMessageType.CLAN_MESSAGE
			|| type == ChatMessageType.CLAN_GUEST_CHAT
			|| type == ChatMessageType.CLAN_GUEST_MESSAGE
			|| type == ChatMessageType.CLAN_GIM_CHAT
			|| type == ChatMessageType.CLAN_GIM_MESSAGE
			|| type == ChatMessageType.TRADE
			|| type == ChatMessageType.TRADEREQ;
	}

	static String matchedTriggerFilter(ChatMessageType type, String message,
		ChatMessageMatcher.CompiledFilters filters)
	{
		if (message != null && message.startsWith("Idle Familiar:"))
		{
			return null;
		}
		if (type == ChatMessageType.SPAM || type == ChatMessageType.UNKNOWN)
		{
			return null;
		}
		return ChatMessageMatcher.matchedFilter(message, filters);
	}
}

package com.idlefamiliar;

import net.runelite.api.ItemID;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.WorldPoint;

/** Emits verified Woodcutting evidence without owning ETA lifecycle. */
final class WoodcuttingRecognizer
{
	private final ActivityAnimationRegistry animationRegistry;
	private final ActivityEvidenceTracker activityEvidence;
	private final GatheringResourceTracker resourceTracker;
	private final ExtendedInventoryTracker extendedInventoryTracker;

	private PendingStorageStart pendingStorageStart;

	WoodcuttingRecognizer(ActivityAnimationRegistry animationRegistry,
		ActivityEvidenceTracker activityEvidence,
		GatheringResourceTracker resourceTracker,
		ExtendedInventoryTracker extendedInventoryTracker)
	{
		this.animationRegistry = animationRegistry;
		this.activityEvidence = activityEvidence;
		this.resourceTracker = resourceTracker;
		this.extendedInventoryTracker = extendedInventoryTracker;
	}

	void reset()
	{
		pendingStorageStart = null;
	}

	boolean isWoodcuttingAnimation(int animationId)
	{
		return "Woodcutting".equals(
			animationRegistry.activityForAnimation(animationId));
	}

	/** Record live animation evidence and report whether it is Woodcutting. */
	boolean onAnimation(int animationId, int tick)
	{
		if (!isWoodcuttingAnimation(animationId))
		{
			return false;
		}
		activityEvidence.mark(ActivityEvidenceTracker.Signal.WOODCUTTING, tick);
		return true;
	}

	/**
	 * Capture the exact tree and click tick that starts its natural active timer.
	 * A pending basket start is armed only under the existing assumed-capacity
	 * policy; this method deliberately does not change that policy.
	 */
	void onTreeInteraction(MenuAction action, String normalizedOption,
		String normalizedTarget, int objectId, WorldPoint location, int tick,
		InventoryState inventory, InventoryState equipment)
	{
		if (!ActivityDetector.isGameObjectAction(action)
			|| (!"chop down".equals(normalizedOption) && !"chop".equals(normalizedOption)))
		{
			return;
		}

		WoodcuttingCatalog.Tree tree = treeForMenuTarget(normalizedTarget);
		if (tree == null)
		{
			return;
		}

		resourceTracker.recordWoodcuttingInteraction(tree, objectId, location, tick);
		if (extendedInventoryTracker.hasOpenLogBasket(inventory, equipment)
			&& !extendedInventoryTracker.isKnownFull(
				ExtendedInventoryTracker.Container.LOG_BASKET))
		{
			pendingStorageStart = new PendingStorageStart(tree, tick);
		}
		else
		{
			pendingStorageStart = null;
		}
	}

	/**
	 * Consume a basket-backed start only after chopping actually begins.
	 */
	StorageStart detectPendingStorageStart(InventoryState inventory,
		InventoryState equipment, int effectiveLevel, int tick, int graceTicks)
	{
		if (pendingStorageStart == null)
		{
			return null;
		}

		int age = tick - pendingStorageStart.interactionTick;
		if (age < 0 || age > graceTicks)
		{
			pendingStorageStart = null;
			return null;
		}
		if (!extendedInventoryTracker.hasOpenLogBasket(inventory, equipment))
		{
			pendingStorageStart = null;
			return null;
		}

		WoodcuttingCatalog.AxeTier axeTier = resolveAxeTier(inventory, equipment);
		boolean eligible = axeTier != null
			&& !hasUnsupportedModifier(inventory, equipment);
		StorageStart result = new StorageStart(
			pendingStorageStart.tree,
			axeTier,
			effectiveLevel,
			inventory.occupiedSlots(),
			ExtendedInventoryTracker.Container.LOG_BASKET.capacity(),
			eligible,
			resourceTracker.remainingWoodcuttingHorizon(pendingStorageStart.tree, tick));
		pendingStorageStart = null;
		return result;
	}

	/**
	 * Strictly recognise one supported non-stackable log result. Nests,
	 * Forestry outputs, banking and unrelated simultaneous changes are rejected.
	 */
	LogResult detectLog(InventoryChange change, InventoryState equipment,
		boolean playerPresent, int animationId, int effectiveLevel, int tick,
		int graceTicks)
	{
		boolean choppingJustNow = playerPresent
			&& (isWoodcuttingAnimation(animationId)
				|| activityEvidence.isRecent(ActivityEvidenceTracker.Signal.WOODCUTTING,
					tick, graceTicks));
		if (change == null || !change.hasBaseline() || !choppingJustNow)
		{
			return null;
		}

		InventoryState before = change.before();
		InventoryState after = change.after();
		Integer producedLogId = null;
		for (Integer itemId : change.delta().itemIds())
		{
			int quantityDelta = after.quantity(itemId) - before.quantity(itemId);
			if (quantityDelta == 0)
			{
				continue;
			}
			if (quantityDelta != 1 || treeForLog(itemId) == null || producedLogId != null)
			{
				return null;
			}
			producedLogId = itemId;
		}

		if (producedLogId == null)
		{
			return null;
		}

		WoodcuttingCatalog.Tree tree = treeForLog(producedLogId);
		activityEvidence.mark(ActivityEvidenceTracker.Signal.WOODCUTTING, tick);
		if (extendedInventoryTracker.hasOpenLogBasket(after, equipment))
		{
			extendedInventoryTracker.markFull(ExtendedInventoryTracker.Container.LOG_BASKET);
		}
		else
		{
			extendedInventoryTracker.markEmptyOrUnknown(
				ExtendedInventoryTracker.Container.LOG_BASKET);
		}

		WoodcuttingCatalog.AxeTier axeTier = resolveAxeTier(after, equipment);
		boolean eligible = axeTier != null && !hasUnsupportedModifier(after, equipment);
		return new LogResult(tree, axeTier, effectiveLevel, after.occupiedSlots(), 1,
			eligible, resourceTracker.remainingWoodcuttingHorizon(tree, tick));
	}

	static boolean isWoodcuttingEtaLabel(String label)
	{
		return label != null && (label.startsWith("Oak (") || label.startsWith("Willow (")
			|| label.startsWith("Teak (") || label.startsWith("Maple (")
			|| label.startsWith("Mahogany (") || label.startsWith("Yew (")
			|| label.startsWith("Magic (") || label.startsWith("Redwood (")
			|| label.startsWith("Camphor ("));
	}

	private static WoodcuttingCatalog.Tree treeForLog(int itemId)
	{
		switch (itemId)
		{
			case ItemID.OAK_LOGS:
				return WoodcuttingCatalog.Tree.OAK;
			case ItemID.WILLOW_LOGS:
				return WoodcuttingCatalog.Tree.WILLOW;
			case ItemID.TEAK_LOGS:
				return WoodcuttingCatalog.Tree.TEAK;
			case ItemID.MAPLE_LOGS:
				return WoodcuttingCatalog.Tree.MAPLE;
			case ItemID.MAHOGANY_LOGS:
				return WoodcuttingCatalog.Tree.MAHOGANY;
			case ItemID.YEW_LOGS:
				return WoodcuttingCatalog.Tree.YEW;
			case ItemID.MAGIC_LOGS:
				return WoodcuttingCatalog.Tree.MAGIC;
			case ItemID.REDWOOD_LOGS:
				return WoodcuttingCatalog.Tree.REDWOOD;
			case ItemID.CAMPHOR_LOGS:
				return WoodcuttingCatalog.Tree.CAMPHOR;
			default:
				return null;
		}
	}

	private static WoodcuttingCatalog.Tree treeForMenuTarget(String target)
	{
		if (target == null)
		{
			return null;
		}
		if (target.contains("redwood"))
		{
			return WoodcuttingCatalog.Tree.REDWOOD;
		}
		if (target.contains("camphor"))
		{
			return WoodcuttingCatalog.Tree.CAMPHOR;
		}
		if (target.contains("mahogany"))
		{
			return WoodcuttingCatalog.Tree.MAHOGANY;
		}
		if (target.contains("willow"))
		{
			return WoodcuttingCatalog.Tree.WILLOW;
		}
		if (target.contains("maple"))
		{
			return WoodcuttingCatalog.Tree.MAPLE;
		}
		if (target.contains("magic"))
		{
			return WoodcuttingCatalog.Tree.MAGIC;
		}
		if (target.contains("teak"))
		{
			return WoodcuttingCatalog.Tree.TEAK;
		}
		if (target.contains("yew"))
		{
			return WoodcuttingCatalog.Tree.YEW;
		}
		return target.contains("oak") ? WoodcuttingCatalog.Tree.OAK : null;
	}

	private static WoodcuttingCatalog.AxeTier resolveAxeTier(InventoryState inventory,
		InventoryState equipment)
	{
		WoodcuttingCatalog.AxeTier best = bestAxe(inventory, null);
		return bestAxe(equipment, best);
	}

	private static WoodcuttingCatalog.AxeTier bestAxe(InventoryState items,
		WoodcuttingCatalog.AxeTier currentBest)
	{
		WoodcuttingCatalog.AxeTier best = currentBest;
		for (Integer itemId : items.itemCounts().keySet())
		{
			WoodcuttingCatalog.AxeTier tier = axeTierFor(itemId);
			if (tier != null && (best == null || tier.ordinal() > best.ordinal()))
			{
				best = tier;
			}
		}
		return best;
	}

	private static WoodcuttingCatalog.AxeTier axeTierFor(int itemId)
	{
		switch (itemId)
		{
			case ItemID.BRONZE_AXE:
				return WoodcuttingCatalog.AxeTier.BRONZE;
			case ItemID.IRON_AXE:
				return WoodcuttingCatalog.AxeTier.IRON;
			case ItemID.STEEL_AXE:
				return WoodcuttingCatalog.AxeTier.STEEL;
			case ItemID.BLACK_AXE:
				return WoodcuttingCatalog.AxeTier.BLACK;
			case ItemID.MITHRIL_AXE:
				return WoodcuttingCatalog.AxeTier.MITHRIL;
			case ItemID.ADAMANT_AXE:
				return WoodcuttingCatalog.AxeTier.ADAMANT;
			case ItemID.RUNE_AXE:
				return WoodcuttingCatalog.AxeTier.RUNE;
			case ItemID.DRAGON_AXE:
			case ItemID.DRAGON_AXE_OR:
			case ItemID.DRAGON_AXE_OR_30352:
				return WoodcuttingCatalog.AxeTier.DRAGON;
			case ItemID.CRYSTAL_AXE:
			case ItemID.CRYSTAL_AXE_23862:
				return WoodcuttingCatalog.AxeTier.CRYSTAL;
			default:
				return null;
		}
	}

	private static boolean hasUnsupportedModifier(InventoryState inventory,
		InventoryState equipment)
	{
		return containsUnsupportedItem(inventory) || containsUnsupportedItem(equipment);
	}

	private static boolean containsUnsupportedItem(InventoryState items)
	{
		for (Integer itemId : items.itemCounts().keySet())
		{
			if (isUnsupportedItem(itemId))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean isUnsupportedItem(int itemId)
	{
		switch (itemId)
		{
			case ItemID.INFERNAL_AXE:
			case ItemID.INFERNAL_AXE_UNCHARGED:
			case ItemID.INFERNAL_AXE_OR:
			case ItemID.INFERNAL_AXE_OR_30347:
			case ItemID.INFERNAL_AXE_UNCHARGED_30348:
			case ItemID.BRONZE_FELLING_AXE:
			case ItemID.IRON_FELLING_AXE:
			case ItemID.STEEL_FELLING_AXE:
			case ItemID.BLACK_FELLING_AXE:
			case ItemID.MITHRIL_FELLING_AXE:
			case ItemID.ADAMANT_FELLING_AXE:
			case ItemID.RUNE_FELLING_AXE:
			case ItemID.DRAGON_FELLING_AXE:
			case ItemID.CRYSTAL_FELLING_AXE:
			case ItemID.CRYSTAL_FELLING_AXE_INACTIVE:
			case ItemID._3RD_AGE_FELLING_AXE:
			case ItemID.KANDARIN_HEADGEAR:
			case ItemID.KANDARIN_HEADGEAR_1:
			case ItemID.KANDARIN_HEADGEAR_2:
			case ItemID.KANDARIN_HEADGEAR_3:
			case ItemID.KANDARIN_HEADGEAR_4:
				return true;
			default:
				return false;
		}
	}

	static final class LogResult
	{
		private final WoodcuttingCatalog.Tree tree;
		private final WoodcuttingCatalog.AxeTier axeTier;
		private final int effectiveLevel;
		private final int occupiedSlots;
		private final int producedSlots;
		private final boolean eligible;
		private final int despawnRemainingTicks;

		private LogResult(WoodcuttingCatalog.Tree tree,
