			int occupiedSlots, int producedSlots, boolean eligible,
			int despawnRemainingTicks)
		{
			this.tree = tree;
			this.axeTier = axeTier;
			this.effectiveLevel = effectiveLevel;
			this.occupiedSlots = occupiedSlots;
			this.producedSlots = producedSlots;
			this.eligible = eligible;
			this.despawnRemainingTicks = despawnRemainingTicks;
		}

		WoodcuttingCatalog.Tree tree()
		{
			return tree;
		}

		WoodcuttingCatalog.AxeTier axeTier()
