		private StorageStart(WoodcuttingCatalog.Tree tree,
			WoodcuttingCatalog.AxeTier axeTier, int effectiveLevel,
			int occupiedSlots, int extraCapacity, boolean eligible,
			int despawnRemainingTicks)
		{
