			this.extraCapacity = extraCapacity;
			this.eligible = eligible;
			this.despawnRemainingTicks = despawnRemainingTicks;
		}

		WoodcuttingCatalog.Tree tree()
		{
			return tree;
		}

		WoodcuttingCatalog.AxeTier axeTier()
