package com.idlefamiliar;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.stream.ImageInputStream;

public class SpriteSheetLoader
{
	/** Hard ceiling applied from image metadata before PNG pixels are decoded. */
	static final long DEFAULT_MAX_DECODED_PIXELS = 1_048_576L;
	private final long maxDecodedPixels;

	public SpriteSheetLoader()
	{
		this(DEFAULT_MAX_DECODED_PIXELS);
	}

	SpriteSheetLoader(long maxDecodedPixels)
	{
		if (maxDecodedPixels <= 0)
		{
			throw new IllegalArgumentException("Maximum decoded pixels must be positive");
		}
		this.maxDecodedPixels = maxDecodedPixels;
	}

	/** Slices and closes a PNG stream from either bundled or local storage. */
	public AvatarAnimation load(InputStream stream, String sourceName, long frameDurationMillis) throws IOException
	{
		try (InputStream managed = stream)
		{
			if (managed == null)
			{
				throw new IOException("Sprite resource not found: " + sourceName);
			}

			try (ImageInputStream imageInput = ImageIO.createImageInputStream(managed))
			{
				if (imageInput == null)
				{
					throw new IOException("Sprite resource could not be read: " + sourceName);
				}
				Iterator<ImageReader> readers = ImageIO.getImageReaders(imageInput);
				if (!readers.hasNext())
				{
					throw new IOException("Sprite resource could not be read: " + sourceName);
				}

				ImageReader reader = readers.next();
				try
				{
					reader.setInput(imageInput, true, true);
					int width = reader.getWidth(0);
					int height = reader.getHeight(0);
					validateDimensions(width, height, sourceName);
					BufferedImage sheet = reader.read(0);
					if (sheet == null)
					{
						throw new IOException("Sprite resource could not be read: " + sourceName);
					}
					return slice(sheet, height, height, frameDurationMillis);
				}
				finally
				{
					reader.dispose();
				}
			}
		}
	}

	private void validateDimensions(int width, int height, String sourceName) throws IOException
	{
		if (width <= 0 || height <= 0 || width % height != 0)
		{
			throw new IOException("Sprite sheet width must be a whole multiple of its height: "
				+ sourceName);
		}
		long decodedPixels = (long) width * height;
		if (decodedPixels > maxDecodedPixels)
		{
			throw new IOException("Sprite sheet exceeds the decoded-pixel limit ("
				+ decodedPixels + " > " + maxDecodedPixels + "): " + sourceName);
		}
	}

	private AvatarAnimation slice(BufferedImage sheet, int frameWidth, int frameHeight, long frameDurationMillis) throws IOException
	{
		if (frameWidth <= 0 || frameHeight <= 0 || sheet.getWidth() < frameWidth || sheet.getHeight() < frameHeight)
		{
			throw new IOException("Invalid sprite sheet dimensions");
		}

		List<BufferedImage> frames = new ArrayList<>();
		int columns = sheet.getWidth() / frameWidth;
		int rows = sheet.getHeight() / frameHeight;
		for (int y = 0; y < rows; y++)
		{
			for (int x = 0; x < columns; x++)
			{
				frames.add(sheet.getSubimage(x * frameWidth, y * frameHeight, frameWidth, frameHeight));
			}
		}

		if (frames.isEmpty())
		{
			throw new IOException("Sprite sheet contained no frames");
		}

		return new AvatarAnimation(frames, frameDurationMillis, true);
	}
}

package com.idlefamiliar;

/**
 * Recognises shipwreck hook yields and salvage-station queues without owning
 * ETA lifecycle state.
 */
final class SalvageActivityDetector
{
	private final ActivityEvidenceTracker evidence;

	SalvageActivityDetector(ActivityEvidenceTracker evidence)
	{
		this.evidence = evidence;
	}

	SortingQueue sortingStart(InventoryState inventory, boolean banking)
	{
		int units = SalvageSortingCatalog.sortableUnits(inventory.itemCounts());
		// A ship's world coordinates can change while the player remains engaged
		// with its station. The exact station pose is stronger evidence than the
		// generic movement flag; banking still makes the queue ineligible.
		return new SortingQueue(units, units > 0 && !banking);
	}

	GatheringStart gatheringStart(InventoryState inventory, boolean moved, boolean banking)
	{
		return new GatheringStart(inventory.occupiedSlots(), !moved && !banking);
	}

	InventoryEvidence detectInventory(InventoryChange change, EtaActivity activeActivity,
		int tick, boolean moved, boolean banking, int animationGraceTicks)
	{
		if (change == null)
		{
			return InventoryEvidence.none();
		}

		SortingQueue sorting = null;
		if (activeActivity == EtaActivity.SALVAGE_SORTING)
		{
			int beforeUnits = SalvageSortingCatalog.sortableUnits(
				change.before().itemCounts());
			int remainingUnits = SalvageSortingCatalog.sortableUnits(
				change.after().itemCounts());
			if (remainingUnits != beforeUnits)
			{
				boolean stationRecent = evidence.isRecent(
					ActivityEvidenceTracker.Signal.SALVAGE_SORTING, tick,
					SalvageSortingCatalog.TICKS_PER_ITEM + 1);
				sorting = new SortingQueue(remainingUnits,
					stationRecent && remainingUnits < beforeUnits && !banking);
			}
		}

		int beforeUnits = SalvageSortingCatalog.sortableUnits(change.before().itemCounts());
		int afterUnits = SalvageSortingCatalog.sortableUnits(change.after().itemCounts());
		int producedSalvage = afterUnits - beforeUnits;
		int producedSlots = change.hasBaseline()
			? change.after().occupiedSlots() - change.before().occupiedSlots() : 0;
		ObservedYield yield = null;
		boolean cancelGathering = false;
		if (producedSalvage > 0)
		{
			boolean hookRecent = evidence.isRecent(
				ActivityEvidenceTracker.Signal.SALVAGE_GATHERING, tick,
				animationGraceTicks);
			boolean verified = hookRecent && producedSlots > 0
				&& producedSalvage == producedSlots && !moved && !banking;
			yield = new ObservedYield(change.after().occupiedSlots(), producedSlots, verified);
		}
		else if (activeActivity == EtaActivity.SALVAGE_GATHERING
			&& change.hasBaseline()
			&& change.after().occupiedSlots() != change.before().occupiedSlots())
		{
			cancelGathering = true;
		}

		return new InventoryEvidence(sorting, yield, cancelGathering);
	}

	static final class SortingQueue
	{
		final int remainingUnits;
		final boolean eligible;

		private SortingQueue(int remainingUnits, boolean eligible)
		{
			this.remainingUnits = remainingUnits;
			this.eligible = eligible;
		}
	}

	static final class GatheringStart
	{
		final int occupiedSlots;
		final boolean eligible;

		private GatheringStart(int occupiedSlots, boolean eligible)
		{
			this.occupiedSlots = occupiedSlots;
			this.eligible = eligible;
		}
	}

	static final class ObservedYield
	{
		final int occupiedSlots;
		final int producedSlots;
		final boolean eligible;

		private ObservedYield(int occupiedSlots, int producedSlots, boolean eligible)
		{
			this.occupiedSlots = occupiedSlots;
			this.producedSlots = producedSlots;
			this.eligible = eligible;
		}
	}

	static final class InventoryEvidence
	{
		private static final InventoryEvidence NONE =
			new InventoryEvidence(null, null, false);

		final SortingQueue sorting;
		final ObservedYield yield;
		final boolean cancelGathering;

		private InventoryEvidence(SortingQueue sorting, ObservedYield yield,
			boolean cancelGathering)
		{
			this.sorting = sorting;
			this.yield = yield;
			this.cancelGathering = cancelGathering;
		}

		static InventoryEvidence none()
		{
			return NONE;
		}
	}
}

package com.idlefamiliar;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/** Coherent local presentation configurations; no preset changes window position or personal text. */
public enum DisplayPreset
{
	CUSTOM("Custom"),
	QUIET_MONITOR("Quiet monitor"),
	AFK_SKILLING("AFK skilling"),
	COMBAT_WATCH("Combat watch"),
	COMPANION("Companion"),
	MINIMAL("Minimal");

	private final String label;

	DisplayPreset(String label)
	{
		this.label = label;
	}

	Map<String, Object> settings()
	{
		if (this == CUSTOM)
		{
			return Collections.emptyMap();
		}
		Map<String, Object> values = new LinkedHashMap<>();
			switch (this)
		{
			case QUIET_MONITOR:
				common(values, 35, 72, false, false, true, true, true, true,
					InventoryDensity.STRIP, WidgetTheme.MINIMAL_GLASS, true);
				avatar(values, AvatarScale.X2, ScaleMultiplier.X1, true, true);
				attention(values, true, true, 20, true, 10, true, true,
					false, 45, true, false, true, true, true, false, 15, 60, 2);
				break;
			case AFK_SKILLING:
				common(values, 55, 95, false, false, true, false, true, true,
					InventoryDensity.MINI_GRID, WidgetTheme.CLASSIC_RUNESCAPE, true);
				avatar(values, AvatarScale.X2, ScaleMultiplier.X1, true, true);
				attention(values, true, true, 20, true, 10, true, true,
					true, 45, true, false, true, true, true, false, 15, 50, 2);
				break;
			case COMBAT_WATCH:
				common(values, 55, 100, true, true, false, false, false, true,
					InventoryDensity.OFF, WidgetTheme.HIGH_VISIBILITY, true);
				avatar(values, AvatarScale.X2, ScaleMultiplier.X1, false, true);
				attention(values, false, true, 30, true, 20, true, false,
					true, 55, false, false, false, true, true, false, 15, 60, 2);
				break;
			case COMPANION:
				common(values, 100, 100, true, true, true, false, true, true,
					InventoryDensity.MINI_GRID, WidgetTheme.CLASSIC_RUNESCAPE, false);
				avatar(values, AvatarScale.X3, ScaleMultiplier.X1, true, true);
				attention(values, true, true, 20, true, 10, true, true,
					false, 70, true, true, true, true, true, false, 15, 60, 2);
				break;
			case MINIMAL:
				common(values, 30, 80, false, false, false, false, true, true,
					InventoryDensity.OFF, WidgetTheme.MINIMAL_GLASS, true);
				avatar(values, AvatarScale.X2, ScaleMultiplier.X1, false, true);
				attention(values, true, true, 20, true, 10, true, false,
					false, 40, true, false, true, true, true, false, 15, 60, 2);
				break;
			default:
				break;
		}
		return Collections.unmodifiableMap(values);
	}

	private static void common(Map<String, Object> values, int avatarOpacity, int widgetOpacity,
		boolean hp, boolean prayer, boolean inventory, boolean xpRate, boolean taskEta, boolean shimmer,
		InventoryDensity density, WidgetTheme theme, boolean collapsed)
	{
		values.put("avatarOpacityPercent", avatarOpacity);
		values.put("widgetOpacityPercent", widgetOpacity);
		values.put("showHpOrb", hp);
		values.put("showPrayerOrb", prayer);
		values.put("showInventoryCount", inventory);
		values.put("showAdvancedInfo", xpRate);
		values.put("showTaskEta", taskEta);
		values.put("showAttentionShimmer", shimmer);
		values.put("showAttentionReason", true);
		values.put("etaCompleteSounds", taskEta);
		values.put("inventoryViewerAlwaysVisible", false);
		values.put("inventoryDensity", density);
		values.put("widgetTheme", theme);
		values.put("showWidgetFrame", true);
		values.put("widgetCollapsed", collapsed);
	}

	private static void avatar(Map<String, Object> values, AvatarScale scale,
		ScaleMultiplier animationSpeed, boolean skillIcon, boolean fullCycleAnimations)
	{
		values.put("avatarScale", scale);
		values.put("animationSpeed", animationSpeed);
		values.put("showSkillIcon", skillIcon);
		values.put("playFullCycleAnimations", fullCycleAnimations);
	}

	private static void attention(Map<String, Object> values,
		boolean inventoryWarning, boolean lowHpWarning, int lowHpThreshold,
		boolean lowPrayerWarning, int lowPrayerThreshold, boolean combatReaction,
		boolean skillingReaction, boolean sounds, int soundVolume,
		boolean inventorySounds, boolean idleSounds, boolean afkSounds,
		boolean lowPrayerSounds, boolean lowHpSounds, boolean chatSounds,
		int idleThreshold, int afkThreshold, int skillingLinger)
	{
		values.put("enableInventoryFullWarning", inventoryWarning);
		values.put("enableLowHpWarning", lowHpWarning);
		values.put("lowHpThreshold", lowHpThreshold);
		values.put("enableLowPrayerWarning", lowPrayerWarning);
		values.put("lowPrayerThreshold", lowPrayerThreshold);
		values.put("reactToCombat", combatReaction);
		values.put("reactToSkilling", skillingReaction);
		// External desktop notifications are deliberately opt-in for every preset.
		values.put("routeAttentionToRuneLite", false);
		values.put("enableSounds", sounds);
		values.put("soundVolumePercent", soundVolume);
		values.put("inventoryFullSounds", inventorySounds);
		values.put("idleSounds", idleSounds);
		values.put("afkSounds", afkSounds);
		values.put("lowPrayerSounds", lowPrayerSounds);
		values.put("lowHpSounds", lowHpSounds);
		values.put("chatMessageSounds", chatSounds);
		values.put("idleThresholdTicks", idleThreshold);
		values.put("afkWarningThresholdTicks", afkThreshold);
		values.put("skillingLingerTicks", skillingLinger);
	}

	static boolean controls(String configKey)
	{
		return configKey != null && (COMPANION.settings().containsKey(configKey)
			// Presets never replace a user's phrases, but editing them still means
			// the active sound configuration is now custom.
			|| "chatMessageFilters".equals(configKey));
	}

	boolean changesAlertOrSoundIntensity(IdleFamiliarConfig config)
	{
		if (this == CUSTOM || config == null)
		{
			return false;
		}
		Map<String, Object> values = settings();
		return differs(values, "enableInventoryFullWarning", config.enableInventoryFullWarning())
			|| differs(values, "enableLowHpWarning", config.enableLowHpWarning())
			|| differs(values, "lowHpThreshold", config.lowHpThreshold())
			|| differs(values, "enableLowPrayerWarning", config.enableLowPrayerWarning())
			|| differs(values, "lowPrayerThreshold", config.lowPrayerThreshold())
			|| differs(values, "reactToCombat", config.reactToCombat())
			|| differs(values, "reactToSkilling", config.reactToSkilling())
			|| differs(values, "routeAttentionToRuneLite", config.routeAttentionToRuneLite())
			|| differs(values, "showAttentionReason", config.showAttentionReason())
			|| differs(values, "enableSounds", config.enableSounds())
			|| differs(values, "soundVolumePercent", config.soundVolumePercent())
			|| differs(values, "inventoryFullSounds", config.inventoryFullSounds())
			|| differs(values, "idleSounds", config.idleSounds())
			|| differs(values, "afkSounds", config.afkSounds())
			|| differs(values, "lowPrayerSounds", config.lowPrayerSounds())
			|| differs(values, "lowHpSounds", config.lowHpSounds())
			|| differs(values, "chatMessageSounds", config.chatMessageSounds())
			|| differs(values, "etaCompleteSounds", config.etaCompleteSounds())
			|| differs(values, "idleThresholdTicks", config.idleThresholdTicks())
			|| differs(values, "afkWarningThresholdTicks", config.afkWarningThresholdTicks());
	}

	private static boolean differs(Map<String, Object> values, String key, Object current)
	{
		return !values.get(key).equals(current);
	}

	/**
	 * ConfigChanged normally carries an enum's constant name, while older or
	 * externally edited RuneLite profiles can contain its display label. Accept
	 * both representations so choosing a preset always applies it.
	 */
	static DisplayPreset fromConfigValue(String value)
	{
		if (value == null)
		{
			return CUSTOM;
		}
		String normalized = value.trim();
		for (DisplayPreset preset : values())
		{
			if (preset.name().equalsIgnoreCase(normalized) || preset.label.equalsIgnoreCase(normalized))
			{
				return preset;
			}
		}
		return CUSTOM;
	}

	/** True when a controlled ConfigChanged value is exactly this preset's value. */
	boolean matchesSetting(String configKey, String serializedValue)
	{
		Object expected = settings().get(configKey);
		if (expected == null || serializedValue == null)
		{
			return false;
		}
		if (expected instanceof Enum<?>)
		{
			Enum<?> expectedEnum = (Enum<?>) expected;
			return expectedEnum.name().equalsIgnoreCase(serializedValue)
				|| expected.toString().equalsIgnoreCase(serializedValue);
		}
		return String.valueOf(expected).equalsIgnoreCase(serializedValue);
	}

	@Override
	public String toString()
	{
		return label;
	}
}

