package com.idlefamiliar;

import net.runelite.api.MenuAction;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.game.FishingSpot;

/** Applies recognition precedence to one committed inventory change. */
final class ActivityDetector
{
	static boolean isGameObjectAction(MenuAction action)
	{
		return action == MenuAction.GAME_OBJECT_FIRST_OPTION
			|| action == MenuAction.GAME_OBJECT_SECOND_OPTION
			|| action == MenuAction.GAME_OBJECT_THIRD_OPTION
			|| action == MenuAction.GAME_OBJECT_FOURTH_OPTION
			|| action == MenuAction.GAME_OBJECT_FIFTH_OPTION;
	}

	enum Kind
	{
		NONE,
		WOODCUTTING,
		FISHING,
		PROCESSING
	}

	private final ActivityEvidenceTracker evidence = new ActivityEvidenceTracker();
	private final ExtendedInventoryTracker extendedInventory = new ExtendedInventoryTracker();
	private final WoodcuttingRecognizer woodcutting;
	private final FishingActivityDetector fishing;
	private final ProcessingActivityDetector processing;
	private final DaeyaltRecognizer daeyalt;

	ActivityDetector(ActivityAnimationRegistry registry,
		GatheringResourceTracker gatheringResources)
	{
		woodcutting = new WoodcuttingRecognizer(registry, evidence,
			gatheringResources, extendedInventory);
		fishing = new FishingActivityDetector(registry, evidence, extendedInventory);
		processing = new ProcessingActivityDetector(registry, evidence);
		daeyalt = new DaeyaltRecognizer(registry);
	}

	void reset()
	{
		evidence.reset();
		extendedInventory.reset();
		woodcutting.reset();
	}

	InventoryDetection detectInventory(InventoryChange change,
		InventoryState equipment, boolean playerPresent, int animationId,
		int woodcuttingLevel, int fishingLevel, int tick,
		int normalGraceTicks, int fishingGraceTicks)
	{
		WoodcuttingRecognizer.LogResult log = woodcutting.detectLog(change, equipment,
			playerPresent, animationId, woodcuttingLevel, tick, normalGraceTicks);
		if (log != null)
		{
			return InventoryDetection.woodcutting(log);
		}

		FishingActivityDetector.Detection fishingResult = fishing.detect(change,
			change == null ? InventoryState.empty() : change.after(), equipment,
			animationId, tick, fishingLevel, fishingGraceTicks);
		if (fishingResult != null)
		{
			return InventoryDetection.fishing(fishingResult);
		}

		ProcessingActivityDetector.Result processingResult = processing.detect(
			change, equipment, animationId, tick, normalGraceTicks);
		return processingResult == null ? InventoryDetection.none()
			: InventoryDetection.processing(processingResult);
	}

	ProcessingContext processingContextForMenu(int itemId, int selectedWidgetItemId,
		MenuAction action, String normalizedOption, String normalizedTarget,
		InventoryState equipment)
	{
		return processing.contextForMenu(itemId, selectedWidgetItemId, action,
			normalizedOption, normalizedTarget, equipment);
	}

	String observedProcessingSkill(String animationLabel, String confirmedSkill)
	{
		return processing.observedProcessingSkill(animationLabel, confirmedSkill);
	}

	void onTreeInteraction(MenuAction action, String normalizedOption,
		String normalizedTarget, int objectId, WorldPoint location, int tick,
		InventoryState inventory, InventoryState equipment)
	{
		woodcutting.onTreeInteraction(action, normalizedOption, normalizedTarget,
			objectId, location, tick, inventory, equipment);
	}

	WoodcuttingRecognizer.StorageStart detectPendingWoodcuttingStorage(
		InventoryState inventory, InventoryState equipment, int effectiveLevel,
		int tick, int graceTicks)
	{
		return woodcutting.detectPendingStorageStart(inventory, equipment,
			effectiveLevel, tick, graceTicks);
	}

	FishingActivityDetector.BarrelStart detectFishingBarrelStart(FishingSpot spot,
		InventoryState inventory, InventoryState equipment, int animationId,
		int effectiveLevel)
	{
		return fishing.detectBarrelStart(spot, inventory, equipment, animationId,
			effectiveLevel);
	}

	boolean onWoodcuttingAnimation(int animationId, int tick)
	{
		return woodcutting.onAnimation(animationId, tick);
	}

	boolean isWoodcuttingAnimation(int animationId)
	{
		return woodcutting.isWoodcuttingAnimation(animationId);
	}

	boolean isFishingAnimation(int animationId)
	{
		return fishing.isFishingAnimation(animationId);
	}

	boolean isSmithingAnimation(int animationId)
	{
		return processing.isSmithingAnimation(animationId);
	}

	boolean isFurnaceAnimation(int animationId)
	{
		return ProcessingActivityDetector.isFurnaceAnimation(animationId);
	}

	boolean isMiningAnimation(int animationId)
	{
		return daeyalt.isMiningAnimation(animationId);
	}

	DaeyaltRecognizer.Interaction detectDaeyaltInteraction(int objectId,
		MenuAction action, String normalizedOption, WorldPoint location,
		InventoryState inventory, InventoryState equipment)
	{
		return daeyalt.detectInteraction(objectId, action, normalizedOption,
			location, inventory, equipment);
	}

	void mark(ActivityEvidenceTracker.Signal signal, int tick)
	{
		evidence.mark(signal, tick);
	}

	ActivityEvidenceTracker evidence()
	{
		return evidence;
	}

	ExtendedInventoryTracker extendedInventory()
	{
		return extendedInventory;
	}

	static final class InventoryDetection
	{
		private static final InventoryDetection NONE =
			new InventoryDetection(Kind.NONE, null, null, null);

		private final Kind kind;
		private final WoodcuttingRecognizer.LogResult woodcutting;
		private final FishingActivityDetector.Detection fishing;
		private final ProcessingActivityDetector.Result processing;

		private InventoryDetection(Kind kind,
			WoodcuttingRecognizer.LogResult woodcutting,
			FishingActivityDetector.Detection fishing,
			ProcessingActivityDetector.Result processing)
		{
			this.kind = kind;
			this.woodcutting = woodcutting;
			this.fishing = fishing;
			this.processing = processing;
		}

		static InventoryDetection none()
		{
			return NONE;
		}

		static InventoryDetection woodcutting(WoodcuttingRecognizer.LogResult result)
		{
			return new InventoryDetection(Kind.WOODCUTTING, result, null, null);
		}

		static InventoryDetection fishing(FishingActivityDetector.Detection result)
		{
