		static InventoryDetection processing(ProcessingActivityDetector.Result result)
		{
			return new InventoryDetection(Kind.PROCESSING, null, null, result);
		}

		Kind kind()
		{
			return kind;
		}

		WoodcuttingRecognizer.LogResult woodcutting()
		{
			return woodcutting;
		}

		FishingActivityDetector.Detection fishing()
		{
