	{
		previewTimer.stop();
		configRefreshTimer.stop();
	}

	/** Coalesce the many ConfigChanged events emitted by one preset application. */
	void scheduleRefresh()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::scheduleRefresh);
			return;
		}
		configRefreshTimer.restart();
	}

	void applyCollapsed(String serializedValue)
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(() -> applyCollapsed(serializedValue));
			return;
		}
		avatarCollapsed = Boolean.parseBoolean(serializedValue);
		avatarButton.setText(avatarCollapsed ? "Show avatar" : "Hide avatar");
	}

	void refreshFromConfig()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::refreshFromConfig);
			return;
		}
		syncing = true;
		try
		{
			previewBox.setSelectedItem(config.debugPreviewState());
			presetBox.setSelectedItem(config.displayPreset());
			themeBox.setSelectedItem(config.widgetTheme());
			scaleBox.setSelectedItem(config.avatarScale());
			frameBox.setSelected(config.showWidgetFrame());
			hpBox.setSelected(config.showHpOrb());
			prayerBox.setSelected(config.showPrayerOrb());
			inventoryCountBox.setSelected(config.showInventoryCount());
			xpRateBox.setSelected(config.showAdvancedInfo());
			etaBox.setSelected(config.showTaskEta());
			densityBox.setSelectedItem(config.inventoryDensity());
			inventoryBox.setSelected(config.inventoryViewerAlwaysVisible());
			shimmerBox.setSelected(config.showAttentionShimmer());
			reasonBox.setSelected(config.showAttentionReason());
			runeLiteNotificationBox.setSelected(config.routeAttentionToRuneLite());
			soundsBox.setSelected(config.enableSounds());
			inventorySoundBox.setSelected(config.inventoryFullSounds());
			idleSoundBox.setSelected(config.idleSounds());
			afkSoundBox.setSelected(config.afkSounds());
			lowPrayerSoundBox.setSelected(config.lowPrayerSounds());
			lowHpSoundBox.setSelected(config.lowHpSounds());
			chatSoundBox.setSelected(config.chatMessageSounds());
			etaSoundBox.setSelected(config.etaCompleteSounds());
			updateSoundControlEnabledState();
			avatarOpacity.setValue(config.avatarOpacityPercent());
			widgetOpacity.setValue(config.widgetOpacityPercent());
			soundVolume.setValue(config.soundVolumePercent());
			avatarCollapsed = config.widgetCollapsed();
			avatarButton.setText(avatarCollapsed ? "Show avatar" : "Hide avatar");
		}
		finally
		{
			syncing = false;
		}
		revalidate();
		repaint();
		if (getParent() != null)
		{
			getParent().revalidate();
			getParent().repaint();
		}
		refreshPreview();
	}

	private void refreshPreview()
	{
		WidgetSnapshot snapshot = contentSource.getWidgetSnapshot();
		String label = snapshot.getAnimationLabel();
		stateLabel.setText(label == null || label.isEmpty()
			? snapshot.getState().name().replace('_', ' ')
			: snapshot.getState().name().replace('_', ' ') + " \u00b7 " + label);
		previewCanvas.repaint();
	}

