	private final class PreviewCanvas extends JPanel
	{
		private PreviewCanvas()
		{
			setPreferredSize(new Dimension(PREVIEW_SIZE, PREVIEW_SIZE));
			setMinimumSize(new Dimension(PREVIEW_SIZE, PREVIEW_SIZE));
			setMaximumSize(new Dimension(PREVIEW_SIZE, PREVIEW_SIZE));
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			setBorder(BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR));
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			super.paintComponent(graphics);
			Graphics2D g = (Graphics2D) graphics.create();
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			BufferedImage avatar = contentSource.getCurrentFrame();
			Rectangle visible = contentSource.getCurrentFrameVisualBounds();
			int stageSize = Math.min(getWidth(), getHeight()) - 12;
			int stageX = (getWidth() - stageSize) / 2;
			int stageY = (getHeight() - stageSize) / 2;
			int inset = Math.max(12, stageSize / 8);
			if (avatar != null && visible != null && visible.width > 0 && visible.height > 0)
			{
				double baseScale = stageSize / 128.0d;
				double fittingScale = Math.min((stageSize - inset * 2) / (double) visible.width,
					(stageSize - inset * 2) / (double) visible.height);
				double scale = Math.min(baseScale, fittingScale);
				int drawWidth = Math.max(1, (int) Math.round(avatar.getWidth() * scale));
				int drawHeight = Math.max(1, (int) Math.round(avatar.getHeight() * scale));
				int drawX = stageX + stageSize / 2
					- (int) Math.round((visible.x + visible.width / 2.0d) * scale);
				int drawY = stageY + stageSize - inset
					- (int) Math.round((visible.y + visible.height) * scale);
				g.drawImage(avatar, drawX, drawY, drawWidth, drawHeight, null);
			}
			g.dispose();
		}
	}
}

