import java.util.Map;

/** Tracks brief proof that useful work continues at 28 occupied slots. */
final class FullInventoryActivityTracker
{
	/** Long enough to bridge the slowest reviewed processing cycle (9 ticks). */
	static final int PROGRESS_GRACE_TICKS = 12;

	private int lastProgressTick = -1;

	void reset()
	{
		lastProgressTick = -1;
	}

	void onInventoryChanged(Map<Integer, Integer> before, Map<Integer, Integer> after,
		int occupiedSlots, int tick)
	{
		if (occupiedSlots < InventorySnapshot.SLOT_COUNT)
		{
			lastProgressTick = -1;
			return;
		}
		if (before != null && !before.isEmpty() && after != null && !before.equals(after))
		{
			markProgress(tick);
		}
	}

	void markProgress(int tick)
	{
		lastProgressTick = Math.max(0, tick);
	}

	boolean isWorkingAtFull(boolean full, boolean confirmedProcessing, boolean skilling, int tick)
	{
		if (!full)
		{
			return false;
		}
		if (confirmedProcessing)
		{
			return true;
		}
		if (!skilling || lastProgressTick < 0 || tick < lastProgressTick)
		{
			return false;
		}
		return tick - lastProgressTick <= PROGRESS_GRACE_TICKS;
	}
}

