package com.idlefamiliar;

/** Client-free native processing durations in 0.6-second game ticks. */
final class ProcessingDuration
{
	private ProcessingDuration()
	{
	}

	static int perAction(int actions, int ticksPerAction)
	{
		return Math.max(0, actions) * Math.max(0, ticksPerAction);
	}

	static int fletchingKnife(int actions)
	{
		return actions <= 0 ? 0 : 3 + 2 * (actions - 1);
	}

	static int arrowShafts(int actions)
	{
		// Native arrow and bolt Make-X batches take two ticks each; unlike
		// bow fletching there is no longer repeat interval after the first batch.
		return perAction(actions, 2);
	}

	static int fletchingKnifeArrowShafts(int actions)
	{
		return actions <= 0 ? 0 : 2 + 2 * (actions - 1);
	}

	static int cookAll(int items)
	{
		return items <= 0 ? 0 : 3 + 4 * (items - 1);
	}

	static int forestersCampfire(int logs)
	{
		return logs <= 0 ? 0 : 6 + 9 * (logs - 1);
	}
}

