package com.idlefamiliar;

/** Bounded text formatting for values painted in the fixed-size desktop widget. */
final class WidgetTextFormatter
{
	private static final String ETA_PLACEHOLDER = "-";
	private static final int COMPACT_ETA_MAX_SECONDS = 99 * 60 + 59;

	private WidgetTextFormatter()
	{
	}

	static String compactTaskEta(TaskEtaSnapshot taskEta)
	{
		if (taskEta == null || !taskEta.isActive())
		{
			return ETA_PLACEHOLDER;
		}

		long seconds = ((long) taskEta.getRemainingTicks() * 3L + 4L) / 5L;
		if (seconds <= COMPACT_ETA_MAX_SECONDS)
		{
			return taskEta.getDisplayText();
		}
		String prefix = taskEta.isApproximate() ? "~" : "";
		long totalMinutes = (seconds + 59L) / 60L;
		long hours = totalMinutes / 60L;
		if (hours >= 100L)
		{
			return prefix + "99h+";
		}
		long minutes = totalMinutes % 60L;
		return prefix + hours + "h" + (minutes < 10L ? "0" : "") + minutes;
	}

	/** Attention facts take precedence over transient speech/status text. */
	static String statusMessage(WidgetSnapshot snapshot)
	{
		if (snapshot == null)
		{
			return null;
		}
		AttentionReason reason = snapshot.getAttentionReason();
		return reason != null && reason.isActive()
			? reason.getDisplayText() : snapshot.getMessage();
	}

	static String visibleStatusMessage(WidgetSnapshot snapshot, boolean showStatusText)
	{
		return showStatusText ? statusMessage(snapshot) : null;
	}

	static String inventoryQuantity(int quantity)
	{
		long value = Math.max(0, quantity);
		if (value < 10_000L)
		{
			return Long.toString(value);
		}
		if (value >= 1_000_000_000L)
		{
			return inventoryUnit(value, 1_000_000_000L, "b");
		}
		if (value >= 1_000_000L)
		{
			return inventoryUnit(value, 1_000_000L, "m");
		}
		return inventoryUnit(value, 1_000L, "k");
	}

	private static String inventoryUnit(long value, long unit, String suffix)
	{
		long tenths = value * 10L / unit;
		long whole = tenths / 10L;
		long fraction = tenths % 10L;
		return fraction == 0L ? whole + suffix : whole + "." + fraction + suffix;
	}
}

package com.idlefamiliar;

import java.awt.Dimension;
import java.awt.Point;
import java.awt.Rectangle;

/** Pure geometry for restoring and snapping the detached desktop window. */
final class WidgetPositioning
{
	private WidgetPositioning()
	{
	}

	static Rectangle anchoredBounds(Rectangle workArea, Dimension size, WidgetAnchor anchor,
		int offsetX, int offsetY, int safeMargin)
	{
		Rectangle work = new Rectangle(workArea);
		int margin = Math.max(0, safeMargin);
		int width = Math.max(1, Math.min(size.width, Math.max(1, work.width - margin * 2)));
		int height = Math.max(1, Math.min(size.height, Math.max(1, work.height - margin * 2)));
		WidgetAnchor safeAnchor = anchor == null ? WidgetAnchor.FREE : anchor;
		int x;
		int y;
		switch (safeAnchor)
		{
			case TOP_LEFT:
				x = work.x + margin + Math.max(0, offsetX);
				y = work.y + margin + Math.max(0, offsetY);
				break;
			case TOP_RIGHT:
				x = work.x + work.width - margin - width - Math.max(0, offsetX);
				y = work.y + margin + Math.max(0, offsetY);
				break;
			case BOTTOM_LEFT:
				x = work.x + margin + Math.max(0, offsetX);
				y = work.y + work.height - margin - height - Math.max(0, offsetY);
				break;
			case BOTTOM_RIGHT:
				x = work.x + work.width - margin - width - Math.max(0, offsetX);
				y = work.y + work.height - margin - height - Math.max(0, offsetY);
				break;
			case FREE:
			default:
				x = offsetX;
				y = offsetY;
				break;
		}
		return clampToWorkArea(new Rectangle(x, y, width, height), work, margin);
	}

	static Rectangle clampToWorkArea(Rectangle desired, Rectangle workArea, int safeMargin)
	{
		int margin = Math.max(0, safeMargin);
		int minX = workArea.x + margin;
		int minY = workArea.y + margin;
		int maxX = Math.max(minX, workArea.x + workArea.width - margin - desired.width);
		int maxY = Math.max(minY, workArea.y + workArea.height - margin - desired.height);
		int x = Math.max(minX, Math.min(maxX, desired.x));
		int y = Math.max(minY, Math.min(maxY, desired.y));
		return new Rectangle(x, y, desired.width, desired.height);
	}

	/** Resize a free window while optionally keeping its bottom edge stationary. */
	static Rectangle resizedFreeBounds(Rectangle current, Dimension targetSize,
		Rectangle workArea, int safeMargin, boolean preserveBottomEdge)
	{
		Rectangle safeCurrent = current == null ? new Rectangle() : new Rectangle(current);
		Dimension safeTarget = targetSize == null ? new Dimension(1, 1) : targetSize;
		int targetY = safeCurrent.y;
		if (preserveBottomEdge)
		{
			targetY += safeCurrent.height - safeTarget.height;
		}
		return clampToWorkArea(new Rectangle(safeCurrent.x, targetY,
			Math.max(1, safeTarget.width), Math.max(1, safeTarget.height)), workArea, safeMargin);
	}

	static WidgetAnchor cornerAnchor(Rectangle bounds, Rectangle workArea, int safeMargin, int snapDistance)
	{
		int margin = Math.max(0, safeMargin);
		int threshold = Math.max(0, snapDistance);
		boolean left = Math.abs(bounds.x - (workArea.x + margin)) <= threshold;
		boolean right = Math.abs(bounds.x + bounds.width
			- (workArea.x + workArea.width - margin)) <= threshold;
		boolean top = Math.abs(bounds.y - (workArea.y + margin)) <= threshold;
		boolean bottom = Math.abs(bounds.y + bounds.height
			- (workArea.y + workArea.height - margin)) <= threshold;
		if (left && top)
		{
			return WidgetAnchor.TOP_LEFT;
		}
		if (right && top)
		{
			return WidgetAnchor.TOP_RIGHT;
		}
		if (left && bottom)
		{
			return WidgetAnchor.BOTTOM_LEFT;
		}
		if (right && bottom)
		{
			return WidgetAnchor.BOTTOM_RIGHT;
		}
		return WidgetAnchor.FREE;
	}

	static Point offsetsFor(Rectangle bounds, Rectangle workArea, WidgetAnchor anchor, int safeMargin)
	{
		int margin = Math.max(0, safeMargin);
		switch (anchor == null ? WidgetAnchor.FREE : anchor)
		{
			case TOP_LEFT:
				return new Point(bounds.x - workArea.x - margin, bounds.y - workArea.y - margin);
			case TOP_RIGHT:
				return new Point(workArea.x + workArea.width - margin - bounds.x - bounds.width,
					bounds.y - workArea.y - margin);
			case BOTTOM_LEFT:
				return new Point(bounds.x - workArea.x - margin,
					workArea.y + workArea.height - margin - bounds.y - bounds.height);
			case BOTTOM_RIGHT:
				return new Point(workArea.x + workArea.width - margin - bounds.x - bounds.width,
					workArea.y + workArea.height - margin - bounds.y - bounds.height);
			case FREE:
			default:
				return bounds.getLocation();
		}
	}

	/**
	 * Inventory details grow away from the nearest vertical screen edge. Corner
	 * anchors are authoritative; a freely positioned widget uses its centre.
	 */
	static boolean inventoryExpandsUp(Rectangle bounds, Rectangle workArea, WidgetAnchor anchor)
	{
		WidgetAnchor safeAnchor = anchor == null ? WidgetAnchor.FREE : anchor;
		if (safeAnchor == WidgetAnchor.BOTTOM_LEFT || safeAnchor == WidgetAnchor.BOTTOM_RIGHT)
		{
			return true;
		}
		if (safeAnchor == WidgetAnchor.TOP_LEFT || safeAnchor == WidgetAnchor.TOP_RIGHT)
		{
			return false;
		}
		if (bounds == null || workArea == null)
		{
			return false;
		}
		long widgetCentreY = (long) bounds.y * 2L + bounds.height;
		long workCentreY = (long) workArea.y * 2L + workArea.height;
		return widgetCentreY > workCentreY;
	}
}

package com.idlefamiliar;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

public final class ChatMessageMatcher
{
	private static final int MIN_WORDS = 3;

	private ChatMessageMatcher()
	{
	}

	public static String matchedFilter(String message, String filters)
	{
		return matchedFilter(message, compile(filters));
	}

	static String matchedFilter(String message, CompiledFilters filters)
	{
		String normalizedMessage = normalize(message);
		if (normalizedMessage.isEmpty())
		{
			return null;
		}

		for (int index = 0; index < filters.values.size(); index += 2)
		{
			if (normalizedMessage.contains(filters.values.get(index + 1)))
			{
				return filters.values.get(index);
			}
		}
		return null;
	}

	static CompiledFilters compile(String filters)
	{
		List<String> compiled = new ArrayList<>();
		for (String filter : parseFilters(filters))
		{
			String normalized = normalize(filter);
			if (!normalized.isEmpty())
			{
				compiled.add(filter);
				compiled.add(normalized);
			}
		}
		return new CompiledFilters(Collections.unmodifiableList(compiled));
	}

	static List<String> parseFilters(String filters)
	{
		List<String> result = new ArrayList<>();
		if (filters == null || filters.trim().isEmpty())
		{
			return result;
		}

		String[] lines = filters.split("\\R");
		for (String line : lines)
		{
			String trimmed = line.trim();
			if (trimmed.isEmpty() || trimmed.startsWith("#"))
			{
				continue;
			}
			if (wordCount(trimmed) >= MIN_WORDS)
			{
				result.add(trimmed);
			}
		}
		return result;
	}

	private static String normalize(String value)
	{
		if (value == null)
		{
			return "";
		}
		String lower = value.toLowerCase(Locale.ROOT);
		String wordsOnly = lower.replaceAll("[^a-z0-9]+", " ").trim();
		return wordsOnly.replaceAll("\\s+", " ");
	}

	private static int wordCount(String value)
	{
		String normalized = normalize(value);
		if (normalized.isEmpty())
		{
			return 0;
		}
		return normalized.split(" ").length;
	}

	static final class CompiledFilters
	{
		private final List<String> values;

		private CompiledFilters(List<String> values)
		{
			this.values = values;
		}
	}
}

package com.idlefamiliar;

import java.util.Collections;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/** Difference between two inventory-count snapshots. Client data is converted to
 * this pure value before Task ETA classification, keeping the prediction logic
 * easy to test and independent of the Swing widget. */
final class InventoryDelta
{
	private final Map<Integer, Integer> before;
	private final Map<Integer, Integer> after;
	private final Set<Integer> itemIds;

	InventoryDelta(Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		this.before = before;
		this.after = after;
		Set<Integer> ids = new HashSet<>(before.keySet());
		ids.addAll(after.keySet());
		this.itemIds = Collections.unmodifiableSet(ids);
	}

	int consumed(int itemId)
	{
		return Math.max(0, quantity(before, itemId) - quantity(after, itemId));
	}

	int produced(int itemId)
	{
		return Math.max(0, quantity(after, itemId) - quantity(before, itemId));
	}

	/** Requires every inventory change to belong to the recipe. */
	boolean hasChangesOnlyWithin(Set<Integer> allowedItemIds)
	{
		for (Integer itemId : itemIds)
		{
			if (quantity(before, itemId) != quantity(after, itemId)
				&& !allowedItemIds.contains(itemId))
			{
				return false;
			}
		}
		return true;
	}

	/** Every item id represented by either side of this immutable delta. */
	Set<Integer> itemIds()
	{
		return itemIds;
	}

	private static int quantity(Map<Integer, Integer> inventory, int itemId)
	{
		Integer quantity = inventory.get(itemId);
		return quantity == null ? 0 : quantity;
	}
}

