package com.idlefamiliar;

import java.util.Map;
import net.runelite.api.SpriteID;

/**
 * Maps a confirmed skill name to its RuneLite skill sprite id, so the desktop
 * widget can draw the matching skill badge.
 */
public final class SkillIcons
{
	private static final Map<String, Integer> SKILL_SPRITE_IDS = Map.ofEntries(
		Map.entry("attack", SpriteID.SKILL_ATTACK),
		Map.entry("strength", SpriteID.SKILL_STRENGTH),
		Map.entry("defence", SpriteID.SKILL_DEFENCE),
		Map.entry("ranged", SpriteID.SKILL_RANGED),
		Map.entry("prayer", SpriteID.SKILL_PRAYER),
		Map.entry("magic", SpriteID.SKILL_MAGIC),
		Map.entry("runecraft", SpriteID.SKILL_RUNECRAFT),
		Map.entry("hitpoints", SpriteID.SKILL_HITPOINTS),
		Map.entry("crafting", SpriteID.SKILL_CRAFTING),
		Map.entry("mining", SpriteID.SKILL_MINING),
		Map.entry("smithing", SpriteID.SKILL_SMITHING),
		Map.entry("fishing", SpriteID.SKILL_FISHING),
		Map.entry("cooking", SpriteID.SKILL_COOKING),
		Map.entry("firemaking", SpriteID.SKILL_FIREMAKING),
		Map.entry("woodcutting", SpriteID.SKILL_WOODCUTTING),
		Map.entry("agility", SpriteID.SKILL_AGILITY),
		Map.entry("herblore", SpriteID.SKILL_HERBLORE),
		Map.entry("thieving", SpriteID.SKILL_THIEVING),
		Map.entry("fletching", SpriteID.SKILL_FLETCHING),
		Map.entry("slayer", SpriteID.SKILL_SLAYER),
		Map.entry("farming", SpriteID.SKILL_FARMING),
		Map.entry("construction", SpriteID.SKILL_CONSTRUCTION),
		Map.entry("hunter", SpriteID.SKILL_HUNTER),
		Map.entry("sailing", net.runelite.api.gameval.SpriteID.Staticons2.SAILING)
	);

	private SkillIcons()
	{
	}

	/**
	 * @return the RuneLite sprite id for {@code skill}, or {@code null} if the
	 *         name is unknown.
	 */
	public static Integer spriteId(String skill)
	{
		return skill == null ? null : SKILL_SPRITE_IDS.get(skill.toLowerCase());
	}
}

package com.idlefamiliar;

public final class NotificationController
{
	private AvatarNotification current;

	public void clear()
	{
		current = null;
	}

	public void show(String text, int priority, long durationMillis)
	{
		long now = System.currentTimeMillis();
		AvatarNotification next = new AvatarNotification(text, priority, now + durationMillis);
		if (next.canReplace(current, now))
		{
			current = next;
		}
	}

	public String getMessage(AvatarState state, ActivityType activityType, String activityLabel)
	{
		long now = System.currentTimeMillis();
		if (current != null && !current.isExpired(now))
		{
			return current.text;
		}

		current = null;
		switch (state)
		{
			case LOGGED_OUT:
				return "Logged out";
			case LOW_HEALTH:
				return "Low HP";
			case LOW_PRAYER:
				return "Low prayer";
			case AFK_WARNING:
				return "Still there?";
			case INVENTORY_FULL:
				return "Inventory full";
			case DEATH:
				return "You died!";
			case LEVEL_UP:
				return "Level up!";
			case BANKING:
				return "Banking";
			case COMBAT:
				return "Combat";
			case SKILLING:
				return activityLabel == null || activityLabel.isEmpty() ? "Skilling" : activityLabel;
			case PLAYER_IDLE:
				return "Idle";
			case PLAYER_ACTIVE:
				return activityType == ActivityType.WALKING ? "Walking" : "Active";
			default:
				return "";
		}
	}

	/** Private value owned only by the transient-message priority queue. */
	private static final class AvatarNotification
	{
		private final String text;
		private final int priority;
		private final long expiresAtMillis;

		private AvatarNotification(String text, int priority, long expiresAtMillis)
		{
			this.text = text;
			this.priority = priority;
			this.expiresAtMillis = expiresAtMillis;
		}

		private boolean isExpired(long now)
		{
			return expiresAtMillis > 0 && now >= expiresAtMillis;
		}

		private boolean canReplace(AvatarNotification other, long now)
		{
			return other == null || other.isExpired(now) || priority >= other.priority;
		}
	}
}

package com.idlefamiliar;

import java.util.Map;

/** Owns the single active ETA engine. Callers must verify all client evidence. */
final class TaskEtaController
{
	private static final int NO_GATHERING_HORIZON = -1;

	private final DeterministicProcessingEtaEngine processing =
		new DeterministicProcessingEtaEngine();
	private final GatheringEtaEngine gathering = new GatheringEtaEngine();
	private final FixedProcessingEtaEngine fixedProcessing = new FixedProcessingEtaEngine();
	private final AttentionHorizonEtaEngine attentionHorizon = new AttentionHorizonEtaEngine();
	private EtaEngine owner;
	/** One-shot completion edge. */
	private boolean expiryPending;

	void reset()
	{
		processing.reset();
		fixedProcessing.cancel();
		gathering.cancel();
		attentionHorizon.cancel();
		owner = null;
		expiryPending = false;
	}

	/** A changed Make-X/tool context invalidates stale timing. */
	void setProcessingContext(ProcessingContext context)
	{
		if (processing.setProcessingContext(context))
		{
			claim(processing);
		}
	}

	/** Arms a short-lived context before its first inventory change. */
	void armProcessingContext(ProcessingContext context, int selectionTick)
	{
		if (processing.armProcessingContext(context, selectionTick))
		{
			claim(processing);
		}
	}

	void seedInventory(Map<Integer, Integer> inventory)
	{
		processing.seedInventory(inventory);
	}

	void setObservedProcessingContext(String activityLabel, boolean eligible)
	{
		processing.setObservedContext(activityLabel, eligible);
	}

	/** Applies one immutable inventory snapshot to the processing engine. */
	void onInventoryChanged(Map<Integer, Integer> inventory, int tick)
	{
		boolean competing = owner != null && owner != processing;
		DeterministicProcessingEtaEngine.Disposition disposition =
			processing.onInventoryChanged(inventory, tick, competing);
		if (disposition == DeterministicProcessingEtaEngine.Disposition.PRESERVE_COMPETING)
		{
			return;
		}
		if (disposition == DeterministicProcessingEtaEngine.Disposition.COMPLETED)
		{
			completeOwner(processing);
			return;
		}
		if (disposition == DeterministicProcessingEtaEngine.Disposition.CANCELLED)
		{
			cancel();
			return;
		}
		claim(processing);
	}

	/** Starts Woodcutting after a verified log delta and mechanics snapshot. */
	void onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree tree,
		WoodcuttingCatalog.AxeTier axeTier, int effectiveLevel, int occupiedInventorySlots,
		int producedLogSlots, boolean eligible, int tick)
	{
		// The static lifetime is a conservative bound when engagement time is unknown.
		int upperBoundHorizon = tree == null ? NO_GATHERING_HORIZON : WoodcuttingCatalog.activeSpotTicks(tree);
		onVerifiedWoodcuttingLogDelta(tree, axeTier, effectiveLevel, occupiedInventorySlots,
			producedLogSlots, eligible, upperBoundHorizon, tick);
	}

	/** Uses the earlier verified inventory or tree-life boundary. */
	void onVerifiedWoodcuttingLogDelta(WoodcuttingCatalog.Tree tree,
		WoodcuttingCatalog.AxeTier axeTier, int effectiveLevel, int occupiedInventorySlots,
		int producedLogSlots, boolean eligible, int despawnRemainingTicks, int tick)
	{
		applyGathering(gathering.onWoodcuttingLog(tree, axeTier, effectiveLevel,
			occupiedInventorySlots, producedLogSlots, eligible, despawnRemainingTicks, tick));
	}

	/** Starts capacity with a verified open log container. */
	void onVerifiedWoodcuttingStorageStart(WoodcuttingCatalog.Tree tree,
		WoodcuttingCatalog.AxeTier axeTier, int effectiveLevel, int occupiedInventorySlots,
		int storageCapacity, boolean eligible, int despawnRemainingTicks, int tick)
	{
		applyGathering(gathering.onWoodcuttingStorageStart(tree, axeTier, effectiveLevel,
			occupiedInventorySlots, storageCapacity, eligible, despawnRemainingTicks, tick));
	}

	/** Starts conventional fishing after a fully verified post-catch delta. */
	void onVerifiedConventionalFishingCatch(GatheringProfile profile,
		int effectiveLevel, int occupiedInventorySlots, int producedFishSlots,
		boolean eligible, int tick)
	{
		onVerifiedConventionalFishingCatch(profile, effectiveLevel, occupiedInventorySlots,
			producedFishSlots, 1d, eligible, FishingCatalog.NO_SPOT_MOVEMENT_HORIZON, tick);
	}

	/** Starts fishing with a verified open, not-yet-full Fish Barrel. */
	void onVerifiedConventionalFishingBarrelStart(GatheringProfile profile,
		int effectiveLevel, int ordinaryFreeSlots, double capacityYieldMultiplier,
		boolean eligible, int tick)
	{
		onVerifiedConventionalFishingBarrelStart(profile, effectiveLevel, ordinaryFreeSlots,
			capacityYieldMultiplier, eligible, FishingCatalog.NO_SPOT_MOVEMENT_HORIZON, tick);
	}

	void onVerifiedConventionalFishingBarrelStart(GatheringProfile profile,
		int effectiveLevel, int ordinaryFreeSlots, double capacityYieldMultiplier,
		boolean eligible, int earliestSpotMoveRemainingTicks, int tick)
	{
		applyGathering(gathering.onConventionalFishingBarrelStart(profile, effectiveLevel,
			ordinaryFreeSlots, capacityYieldMultiplier, eligible,
			earliestSpotMoveRemainingTicks, tick));
	}

	void onVerifiedConventionalFishingCatch(GatheringProfile profile,
		int effectiveLevel, int occupiedInventorySlots, int producedFishSlots,
		double capacityYieldMultiplier, boolean eligible, int tick)
	{
		onVerifiedConventionalFishingCatch(profile, effectiveLevel, occupiedInventorySlots,
			producedFishSlots, capacityYieldMultiplier, eligible,
			FishingCatalog.NO_SPOT_MOVEMENT_HORIZON, tick);
	}

	/** Adds a spot-move horizon only when engagement time was observed. */
	void onVerifiedConventionalFishingCatch(GatheringProfile profile,
		int effectiveLevel, int occupiedInventorySlots, int producedFishSlots,
		boolean eligible, int earliestSpotMoveRemainingTicks, int tick)
	{
		onVerifiedConventionalFishingCatch(profile, effectiveLevel, occupiedInventorySlots,
			producedFishSlots, 1d, eligible, earliestSpotMoveRemainingTicks, tick);
	}

	void onVerifiedConventionalFishingCatch(GatheringProfile profile,
		int effectiveLevel, int occupiedInventorySlots, int producedFishSlots,
		double capacityYieldMultiplier, boolean eligible,
		int earliestSpotMoveRemainingTicks, int tick)
	{
		applyGathering(gathering.onConventionalFishingCatch(profile, effectiveLevel,
			occupiedInventorySlots, producedFishSlots, capacityYieldMultiplier, eligible,
			earliestSpotMoveRemainingTicks, tick));
	}

	/** Applies one verified Karambwan attempt and its post-attempt bait count. */
	void onVerifiedKarambwanAttempt(int effectiveLevel, int occupiedInventorySlots,
		int remainingKarambwanji, boolean caught, boolean eligible, int tick)
	{
		applyGathering(gathering.onKarambwanAttempt(effectiveLevel, occupiedInventorySlots,
			remainingKarambwanji, caught, eligible, tick));
	}

	/** Starts Karambwan capacity when catches enter a verified Fish Barrel. */
	void onVerifiedKarambwanBarrelAttempt(int effectiveLevel, int ordinaryFreeSlots,
		int remainingKarambwanAttempts, double capacityYieldMultiplier, boolean eligible, int tick)
	{
		applyGathering(gathering.onKarambwanBarrelAttempt(effectiveLevel, ordinaryFreeSlots,
			remainingKarambwanAttempts, capacityYieldMultiplier, eligible, tick));
	}

	/** Shows the earliest verified Daeyalt rock movement. */
	void onVerifiedDaeyaltRockActive(DaeyaltCatalog.PickaxeTier pickaxeTier,
		int earliestMoveRemainingTicks, boolean eligible, int tick)
	{
		if (!eligible || pickaxeTier == null
			|| earliestMoveRemainingTicks < 0
			|| earliestMoveRemainingTicks > DaeyaltCatalog.MAX_ACTIVE_TICKS)
		{
			cancel();
			return;
		}

		startAttentionHorizon(DaeyaltCatalog.LABEL, earliestMoveRemainingTicks, true, true, tick);
	}

	/** Starts an exact fixed-duration horizon after a client-visible start signal. */
	void onVerifiedFixedAttentionHorizon(String label, int horizonTicks, boolean eligible, int tick)
	{
		startAttentionHorizon(label, horizonTicks, eligible, false, tick);
	}

	/** Starts a fixed queue after its animation and input count are verified. */
	void onVerifiedFixedProcessingQueue(String label, int remainingUnits, int ticksPerUnit,
		boolean eligible, int tick)
	{
		if (eligible && remainingUnits <= 0 && owner == fixedProcessing)
		{
			completeOwner(fixedProcessing);
			return;
		}
		if (!fixedProcessing.update(label, remainingUnits, ticksPerUnit, eligible, tick))
		{
			cancel();
			return;
		}

		claim(fixedProcessing);
	}

	/** Starts local gathering calibration from a verified animation. */
	void onObservedGatheringStart(String label, int occupiedInventorySlots, boolean eligible, int tick)
	{
		applyGathering(gathering.startObserved(label, occupiedInventorySlots, eligible, tick));
	}

	/** Records a complete, caller-verified non-stackable yield for local calibration. */
	void onVerifiedObservedGatheringYield(String label, int occupiedInventorySlots,
		int producedSlots, boolean eligible, int tick)
	{
		applyGathering(gathering.onObservedYield(label, occupiedInventorySlots,
			producedSlots, eligible, tick));
	}

	private void startAttentionHorizon(String label, int horizonTicks, boolean eligible,
		boolean approximate, int tick)
	{
		if (!eligible || label == null || label.trim().isEmpty() || horizonTicks < 0)
		{
			cancel();
			return;
		}

		if (!attentionHorizon.start(label, horizonTicks, eligible, approximate, tick))
		{
			cancel();
			return;
		}
		claim(attentionHorizon);
	}

	/** Advance a known run without reading inventory, skills, equipment, or client state. */
	void onGameTick(int tick)
	{
		if (owner == null)
		{
			return;
		}

		TaskEtaSnapshot before = owner.snapshot();
		// Silence does not stop probabilistic gathering; the recognizer proves stops.
		owner.onGameTick(tick);
		TaskEtaSnapshot after = owner.snapshot();
		recordExpiry(before, after);
		if (!owner.isActive())
		{
			owner = null;
		}
	}

	/** Returns the ETA-completed edge exactly once. */
	boolean consumeExpiry()
	{
		boolean expired = expiryPending;
		expiryPending = false;
		return expired;
	}

	void cancel()
	{
		processing.cancel();
		fixedProcessing.cancel();
		gathering.cancel();
		attentionHorizon.cancel();
		owner = null;
	}

	/** Publish a single completion only when a caller has verified the ETA's terminal event. */
	void complete()
	{
		if (owner != null)
		{
			expiryPending = true;
		}
		cancel();
	}

	/** Makes one engine the owner and clears every competitor. */
	private void claim(EtaEngine nextOwner)
	{
		if (nextOwner != processing)
		{
			processing.cancel();
		}
		if (nextOwner != fixedProcessing)
		{
			fixedProcessing.cancel();
		}
		if (nextOwner != gathering)
		{
			gathering.cancel();
		}
		if (nextOwner != attentionHorizon)
		{
			attentionHorizon.cancel();
		}
		owner = nextOwner != null && nextOwner.isActive() ? nextOwner : null;
	}

	private void applyGathering(GatheringEtaEngine.Disposition disposition)
	{
		if (disposition == GatheringEtaEngine.Disposition.IGNORED)
		{
			return;
		}
		if (disposition == GatheringEtaEngine.Disposition.COMPLETED)
		{
			completeOwner(gathering);
			return;
		}
		if (disposition == GatheringEtaEngine.Disposition.CANCELLED)
		{
			cancel();
			return;
		}

		claim(gathering);
	}

	TaskEtaSnapshot snapshot()
	{
		return owner == null ? TaskEtaSnapshot.inactive() : owner.snapshot();
	}

	private void recordExpiry(TaskEtaSnapshot before, TaskEtaSnapshot after)
	{
		if (before != null && before.isActive() && before.getRemainingTicks() > 0
			&& after != null && after.isActive() && after.getRemainingTicks() <= 0)
		{
			expiryPending = true;
		}
	}

	private void completeOwner(EtaEngine completedOwner)
	{
		if (owner == completedOwner)
		{
			complete();
		}
	}

	boolean isActiveProcessingContext(ProcessingContext.Kind kind)
	{
		return owner == processing && processing.isActiveContext(kind);
	}

	boolean isDeterministicProcessingOwner()
	{
		return owner == processing;
	}

}

