	static boolean isFishBarrelCompatible(GatheringProfile profile)
	{
		return profile != null && isConventionalV1Profile(profile)
			&& profile != OILY_ROD_INFERNAL_EEL;
	}

	/** True for the display label of every fishing ETA owned by this catalogue. */
	static boolean isFishingProfileLabel(String label)
	{
		if (label == null)
		{
			return false;
		}
		for (GatheringProfile profile : ALL_PROFILES)
		{
			if (profile.getLabel().equals(label))
			{
				return true;
			}
		}
		return false;
