package com.idlefamiliar;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

/**
 * Conservative local calibration for a repeating inventory transformation not
 * present in the static catalog. It publishes no time until three identical
 * deltas occur under a caller-verified processing skill.
 */
final class ObservedProcessingTracker
{
	static final int REQUIRED_SAMPLES = 3;
	private static final int MAX_CYCLE_TICKS = 50;

	private Signature signature;
	private String label = "";
	private int samples;
	private int initialUnits;
	private int remainingUnits;
	private int lastTick;
	private final List<Integer> intervals = new ArrayList<>();

	TaskEtaSnapshot observe(InventoryDelta delta, Map<Integer, Integer> before,
		Map<Integer, Integer> after, String activityLabel, boolean eligible, int tick)
	{
		if (!eligible || activityLabel == null || activityLabel.trim().isEmpty())
		{
			reset();
			return TaskEtaSnapshot.inactive();
		}
		Signature nextSignature = Signature.from(delta);
		if (nextSignature == null)
		{
			reset();
			return TaskEtaSnapshot.inactive();
		}
		String nextLabel = activityLabel.trim();
		if (signature == null || !signature.equals(nextSignature) || !label.equals(nextLabel))
		{
			start(nextSignature, nextLabel, before, after, tick);
			return currentSnapshot(tick);
		}

		int interval = tick - lastTick;
		if (interval <= 0 || interval > MAX_CYCLE_TICKS)
		{
			reset();
			return TaskEtaSnapshot.inactive();
		}
		int nextRemaining = signature.availableUnits(after);
		if (nextRemaining >= remainingUnits || nextRemaining < 0)
		{
			reset();
			return TaskEtaSnapshot.inactive();
		}

		intervals.add(interval);
		if (intervals.size() > 7)
		{
			intervals.remove(0);
		}
		samples++;
		remainingUnits = nextRemaining;
		lastTick = tick;
		if (remainingUnits <= 0)
		{
			reset();
			return TaskEtaSnapshot.inactive();
		}
		return currentSnapshot(tick);
	}

	TaskEtaSnapshot onGameTick(int tick)
	{
		if (signature == null)
		{
			return TaskEtaSnapshot.inactive();
		}
		int grace = samples < REQUIRED_SAMPLES ? MAX_CYCLE_TICKS : Math.max(4, medianInterval() * 2);
		if (tick - lastTick > grace)
		{
			reset();
			return TaskEtaSnapshot.inactive();
		}
		return currentSnapshot(tick);
	}

	boolean isTracking()
	{
		return signature != null;
	}

	void reset()
	{
		signature = null;
		label = "";
		samples = 0;
		initialUnits = 0;
		remainingUnits = 0;
		lastTick = 0;
		intervals.clear();
	}

	private void start(Signature nextSignature, String nextLabel, Map<Integer, Integer> before,
		Map<Integer, Integer> after, int tick)
	{
		signature = nextSignature;
		label = nextLabel;
		samples = 1;
		initialUnits = signature.availableUnits(before);
		remainingUnits = signature.availableUnits(after);
		lastTick = tick;
		intervals.clear();
		if (initialUnits <= 0 || remainingUnits < 0 || remainingUnits >= initialUnits)
		{
			reset();
		}
	}

	private TaskEtaSnapshot currentSnapshot(int tick)
	{
		if (signature == null)
		{
			return TaskEtaSnapshot.inactive();
		}
		if (samples < REQUIRED_SAMPLES)
		{
			return TaskEtaSnapshot.calibrating(label, samples, REQUIRED_SAMPLES);
		}
		int median = medianInterval();
		int elapsed = Math.max(0, tick - lastTick);
		int remainingTicks = Math.max(0, safeMultiply(remainingUnits, median) - elapsed);
		int lowerTicks = Math.max(0, safeMultiply(remainingUnits, minimumInterval()) - elapsed);
		int upperTicks = Math.max(lowerTicks, safeMultiply(remainingUnits, maximumInterval()) - elapsed);
		return TaskEtaSnapshot.observedProcessing(label, initialUnits, remainingUnits,
			remainingTicks, safeMultiply(initialUnits, median), lowerTicks, upperTicks);
	}

	private int medianInterval()
	{
		if (intervals.isEmpty())
		{
			return 1;
		}
		List<Integer> sorted = new ArrayList<>(intervals);
		Collections.sort(sorted);
		int middle = sorted.size() / 2;
		return sorted.size() % 2 == 1 ? sorted.get(middle)
			: (sorted.get(middle - 1) + sorted.get(middle) + 1) / 2;
	}

	private int minimumInterval()
	{
		return intervals.isEmpty() ? 1 : Collections.min(intervals);
	}

	private int maximumInterval()
	{
		return intervals.isEmpty() ? 1 : Collections.max(intervals);
	}

	private static int safeMultiply(int left, int right)
	{
		long product = (long) Math.max(0, left) * Math.max(0, right);
		return product >= Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) product;
	}

	private static int quantity(Map<Integer, Integer> inventory, int itemId)
	{
		Integer value = inventory.get(itemId);
		return value == null ? 0 : Math.max(0, value);
	}

	private static final class Signature
	{
		private final Map<Integer, Integer> consumed;
		private final Map<Integer, Integer> produced;

		private Signature(Map<Integer, Integer> consumed, Map<Integer, Integer> produced)
		{
			this.consumed = Collections.unmodifiableMap(consumed);
			this.produced = Collections.unmodifiableMap(produced);
		}

		private static Signature from(InventoryDelta delta)
		{
			Map<Integer, Integer> consumed = new TreeMap<>();
			Map<Integer, Integer> produced = new TreeMap<>();
			Set<Integer> itemIds = delta.itemIds();
			for (Integer itemId : itemIds)
			{
				int removed = delta.consumed(itemId);
				int added = delta.produced(itemId);
				if (removed > 0)
				{
					consumed.put(itemId, removed);
				}
				if (added > 0)
				{
					produced.put(itemId, added);
				}
			}
			// Cover the roadmap's processing shapes plus automatic Plank Make
			// (log, rune stack, and coins). Repeated activity-skill verification is
			// still mandatory, and broad bank/deposit deltas or output-only pickups
			// remain outside this deliberately small transformation envelope.
			if (consumed.isEmpty() || consumed.size() > 3 || produced.isEmpty() || produced.size() > 2)
			{
				return null;
			}
			return new Signature(consumed, produced);
		}

		private int availableUnits(Map<Integer, Integer> inventory)
		{
			int units = Integer.MAX_VALUE;
			for (Map.Entry<Integer, Integer> input : consumed.entrySet())
			{
				units = Math.min(units, quantity(inventory, input.getKey()) / input.getValue());
			}
			return units == Integer.MAX_VALUE ? 0 : units;
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other)
			{
				return true;
			}
			if (!(other instanceof Signature))
			{
				return false;
			}
			Signature that = (Signature) other;
			return consumed.equals(that.consumed) && produced.equals(that.produced);
		}

		@Override
		public int hashCode()
		{
			return 31 * consumed.hashCode() + produced.hashCode();
		}
	}
}

package com.idlefamiliar;

import java.util.EnumSet;
import java.util.Set;

/**
 * Edge-triggered attention shimmer. Danger alerts survive combat until vitals
 * recover; normal alerts clear on active play.
 */
public class ShimmerController
{
	/** States that count as evidence of player input and can clear the shimmer. */
	private static final Set<AvatarState> ACTIVE_STATES = EnumSet.of(
		AvatarState.PLAYER_ACTIVE,
		AvatarState.SKILLING,
		AvatarState.COMBAT,
		AvatarState.BANKING,
		AvatarState.GRAND_EXCHANGE,
		AvatarState.TELEPORTING,
		AvatarState.WALKING,
		AvatarState.RUNNING);
	private static final Set<AttentionReason> NORMAL_REASONS = EnumSet.of(
		AttentionReason.INVENTORY_FULL,
		AttentionReason.AFK_WARNING,
		AttentionReason.DEATH,
		AttentionReason.LEVEL_UP);
	private static final Set<AttentionReason> DANGER_REASONS = EnumSet.of(
		AttentionReason.LOW_HITPOINTS,
		AttentionReason.LOW_PRAYER);

	/** Independent latches; the highest priority one is published to the widget. */
	private final EnumSet<AttentionReason> reasons = EnumSet.noneOf(AttentionReason.class);

	// Previous-tick values for rising-edge detection.
	private boolean prevInvFull;
	private boolean prevAfk;
	private boolean prevLowHp;
	private boolean prevLowPrayer;
	private boolean prevDeath;
	private boolean prevLevelUp;
	private boolean unexpectedDisconnect;

	/** Advances one tick, clearing before evaluating new trigger edges. */
	public void tick(
		AvatarState state,
		boolean inventoryFull,
		boolean lowHp, boolean lowPrayer,
		boolean afkWarning, boolean death, boolean levelUp,
		boolean hpSafe, boolean prayerSafe)
	{
		boolean activeState = ACTIVE_STATES.contains(state);
		boolean danger = hasAny(DANGER_REASONS);
		if (danger)
		{
			boolean vitalsRecovered = (!reasons.contains(AttentionReason.LOW_HITPOINTS) || hpSafe)
				&& (!reasons.contains(AttentionReason.LOW_PRAYER) || prayerSafe);
			boolean activeNonCombat = activeState && state != AvatarState.COMBAT;
			if (vitalsRecovered || activeNonCombat)
			{
				reasons.removeAll(DANGER_REASONS);
			}
		}
		if (activeState)
		{
			reasons.removeAll(NORMAL_REASONS);
		}

		boolean invEdge = inventoryFull && !prevInvFull;
		boolean afkEdge = afkWarning && !prevAfk;
		boolean lowHpEdge = lowHp && !prevLowHp;
		boolean lowPrayerEdge = lowPrayer && !prevLowPrayer;
		boolean deathEdge = death && !prevDeath;
		boolean levelUpEdge = levelUp && !prevLevelUp;

		armIf(invEdge, AttentionReason.INVENTORY_FULL);
		armIf(afkEdge, AttentionReason.AFK_WARNING);
		armIf(deathEdge, AttentionReason.DEATH);
		armIf(levelUpEdge, AttentionReason.LEVEL_UP);
		armIf(lowHpEdge, AttentionReason.LOW_HITPOINTS);
		armIf(lowPrayerEdge, AttentionReason.LOW_PRAYER);

		prevInvFull = inventoryFull;
		prevAfk = afkWarning;
		prevLowHp = lowHp;
		prevLowPrayer = lowPrayer;
		prevDeath = death;
		prevLevelUp = levelUp;
	}

	/** Arm a completion notice that continued skilling cannot dismiss. */
	public void armEtaExpired()
	{
		reasons.add(AttentionReason.ETA_REACHED);
	}

	/** Replace stale gameplay reasons with one local unexpected-disconnect latch. */
	public void armDisconnected()
	{
		resetReasons();
		reasons.add(AttentionReason.DISCONNECTED);
	}

	public void onConnectionLost()
	{
		unexpectedDisconnect = true;
		armDisconnected();
	}

	public void onLoggedIn()
	{
		unexpectedDisconnect = false;
		clearDisconnected();
	}

	public void maintainLoggedOut()
	{
		if (unexpectedDisconnect)
		{
			armDisconnected();
		}
		else
		{
			reset();
		}
	}

	/** Clear the disconnect latch after login or an intentional logout/hop state. */
	public void clearDisconnected()
	{
		reasons.remove(AttentionReason.DISCONNECTED);
	}

	/** Clear the ETA latch only after an actual interaction with the RuneLite client. */
	public void onClientInteraction()
	{
		reasons.remove(AttentionReason.ETA_REACHED);
		reasons.removeAll(NORMAL_REASONS);
	}

	/** @return whether the shimmer should be drawn this tick. */
	public boolean isActive()
	{
		return !reasons.isEmpty();
	}

	/** @return the highest-priority currently latched reason. */
	public AttentionReason attentionReason()
	{
		AttentionReason primary = AttentionReason.NONE;
		for (AttentionReason reason : reasons)
		{
			if (reason.priority() > primary.priority())
			{
				primary = reason;
			}
		}
		return primary;
	}

	/** Clear everything, including the edge trackers. Call on logout. */
	public void reset()
	{
		unexpectedDisconnect = false;
		resetReasons();
	}

	private void resetReasons()
	{
		reasons.clear();
		prevInvFull = false;
		prevAfk = false;
		prevLowHp = false;
		prevLowPrayer = false;
		prevDeath = false;
		prevLevelUp = false;
	}

	private void armIf(boolean condition, AttentionReason reason)
	{
		if (condition)
		{
			reasons.add(reason);
		}
	}

	private boolean hasAny(Set<AttentionReason> candidates)
	{
		for (AttentionReason reason : candidates)
		{
			if (reasons.contains(reason))
			{
				return true;
			}
		}
		return false;
	}
}

