package com.idlefamiliar;

/**
 * Resets per-session state. An epoch rejects queued inventory reads from an
 * earlier login.
 */
final class SessionLifecycleCoordinator
{
	private final EtaSessionManager etaSessionManager;
	private final InventoryHistory inventoryHistory;
	private final FullInventoryActivityTracker fullInventoryActivityTracker;
	private final ActivityDetector activityDetector;
	private final SkillProgressTracker skillProgressTracker;

	private int epoch;

	SessionLifecycleCoordinator(EtaSessionManager etaSessionManager,
		InventoryHistory inventoryHistory,
		FullInventoryActivityTracker fullInventoryActivityTracker,
		ActivityDetector activityDetector,
		SkillProgressTracker skillProgressTracker)
	{
		this.etaSessionManager = etaSessionManager;
		this.inventoryHistory = inventoryHistory;
		this.fullInventoryActivityTracker = fullInventoryActivityTracker;
		this.activityDetector = activityDetector;
		this.skillProgressTracker = skillProgressTracker;
	}

	/** Invalidates queued work, clears session state, and returns the new epoch. */
	synchronized int reset()
	{
		epoch++;
		etaSessionManager.reset();
		inventoryHistory.reset();
		activityDetector.reset();
		fullInventoryActivityTracker.reset();
		skillProgressTracker.reset();
		return epoch;
	}

	synchronized int epoch()
	{
		return epoch;
	}

	synchronized boolean isCurrent(int expectedEpoch)
	{
		return expectedEpoch == epoch;
	}

	/**
	 * Commit the same guarded baseline to inventory recognition and the ETA
	 * controller. A stale queued read is ignored without touching either owner.
	 */
	synchronized boolean seedIfCurrent(int expectedEpoch, InventoryState inventory,
		InventoryState equipment)
	{
		if (expectedEpoch != epoch)
		{
			return false;
		}

		InventoryState safeInventory = inventory == null ? InventoryState.empty() : inventory;
		inventoryHistory.seed(safeInventory, equipment);
		etaSessionManager.seedInventory(safeInventory);
		return true;
	}
}

package com.idlefamiliar;

/** One committed inventory transition shared by every activity consumer. */
final class InventoryChange
{
	private final InventoryState before;
	private final InventoryState after;
	private final InventoryDelta delta;
	private final boolean hasBaseline;

	InventoryChange(InventoryState before, InventoryState after)
	{
		this.hasBaseline = before != null;
		this.before = before == null ? InventoryState.empty() : before;
		this.after = after == null ? InventoryState.empty() : after;
		this.delta = new InventoryDelta(this.before.itemCounts(), this.after.itemCounts());
	}

	InventoryState before()
	{
		return before;
	}

	InventoryState after()
	{
		return after;
	}

	InventoryDelta delta()
	{
		return delta;
	}

	boolean hasBaseline()
	{
		return hasBaseline;
	}
}

