	public AvatarPackManifest(String identifier, String displayName, int nativeSize, Point visualAnchor,
		AvatarState fallbackState, Set<AvatarState> supportedStates, WidgetTheme recommendedTheme)
	{
		this(identifier, displayName, nativeSize, visualAnchor, fallbackState,
			supportedStates, recommendedTheme, nativeSize,
			SpriteSheetLoader.DEFAULT_MAX_DECODED_PIXELS, Collections.emptySet());
	}

	public AvatarPackManifest(String identifier, String displayName, int nativeSize, Point visualAnchor,
		AvatarState fallbackState, Set<AvatarState> supportedStates, WidgetTheme recommendedTheme,
		int sourceFrameSize, long maximumDecodedPixels, Set<String> bundledSpriteSheets)
	{
		if (identifier == null || identifier.trim().isEmpty() || displayName == null || displayName.trim().isEmpty())
		{
			throw new IllegalArgumentException("Avatar packs require an identifier and display name");
		}
		if (nativeSize <= 0)
		{
			throw new IllegalArgumentException("Avatar native size must be positive");
		}
		if (sourceFrameSize <= 0 || maximumDecodedPixels <= 0)
		{
			throw new IllegalArgumentException("Avatar source dimensions and pixel limit must be positive");
		}
		this.identifier = identifier;
		this.displayName = displayName;
		this.nativeSize = nativeSize;
		this.visualAnchor = visualAnchor == null ? new Point(nativeSize / 2, nativeSize) : new Point(visualAnchor);
		this.fallbackState = fallbackState == null ? AvatarState.DEFAULT : fallbackState;
		EnumSet<AvatarState> states = supportedStates == null || supportedStates.isEmpty()
			? EnumSet.of(this.fallbackState) : EnumSet.copyOf(supportedStates);
		states.add(this.fallbackState);
		this.supportedStates = Collections.unmodifiableSet(states);
		this.recommendedTheme = recommendedTheme == null ? WidgetTheme.CLASSIC_RUNESCAPE : recommendedTheme;
		this.sourceFrameSize = sourceFrameSize;
		this.maximumDecodedPixels = maximumDecodedPixels;
		Set<String> sheets = bundledSpriteSheets == null
			? Collections.emptySet() : new LinkedHashSet<>(bundledSpriteSheets);
		if (sheets.stream().anyMatch(name -> name == null || !name.endsWith(".png")))
		{
			throw new IllegalArgumentException("Bundled sprite manifest entries must be PNG filenames");
		}
		this.bundledSpriteSheets = Collections.unmodifiableSet(sheets);
	}

	public static AvatarPackManifest goldenToad()
	{
		return GOLDEN_TOAD;
	}

	public String getIdentifier()
	{
		return identifier;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public int getNativeSize()
	{
		return nativeSize;
	}

	public Point getVisualAnchor()
	{
		return new Point(visualAnchor);
	}

	public AvatarState getFallbackState()
	{
		return fallbackState;
	}

	public Set<AvatarState> getSupportedStates()
	{
		return supportedStates;
	}

	public WidgetTheme getRecommendedTheme()
	{
		return recommendedTheme;
	}

	/** Physical square-frame size in the bundled source sheets. */
	public int getSourceFrameSize()
	{
		return sourceFrameSize;
	}

	/** Maximum pixels one compressed sheet may decode into. */
	public long getMaximumDecodedPixels()
	{
		return maximumDecodedPixels;
	}

	/** Exact PNG inventory expected in the bundled avatar pack. */
	public Set<String> getBundledSpriteSheets()
	{
		return bundledSpriteSheets;
	}
}

package com.idlefamiliar;

import java.util.HashMap;
import java.util.Map;

/** Tracks session XP/hour from each skill's first real gain. */
public class XpRateTracker
{
	/** Suppresses startup spikes. */
	static final long MIN_ELAPSED_MILLIS = 5_000L;

	private static final double MILLIS_PER_HOUR = 3_600_000.0;

	private static final class Entry
	{
		private long startXp;
		private long startMillis;
		private long currentXp;
		private boolean started;

		private Entry(long startXp, long startMillis)
		{
			this.startXp = startXp;
			this.startMillis = startMillis;
			this.currentXp = startXp;
		}
	}

	private final Map<String, Entry> bySkill = new HashMap<>();

	/** Records total XP and starts timing on the first gain. */
	public void record(String skill, long totalXp, long nowMillis)
	{
		if (skill == null || skill.isEmpty())
		{
			return;
		}
		Entry entry = bySkill.get(skill);
		if (entry == null)
		{
			bySkill.put(skill, new Entry(totalXp, nowMillis));
			return;
		}
		if (entry.started)
		{
			entry.currentXp = totalXp;
			return;
		}
		if (totalXp > entry.startXp)
		{
			// Count training time, not idle time since login.
			entry.started = true;
			entry.startMillis = nowMillis;
			entry.currentXp = totalXp;
		}
		else
		{
			// Login syncs and corrections keep the baseline current.
			entry.startXp = totalXp;
			entry.startMillis = nowMillis;
			entry.currentXp = totalXp;
		}
	}

	public long ratePerHour(String skill, long nowMillis)
	{
		if (skill == null)
		{
			return 0;
		}
		Entry entry = bySkill.get(skill);
		if (entry == null)
		{
			return 0;
		}
		long elapsed = nowMillis - entry.startMillis;
		long gained = entry.currentXp - entry.startXp;
		if (elapsed < MIN_ELAPSED_MILLIS || gained <= 0)
		{
			return 0;
		}
		return Math.round(gained * MILLIS_PER_HOUR / elapsed);
	}

	public void reset()
	{
		bySkill.clear();
	}

	/** Formats a compact display rate; non-positive values show a dash. */
	public static String formatRate(long perHour)
	{
		if (perHour <= 0)
		{
			return "–/hr";
		}
		if (perHour >= 1_000_000)
		{
			return String.format("%.1fm/hr", perHour / 1_000_000.0);
		}
		if (perHour >= 100_000)
		{
			return String.format("%.0fk/hr", perHour / 1_000.0);
		}
		if (perHour >= 1_000)
		{
			return String.format("%.1fk/hr", perHour / 1_000.0);
		}
		return perHour + "/hr";
	}
}

