import net.runelite.client.config.ConfigManager;

public class DesktopPetWindow
{
	private static final int BASE_AVATAR_SIZE = 64;

	// Dynamic content must not resize the desktop window.
	private static final int MARGIN = 10;
	private static final int TEXT_GAP = 6;
	private static final int TEXT_ROW_HEIGHT = 20;
	private static final int TEXT_PADDING_X = 9;
	private static final int MIN_WIDTH = 80;
	private static final int MIN_HEIGHT = 64;

	public static final int CARROT_SIZE = 18;

	private static final long TOPMOST_REASSERT_INTERVAL_MS = 4000;
	static final int ANIMATED_REPAINT_INTERVAL_MS = 100;
	static final int STATIC_REPAINT_INTERVAL_MS = 500;
	static final int LOGGED_OUT_REPAINT_INTERVAL_MS = 1000;

	private static final int CARET_SIZE = CARROT_SIZE;

	private static final int SHIMMER_PERIOD_MS = 2200;
	private static final int SHIMMER_MAX_ALPHA = 85;

	// Side-panel metrics.
	private static final int PANEL_PADDING = 7;
	private static final int PANEL_ROW_HEIGHT = 16;
	private static final int PANEL_LABEL_GAP = 14;
	private static final int PANEL_GAP = 8;
	private static final int CONTROL_BUTTON_GAP = 6;
	private static final int AVATAR_FRAME_PADDING = 16;
	private static final int INVENTORY_VIEWER_GAP = 6;
	private static final int INVENTORY_BUTTON_HORIZONTAL_PADDING = 6;
	private static final String RESERVED_PANEL_VALUE = "~99h59";
	private static final String RESERVED_VITAL_VALUE = "999/999";
	private static final String RESERVED_XP_RATE_VALUE = "99.9m";

	private final WidgetContentSource contentSource;
	private final IdleFamiliarConfig config;
	private final ConfigManager configManager;
	private final DesktopWindowPositionController positionController;
	private final IntUnaryOperator uiScaler = this::ui;
	/** Event-backed values avoid stale config-proxy reads. */
	private volatile WidgetTheme selectedTheme;
	private volatile AvatarScale selectedScale;
	private JWindow window;
	private Timer repaintTimer;
	private long lastTopmostAssertMs;
	private volatile boolean collapsed;

	public DesktopPetWindow(WidgetContentSource contentSource, IdleFamiliarConfig config,
		ConfigManager configManager)
	{
		this.contentSource = contentSource;
		this.config = config;
		this.configManager = configManager;
		this.positionController = new DesktopWindowPositionController(config, configManager);
		this.collapsed = config != null && config.widgetCollapsed();
		this.selectedScale = config == null || config.avatarScale() == null
			? AvatarScale.X2 : config.avatarScale();
		this.selectedTheme = config == null || config.widgetTheme() == null
			? WidgetTheme.CLASSIC_RUNESCAPE : config.widgetTheme();
	}

	public void show()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (window != null)
			{
				return;
			}

			window = new JWindow();
			// Accept pointer input without taking keyboard focus.
			window.setFocusableWindowState(false);
			window.setAutoRequestFocus(false);
			window.setAlwaysOnTop(true);
			window.setBackground(new Color(0, 0, 0, 0));
			window.setContentPane(new PetComponent());
			window.setSize(MIN_WIDTH, MIN_HEIGHT);
			positionController.attach(window);
			positionController.restore();
			window.setVisible(true);
			lastTopmostAssertMs = System.currentTimeMillis();

			repaintTimer = new Timer(ANIMATED_REPAINT_INTERVAL_MS,
				event -> onRepaintTimer());
			repaintTimer.start();
		});
	}

	private void onRepaintTimer()
	{
		if (window == null)
		{
			return;
		}
		WidgetSnapshot snapshot = contentSource == null
			? null : contentSource.getWidgetSnapshot();
		int nextDelay = repaintIntervalMillis(collapsed,
			config == null || config.showAttentionShimmer(), snapshot);
		if (repaintTimer != null && repaintTimer.getDelay() != nextDelay)
		{
			repaintTimer.setDelay(nextDelay);
		}
		window.repaint();
		reassertAlwaysOnTop();
	}

	/** Selects a repaint rate for animated, static, or logged-out content. */
	static int repaintIntervalMillis(boolean collapsed, boolean shimmerEnabled,
		WidgetSnapshot snapshot)
	{
		if (!collapsed || (shimmerEnabled && snapshot != null && snapshot.isShimmerActive()))
		{
			return ANIMATED_REPAINT_INTERVAL_MS;
		}
		if (snapshot == null || snapshot.getState() == AvatarState.LOGGED_OUT)
		{
			return LOGGED_OUT_REPAINT_INTERVAL_MS;
		}
		return STATIC_REPAINT_INTERVAL_MS;
	}

	public void hide()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (repaintTimer != null)
			{
				repaintTimer.stop();
				repaintTimer = null;
			}

			if (window != null)
			{
				window.dispose();
				window = null;
				positionController.attach(null);
			}
		});
	}

	/** Re-applies always-on-top after Windows silently drops it. */
	private void reassertAlwaysOnTop()
	{
		if (window == null)
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (now - lastTopmostAssertMs < TOPMOST_REASSERT_INTERVAL_MS)
		{
			return;
		}
		lastTopmostAssertMs = now;
		if (window.isAlwaysOnTopSupported())
		{
			window.setAlwaysOnTop(false);
			window.setAlwaysOnTop(true);
		}
	}

	/** Converts wall-clock time to a repeatable shimmer phase. */
	static double shimmerPhaseAt(long wallClockMillis)
	{
		return Math.floorMod(wallClockMillis, (long) SHIMMER_PERIOD_MS) / (double) SHIMMER_PERIOD_MS;
	}

	static Rectangle standaloneControlBounds(int bodyX, int bodyY, int bodyHeight,
		Rectangle avatarBounds, int controlSize, int gap)
	{
		int controlY = avatarBounds == null
			? bodyY + (bodyHeight - controlSize) / 2
			: avatarBounds.y + (avatarBounds.height - controlSize) / 2;
		return new Rectangle(bodyX - gap - controlSize, controlY, controlSize, controlSize);
	}

	public void refreshVisibility()
	{
		show();
		SwingUtilities.invokeLater(() ->
		{
			refreshRepaintCadence();
			if (window != null)
			{
				window.repaint();
			}
		});
	}

	/** Applies the event value without rereading the config proxy. */
	public void applyTheme(String serializedTheme)
	{
		selectedTheme = WidgetTheme.fromConfigValue(serializedTheme);
	}

	public void applyScale(String serializedScale)
	{
		selectedScale = AvatarScale.fromConfigValue(serializedScale);
	}

	public boolean isCollapsed()
	{
		return collapsed;
	}

	public void applyCollapsed(String serializedValue)
	{
		collapsed = Boolean.parseBoolean(serializedValue);
	}

	public void applySelectedAnchor()
	{
		positionController.applySelectedAnchor();
	}

	public void resetPosition()
	{
		positionController.resetPosition();
	}

	public void moveToPointerDisplay()
	{
		positionController.moveToPointerDisplay();
	}

	boolean isWritingPositionConfiguration()
	{
		return positionController.isWritingConfiguration();
	}

	public void collapse()
	{
		setCollapsed(true, true);
	}

	public void expand()
	{
		setCollapsed(false, true);
	}

	void toggleCollapse()
	{
		setCollapsed(!collapsed, true);
	}

	private void setCollapsed(boolean value, boolean persist)
	{
		if (collapsed == value)
		{
			applyWindowSize();
			return;
		}
		collapsed = value;
		if (persist && configManager != null)
		{
			configManager.setConfiguration(IdleFamiliarConfig.GROUP, "widgetCollapsed", value);
		}
		applyWindowSize();
	}

	private void applyWindowSize()
	{
		SwingUtilities.invokeLater(() ->
		{
			refreshRepaintCadence();
			if (window != null)
			{
				window.repaint();
			}
		});
	}

	private void refreshRepaintCadence()
	{
		if (repaintTimer == null)
		{
			return;
		}
		WidgetSnapshot snapshot = contentSource == null
			? null : contentSource.getWidgetSnapshot();
		repaintTimer.setDelay(repaintIntervalMillis(collapsed,
			config == null || config.showAttentionShimmer(), snapshot));
	}

	private final class PetComponent extends JComponent
	{
		private Point dragOffset;
		private boolean dragging;
		private Rectangle caretBounds;
		private Rectangle inventoryRowBounds;
		private Rectangle inventoryViewerBounds;
		/** Keeps the viewer open while crossing the row-to-grid gap. */
		private Rectangle inventoryHoverBounds;
		private Rectangle etaRowBounds;
		private String etaTooltip;
		private boolean inventoryButtonHovered;
		/** Lock expansion while visible to prevent side flipping. */
		private boolean inventoryViewerPaintedVisible;
		private boolean inventoryViewerExpansionUp;
		private final InventoryGridRenderer inventoryRenderer = new InventoryGridRenderer();
		private WidgetTheme activeTheme = selectedTheme;

		private PetComponent()
		{
			MouseAdapter handler = new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent event)
				{
					dragOffset = event.getPoint();
					dragging = true;
				}

				@Override
				public void mouseDragged(MouseEvent event)
				{
					if (dragOffset != null && window != null)
					{
						window.setLocation(event.getXOnScreen() - dragOffset.x, event.getYOnScreen() - dragOffset.y);
					}
				}

				@Override
				public void mouseReleased(MouseEvent event)
				{
					dragOffset = null;
					dragging = false;
					persistDraggedPosition();
				}

				@Override
				public void mouseClicked(MouseEvent event)
				{
					if (controlBounds().contains(event.getPoint()))
					{
						toggleCollapse();
					}
				}

				@Override
				public void mouseEntered(MouseEvent event)
				{
					updateInventoryViewer(event.getPoint());
				}

				@Override
				public void mouseExited(MouseEvent event)
				{
					setInventoryButtonHovered(false);
					setToolTipText(null);
				}

				@Override
				public void mouseMoved(MouseEvent event)
				{
					updateInventoryViewer(event.getPoint());
					updateEtaTooltip(event.getPoint());
				}
			};
			addMouseListener(handler);
			addMouseMotionListener(handler);
		}

		private void updateInventoryViewer(Point point)
		{
			boolean inInventory = point != null
				&& ((inventoryHoverBounds != null && inventoryHoverBounds.contains(point))
					|| (inventoryRowBounds != null && inventoryRowBounds.contains(point)));
			setInventoryButtonHovered(inInventory);
		}

		private void setInventoryButtonHovered(boolean hovered)
		{
			if (inventoryButtonHovered != hovered)
			{
				inventoryButtonHovered = hovered;
				repaint();
			}
		}

		private void updateEtaTooltip(Point point)
		{
			String next = point != null && etaRowBounds != null && etaRowBounds.contains(point)
				? etaTooltip : null;
			setToolTipText(next == null || next.isEmpty() ? null : next);
		}

		@Override
		public Dimension getPreferredSize()
		{
			return new Dimension(MIN_WIDTH, MIN_HEIGHT);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

			float avatarAlpha = clampAlpha(config != null ? config.avatarOpacityPercent() / 100.0f : 1.0f);
			float widgetAlpha = clampAlpha(config != null ? config.widgetOpacityPercent() / 100.0f : 1.0f);
			activeTheme = selectedTheme == null ? WidgetTheme.CLASSIC_RUNESCAPE : selectedTheme;
			Font baseFont = g.getFont();
			g.setFont(baseFont.deriveFont(Math.max(6f,
				(float) (baseFont.getSize2D() * widgetScaleMultiplier()))));
			FontMetrics metrics = g.getFontMetrics();

			// One snapshot prevents mixed-tick paints; animation remains live.
			WidgetSnapshot snapshot = contentSource != null ? contentSource.getWidgetSnapshot() : null;
			inventoryRowBounds = null;
			inventoryViewerBounds = null;
			inventoryHoverBounds = null;
			etaRowBounds = null;
			etaTooltip = null;
			long paintTimeMs = System.currentTimeMillis();
			inventoryRenderer.recordChanges(
				snapshot == null ? InventorySnapshot.empty() : snapshot.getInventory(), paintTimeMs);

			BufferedImage skillIcon = (config != null && config.showSkillIcon() && snapshot != null)
				? snapshot.getSkillIcon() : null;

			// A fixed square canvas prevents sprite-frame layout shifts.
			boolean avatarVisible = !collapsed;
			AvatarPackManifest avatarManifest = contentSource == null
				? AvatarPackManifest.goldenToad() : contentSource.getAvatarPackManifest();
			int avatarNativeSize = avatarManifest == null ? BASE_AVATAR_SIZE : avatarManifest.getNativeSize();
			BufferedImage frame = (avatarVisible && contentSource != null)
				? contentSource.getCurrentFrame() : null;
			int avatarDrawWidth = 0;
			int avatarDrawHeight = 0;
			double avatarFrameScale = 1.0d;
			if (frame != null)
			{
				avatarFrameScale = avatarScaleMultiplier() * (avatarNativeSize / (double) frame.getHeight());
				avatarDrawWidth = Math.max(1, (int) Math.round(frame.getWidth() * avatarFrameScale));
				avatarDrawHeight = Math.max(1, (int) Math.round(frame.getHeight() * avatarFrameScale));
			}
			int avatarFramePadding = avatarVisible && config.showWidgetFrame()
				? ui(AVATAR_FRAME_PADDING) : 0;
			int avatarCanvas = !avatarVisible ? 0 : Math.max(1,
				(int) Math.round(avatarNativeSize * avatarScaleMultiplier())
					+ avatarFramePadding * 2);

			boolean loggedInish = snapshot != null && snapshot.getMaxHitpoints() > 0;
			String[] rowLabels = new String[6];
			String[] rowValues = new String[6];
			int rowCount = 0;
			boolean hasInventoryRow = false;
			if (loggedInish && config.showHpOrb())
			{
				rowLabels[rowCount] = "HP";
				rowValues[rowCount++] = snapshot.getHitpoints() + "/" + snapshot.getMaxHitpoints();
			}
			if (loggedInish && config.showPrayerOrb())
			{
				rowLabels[rowCount] = "Pray";
				rowValues[rowCount++] = snapshot.getPrayer() + "/" + snapshot.getMaxPrayer();
			}
			if (loggedInish && config.showInventoryCount())
			{
				rowLabels[rowCount] = "Inv";
				rowValues[rowCount++] = snapshot.getInventoryCount() + "/28";
				hasInventoryRow = true;
			}
			if (config.showAdvancedInfo())
			{
				String xpHr = snapshot != null ? snapshot.getXpHr() : null;
				rowLabels[rowCount] = "XP/h";
				rowValues[rowCount++] = xpHr != null ? xpHr : "-";
			}
			TaskEtaSnapshot taskEta = snapshot != null ? snapshot.getTaskEta() : TaskEtaSnapshot.inactive();
			// Reserve the ETA row so countdown changes cannot shift layout.
			if (loggedInish && config.showTaskEta())
			{
				rowLabels[rowCount] = "ETA";
				rowValues[rowCount++] = WidgetTextFormatter.compactTaskEta(taskEta);
			}

			int panelRowHeight = ui(PANEL_ROW_HEIGHT);
			int panelPadding = ui(PANEL_PADDING);
			int panelGap = ui(PANEL_GAP);
			int labelWidth = reservedPanelLabelWidth(metrics, panelRowHeight);
			int valueWidth = reservedPanelValueWidth(metrics);
			for (int i = 0; i < rowCount; i++)
			{
				int etaIconWidth = "ETA".equals(rowLabels[i]) ? panelRowHeight - ui(2) : 0;
				labelWidth = Math.max(labelWidth, metrics.stringWidth(rowLabels[i]) + etaIconWidth);
			}
			boolean hasPanel = rowCount > 0;
			int panelInnerWidth = labelWidth + ui(PANEL_LABEL_GAP) + valueWidth;
			int panelWidth = hasPanel ? panelInnerWidth + panelPadding * 2 : 0;
			int panelHeight = hasPanel ? rowCount * panelRowHeight + panelPadding * 2 : 0;
			InventoryDensity inventoryDensity = config.inventoryDensity() == null
				? InventoryDensity.MINI_GRID : config.inventoryDensity();
			boolean inventoryDetailsEnabled = inventoryDensity != InventoryDensity.OFF;
			boolean showInventoryViewer = hasInventoryRow && inventoryDetailsEnabled
				&& (inventoryButtonHovered || config.inventoryViewerAlwaysVisible());
			Rectangle widgetBounds = window == null ? null : window.getBounds();
			Rectangle widgetWorkArea = widgetBounds == null ? null : positionController.workAreaFor(widgetBounds);
			WidgetAnchor widgetAnchor = config == null || config.widgetAnchor() == null
				? WidgetAnchor.FREE : config.widgetAnchor();
			boolean resolvedInventoryViewerAbove = WidgetPositioning.inventoryExpandsUp(
				widgetBounds, widgetWorkArea, widgetAnchor);
			if (!inventoryViewerPaintedVisible)
			{
				inventoryViewerExpansionUp = resolvedInventoryViewerAbove;
			}
			boolean inventoryViewerAbove = inventoryViewerPaintedVisible
				? inventoryViewerExpansionUp : resolvedInventoryViewerAbove;
			boolean preserveInventoryBottomEdge = inventoryViewerAbove
				&& (showInventoryViewer || inventoryViewerPaintedVisible);
			int inventoryViewerGap = ui(INVENTORY_VIEWER_GAP);
			Dimension inventoryViewerSize = InventoryGridRenderer.viewerSize(
				inventoryDensity, uiScaler);
			int inventoryViewerWidth = inventoryViewerSize.width;
			int inventoryViewerHeight = inventoryViewerSize.height;
			// The viewer and monitor share one width.
			if (hasPanel && hasInventoryRow && inventoryDetailsEnabled)
			{
				panelWidth = Math.max(panelWidth, inventoryViewerWidth);
				panelInnerWidth = panelWidth - panelPadding * 2;
			}
			int inventoryViewerExtraHeight = showInventoryViewer
				? inventoryViewerGap + inventoryViewerHeight : 0;

			boolean statusTextEnabled = config.showAttentionReason();
			String message = WidgetTextFormatter.visibleStatusMessage(snapshot, statusTextEnabled);
			// Status text changes without changing the widget silhouette.
			boolean hasText = statusTextEnabled;
			int textHeight = hasText ? ui(TEXT_ROW_HEIGHT) : 0;

			int bodyWidth = avatarCanvas + (avatarCanvas > 0 && hasPanel ? panelGap : 0) + panelWidth;
			if (hasText)
			{
				bodyWidth = Math.max(bodyWidth, ui(120));
			}
			int bodyHeight = Math.max(avatarCanvas, panelHeight);
			int controlSize = ui(CARET_SIZE);
			int controlGap = ui(CONTROL_BUTTON_GAP);
			int controlRail = controlSize + controlGap;

			// Reserve viewer width to prevent hover shifts and clipping.
			int reservedInventoryWidth = hasInventoryRow && inventoryDetailsEnabled
				? inventoryViewerWidth : 0;
			int contentWidth = Math.max(controlRail + bodyWidth, reservedInventoryWidth);
			int contentHeight = bodyHeight + inventoryViewerExtraHeight
				+ (hasText ? ui(TEXT_GAP) + textHeight : 0);
			contentWidth = Math.max(contentWidth, controlSize);
			contentHeight = Math.max(contentHeight, controlSize);

			fitWindow(contentWidth, contentHeight, preserveInventoryBottomEdge);
			inventoryViewerPaintedVisible = showInventoryViewer;

			// Keep the widget fixed while the hover viewer resizes the window.
			int originX = ui(MARGIN);
			int originY = ui(MARGIN);
			int bodyY = originY + (showInventoryViewer && inventoryViewerAbove
				? inventoryViewerExtraHeight : 0);
			int bodyX = originX + controlRail;
			int panelX = bodyX + avatarCanvas + (avatarCanvas > 0 ? panelGap : 0);
			int panelY = bodyY + (bodyHeight - panelHeight) / 2;
			int avatarY = bodyY + (bodyHeight - avatarCanvas) / 2;
			Rectangle avatarCanvasBounds = avatarVisible
				? new Rectangle(bodyX, avatarY, avatarCanvas, avatarCanvas) : null;
			int avatarX = bodyX + Math.max(0, (avatarCanvas - avatarDrawWidth) / 2);
			int avatarDrawY = avatarY + Math.max(0, (avatarCanvas - avatarDrawHeight) / 2);
			caretBounds = standaloneControlBounds(bodyX, bodyY, bodyHeight,
				avatarCanvasBounds, controlSize, controlGap);
			int controlX = caretBounds.x;
			int controlY = caretBounds.y;
			Composite original = g.getComposite();

			// Connect from the fixed frame edge, not sprite alpha bounds.
			if (avatarVisible && config.showWidgetFrame())
			{
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, widgetAlpha));
				if (hasPanel)
				{
					drawCompanionBridge(g, avatarCanvasBounds.x + avatarCanvasBounds.width, panelX,
						panelY + panelHeight / 2, panelRowHeight);
				}
				g.setComposite(original);
			}

			if (frame != null)
			{
				original = g.getComposite();
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, avatarAlpha));
				g.drawImage(frame, avatarX, avatarDrawY, avatarDrawWidth, avatarDrawHeight, null);
				g.setComposite(original);
			}

			// Foreground frame art masks sprite overflow.
			if (drawsAvatarFrame(avatarVisible, config.showWidgetFrame()))
			{
				original = g.getComposite();
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, widgetAlpha));
				drawAvatarContainment(g, avatarCanvasBounds);
				g.setComposite(original);
			}

			if (hasPanel)
			{
				original = g.getComposite();
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, widgetAlpha));
				drawStonePanel(g, panelX, panelY, panelWidth, panelHeight);
				if (config.showWidgetFrame())
				{
					ThemeDecorationRenderer.draw(g,
						ThemeAssets.forTheme(activeTheme).panelDecorations(),
						new Rectangle(panelX, panelY, panelWidth, panelHeight),
						widgetScaleMultiplier());
				}
				int rowY = panelY + panelPadding;
				for (int i = 0; i < rowCount; i++)
				{
					BufferedImage rowIcon = "XP/h".equals(rowLabels[i]) ? skillIcon : null;
					TaskEtaSnapshot rowEta = "ETA".equals(rowLabels[i]) ? taskEta : TaskEtaSnapshot.inactive();
					if ("ETA".equals(rowLabels[i]))
					{
						etaRowBounds = new Rectangle(panelX + panelPadding, rowY, panelInnerWidth, panelRowHeight);
						etaTooltip = rowEta == null ? null : rowEta.getDetailText();
					}
					if ("Inv".equals(rowLabels[i]) && inventoryDetailsEnabled)
					{
						inventoryRowBounds = drawInventoryPanelRow(g, rowValues[i],
							panelX + panelPadding, rowY, panelInnerWidth, metrics, inventoryButtonHovered,
							panelRowHeight);
					}
					else
					{
						drawPanelRow(g, rowLabels[i], rowValues[i], rowIcon, rowEta,
							panelX + panelPadding, rowY, panelInnerWidth, metrics, panelRowHeight);
					}
					rowY += panelRowHeight;
				}
				// Draw shimmer inside the panel opacity composite.
				if (config.showAttentionShimmer() && snapshot != null && snapshot.isShimmerActive())
				{
					drawShimmer(g, panelX, panelY, panelWidth, panelHeight);
				}
				g.setComposite(original);
			}

			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, widgetAlpha));
			drawCaret(g, controlX, controlY, controlSize, collapsed);
			g.setComposite(original);

			if (showInventoryViewer && snapshot != null)
			{
				int viewerX = panelX;
				int viewerY = inventoryViewerAbove ? originY
					: bodyY + bodyHeight + inventoryViewerGap;
				original = g.getComposite();
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, widgetAlpha));
				inventoryViewerBounds = new Rectangle(viewerX, viewerY,
					inventoryViewerWidth, inventoryViewerHeight);
				inventoryRenderer.paint(g, snapshot.getInventory(), snapshot.getInventoryCount(),
					inventoryDensity, viewerX, viewerY, inventoryViewerWidth, inventoryViewerHeight,
					activeTheme, widgetScaleMultiplier(), uiScaler, paintTimeMs);
				if (config.showAttentionShimmer() && snapshot.isShimmerActive())
				{
					drawShimmer(g, viewerX, viewerY, inventoryViewerWidth, inventoryViewerHeight);
				}
				g.setComposite(original);
			}
			if (inventoryRowBounds != null && inventoryViewerBounds != null)
			{
				inventoryHoverBounds = inventoryRowBounds.union(inventoryViewerBounds);
			}
			else
			{
				inventoryHoverBounds = inventoryRowBounds;
			}

			// Inactive status leaves the fixed row empty.
			if (hasText)
			{
				int textY = bodyY + bodyHeight
					+ (inventoryViewerAbove ? 0 : inventoryViewerExtraHeight) + ui(TEXT_GAP);
				int textX = bodyX;
				original = g.getComposite();
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, widgetAlpha));
				drawActionText(g, message == null ? "" : message, metrics, textX, textY, bodyWidth, textHeight);
				g.setComposite(original);
			}

			g.dispose();
		}

		private void drawPanelRow(Graphics2D g, String label, String value, BufferedImage icon, TaskEtaSnapshot taskEta,
			int x, int top, int innerWidth, FontMetrics metrics, int rowHeight)
		{
			int baseline = top + metrics.getAscent();
			int labelX = x;
			boolean etaRow = "ETA".equals(label);
			if (icon != null)
			{
				int size = rowHeight - ui(2);
				int iconY = top + (rowHeight - size) / 2;
				g.drawImage(icon, x, iconY, size, size, null);
			}
			else if (etaRow)
			{
				// Keep the marker still; only the numeric countdown changes.
				drawTaskEtaBadge(g, x, top, taskEta, rowHeight);
				labelX += rowHeight - ui(2);
			}
			else
			{
				g.setColor(activeTheme.shadow());
				g.drawString(label, labelX + 1, baseline + 1);
				g.setColor(activeTheme.borderLight());
				g.drawString(label, labelX, baseline);
			}
			if (etaRow)
			{
				g.setColor(activeTheme.shadow());
				g.drawString(label, labelX + 1, baseline + 1);
				g.setColor(activeTheme.borderLight());
				g.drawString(label, labelX, baseline);
			}

			int valueX = x + innerWidth - metrics.stringWidth(value);
			g.setColor(activeTheme.shadow());
			g.drawString(value, valueX + 1, baseline + 1);
			g.setColor(activeTheme.text());
			g.drawString(value, valueX, baseline);
		}

		/** Draws a fixed-size inventory hover control. */
		private Rectangle drawInventoryPanelRow(Graphics2D g, String value, int x, int top,
			int innerWidth, FontMetrics metrics, boolean depressed, int rowHeight)
		{
			int baseline = top + metrics.getAscent();
			g.setColor(activeTheme.shadow());
			g.drawString("Inv", x + 1, baseline + 1);
			g.setColor(activeTheme.borderLight());
			g.drawString("Inv", x, baseline);

			int buttonWidth = metrics.stringWidth(value) + ui(INVENTORY_BUTTON_HORIZONTAL_PADDING) * 2;
			int buttonHeight = rowHeight;
			int buttonX = x + innerWidth - buttonWidth;
			int buttonY = top;
			drawInventoryButton(g, buttonX, buttonY, buttonWidth, buttonHeight, depressed);

			int textX = buttonX + (buttonWidth - metrics.stringWidth(value)) / 2;
			int textBaseline = buttonY + (buttonHeight - metrics.getHeight()) / 2 + metrics.getAscent()
				+ (depressed ? 1 : 0);
			g.setColor(activeTheme.shadow());
			g.drawString(value, textX + 1, textBaseline + 1);
			g.setColor(activeTheme.text());
			g.drawString(value, textX, textBaseline);
			return new Rectangle(buttonX, buttonY, buttonWidth, buttonHeight);
		}

		private void drawInventoryButton(Graphics2D g, int x, int y, int width, int height, boolean depressed)
		{
			g.setColor(depressed ? activeTheme.panelDark() : activeTheme.panel().brighter());
			g.fillRoundRect(x, y, width, height, 4, 4);
			g.setColor(depressed ? activeTheme.panelDark() : activeTheme.borderLight());
			g.drawLine(x + 1, y + 1, x + width - 2, y + 1);
			g.drawLine(x + 1, y + 1, x + 1, y + height - 2);
			g.setColor(depressed ? activeTheme.borderLight() : activeTheme.panelDark());
			g.drawLine(x + 1, y + height - 2, x + width - 2, y + height - 2);
			g.drawLine(x + width - 2, y + 1, x + width - 2, y + height - 2);
			g.setColor(activeTheme.border());
			g.drawRoundRect(x, y, width - 1, height - 1, 4, 4);
		}

		private int reservedPanelLabelWidth(FontMetrics metrics, int rowHeight)
		{
			return Math.max(metrics.stringWidth("Pray"),
				metrics.stringWidth("ETA") + rowHeight - ui(2));
		}

		private int reservedPanelValueWidth(FontMetrics metrics)
		{
			int inventoryButtonWidth = metrics.stringWidth("28/28")
				+ ui(INVENTORY_BUTTON_HORIZONTAL_PADDING) * 2;
			return Math.max(inventoryButtonWidth, Math.max(metrics.stringWidth(RESERVED_PANEL_VALUE),
				Math.max(metrics.stringWidth(RESERVED_VITAL_VALUE), metrics.stringWidth(RESERVED_XP_RATE_VALUE))));
		}

		private void drawTaskEtaBadge(Graphics2D g, int x, int top, TaskEtaSnapshot taskEta, int rowHeight)
		{
			Stroke originalStroke = g.getStroke();
			boolean active = taskEta != null && taskEta.isActive();
			int size = rowHeight - ui(5);
			int y = top + (rowHeight - size) / 2;
			g.setColor(activeTheme.panelDark());
			g.fillOval(x, y, size, size);
			g.setColor(active ? activeTheme.text() : activeTheme.border());
			if (active && taskEta.isApproximate() && !taskEta.isCalibrating())
			{
				g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND,
					10f, new float[]{2f, 2f}, 0f));
			}
			else
			{
				g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			}
			g.drawOval(x, y, size, size);
			if (active && taskEta.isCalibrating())
			{
				int dotY = y + size / 2;
				for (int dot = 0; dot < 3; dot++)
				{
					g.fillOval(x + 3 + dot * 3, dotY, 1, 1);
				}
				g.setStroke(originalStroke);
				return;
			}
			int centerX = x + size / 2;
			int centerY = y + size / 2;
			g.drawLine(centerX, centerY, centerX, y + 3);
			g.drawLine(centerX, centerY, x + size - 3, centerY);
			g.setStroke(originalStroke);
		}

		/** Draws a clipped diagonal shimmer without affecting layout. */
		private void drawShimmer(Graphics2D g, int x, int y, int w, int h)
		{
			double phase = shimmerPhaseAt(System.currentTimeMillis());
			int band = Math.max(18, (w + h) / 3);
			Color shimmerColor = activeTheme.shimmer();

			// Sweep the band fully from top-left to bottom-right.
			float u = (float) (phase * (w + h + 2 * band)) - band;
			float cx = x + u / 2f;
			float cy = y + u / 2f;
			float k = (float) (band / (2 * Math.sqrt(2)));

			Color edge = new Color(shimmerColor.getRed(), shimmerColor.getGreen(), shimmerColor.getBlue(), 0);
			Color core = new Color(shimmerColor.getRed(), shimmerColor.getGreen(), shimmerColor.getBlue(),
				SHIMMER_MAX_ALPHA);
			LinearGradientPaint shimmer = new LinearGradientPaint(
				new Point2D.Float(cx - k, cy - k),
				new Point2D.Float(cx + k, cy + k),
				new float[]{0f, 0.5f, 1f},
				new Color[]{edge, core, edge});

			Shape oldClip = g.getClip();
			Paint oldPaint = g.getPaint();
			g.clip(new RoundRectangle2D.Float(x, y, w, h, 5, 5));
			g.setPaint(shimmer);
			g.fillRect(x, y, w, h);
			g.setPaint(oldPaint);
			g.setClip(oldClip);
		}

		private void drawActionText(Graphics2D graphics, String message, FontMetrics metrics,
			int x, int top, int bubbleWidth, int bubbleHeight)
		{
			drawStonePanel(graphics, x, top, bubbleWidth, bubbleHeight);
			int textPadding = ui(TEXT_PADDING_X);
			String renderedMessage = ellipsize(message, metrics, bubbleWidth - textPadding * 2);
			int baseline = top + (bubbleHeight - metrics.getHeight()) / 2 + metrics.getAscent();
			graphics.setColor(activeTheme.shadow());
			graphics.drawString(renderedMessage, x + textPadding + ui(1), baseline + ui(1));
			graphics.setColor(new Color(255, 255, 255, 240));
			graphics.drawString(renderedMessage, x + textPadding, baseline);
		}

		private String ellipsize(String message, FontMetrics metrics, int maxWidth)
		{
			if (message == null || metrics.stringWidth(message) <= maxWidth)
			{
				return message == null ? "" : message;
			}
			final String suffix = "...";
			int end = message.length();
			while (end > 0 && metrics.stringWidth(message.substring(0, end) + suffix) > maxWidth)
			{
				end--;
			}
			return end == 0 ? suffix : message.substring(0, end) + suffix;
		}

		private void drawAvatarContainment(Graphics2D g, Rectangle bounds)
		{
			BufferedImage frameArt = ThemeAssets.forTheme(activeTheme).avatarFrame();
			if (frameArt != null)
			{
				g.drawImage(frameArt, bounds.x, bounds.y, bounds.width, bounds.height, null);
				return;
			}

			// Missing-resource fallback.
			g.setColor(activeTheme.borderLight());
			g.drawRoundRect(bounds.x, bounds.y, Math.max(1, bounds.width - ui(1)),
				Math.max(1, bounds.height - ui(1)), ui(8), ui(8));
		}

		private void drawCompanionBridge(Graphics2D g, int avatarRight, int panelLeft, int centerY, int rowHeight)
		{
			if (panelLeft <= avatarRight)
			{
				return;
			}
			int bridgeHeight = Math.max(ui(8), rowHeight - ui(4));
			int top = centerY - bridgeHeight / 2;
			g.setColor(activeTheme.panelDark());
			g.fillRect(avatarRight - ui(1), top, panelLeft - avatarRight + ui(2), bridgeHeight);
			g.setColor(activeTheme.borderLight());
			g.drawLine(avatarRight, top, panelLeft, top);
			g.setColor(activeTheme.border());
			g.drawLine(avatarRight, top + bridgeHeight - ui(1), panelLeft,
				top + bridgeHeight - ui(1));
		}

		private void drawStonePanel(Graphics2D g, int x, int y, int w, int h)
		{
			int one = ui(1);
			int two = ui(2);
			int radius = ui(5);
			g.setColor(activeTheme.panel());
			g.fillRoundRect(x, y, w, h, radius, radius);
			g.setStroke(new BasicStroke(1f));
			g.setColor(activeTheme.borderLight());
			g.drawLine(x + one, y + one, x + w - two, y + one);
			g.drawLine(x + one, y + one, x + one, y + h - two);
			g.setColor(activeTheme.border());
			g.drawLine(x + one, y + h - two, x + w - two, y + h - two);
			g.drawLine(x + w - two, y + one, x + w - two, y + h - two);
			g.setColor(activeTheme.panelDark());
			g.drawRoundRect(x, y, w - one, h - one, radius, radius);
		}

		private void fitWindow(int contentWidth, int contentHeight, boolean preserveBottomEdge)
		{
			int targetWidth = Math.max(ui(MIN_WIDTH), contentWidth + ui(MARGIN) * 2);
			int targetHeight = Math.max(ui(MIN_HEIGHT), contentHeight + ui(MARGIN) * 2);
			ensureWindowSize(targetWidth, targetHeight, preserveBottomEdge);
		}

		private void ensureWindowSize(int targetWidth, int targetHeight, boolean preserveBottomEdge)
		{
			positionController.resize(targetWidth, targetHeight, preserveBottomEdge, dragging);
		}

		private void persistDraggedPosition()
		{
			positionController.persistDraggedPosition();
		}

		private Rectangle controlBounds()
		{
			if (caretBounds != null)
			{
				return caretBounds;
			}
			int size = ui(CARET_SIZE);
			return new Rectangle(Math.max(0, getWidth() - size), 0, size, size);
		}

		private void drawCaret(Graphics2D graphics, int x, int y, int size, boolean pointRight)
		{
			drawStonePanel(graphics, x, y, size, size);

			int pad = Math.max(ui(5), size / 4);
			int left = x + pad;
			int right = x + size - pad;
			int top = y + pad;
			int bottom = y + size - pad;
			int cy = (top + bottom) / 2;

			graphics.setColor(activeTheme.text());
			graphics.setStroke(new BasicStroke(Math.max(1f, (float) widgetScaleMultiplier() * 1.6f),
				BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			if (pointRight)
			{
				graphics.drawLine(left, top, right, cy);
				graphics.drawLine(right, cy, left, bottom);
			}
			else
			{
				graphics.drawLine(right, top, left, cy);
				graphics.drawLine(left, cy, right, bottom);
			}
		}
	}

	static float clampAlpha(float value)
	{
		if (value < 0f)
		{
			return 0f;
		}
		return Math.min(1f, value);
	}

	private double avatarScaleMultiplier()
	{
		return selectedScale.avatarMultiplier();
	}

	private double widgetScaleMultiplier()
	{
		return selectedScale.widgetMultiplier();
	}

	private int ui(int basePixels)
	{
		return scaledUiMetric(basePixels, selectedScale);
	}

	static boolean drawsAvatarFrame(boolean avatarVisible, boolean widgetFrameVisible)
	{
		return avatarVisible && widgetFrameVisible;
	}

	static int scaledUiMetric(int basePixels, AvatarScale scale)
	{
		AvatarScale safeScale = scale == null ? AvatarScale.X2 : scale;
		return Math.max(1, (int) Math.round(basePixels * safeScale.widgetMultiplier()));
	}
}

package com.idlefamiliar;

/** Owns committed inventory history and the latest equipment snapshot. */
final class InventoryHistory
{
	private InventoryState current;
	private InventoryState equipment;

	void reset()
	{
		current = null;
		equipment = null;
	}

	void seed(InventoryState state, InventoryState equipped)
	{
		current = state == null ? InventoryState.empty() : state;
		equipment = equipped == null ? InventoryState.empty() : equipped;
	}

	InventoryChange observe(InventoryState next)
	{
		InventoryState after = next == null ? InventoryState.empty() : next;
		InventoryState before = current;
		current = after;
		return new InventoryChange(before, after);
	}

	InventoryState current()
	{
		return current == null ? InventoryState.empty() : current;
	}

	void observeEquipment(InventoryState state)
	{
		equipment = state == null ? InventoryState.empty() : state;
	}

	InventoryState equipment()
	{
		return equipment == null ? InventoryState.empty() : equipment;
	}

	boolean isSeeded()
	{
		return current != null;
	}

	boolean isEquipmentSeeded()
	{
		return equipment != null;
	}
}

package com.idlefamiliar;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.EnumMap;
import java.util.Map;
import javax.imageio.ImageIO;

/** Loads each active theme's compiled artwork once per plugin JVM. */
final class ThemeAssets
{
	private static final String RESOURCE_ROOT = "/com/idlefamiliar/themes/";
	private static final Map<WidgetTheme, Bundle> THEMES = loadThemes();

	private ThemeAssets()
	{
	}

	static Bundle forTheme(WidgetTheme theme)
	{
		WidgetTheme safeTheme = theme == null ? WidgetTheme.CLASSIC_RUNESCAPE : theme;
		Bundle assets = THEMES.get(safeTheme);
		return assets == null ? Bundle.EMPTY : assets;
	}

	private static Map<WidgetTheme, Bundle> loadThemes()
	{
		Map<WidgetTheme, Bundle> themes = new EnumMap<>(WidgetTheme.class);
		for (WidgetTheme theme : WidgetTheme.values())
		{
			String themeRoot = RESOURCE_ROOT + theme.assetId() + "/";
			themes.put(theme, new Bundle(
				load(themeRoot + "avatar-frame.png"),
				load(themeRoot + "panel-decorations.png")));
		}
		return themes;
	}

	private static BufferedImage load(String resource)
	{
		try (InputStream stream = ThemeAssets.class.getResourceAsStream(resource))
		{
			return stream == null ? null : ImageIO.read(stream);
		}
		catch (IOException ignored)
		{
			// DesktopPetWindow retains palette-only fallbacks for a damaged jar.
			return null;
		}
	}

	static final class Bundle
	{
		private static final Bundle EMPTY = new Bundle(null, null);
		private final BufferedImage avatarFrame;
		private final BufferedImage panelDecorations;

		private Bundle(BufferedImage avatarFrame, BufferedImage panelDecorations)
		{
			this.avatarFrame = avatarFrame;
			this.panelDecorations = panelDecorations;
		}

		BufferedImage avatarFrame()
		{
			return avatarFrame;
		}

		BufferedImage panelDecorations()
		{
			return panelDecorations;
		}
	}
}

package com.idlefamiliar;

/** Caller-verified approximate or fixed attention horizon. */
final class AttentionHorizonEtaEngine implements EtaEngine
{
	private HorizonRun run;
	private TaskEtaSnapshot snapshot = TaskEtaSnapshot.inactive();

	boolean start(String label, int horizonTicks, boolean eligible,
		boolean approximate, int tick)
	{
		if (!eligible || label == null || label.trim().isEmpty() || horizonTicks < 0)
		{
			cancel();
			return false;
		}
		run = new HorizonRun(label, horizonTicks, approximate, tick);
		snapshot = run.snapshotAt(tick);
		return true;
	}

	@Override
	public void onGameTick(int tick)
	{
		if (run != null)
		{
			snapshot = run.snapshotAt(tick);
		}
	}

	@Override
	public void cancel()
	{
		run = null;
		snapshot = TaskEtaSnapshot.inactive();
	}

	@Override
	public boolean isActive()
	{
		return run != null;
	}

	@Override
	public TaskEtaSnapshot snapshot()
	{
		return snapshot;
	}

	private static final class HorizonRun implements EtaRun
	{
		private final String label;
		private final int startedTick;
		private final int totalTicks;
		private final boolean approximate;

		private HorizonRun(String label, int totalTicks, boolean approximate, int startedTick)
		{
			this.label = label;
			this.startedTick = startedTick;
			this.totalTicks = totalTicks;
			this.approximate = approximate;
		}

		@Override
		public TaskEtaSnapshot snapshotAt(int tick)
		{
			int remaining = Math.max(0, totalTicks - Math.max(0, tick - startedTick));
			return approximate
				? TaskEtaSnapshot.gatheringHorizon(label, remaining, totalTicks)
				: TaskEtaSnapshot.fixedAttentionHorizon(label, remaining, totalTicks);
		}
	}
}

package com.idlefamiliar;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Owns inventory-delta processing detection, confirmation, queue timing and
 * the conservative observed-processing fallback.
 */
final class DeterministicProcessingEtaEngine implements EtaEngine
{
	private static final int INTERRUPTION_GRACE_TICKS = 4;
	private static final int INTERACTION_CONTEXT_LIFETIME_TICKS = 100;

	enum Disposition
	{
		/** An unrelated inventory refresh must not disturb another verified mode. */
		PRESERVE_COMPETING,
		/** Processing handled the refresh; competing modes may now be cleared. */
		UPDATED,
		/** The verified final input was consumed. */
		COMPLETED,
		/** Active deterministic evidence became inconsistent. */
		CANCELLED
	}

	private Map<Integer, Integer> previousInventory = Collections.emptyMap();
	private ProcessingContext processingContext = ProcessingContext.none();
	private int processingContextExpiryTick = Integer.MAX_VALUE;
	private ProcessingCandidate candidate;
	private TaskRun run;
	private final ObservedProcessingTracker observed = new ObservedProcessingTracker();
	private String observedLabel = "";
	private boolean observedEligible;
	private TaskEtaSnapshot snapshot = TaskEtaSnapshot.inactive();

	void reset()
	{
		previousInventory = Collections.emptyMap();
		processingContext = ProcessingContext.none();
		processingContextExpiryTick = Integer.MAX_VALUE;
		candidate = null;
		cancel();
	}

	boolean setProcessingContext(ProcessingContext context)
	{
		ProcessingContext next = context == null ? ProcessingContext.none() : context;
		boolean cancelledRun = !processingContext.sameAs(next) && run != null;
		if (cancelledRun)
		{
			cancel();
		}
		processingContext = next;
		processingContextExpiryTick = Integer.MAX_VALUE;
		candidate = null;
		return cancelledRun;
	}

	boolean armProcessingContext(ProcessingContext context, int selectionTick)
	{
		boolean cancelledRun = setProcessingContext(context);
		long expiry = (long) selectionTick + INTERACTION_CONTEXT_LIFETIME_TICKS;
		processingContextExpiryTick = expiry >= Integer.MAX_VALUE
			? Integer.MAX_VALUE : (int) expiry;
		return cancelledRun;
	}

	void seedInventory(Map<Integer, Integer> inventory)
	{
		previousInventory = copyInventory(inventory);
	}

	void setObservedContext(String activityLabel, boolean eligible)
	{
		observedLabel = activityLabel == null ? "" : activityLabel.trim();
		observedEligible = eligible && !observedLabel.isEmpty();
	}

	Disposition onInventoryChanged(Map<Integer, Integer> inventory, int tick,
		boolean competingModeActive)
	{
		Map<Integer, Integer> nextInventory = copyInventory(inventory);
		if (previousInventory.isEmpty())
		{
			previousInventory = nextInventory;
			return competingModeActive ? Disposition.PRESERVE_COMPETING : Disposition.UPDATED;
		}

		Map<Integer, Integer> beforeInventory = previousInventory;
		if (run == null && tick > processingContextExpiryTick)
		{
			processingContext = ProcessingContext.none();
			processingContextExpiryTick = Integer.MAX_VALUE;
		}
		InventoryDelta delta = new InventoryDelta(beforeInventory, nextInventory);
		ProcessingProfile match = ProcessingCatalog.match(delta, nextInventory, processingContext);
		previousInventory = nextInventory;

		if (competingModeActive)
		{
			if (match == null)
			{
				return Disposition.PRESERVE_COMPETING;
			}
			clearRuns();
		}

		if (run == null)
		{
			if (match != null && match.requiresRepeatConfirmation())
			{
				observed.reset();
				if (candidate != null && candidate.confirms(match, tick))
				{
					candidate = null;
					startIfConfirmed(match, beforeInventory, nextInventory, tick);
				}
				else
				{
					candidate = new ProcessingCandidate(match, tick);
					snapshot = TaskEtaSnapshot.inactive();
				}
				return Disposition.UPDATED;
			}

			candidate = null;
			if (match == null)
			{
				snapshot = observed.observe(delta, beforeInventory, nextInventory,
					observedLabel, observedEligible, tick);
				return Disposition.UPDATED;
			}
			observed.reset();
			startIfConfirmed(match, beforeInventory, nextInventory, tick);
			return Disposition.UPDATED;
		}

		if (match == null || !match.sameRecipe(run.profile))
		{
			cancel();
			return Disposition.CANCELLED;
		}

		int remaining = run.profile.remainingUnits(nextInventory);
		if (remaining <= 0)
		{
			cancel();
			return Disposition.COMPLETED;
		}
		run = run.confirm(remaining, tick);
		snapshot = run.snapshotAt(tick);
		return Disposition.UPDATED;
	}

	boolean isActiveContext(ProcessingContext.Kind kind)
	{
		return run != null && run.profile.requiresContext(kind);
	}

	@Override
	public void onGameTick(int tick)
	{
		if (run != null)
		{
			if (tick - run.lastConfirmationTick > Math.max(INTERRUPTION_GRACE_TICKS,
				run.profile.continuationGraceTicks()))
			{
				cancel();
				return;
			}
			snapshot = run.snapshotAt(tick);
			return;
		}
		if (observed.isTracking())
		{
			snapshot = observed.onGameTick(tick);
		}
	}

	@Override
	public void cancel()
	{
		clearRuns();
		snapshot = TaskEtaSnapshot.inactive();
	}

	@Override
	public boolean isActive()
	{
		return run != null || observed.isTracking();
	}

	@Override
	public TaskEtaSnapshot snapshot()
	{
		return snapshot;
	}

	private void startIfConfirmed(ProcessingProfile profile,
		Map<Integer, Integer> beforeInventory, Map<Integer, Integer> nextInventory, int tick)
	{
		if (profile == null || !profile.canStart(beforeInventory))
		{
			snapshot = TaskEtaSnapshot.inactive();
			return;
		}
		int initialUnits = profile.initialUnits(beforeInventory);
		int remainingUnits = profile.remainingUnits(nextInventory);
		if (initialUnits <= 0 || remainingUnits <= 0)
		{
			snapshot = TaskEtaSnapshot.inactive();
			return;
		}
		clearRuns();
		run = new TaskRun(profile, initialUnits, remainingUnits, tick);
		snapshot = run.snapshotAt(tick);
	}

	private void clearRuns()
	{
		run = null;
		candidate = null;
		observed.reset();
	}

	private static Map<Integer, Integer> copyInventory(Map<Integer, Integer> inventory)
	{
		if (inventory == null || inventory.isEmpty())
		{
			return Collections.emptyMap();
		}
		Map<Integer, Integer> copy = new HashMap<>();
		for (Map.Entry<Integer, Integer> item : inventory.entrySet())
		{
			if (item.getKey() != null && item.getValue() != null && item.getValue() > 0)
			{
				copy.put(item.getKey(), item.getValue());
			}
		}
		return Collections.unmodifiableMap(copy);
	}

	private static final class ProcessingCandidate
	{
		private final ProcessingProfile profile;
		private final int tick;

		private ProcessingCandidate(ProcessingProfile profile, int tick)
		{
			this.profile = profile;
			this.tick = tick;
		}

		private boolean confirms(ProcessingProfile next, int nextTick)
		{
			return profile.sameRecipe(next)
				&& nextTick - tick == profile.repeatConfirmationTicks();
		}
	}

	private static final class TaskRun implements EtaRun
	{
		private final ProcessingProfile profile;
		private final int initialUnits;
		private final int remainingUnits;
		private final int lastConfirmationTick;

		private TaskRun(ProcessingProfile profile, int initialUnits, int remainingUnits,
			int lastConfirmationTick)
		{
			this.profile = profile;
			this.initialUnits = initialUnits;
			this.remainingUnits = remainingUnits;
			this.lastConfirmationTick = lastConfirmationTick;
		}

		private TaskRun confirm(int remainingUnits, int tick)
		{
			return new TaskRun(profile, initialUnits, remainingUnits, tick);
		}

		@Override
		public TaskEtaSnapshot snapshotAt(int tick)
		{
			int elapsed = Math.max(0, tick - lastConfirmationTick);
			int remainingTicks = Math.max(0,
				profile.remainingDurationTicks(remainingUnits) - elapsed);
			return TaskEtaSnapshot.processing(profile.label(), initialUnits, remainingUnits,
				remainingTicks, profile.durationTicks(initialUnits));
		}
	}
}

package com.idlefamiliar;

/** Immutable exact, approximate, or calibrating Task ETA presentation data. */
public final class TaskEtaSnapshot
{
	public enum Mode
	{
		PROCESSING,
		GATHERING
	}

	public enum Confidence
	{
		EXACT("Exact"),
		HIGH("High confidence"),
		MEDIUM("Estimate"),
		CALIBRATING("Calibrating");

		private final String label;

		Confidence(String label)
		{
			this.label = label;
		}
	}

	private static final TaskEtaSnapshot INACTIVE =
		new TaskEtaSnapshot(null, "", 0, 0, 0, 0, false, Confidence.EXACT, 0, 0, 0, 0);

	private final Mode mode;
	private final String profileLabel;
	private final int initialUnits;
	private final int remainingUnits;
	private final int remainingTicks;
	private final int totalTicks;
	private final boolean approximate;
	private final Confidence confidence;
	private final int lowerRemainingTicks;
	private final int upperRemainingTicks;
	private final int calibrationSamples;
	private final int calibrationTarget;

	private TaskEtaSnapshot(Mode mode, String profileLabel, int initialUnits, int remainingUnits,
		int remainingTicks, int totalTicks, boolean approximate, Confidence confidence,
		int lowerRemainingTicks, int upperRemainingTicks, int calibrationSamples, int calibrationTarget)
	{
		this.mode = mode;
		this.profileLabel = profileLabel;
		this.initialUnits = initialUnits;
		this.remainingUnits = remainingUnits;
		this.remainingTicks = remainingTicks;
		this.totalTicks = totalTicks;
		this.approximate = approximate;
		this.confidence = confidence == null ? Confidence.MEDIUM : confidence;
		this.lowerRemainingTicks = Math.max(0, lowerRemainingTicks);
		this.upperRemainingTicks = Math.max(this.lowerRemainingTicks, upperRemainingTicks);
		this.calibrationSamples = Math.max(0, calibrationSamples);
		this.calibrationTarget = Math.max(0, calibrationTarget);
	}

	public static TaskEtaSnapshot inactive()
	{
		return INACTIVE;
	}

	public static TaskEtaSnapshot processing(String profileLabel, int initialUnits, int remainingUnits,
		int remainingTicks, int totalTicks)
	{
		int safeRemainingTicks = Math.max(0, remainingTicks);
		return new TaskEtaSnapshot(Mode.PROCESSING, profileLabel, initialUnits, remainingUnits,
			safeRemainingTicks, Math.max(0, totalTicks), false, Confidence.EXACT,
			safeRemainingTicks, safeRemainingTicks, 0, 0);
	}

	/** Locally learned inventory processing after three consistent task cycles. */
	public static TaskEtaSnapshot observedProcessing(String profileLabel, int initialUnits, int remainingUnits,
		int remainingTicks, int totalTicks, int lowerRemainingTicks, int upperRemainingTicks)
	{
		return new TaskEtaSnapshot(Mode.PROCESSING, profileLabel, initialUnits, remainingUnits,
			Math.max(0, remainingTicks), Math.max(0, totalTicks), true, Confidence.HIGH,
			lowerRemainingTicks, upperRemainingTicks, 0, 0);
	}

	public static TaskEtaSnapshot calibrating(String profileLabel, int samples, int target)
	{
		return new TaskEtaSnapshot(Mode.PROCESSING, profileLabel, 0, 0, 0, 0, true,
			Confidence.CALIBRATING, 0, 0, samples, target);
	}

	/** Caller-verified gathering cadence that is still collecting local yield intervals. */
	public static TaskEtaSnapshot calibratingGathering(String profileLabel, int initialFreeSlots,
		int remainingFreeSlots, int samples, int target)
	{
		return new TaskEtaSnapshot(Mode.GATHERING, profileLabel, initialFreeSlots,
			remainingFreeSlots, 0, 0, true, Confidence.CALIBRATING,
			0, 0, samples, target);
	}

	/**
	 * Approximate inventory-capacity ETA for a source-modelled gathering run.
	 * The units are free usable inventory slots, not a claim about guaranteed
	 * future yields.
	 */
	public static TaskEtaSnapshot gathering(String profileLabel, int initialFreeSlots,
		int remainingFreeSlots, int remainingTicks, int totalTicks,
		int lowerRemainingTicks, int upperRemainingTicks)
	{
		return gathering(profileLabel, initialFreeSlots, remainingFreeSlots, remainingTicks,
			totalTicks, lowerRemainingTicks, upperRemainingTicks, Confidence.MEDIUM);
	}

	public static TaskEtaSnapshot gathering(String profileLabel, int initialFreeSlots,
		int remainingFreeSlots, int remainingTicks, int totalTicks,
		int lowerRemainingTicks, int upperRemainingTicks, Confidence confidence)
	{
		return new TaskEtaSnapshot(Mode.GATHERING, profileLabel, initialFreeSlots,
			remainingFreeSlots, Math.max(0, remainingTicks), Math.max(0, totalTicks), true,
			confidence, lowerRemainingTicks, upperRemainingTicks, 0, 0);
	}

	/**
	 * Approximate time to an externally verified gathering interruption.  This
	 * is deliberately separate from an inventory-capacity estimate: stackable
	 * resources such as daeyalt essence do not have a meaningful time-to-full.
	 */
	public static TaskEtaSnapshot gatheringHorizon(String profileLabel, int remainingTicks, int totalTicks)
	{
		int safeRemainingTicks = Math.max(0, remainingTicks);
		return new TaskEtaSnapshot(Mode.GATHERING, profileLabel, 1, 1,
			safeRemainingTicks, Math.max(0, totalTicks), true, Confidence.MEDIUM,
			safeRemainingTicks, safeRemainingTicks, 0, 0);
	}

	/** Exact time to a client-verified, deterministic attention event. */
	public static TaskEtaSnapshot fixedAttentionHorizon(String profileLabel, int remainingTicks, int totalTicks)
	{
		int safeRemainingTicks = Math.max(0, remainingTicks);
		return new TaskEtaSnapshot(Mode.GATHERING, profileLabel, 1, 1,
			safeRemainingTicks, Math.max(0, totalTicks), false, Confidence.EXACT,
			safeRemainingTicks, safeRemainingTicks, 0, 0);
	}

	public boolean isActive()
	{
		return mode != null;
	}

	public Mode getMode()
	{
		return mode;
	}

	public String getProfileLabel()
	{
		return profileLabel;
	}

	public int getInitialUnits()
	{
		return initialUnits;
	}

	public int getRemainingUnits()
	{
		return remainingUnits;
	}

	public int getRemainingTicks()
	{
		return remainingTicks;
	}

	/** Whether the time is an estimate rather than an observed fixed duration. */
	public boolean isApproximate()
	{
		return approximate;
	}

	public boolean isCalibrating()
	{
		return confidence == Confidence.CALIBRATING;
	}

	public Confidence getConfidence()
	{
		return confidence;
	}

	public int getLowerRemainingTicks()
	{
		return lowerRemainingTicks;
	}

	public int getUpperRemainingTicks()
	{
		return upperRemainingTicks;
	}

	/**
	 * Fraction of the run still expected to remain.  A full ring drains to zero.
	 */
	public double getProgress()
	{
		if (!isActive() || totalTicks <= 0)
		{
			return 0d;
		}
		return Math.max(0d, Math.min(1d, remainingTicks / (double) totalTicks));
	}

	/** Compact, deliberately exact processing readout (for example {@code 0:32}). */
	public String getDisplayText()
	{
		if (!isActive())
		{
			return "";
		}
		if (isCalibrating())
		{
			return "Cal " + calibrationSamples + "/" + calibrationTarget;
		}

		// A game tick is 0.6 seconds. Round up rather than promise an earlier end.
		long seconds = ((long) remainingTicks * 3L + 4L) / 5L;
		String prefix = approximate ? "~" : "";
		long secondsPart = seconds % 60L;
		return prefix + (seconds / 60) + ":" + (secondsPart < 10 ? "0" : "") + secondsPart;
	}

	/** More explicit confidence/range text suitable for the ETA-row hover tooltip. */
	public String getDetailText()
	{
		if (!isActive())
		{
			return "";
		}
		if (isCalibrating())
		{
			return profileLabel + " · Calibrating " + calibrationSamples + "/" + calibrationTarget;
		}
		String center = formatTicks(remainingTicks);
		if (approximate && upperRemainingTicks > lowerRemainingTicks)
		{
			return profileLabel + " · " + confidence.label + " " + formatTicks(lowerRemainingTicks)
				+ "–" + formatTicks(upperRemainingTicks) + " (centre " + center + ")";
		}
		return profileLabel + " · " + confidence.label + " " + center;
	}

	private static String formatTicks(int ticks)
	{
		long seconds = ((long) Math.max(0, ticks) * 3L + 4L) / 5L;
		long secondsPart = seconds % 60L;
		return (seconds / 60L) + ":" + (secondsPart < 10L ? "0" : "") + secondsPart;
	}
}

package com.idlefamiliar;

import java.util.EnumMap;
import java.util.Map;

/**
 * Client-thread timestamps for animation evidence used by activity and ETA
 * recognizers. Centralising this state keeps login/logout/reset semantics
 * consistent across every supported activity family.
 */
final class ActivityEvidenceTracker
{
	enum Signal
	{
		WOODCUTTING,
		FISHING,
		MINING,
		STYMPHIKE,
		SMITHING,
		FURNACE,
		SALVAGE_SORTING,
		SALVAGE_GATHERING
	}

	private final Map<Signal, Integer> lastTicks = new EnumMap<>(Signal.class);

	ActivityEvidenceTracker()
	{
		reset();
	}

	void mark(Signal signal, int tick)
	{
		lastTicks.put(signal, tick);
	}

	int lastTick(Signal signal)
	{
		return lastTicks.get(signal);
	}

	boolean isRecent(Signal signal, int currentTick, int graceTicks)
	{
		int lastTick = lastTick(signal);
		return lastTick >= 0 && lastTick >= currentTick - Math.max(0, graceTicks);
	}

	void reset()
	{
		for (Signal signal : Signal.values())
		{
			lastTicks.put(signal, -1);
		}
	}
}

