		{
			desktopUiCoordinator.stop();
			desktopUiCoordinator = null;
		}
		notificationController.clear();
		resetSessionRuntime();
		attentionNotificationGate.reset();
		log.debug("Idle Familiar stopped");
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int tick = idleStateTracker.getCurrentTick() + 1;
		idleStateTracker.setCurrentTick(tick);
		Player localPlayer = client.getLocalPlayer();
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN && localPlayer != null;
		boolean wasLoggedIn = activityService.isLoggedIn();
		activityService.setLoggedIn(loggedIn);

		if (!loggedIn)
		{
			if (wasLoggedIn || currentAvatarState != AvatarState.LOGGED_OUT
				|| inventoryHistory.isSeeded() || etaSessionManager.snapshot().isActive())
			{
				resetSessionRuntime();
			}
			shimmerController.maintainLoggedOut();
			handleAvatarStateTransition(AvatarState.LOGGED_OUT);
			publishWidgetSnapshot();
			return;
		}

		updateMovement(localPlayer);
		skillProgressTracker.primeXpCache(client);
		int animationId = localPlayer.getAnimation();
		String registeredActivity = activityRegistry.activityForAnimation(animationId);
		updateSkillingFromAnimation(animationId, registeredActivity, tick);
		if (activityDetector.isFishingAnimation(animationId))
		{
			startOpenFishBarrelFishingEta(localPlayer, animationId, tick);
		}
		if (activityDetector.isWoodcuttingAnimation(animationId))
		{
			startPendingWoodcuttingStorageEta(tick);
		}
		if (activityDetector.isMiningAnimation(animationId))
		{
			etaSessionManager.startPendingDaeyalt(tick,
				DAEYALT_INTERACTION_GRACE_TICKS);
		}
		salvageSessionCoordinator.onAnimation(animationId, tick, movedThisTick,
			activityService.isBanking(), currentPlayerInventorySupplier);
		activityService.advanceLingers();
		int lowHitpointsThreshold = config.lowHpThreshold();
		int lowPrayerThreshold = config.lowPrayerThreshold();
		updateVitals(lowHitpointsThreshold, lowPrayerThreshold);
		if (activityService.isLingering(PlayerActivityService.Linger.DEATH))
		{
			etaSessionManager.cancel();
		}
		else
		{
			etaSessionManager.onGameTick(localPlayer, tick,
				movedThisTick, activityRegistry, activityDetector.evidence(),
				MAX_SKILLING_LINGER_TICKS, fishingResultGraceTicks());
			if (etaSessionManager.consumeExpiry())
			{
				if (config.showTaskEta())
				{
					shimmerController.armEtaExpired();
				}
				playGameSound(GameSoundEvent.ETA_COMPLETE);
			}
			maintainCampfireSkillingSignal(registeredActivity == null, tick);
		}
		int lingerTicks = skillingLingerTicks();
		updateInventoryFullWarning(tick, lingerTicks);
		updateLingeringActivity(localPlayer, tick, lingerTicks);
		boolean idle = idleStateTracker.isIdle(config.idleThresholdTicks());
		boolean afkWarning = idleStateTracker.isAfkWarning(config.afkWarningThresholdTicks());
		resolveCurrentState(idle, afkWarning);
		updateShimmer(afkWarning, lowHitpointsThreshold, lowPrayerThreshold);
		skillProgressTracker.updatePublishedValues(
			confirmedSkillForCurrentState(tick, lingerTicks),
			config.showAdvancedInfo(), tick,
			System.currentTimeMillis());
		publishWidgetSnapshot();
		logDebugState(localPlayer, tick, animationId, registeredActivity);
	}

	private void logDebugState(Player localPlayer, int tick, int animationId,
		String registeredActivity)
	{
		if (!config.debugState() || localPlayer == null)
		{
			return;
		}
		Actor interacting = localPlayer.getInteracting();
		String interactingDesc = "none";
		if (interacting != null)
		{
			interactingDesc = interacting.getName()
				+ (interacting instanceof NPC
					? " npcId=" + ((NPC) interacting).getId()
					: "")
				+ " token=" + System.identityHashCode(interacting);
		}
		log.info("[idle-familiar] tick={} anim={} regLabel={} interacting=[{}] moved={} skilling={} sustained={} state={} label={}",
			tick,
			animationId,
			registeredActivity == null ? "-" : registeredActivity,
			interactingDesc,
			movedThisTick,
			activityService.isSkilling(),
			skillingTracker.isSustainedByTarget(),
			currentAvatarState,
			activityService.getActivityLabel());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!"idlefamiliar".equals(event.getGroup()))
		{
			return;
		}
		if (displayPresetController != null)
		{
			displayPresetController.onConfigChanged(event.getKey(), event.getNewValue());
		}
		if ("chatMessageFilters".equals(event.getKey()))
		{
			chatMessageFilters = ChatMessageMatcher.compile(event.getNewValue());
		}

		// Reset action toggles after firing so they can be used again.
		if ("reloadAnimations".equals(event.getKey()) && "true".equals(event.getNewValue()))
		{
			configManager.setConfiguration(IdleFamiliarConfig.GROUP, "reloadAnimations", false);
			if (avatarAssetManager != null)
			{
				avatarAssetManager.reload();
			}
			return;
		}
		if ("validateAnimations".equals(event.getKey()) && "true".equals(event.getNewValue()))
		{
			configManager.setConfiguration(IdleFamiliarConfig.GROUP, "validateAnimations", false);
			if (avatarAssetManager != null)
			{
				avatarAssetManager.validate();
			}
			return;
		}
		if ("resetWidgetPosition".equals(event.getKey()) && "true".equals(event.getNewValue()))
		{
			configManager.setConfiguration(IdleFamiliarConfig.GROUP, "resetWidgetPosition", false);
			if (desktopUiCoordinator != null)
			{
				desktopUiCoordinator.resetPosition();
			}
			return;
		}
		if ("moveWidgetToCurrentDisplay".equals(event.getKey()) && "true".equals(event.getNewValue()))
		{
			configManager.setConfiguration(IdleFamiliarConfig.GROUP, "moveWidgetToCurrentDisplay", false);
			if (desktopUiCoordinator != null)
			{
				desktopUiCoordinator.moveToPointerDisplay();
			}
			return;
		}

		if (desktopUiCoordinator != null)
		{
			desktopUiCoordinator.onConfigChanged(event.getKey(), event.getNewValue());
		}
		applyAnimationConfigurationChange(event.getKey(), event.getNewValue());
		soundController.applyConfigurationChange(event.getKey(), event.getNewValue());
	}

