	/** Applies event values directly to Swing-owned presentation state. */
	private void applyAnimationConfigurationChange(String key, String serializedValue)
	{
		if ("debugPreviewState".equals(key))
		{
			debugPreview = AvatarPreview.fromConfigValue(serializedValue);
			return;
		}
		if ("playFullCycleAnimations".equals(key))
		{
			animationController.setPlayFullCycleOneShots(Boolean.parseBoolean(serializedValue));
			return;
		}
		if (!"animationSpeed".equals(key) || serializedValue == null)
		{
			return;
		}
		for (ScaleMultiplier speed : ScaleMultiplier.values())
		{
			if (speed.name().equalsIgnoreCase(serializedValue)
				|| speed.toString().equalsIgnoreCase(serializedValue))
			{
				animationController.setPlaybackSpeed(speed.multiplier());
				return;
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			shimmerController.onLoggedIn();
			sessionLifecycleCoordinator.reset();
			cachedInventorySnapshot = InventorySnapshot.empty();
			scheduleTaskEtaInventorySeed();
			activityService.setLoggedIn(true);
			markActivity(ActivityType.UNKNOWN);
		}
		else if (event.getGameState() == GameState.CONNECTION_LOST)
		{
			resetSessionRuntime();
			shimmerController.onConnectionLost();
			// Publish immediately because another game tick may not arrive.
			publishWidgetSnapshot();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			// Preserve unexpected disconnects through the following login screen.
			if (event.getGameState() == GameState.LOGIN_SCREEN)
			{
				shimmerController.maintainLoggedOut();
			}
			else
			{
				shimmerController.reset();
			}
			resetSessionRuntime();
			// Hop/disconnect may omit WidgetClosed.
			publishWidgetSnapshot();
		}
	}

	/** Seeds inventory on the client thread after startup. */
	private void scheduleTaskEtaInventorySeed()
	{
		int expectedEpoch = sessionLifecycleCoordinator.epoch();
		clientThread.invokeLater(() ->
		{
			if (!sessionLifecycleCoordinator.isCurrent(expectedEpoch))
			{
				return;
			}
			ItemContainer inventory = client.getItemContainer(InventoryID.INV);
			InventoryState inventoryState = InventoryState.from(inventory);
			InventoryState equipmentState = InventoryState.from(
				client.getItemContainer(InventoryID.WORN));
			if (sessionLifecycleCoordinator.seedIfCurrent(
				expectedEpoch, inventoryState, equipmentState))
			{
				captureInventory(inventory, inventoryState);
			}
		});
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null || event.getActor() != localPlayer)
		{
			return;
		}

		int animId = localPlayer.getAnimation();
		if (animId == -1)
		{
			return;
		}
		int tick = idleStateTracker.getCurrentTick();

		// Only reviewed skilling animations refresh linger.
		String registeredActivity = activityRegistry.activityForAnimation(animId);
		if (registeredActivity != null)
		{
			markSkillingSignal(registeredActivity, tick);
		}
		if (activityDetector.onWoodcuttingAnimation(animId, tick))
		{
			startPendingWoodcuttingStorageEta(tick);
		}
		if (activityDetector.isFishingAnimation(animId))
		{
			activityDetector.mark(ActivityEvidenceTracker.Signal.FISHING,
				tick);
		}
		if (activityDetector.isMiningAnimation(animId))
		{
			activityDetector.mark(ActivityEvidenceTracker.Signal.MINING,
				tick);
			etaSessionManager.startPendingDaeyalt(tick,
				DAEYALT_INTERACTION_GRACE_TICKS);
		}
		if (StymphikeCatalog.isWaitingAnimation(animId))
		{
			activityDetector.mark(ActivityEvidenceTracker.Signal.STYMPHIKE,
				tick);
			markSkillingSignal("Hunter", tick);
			if (animId == StymphikeCatalog.HIDE_ANIMATION)
			{
				etaSessionManager.onVerifiedFixedAttentionHorizon(EtaActivity.STYMPHIKE,
					StymphikeCatalog.LABEL, StymphikeCatalog.WAIT_TICKS, true,
					tick);
			}
		}
		if (activityDetector.isSmithingAnimation(animId))
		{
			activityDetector.mark(ActivityEvidenceTracker.Signal.SMITHING,
				tick);
		}
		if (activityDetector.isFurnaceAnimation(animId))
		{
			activityDetector.mark(ActivityEvidenceTracker.Signal.FURNACE,
				tick);
		}
		salvageSessionCoordinator.onAnimation(animId, tick, movedThisTick,
			activityService.isBanking(), currentPlayerInventorySupplier);

		// Teleports are visible but silent.
		if (activityRegistry.isTeleportAnimation(animId))
		{
			activityService.arm(PlayerActivityService.Linger.TELEPORTING);
		}
	}

