	/** Captures queue intent that inventory deltas cannot identify. */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		shimmerController.onClientInteraction();
		String option = normalizedMenuText(event.getMenuOption());
		String target = normalizedMenuText(event.getMenuTarget());
		int tick = idleStateTracker.getCurrentTick();
		MenuAction menuAction = event.getMenuAction();
		boolean gameObjectAction = ActivityDetector.isGameObjectAction(menuAction);
		WorldPoint objectLocation = objectWorldPoint(event, gameObjectAction);
		InventoryState playerInventory = !gameObjectAction
			? null : currentPlayerInventory();
		InventoryState safeInventory = playerInventory == null
			? InventoryState.empty() : playerInventory;
		InventoryState equipment = gameObjectAction
			|| menuAction == MenuAction.WIDGET_TARGET_ON_WIDGET
			? currentEquipment() : InventoryState.empty();
		activityDetector.extendedInventory().onMenuAction(
			option, target);
		salvageSessionCoordinator.onMenuInteraction(
			option, target, tick, activityService.isBanking(),
			currentPlayerInventorySupplier);
		captureProcessingContext(event, option, target, equipment, tick);
		captureWoodcuttingInteraction(event, option, target, objectLocation,
			safeInventory, equipment, tick);
		captureDaeyaltInteraction(event, option, objectLocation,
			safeInventory, equipment, tick);
	}

