	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		int tick = idleStateTracker.getCurrentTick();
		SkillProgressTracker.SkillChange skillChange = skillProgressTracker.record(
			skill, event.getXp(), event.getLevel(), System.currentTimeMillis());
		if (skillChange.levelUp())
		{
			activityService.arm(PlayerActivityService.Linger.LEVEL_UP);
		}
		boolean activeXpGain = skillChange.activeXpGain();
		String skillName = skill.getName();
		boolean combatSkill = SkillProgressTracker.isLikelyCombatStat(skill);
		if (activeXpGain && cachedInventoryCount >= InventorySnapshot.SLOT_COUNT
			&& !combatSkill && !SkillingActivityTracker.isPassiveSkill(skillName))
		{
			fullInventoryActivityTracker.markProgress(tick);
		}

		if (combatSkill
			&& activityService.isLingering(PlayerActivityService.Linger.COMBAT))
		{
			// Retain the latest combat style for its sprite sheet.
			String style = SkillProgressTracker.combatStyle(skill);
			if (style != null)
			{
				combatStyle = style;
			}
			markActivity(ActivityType.COMBAT);
			return;
		}

		// Login syncs, boosts, and passive stat changes do not prove skilling.
		if (!activeXpGain)
		{
			return;
		}

		// Agility needs a short movement-resistant animation hold.
		if (skill == Skill.AGILITY)
		{
			activityService.arm(PlayerActivityService.Linger.AGILITY);
		}

		markSkillingSignal(skillName, true, tick);
		if (config.reactToSkilling())
		{
			notificationController.show(skillName, 1, 1600);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.WORN)
		{
			inventoryHistory.observeEquipment(InventoryState.from(event.getItemContainer()));
			return;
		}
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}

		int tick = idleStateTracker.getCurrentTick();
		int lingerTicks = skillingLingerTicks();
		boolean banking = activityService.isBanking();
		InventoryChange inventoryChange = inventoryHistory.observe(
			InventoryState.from(event.getItemContainer()));
		Map<Integer, Integer> currentInventory = inventoryChange.after().itemCounts();
		salvageSessionCoordinator.onPlayerInventoryChanged(inventoryChange,
			tick, movedThisTick, banking, MAX_SKILLING_LINGER_TICKS);
		Player localPlayer = client.getLocalPlayer();
		int animationId = localPlayer == null ? -1 : localPlayer.getAnimation();
		String observedProcessingSkill = observedProcessingSkill(
			animationId, tick, lingerTicks);
		etaSessionManager.setObservedProcessingContext(observedProcessingSkill,
			observedProcessingSkill != null && !movedThisTick && !banking);
		fullInventoryActivityTracker.onInventoryChanged(
			inventoryChange.before().itemCounts(),
			currentInventory,
			inventoryChange.after().occupiedSlots(),
			tick);
		ActivityDetector.InventoryDetection detection = activityDetector.detectInventory(
			inventoryChange, currentEquipment(), localPlayer != null, animationId,
			client.getBoostedSkillLevel(Skill.WOODCUTTING),
			client.getBoostedSkillLevel(Skill.FISHING),
			tick, MAX_SKILLING_LINGER_TICKS, fishingResultGraceTicks());
		WoodcuttingRecognizer.LogResult woodcuttingLog = detection.woodcutting();
		FishingActivityDetector.Detection fishingDetection = detection.fishing();
		ProcessingActivityDetector.Result processingResult = detection.processing();
		if (woodcuttingLog != null)
		{
			etaSessionManager.onVerifiedWoodcuttingLogDelta(
				woodcuttingLog.tree(),
				woodcuttingLog.axeTier(),
				woodcuttingLog.effectiveLevel(),
				woodcuttingLog.occupiedSlots(),
				woodcuttingLog.producedSlots(),
				woodcuttingLog.eligible(),
				woodcuttingLog.despawnRemainingTicks(),
				tick);
			etaSessionManager.syncInventoryBaseline(inventoryChange.after());
		}
		else if (fishingDetection instanceof FishingActivityDetector.ConventionalCatch)
		{
			FishingActivityDetector.ConventionalCatch fishingCatch =
				(FishingActivityDetector.ConventionalCatch) fishingDetection;
			int movementHorizon = currentFishingMovementHorizon(
				fishingCatch.profile, localPlayer, tick);
			etaSessionManager.onVerifiedConventionalFishingCatch(
				fishingCatch.profile,
				fishingCatch.effectiveLevel,
				fishingCatch.occupiedSlots,
				fishingCatch.producedSlots,
				fishingCatch.capacityYieldMultiplier,
				fishingCatch.eligible,
				movementHorizon,
				tick);
			etaSessionManager.syncInventoryBaseline(inventoryChange.after());
		}
		else if (fishingDetection instanceof FishingActivityDetector.KarambwanAttempt)
		{
			FishingActivityDetector.KarambwanAttempt karambwanAttempt =
				(FishingActivityDetector.KarambwanAttempt) fishingDetection;
			if (karambwanAttempt.usesFishBarrel)
			{
				etaSessionManager.onVerifiedKarambwanBarrelAttempt(
					karambwanAttempt.effectiveLevel,
					InventorySnapshot.SLOT_COUNT - karambwanAttempt.occupiedSlots,
					karambwanAttempt.remainingKarambwanji,
					karambwanAttempt.capacityYieldMultiplier,
					karambwanAttempt.eligible,
					tick);
			}
			else
			{
				etaSessionManager.onVerifiedKarambwanAttempt(
					karambwanAttempt.effectiveLevel,
					karambwanAttempt.occupiedSlots,
					karambwanAttempt.remainingKarambwanji,
					karambwanAttempt.caught,
					karambwanAttempt.eligible,
					tick);
			}
			etaSessionManager.syncInventoryBaseline(inventoryChange.after());
		}
		else if (processingResult != null)
		{
			etaSessionManager.armProcessingContext(processingResult.context(), tick);
			etaSessionManager.onInventoryChanged(currentInventory, tick);
		}
		else
		{
			etaSessionManager.onInventoryChanged(currentInventory, tick);
		}
		markActivity(skillingTracker.isSkilling(tick, lingerTicks)
			? ActivityType.SKILLING : ActivityType.INVENTORY);
		captureInventory(event.getItemContainer(), inventoryChange.after());
		updateInventoryFullWarning(tick, lingerTicks);
	}

	private InventoryState currentPlayerInventory()
	{
		if (inventoryHistory.isSeeded())
		{
			return inventoryHistory.current();
		}
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		return inventory == null ? null : InventoryState.from(inventory);
	}

	private InventoryState currentEquipment()
	{
		if (inventoryHistory.isEquipmentSeeded())
		{
			return inventoryHistory.equipment();
		}
		InventoryState equipment = InventoryState.from(
			client.getItemContainer(InventoryID.WORN));
		inventoryHistory.observeEquipment(equipment);
		return equipment;
	}

