	/** Starts Fish Barrel capacity only from an unambiguous spot, tool, and bait. */
	private void startOpenFishBarrelFishingEta(Player localPlayer, int animationId, int tick)
	{
		Actor interacting = localPlayer.getInteracting();
		FishingSpot spot = interacting instanceof NPC
			? FishingSpot.findSpot(((NPC) interacting).getId())
			: null;
		InventoryState inventory = currentPlayerInventory();
		FishingActivityDetector.BarrelStart start = activityDetector.detectFishingBarrelStart(
			spot,
			inventory == null ? InventoryState.empty() : inventory,
			currentEquipment(),
			animationId,
			client.getBoostedSkillLevel(Skill.FISHING));
		if (start == null)
		{
			return;
		}
		etaSessionManager.onVerifiedConventionalFishingBarrelStart(start.profile,
			start.effectiveLevel, start.ordinaryFreeSlots,
			start.capacityYieldMultiplier, start.eligible,
			currentFishingMovementHorizon(start.profile, localPlayer, tick),
			tick);
	}

	private int currentFishingMovementHorizon(GatheringProfile profile, Player localPlayer,
		int tick)
	{
		return etaSessionManager.earliestFishingSpotMoveRemainingTicks(
			localPlayer == null ? null : localPlayer.getInteracting(), profile,
			tick);
	}

