	/** Publishes the end-of-tick widget snapshot. */
	private void publishWidgetSnapshot()
	{
		String activityLabel = activityService.getActivityLabel();
		String animationLabel = animationLabelFor(currentAvatarState);
		String message = notificationController.getMessage(
			currentAvatarState, activityService.getCurrentActivity(), activityLabel);
		AttentionReason attentionReason = shimmerController.attentionReason();
		String routedNotification = attentionNotificationGate.update(attentionReason,
			config.routeAttentionToRuneLite());
		if (routedNotification != null && notifier != null)
		{
			notifier.notify(routedNotification);
		}
		widgetStatePublisher.publish(
			currentAvatarState,
			animationLabel,
			cachedHitpoints,
			cachedMaxHitpoints,
			cachedPrayer,
			cachedMaxPrayer,
			cachedInventoryCount,
			skillProgressTracker.cachedXpHr(),
			message,
			skillProgressTracker.confirmedSkillIcon(),
			attentionReason != AttentionReason.NONE,
			attentionReason,
			etaSessionManager.snapshot(),
			cachedInventorySnapshot);
	}

	private void updateMovement(Player localPlayer)
	{
		WorldPoint currentLocation = localPlayer.getWorldLocation();
		activityService.setWalking(false);
		activityService.setRunning(false);
		movedThisTick = false;

		if (lastPlayerLocation == null || currentLocation == null)
		{
			lastPlayerLocation = currentLocation;
			return;
		}

		if (currentLocation.equals(lastPlayerLocation))
		{
			return;
		}

		movedThisTick = true;
		// Station pose preserves sorting cadence while the vessel moves.
		boolean sortingOnMovingVessel = salvageSessionCoordinator.isSortingEngaged(
			localPlayer.getAnimation(), idleStateTracker.getCurrentTick());
		if (!sortingOnMovingVessel)
		{
			etaSessionManager.cancel();
		}

		// Movement ends skilling linger and any missed bank-close state.
		skillingTracker.cancelLinger();
		activityService.setActivityLabel("");
		activityService.setBanking(false);
		markActivity(ActivityType.WALKING);

		// Larger deltas belong to teleport or region changes.
		int distance = currentLocation.distanceTo(lastPlayerLocation);
		if (distance == 1)
		{
			activityService.setWalking(true);
		}
		else if (distance == 2)
		{
			activityService.setRunning(true);
		}

		lastPlayerLocation = currentLocation;
	}

	/** Refreshes skilling from a reviewed live animation. */
	private void updateSkillingFromAnimation(int animationId, String registeredActivity,
		int tick)
	{
		// Movement wins over skilling on the same tick.
		if (movedThisTick)
		{
			return;
		}

		if (animationId == -1)
		{
			return;
		}

		if (registeredActivity != null)
		{
			markSkillingSignal(registeredActivity, tick);
		}
		if (StymphikeCatalog.isWaitingAnimation(animationId))
		{
			activityDetector.mark(ActivityEvidenceTracker.Signal.STYMPHIKE,
				tick);
			markSkillingSignal("Hunter", tick);
		}
	}

	private void updateVitals(int lowHitpointsThreshold, int lowPrayerThreshold)
	{
		int previousHitpoints = cachedHitpoints;
		int hitpoints = client.getBoostedSkillLevel(Skill.HITPOINTS);
		int prayer = client.getBoostedSkillLevel(Skill.PRAYER);
		boolean lowHitpoints = config.enableLowHpWarning()
			&& hitpoints > 0 && hitpoints <= lowHitpointsThreshold;
		boolean lowPrayer = config.enableLowPrayerWarning()
			&& prayer <= lowPrayerThreshold;
		boolean lowHitpointsWasActive = activityService.isLowHitpoints();
		boolean lowPrayerWasActive = activityService.isLowPrayer();
		activityService.setLowHitpoints(lowHitpoints);
		activityService.setLowPrayer(lowPrayer);
		if (lowHitpoints && !lowHitpointsWasActive)
		{
			playGameSound(GameSoundEvent.LOW_HEALTH);
		}
		if (lowPrayer && !lowPrayerWasActive)
		{
			playGameSound(GameSoundEvent.LOW_PRAYER);
		}
		// Cache vitals on the client thread for Swing.
		cachedHitpoints = hitpoints;
		cachedMaxHitpoints = client.getRealSkillLevel(Skill.HITPOINTS);
		cachedPrayer = prayer;
		cachedMaxPrayer = client.getRealSkillLevel(Skill.PRAYER);
		if (previousHitpoints > 0 && hitpoints == 0)
		{
			activityService.arm(PlayerActivityService.Linger.DEATH);
		}
	}

	private void captureInventory(ItemContainer inventory, InventoryState inventoryState)
	{
		InventoryState safeState = inventoryState == null ? InventoryState.empty() : inventoryState;
		cachedInventoryCount = safeState.occupiedSlots();
		// Item lookup stays on the client thread.
		cachedInventorySnapshot = InventorySnapshot.capture(inventory, cachedInventorySnapshot, itemManager);
	}

	private void updateInventoryFullWarning(int tick, int lingerTicks)
	{
		boolean full = cachedInventoryCount >= InventorySnapshot.SLOT_COUNT;

		// A full inventory is actionable only after useful work stops.
		boolean fullWhileProcessing = isFullWhileProcessing(full, tick, lingerTicks);
		boolean reactFull = config.enableInventoryFullWarning() && full && !fullWhileProcessing;

		// Cancel target sustain so a new full warning is visible this tick.
		if (reactFull && !activityService.isInventoryFull())
		{
			skillingTracker.cancelLinger();
			activityService.setSkilling(false);
			playGameSound(GameSoundEvent.INVENTORY_FULL);
		}
		activityService.setInventoryFull(reactFull);
	}

	private boolean isFullWhileProcessing(boolean full, int tick, int lingerTicks)
	{
		TaskEtaSnapshot taskEta = etaSessionManager.snapshot();
		boolean confirmedProcessing = taskEta.isActive()
			&& taskEta.getMode() == TaskEtaSnapshot.Mode.PROCESSING;
		boolean skilling = skillingTracker.isSkilling(tick, lingerTicks);
		return fullInventoryActivityTracker.isWorkingAtFull(
			full, confirmedProcessing, skilling, tick);
	}

	private void updateLingeringActivity(Player localPlayer, int currentTick, int lingerTicks)
	{
		Actor target = localPlayer.getInteracting();
		boolean hasTarget = target != null;

		// The same confirmed actor bridges NPC-skill animation gaps.
		int targetToken = hasTarget ? System.identityHashCode(target) : SkillingActivityTracker.NO_TARGET;
		skillingTracker.recordInteractionTarget(targetToken, currentTick);

		// Target presence does not prove combat; only hit evidence arms it.
		boolean combatLingering = activityService.isLingering(
			PlayerActivityService.Linger.COMBAT);
		if (!combatLingering)
		{
			// A later fight starts generic until combat XP identifies its style.
			combatStyle = null;
		}

		// Agility alone can retain skilling across required movement.
		boolean agilityHold = activityService.isLingering(
			PlayerActivityService.Linger.AGILITY);

		activityService.setInCombat(config.reactToCombat() && combatLingering);
		activityService.setSkilling(config.reactToSkilling()
			&& (skillingTracker.isSkilling(currentTick, lingerTicks) || agilityHold));
		if (activityService.isSkilling())
		{
			idleStateTracker.markActivity(ActivityType.SKILLING);
			activityService.setCurrentActivity(ActivityType.SKILLING);
			String confirmedSkill = skillingTracker.getConfirmedSkill(currentTick, lingerTicks);
			if (confirmedSkill != null && !confirmedSkill.isEmpty())
			{
				activityService.setActivityLabel(confirmedSkill);
			}
			else if (agilityHold)
			{
				// Restore the Agility label for its hold window.
				activityService.setActivityLabel("Agility");
			}
			else if (activityService.getActivityLabel().isEmpty())
			{
				activityService.setActivityLabel("Skilling");
			}
		}
	}

	/** Bridges Firemaking only while the exact campfire queue is active. */
	private void maintainCampfireSkillingSignal(boolean noRegisteredAnimation, int tick)
	{
		if (!movedThisTick && !activityService.isBanking()
			&& noRegisteredAnimation
			&& etaSessionManager.isActiveProcessingContext(
				ProcessingContext.Kind.FORESTERS_CAMPFIRE))
		{
			markSkillingSignal("Firemaking", tick);
		}
	}

	private void resolveCurrentState(boolean idle, boolean afkWarning)
	{
		AvatarState nextState = activityService.resolveState(idle, afkWarning);
		handleAvatarStateTransition(nextState);
		currentAvatarState = nextState;
	}

	private void handleAvatarStateTransition(AvatarState nextState)
	{
		String nextLabel = animationLabelFor(nextState);
		String nextKey = animationController.resolveAssetName(nextState, nextLabel);
		if (!soundCueGate.claimAnimationStart(nextKey))
		{
			return;
		}

		if (SoundActivation.animationStart(config, nextState))
		{
			boolean suppressed = soundCueGate.consumeSuppressedAnimationStart(
				nextKey, idleStateTracker.getCurrentTick());
			if (!suppressed)
			{
				soundController.playAnimationStart(nextState);
			}
		}
	}

	private void markActivity(ActivityType activityType)
	{
		idleStateTracker.markActivity(activityType);
		activityService.setCurrentActivity(activityType);
	}

	private void markSkillingSignal(String activityLabel, int tick)
	{
		markSkillingSignal(activityLabel, false, tick);
	}

	private void markSkillingSignal(String activityLabel, boolean confirmedXpGain, int tick)
	{
		if (confirmedXpGain)
		{
			skillingTracker.recordXpSkillSignal(activityLabel, tick);
		}
		else
		{
			skillingTracker.recordSkillSignal(activityLabel, tick);
		}
		markActivity(ActivityType.SKILLING);
		if (activityLabel != null && !activityLabel.isEmpty())
		{
			activityService.setActivityLabel(activityLabel);
		}
		else if (activityService.getActivityLabel().isEmpty())
		{
			activityService.setActivityLabel("Skilling");
		}
	}

	private void playGameSound(GameSoundEvent event)
	{
		if (SoundActivation.gameEvent(config, event))
		{
			soundController.playGameEvent(event);
			soundCueGate.suppressAnimationStart(
				animationKeyForGameEvent(event), idleStateTracker.getCurrentTick(), 2);
		}
	}

	private String animationKeyForGameEvent(GameSoundEvent event)
	{
		switch (event)
		{
			case INVENTORY_FULL:
				return animationController.resolveAssetName(AvatarState.INVENTORY_FULL, "");
			case LOW_HEALTH:
				return animationController.resolveAssetName(AvatarState.LOW_HEALTH, "");
			case LOW_PRAYER:
				return animationController.resolveAssetName(AvatarState.LOW_PRAYER, "");
			default:
				return null;
		}
	}

	private String animationLabelFor(AvatarState state)
	{
		return state == AvatarState.COMBAT
			? (combatStyle == null ? "" : combatStyle)
			: activityService.getActivityLabel();
	}

	private String shortChatNotification(String matchedFilter)
	{
		if (matchedFilter == null)
		{
			return "Chat trigger";
		}
		String trimmed = matchedFilter.trim();
		if (trimmed.isEmpty())
		{
			return "Chat trigger";
		}
		if (trimmed.length() <= 42)
		{
			return trimmed;
		}
		return trimmed.substring(0, 39) + "...";
	}

	private String confirmedSkillForCurrentState(int tick, int lingerTicks)
	{
		if (currentAvatarState != AvatarState.SKILLING)
		{
			return null;
		}
		return skillingTracker.getConfirmedSkill(tick, lingerTicks);
	}

	/** Clamps stale saved linger values. */
	private int skillingLingerTicks()
	{
		return Math.max(1, Math.min(MAX_SKILLING_LINGER_TICKS, config.skillingLingerTicks()));
	}

	private int fishingResultGraceTicks()
	{
		return FishingActivityDetector.clampResultGraceTicks(
			config.fishingResultGraceTicks());
	}

	@Provides
	IdleFamiliarConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(IdleFamiliarConfig.class);
	}

	/** Updates shimmer from the same resolved state published to the widget. */
	private void updateShimmer(boolean afkWarning, int lowHitpointsThreshold,
		int lowPrayerThreshold)
	{
		shimmerController.tick(
			currentAvatarState,
			activityService.isInventoryFull(),
			activityService.isLowHitpoints(),
			activityService.isLowPrayer(),
			afkWarning,
			activityService.isLingering(PlayerActivityService.Linger.DEATH),
			activityService.isLingering(PlayerActivityService.Linger.LEVEL_UP),
			cachedHitpoints > lowHitpointsThreshold,
			cachedPrayer > lowPrayerThreshold);
	}
}

package com.idlefamiliar;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;

/** Immutable item counts and occupied slots from one client-thread event. */
final class InventoryState
{
	private static final int NATIVE_CAPACITY = 28;
	private static final InventoryState EMPTY =
		new InventoryState(Collections.emptyMap(), 0, false);

	private final Map<Integer, Integer> itemCounts;
	private final int occupiedSlots;

	private InventoryState(Map<Integer, Integer> itemCounts, int occupiedSlots, boolean copy)
	{
		Map<Integer, Integer> safeCounts = itemCounts == null ? Collections.emptyMap() : itemCounts;
		this.itemCounts = safeCounts.isEmpty() ? Collections.emptyMap()
			: Collections.unmodifiableMap(copy ? new HashMap<>(safeCounts) : safeCounts);
		this.occupiedSlots = Math.max(0, Math.min(NATIVE_CAPACITY, occupiedSlots));
	}

	static InventoryState empty()
	{
		return EMPTY;
	}

	static InventoryState from(ItemContainer container)
	{
		if (container == null || container.getItems() == null)
		{
			return EMPTY;
		}

		Map<Integer, Integer> counts = new HashMap<>();
		int occupied = 0;
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() < 0)
			{
				continue;
			}
			occupied++;
			if (item.getQuantity() > 0)
			{
				counts.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		// The map was created in this method and is never exposed mutable, so avoid
		// copying it a second time before wrapping it as immutable.
		return new InventoryState(counts, occupied, false);
	}

	static InventoryState of(Map<Integer, Integer> itemCounts, int occupiedSlots)
	{
		return new InventoryState(itemCounts, occupiedSlots, true);
	}

	Map<Integer, Integer> itemCounts()
	{
		return itemCounts;
	}

	int occupiedSlots()
	{
		return occupiedSlots;
	}

	int freeSlots()
	{
		return NATIVE_CAPACITY - occupiedSlots;
	}

	int quantity(int itemId)
	{
		Integer value = itemCounts.get(itemId);
		return value == null ? 0 : value;
	}

	boolean containsAny(int... itemIds)
	{
		if (itemIds == null)
		{
			return false;
		}
		for (int itemId : itemIds)
		{
			if (quantity(itemId) > 0)
			{
				return true;
			}
		}
		return false;
	}

}

package com.idlefamiliar;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/** Inventory-only recipe that accepts one complete, unambiguous action delta. */
final class ProcessingProfile
{
	enum CapacityModel
	{
		PRIMARY_INPUT,
		ALL_CONSUMED_INPUTS,
		LEATHER
	}

	enum DurationModel
	{
		PER_ACTION,
		FLETCHING_KNIFE,
		ARROW_SHAFTS,
		FLETCHING_KNIFE_ARROW_SHAFTS,
		COOK_ALL,
		FORESTERS_CAMPFIRE
	}

	private final String key;
	private final String label;
	private final int ticksPerAction;
	private final int primaryInputItemId;
	private final Map<Integer, Integer> consumedPerAction;
	private final Map<Integer, Integer> producedPerAction;
	private final Map<Integer, Integer> optionalConsumedMaximums;
	private final Set<Integer> requiredItemIds;
	private final Set<Integer> forbiddenItemIds;
	private final Set<Integer> affectedItemIds;
	private final CapacityModel capacityModel;
	private final DurationModel durationModel;
	private final ProcessingContext.Kind requiredContext;
	/** Iron can consume an ore without producing a bar; its furnace queue is still exact. */
	private final boolean outputMayBeAbsent;
	/** Varrock armour can add one furnace bar without consuming more ore. */
	private final int maximumOutputMultiplier;

	ProcessingProfile(String key, String label, int ticksPerAction, int primaryInputItemId,
		Map<Integer, Integer> consumedPerAction, Set<Integer> producedItemIds,
		Map<Integer, Integer> optionalConsumedMaximums, Set<Integer> requiredItemIds,
		Set<Integer> forbiddenItemIds, CapacityModel capacityModel)
	{
		this(key, label, ticksPerAction, primaryInputItemId, consumedPerAction,
			unitOutputs(producedItemIds), optionalConsumedMaximums, requiredItemIds,
			forbiddenItemIds, capacityModel, DurationModel.PER_ACTION, ProcessingContext.Kind.NONE);
	}

	ProcessingProfile(String key, String label, int ticksPerAction, int primaryInputItemId,
		Map<Integer, Integer> consumedPerAction, Map<Integer, Integer> producedPerAction,
		Map<Integer, Integer> optionalConsumedMaximums, Set<Integer> requiredItemIds,
		Set<Integer> forbiddenItemIds, CapacityModel capacityModel, DurationModel durationModel,
		ProcessingContext.Kind requiredContext)
	{
		this(key, label, ticksPerAction, primaryInputItemId, consumedPerAction, producedPerAction,
			optionalConsumedMaximums, requiredItemIds, forbiddenItemIds, capacityModel, durationModel,
			requiredContext, false);
	}

	ProcessingProfile(String key, String label, int ticksPerAction, int primaryInputItemId,
		Map<Integer, Integer> consumedPerAction, Map<Integer, Integer> producedPerAction,
		Map<Integer, Integer> optionalConsumedMaximums, Set<Integer> requiredItemIds,
		Set<Integer> forbiddenItemIds, CapacityModel capacityModel, DurationModel durationModel,
		ProcessingContext.Kind requiredContext, boolean outputMayBeAbsent)
	{
		this(key, label, ticksPerAction, primaryInputItemId, consumedPerAction, producedPerAction,
			optionalConsumedMaximums, requiredItemIds, forbiddenItemIds, capacityModel, durationModel,
			requiredContext, outputMayBeAbsent, 1);
	}

	ProcessingProfile(String key, String label, int ticksPerAction, int primaryInputItemId,
		Map<Integer, Integer> consumedPerAction, Map<Integer, Integer> producedPerAction,
		Map<Integer, Integer> optionalConsumedMaximums, Set<Integer> requiredItemIds,
		Set<Integer> forbiddenItemIds, CapacityModel capacityModel, DurationModel durationModel,
		ProcessingContext.Kind requiredContext, boolean outputMayBeAbsent, int maximumOutputMultiplier)
	{
		this.key = key;
		this.label = label;
		this.ticksPerAction = ticksPerAction;
		this.primaryInputItemId = primaryInputItemId;
		this.consumedPerAction = immutablePositiveMap(consumedPerAction);
		this.producedPerAction = immutablePositiveMap(producedPerAction);
		this.optionalConsumedMaximums = immutablePositiveMap(optionalConsumedMaximums);
		this.requiredItemIds = immutableSet(requiredItemIds);
		this.forbiddenItemIds = immutableSet(forbiddenItemIds);
		this.capacityModel = capacityModel;
		this.durationModel = durationModel == null ? DurationModel.PER_ACTION : durationModel;
		this.requiredContext = requiredContext == null ? ProcessingContext.Kind.NONE : requiredContext;
		this.outputMayBeAbsent = outputMayBeAbsent;
		this.maximumOutputMultiplier = Math.max(1, maximumOutputMultiplier);

		Set<Integer> affected = new HashSet<>();
		affected.addAll(this.consumedPerAction.keySet());
		affected.addAll(this.producedPerAction.keySet());
		affected.addAll(this.optionalConsumedMaximums.keySet());
		this.affectedItemIds = Collections.unmodifiableSet(affected);
	}

	String key()
	{
		return key;
	}

	String label()
	{
		return label;
	}

	int durationTicks(int units)
	{
		switch (durationModel)
		{
			case FLETCHING_KNIFE:
				return ProcessingDuration.fletchingKnife(units);
			case ARROW_SHAFTS:
				return ProcessingDuration.arrowShafts(units);
			case FLETCHING_KNIFE_ARROW_SHAFTS:
				return ProcessingDuration.fletchingKnifeArrowShafts(units);
			case COOK_ALL:
				return ProcessingDuration.cookAll(units);
			case FORESTERS_CAMPFIRE:
				return ProcessingDuration.forestersCampfire(units);
			case PER_ACTION:
			default:
				return ProcessingDuration.perAction(units, ticksPerAction);
		}
	}

	/** Time left after the queue's first confirmed action has already completed. */
	int remainingDurationTicks(int units)
	{
		switch (durationModel)
		{
			case FLETCHING_KNIFE:
			case FLETCHING_KNIFE_ARROW_SHAFTS:
				return ProcessingDuration.perAction(units, 2);
			case ARROW_SHAFTS:
				return ProcessingDuration.arrowShafts(units);
			case COOK_ALL:
				return ProcessingDuration.perAction(units, 4);
			case FORESTERS_CAMPFIRE:
				return ProcessingDuration.perAction(units, 9);
			case PER_ACTION:
			default:
				return ProcessingDuration.perAction(units, ticksPerAction);
		}
	}

	/** Latest expected repeat interval for the resolved native queue. */
	int continuationGraceTicks()
	{
		switch (durationModel)
		{
			case FLETCHING_KNIFE:
			case FLETCHING_KNIFE_ARROW_SHAFTS:
				return 4;
			case ARROW_SHAFTS:
				return 4;
			case COOK_ALL:
				return 4;
			case FORESTERS_CAMPFIRE:
				return 9;
			case PER_ACTION:
			default:
				return Math.max(4, ticksPerAction);
		}
	}

	boolean matches(InventoryDelta delta, Map<Integer, Integer> inventoryAfter, ProcessingContext context)
	{
		if (!hasRequiredItems(inventoryAfter) || hasForbiddenItems(inventoryAfter)
			|| (requiredContext != ProcessingContext.Kind.NONE
				&& (context == null || context.kind() != requiredContext))
			|| (context != null && context.kind() == ProcessingContext.Kind.FLETCHING_KNIFE
				&& requiredContext != ProcessingContext.Kind.FLETCHING_KNIFE)
			|| !delta.hasChangesOnlyWithin(affectedItemIds))
		{
			return false;
		}

		for (Map.Entry<Integer, Integer> input : consumedPerAction.entrySet())
		{
			if (delta.consumed(input.getKey()) != input.getValue()
				|| delta.produced(input.getKey()) != 0)
			{
				return false;
			}
		}

		if (producedPerAction.isEmpty())
		{
			return true;
		}

		int producedOutputs = 0;
		for (Map.Entry<Integer, Integer> output : producedPerAction.entrySet())
		{
			int produced = delta.produced(output.getKey());
			int expected = output.getValue();
			if (produced != 0 && (produced < expected
				|| produced > expected * maximumOutputMultiplier))
			{
				return false;
			}
			if (delta.consumed(output.getKey()) != 0)
			{
				return false;
			}
			if (produced >= expected)
			{
				producedOutputs++;
			}
		}
		if ((!outputMayBeAbsent && producedOutputs != 1)
			|| (outputMayBeAbsent && producedOutputs > 1))
		{
			return false;
		}

		for (Map.Entry<Integer, Integer> optional : optionalConsumedMaximums.entrySet())
		{
			if (delta.consumed(optional.getKey()) > optional.getValue()
				|| delta.produced(optional.getKey()) != 0)
			{
				return false;
			}
		}
		return true;
	}

	boolean sameRecipe(ProcessingProfile other)
	{
		return other != null && key.equals(other.key)
			&& durationModel == other.durationModel && ticksPerAction == other.ticksPerAction
			&& outputMayBeAbsent == other.outputMayBeAbsent
			&& maximumOutputMultiplier == other.maximumOutputMultiplier;
	}

	boolean requiresContext(ProcessingContext.Kind kind)
	{
		return kind != null && requiredContext == kind;
	}

	static ProcessingProfile anvilSmithing(int bar, int barsPerOutput, int outputItemId,
		int outputQuantity, ProcessingContext context)
	{
		int ticks = context != null && context.hasFullSmithsUniform() ? 4 : 5;
		Set<Integer> hammer = context != null && context.hasOffhandHammer()
			? Collections.emptySet() : Set.of(net.runelite.api.ItemID.HAMMER);
		String key = "anvil." + bar + "." + barsPerOutput + "." + outputItemId + "."
			+ outputQuantity + "." + ticks + "." + (hammer.isEmpty() ? "offhand" : "inventory");
		return new ProcessingProfile(key, "Anvil smithing", ticks, bar,
			Map.of(bar, barsPerOutput), Map.of(outputItemId, outputQuantity), Collections.emptyMap(),
			hammer, Collections.emptySet(), CapacityModel.ALL_CONSUMED_INPUTS,
			DurationModel.PER_ACTION, ProcessingContext.Kind.ANVIL_SMITHING);
	}

	static ProcessingProfile forestersCampfire(int logItemId)
	{
		return new ProcessingProfile("foresters-campfire." + logItemId, "Forester's Campfire", 0,
			logItemId, Map.of(logItemId, 1), Collections.emptyMap(), Collections.emptyMap(),
			Collections.emptySet(), Collections.emptySet(), CapacityModel.PRIMARY_INPUT,
			DurationModel.FORESTERS_CAMPFIRE, ProcessingContext.Kind.FORESTERS_CAMPFIRE);
	}

	/** Standard furnace recipe; the queue consumes inputs once every five ticks. */
	static ProcessingProfile furnaceSmelting(String key, Map<Integer, Integer> inputs,
		int outputItemId, boolean outputMayBeAbsent)
	{
		if (inputs == null || inputs.isEmpty())
		{
			throw new IllegalArgumentException("Furnace recipe needs at least one ore input");
		}
		int primaryInput = inputs.keySet().iterator().next();
		return new ProcessingProfile(key, "Furnace smelting", 5, primaryInput, inputs,
			Map.of(outputItemId, 1), Collections.emptyMap(), Collections.emptySet(),
			Collections.emptySet(), CapacityModel.ALL_CONSUMED_INPUTS, DurationModel.PER_ACTION,
			ProcessingContext.Kind.FURNACE_SMELTING, outputMayBeAbsent, 2);
	}

	static ProcessingProfile cookAll(int rawItemId, int outputItemId,
		ProcessingContext.Kind requiredContext)
	{
		// A burn and a successful cook are two legitimate results of the same
		// raw-food queue. Like gem cutting's cut/crushed alternatives, output
		// identity must not split the underlying recipe or reset the ETA.
		return new ProcessingProfile("cook-all." + rawItemId, "Cooking", 0,
			rawItemId, Map.of(rawItemId, 1), Map.of(outputItemId, 1), Collections.emptyMap(),
			Collections.emptySet(), Collections.emptySet(), CapacityModel.PRIMARY_INPUT,
			DurationModel.COOK_ALL, requiredContext);
	}

	/** A single cooking delta is ambiguous; a native queue is proven by its repeat cadence. */
	boolean requiresRepeatConfirmation()
	{
		return durationModel == DurationModel.COOK_ALL
			&& requiredContext != ProcessingContext.Kind.COOKING;
	}

	int repeatConfirmationTicks()
	{
		return durationModel == DurationModel.COOK_ALL ? 4 : 0;
	}

	static ProcessingProfile finishedPotion(Map<Integer, Integer> consumed, int outputItemId)
	{
		return finishedPotion(consumed, outputItemId, 2);
	}

	static ProcessingProfile finishedPotion(Map<Integer, Integer> consumed, int outputItemId,
		int ticksPerAction)
	{
		StringBuilder key = new StringBuilder("finished-potion");
		consumed.keySet().stream().sorted().forEach(id -> key.append('.').append(id).append('x').append(consumed.get(id)));
		return new ProcessingProfile(key.append('.').append(outputItemId).toString(), "Finished potions",
			ticksPerAction,
			consumed.keySet().iterator().next(), consumed, Map.of(outputItemId, 1), Collections.emptyMap(),
			Collections.emptySet(), Collections.emptySet(), CapacityModel.ALL_CONSUMED_INPUTS,
			DurationModel.PER_ACTION, ProcessingContext.Kind.FINISHED_POTION);
	}

	/** A verified native 15-arrow or 10-bolt Make-X batch. */
	static ProcessingProfile fletchingBatch(Map<Integer, Integer> consumed, int outputItemId,
		int outputQuantity, ProcessingContext.Kind context)
	{
		StringBuilder key = new StringBuilder("fletching-batch");
		consumed.keySet().stream().sorted()
			.forEach(id -> key.append('.').append(id).append('x').append(consumed.get(id)));
		key.append('.').append(outputItemId).append('x').append(outputQuantity)
			.append('.').append(context == ProcessingContext.Kind.FLETCHING_KNIFE ? "fletching-knife" : "knife");
		boolean fletchingKnife = context == ProcessingContext.Kind.FLETCHING_KNIFE;
		return new ProcessingProfile(key.toString(), "Arrow / bolt fletching", 0,
			consumed.keySet().iterator().next(), consumed, Map.of(outputItemId, outputQuantity),
			// Feathering shafts/bolts and attaching arrowtips are item-pair actions;
			// unlike cutting logs into shafts, they do not require a knife to remain
			// visible in inventory. The complete 15/10-item delta is the proof.
			Collections.emptyMap(), Collections.emptySet(), Collections.emptySet(),
			CapacityModel.ALL_CONSUMED_INPUTS, DurationModel.ARROW_SHAFTS,
			fletchingKnife ? ProcessingContext.Kind.FLETCHING_KNIFE : ProcessingContext.Kind.NONE);
	}

	boolean canStart(Map<Integer, Integer> inventory)
	{
		return hasRequiredItems(inventory) && !hasForbiddenItems(inventory) && initialUnits(inventory) > 0;
	}

	int initialUnits(Map<Integer, Integer> inventory)
	{
		switch (capacityModel)
		{
			case ALL_CONSUMED_INPUTS:
				return unitsFromAllInputs(inventory);
			case LEATHER:
				return leatherUnitsAtStart(inventory);
			case PRIMARY_INPUT:
			default:
				return quantity(inventory, primaryInputItemId);
		}
	}

	/** Remaining units after the profile has started and each later delta proves an action. */
	int remainingUnits(Map<Integer, Integer> inventory)
	{
		if (!hasRequiredItems(inventory) || hasForbiddenItems(inventory))
		{
			return 0;
		}
		if (capacityModel == CapacityModel.ALL_CONSUMED_INPUTS)
		{
			return unitsFromAllInputs(inventory);
		}
		// A leather action can consume the thread that pays for the current group of
		// five. Once the first delta proved an active queue, the remaining leather
		// count is the honest horizon; a later missing thread simply causes the queue
		// to stop and the controller clears after its interruption grace window.
		return quantity(inventory, primaryInputItemId);
	}

	private int unitsFromAllInputs(Map<Integer, Integer> inventory)
	{
		int units = Integer.MAX_VALUE;
		for (Map.Entry<Integer, Integer> input : consumedPerAction.entrySet())
		{
			units = Math.min(units, quantity(inventory, input.getKey()) / input.getValue());
		}
		return units == Integer.MAX_VALUE ? 0 : units;
	}

	private int leatherUnitsAtStart(Map<Integer, Integer> inventory)
	{
		int leather = quantity(inventory, primaryInputItemId);
		int thread = optionalConsumedMaximums.isEmpty() ? 0
			: quantity(inventory, optionalConsumedMaximums.keySet().iterator().next());
		// The current partial-use state of a spool cannot be observed. We only start
		// when the visible stack is enough even in the conservative, fresh-spool case.
		return thread >= (leather + 4) / 5 ? leather : 0;
	}

	private boolean hasRequiredItems(Map<Integer, Integer> inventory)
	{
		for (Integer itemId : requiredItemIds)
		{
			if (quantity(inventory, itemId) <= 0)
			{
				return false;
			}
		}
		return true;
	}

	private boolean hasForbiddenItems(Map<Integer, Integer> inventory)
	{
		for (Integer itemId : forbiddenItemIds)
		{
			if (quantity(inventory, itemId) > 0)
			{
				return true;
			}
		}
		return false;
	}

	private static int quantity(Map<Integer, Integer> inventory, int itemId)
	{
		Integer quantity = inventory.get(itemId);
		return quantity == null ? 0 : quantity;
	}

	private static Map<Integer, Integer> immutablePositiveMap(Map<Integer, Integer> source)
	{
		Map<Integer, Integer> copy = new HashMap<>();
		if (source != null)
		{
			for (Map.Entry<Integer, Integer> entry : source.entrySet())
			{
				if (entry.getKey() != null && entry.getValue() != null && entry.getValue() > 0)
				{
					copy.put(entry.getKey(), entry.getValue());
				}
			}
		}
		return Collections.unmodifiableMap(copy);
	}

	private static Set<Integer> immutableSet(Set<Integer> source)
	{
		return source == null || source.isEmpty() ? Collections.emptySet()
			: Collections.unmodifiableSet(new HashSet<>(source));
	}

	private static Map<Integer, Integer> unitOutputs(Set<Integer> itemIds)
	{
		Map<Integer, Integer> result = new HashMap<>();
		if (itemIds != null)
		{
			for (Integer itemId : itemIds)
			{
				if (itemId != null)
				{
					result.put(itemId, 1);
				}
			}
		}
		return result;
	}
}

package com.idlefamiliar;

import net.runelite.api.ItemID;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.WorldPoint;

/** Client-facing recognition for the exact active Daeyalt rock interaction. */
final class DaeyaltRecognizer
{
	private static final int ACTIVE_DAEYALT_OBJECT_ID = 39095;
	private final ActivityAnimationRegistry animationRegistry;

	DaeyaltRecognizer(ActivityAnimationRegistry animationRegistry)
	{
		this.animationRegistry = animationRegistry;
	}

	boolean isMiningAnimation(int animationId)
	{
		return "Mining".equals(
			animationRegistry.activityForAnimation(animationId));
	}

	Interaction detectInteraction(int objectId, MenuAction action,
		String normalizedOption, WorldPoint location, InventoryState inventory,
		InventoryState equipment)
	{
		if (objectId != ACTIVE_DAEYALT_OBJECT_ID || !"mine".equals(normalizedOption)
			|| !ActivityDetector.isGameObjectAction(action))
		{
			return null;
		}
		return new Interaction(location, resolvePickaxe(inventory, equipment));
	}

	private static DaeyaltCatalog.PickaxeTier resolvePickaxe(InventoryState inventory,
		InventoryState equipment)
	{
		DaeyaltCatalog.PickaxeTier best = bestPickaxe(inventory, null);
		return bestPickaxe(equipment, best);
	}

	private static DaeyaltCatalog.PickaxeTier bestPickaxe(InventoryState items,
		DaeyaltCatalog.PickaxeTier currentBest)
	{
		DaeyaltCatalog.PickaxeTier best = currentBest;
		for (Integer itemId : items.itemCounts().keySet())
		{
			DaeyaltCatalog.PickaxeTier tier = pickaxeTier(itemId);
			if (tier != null && (best == null || tier.ordinal() > best.ordinal()))
			{
				best = tier;
			}
		}
		return best;
	}

	private static DaeyaltCatalog.PickaxeTier pickaxeTier(int itemId)
	{
		switch (itemId)
		{
			case ItemID.BRONZE_PICKAXE:
				return DaeyaltCatalog.PickaxeTier.BRONZE;
			case ItemID.IRON_PICKAXE:
				return DaeyaltCatalog.PickaxeTier.IRON;
			case ItemID.STEEL_PICKAXE:
				return DaeyaltCatalog.PickaxeTier.STEEL;
			case ItemID.BLACK_PICKAXE:
				return DaeyaltCatalog.PickaxeTier.BLACK;
			case ItemID.MITHRIL_PICKAXE:
				return DaeyaltCatalog.PickaxeTier.MITHRIL;
			case ItemID.ADAMANT_PICKAXE:
				return DaeyaltCatalog.PickaxeTier.ADAMANT;
			case ItemID.RUNE_PICKAXE:
			case ItemID.GILDED_PICKAXE:
				return DaeyaltCatalog.PickaxeTier.RUNE;
			case ItemID.DRAGON_PICKAXE:
			case ItemID.DRAGON_PICKAXE_OR:
			case ItemID.DRAGON_PICKAXE_OR_25376:
			case ItemID.DRAGON_PICKAXE_OR_30351:
				return DaeyaltCatalog.PickaxeTier.DRAGON;
			case ItemID.INFERNAL_PICKAXE:
			case ItemID.INFERNAL_PICKAXE_OR:
			case ItemID.INFERNAL_PICKAXE_OR_30345:
				return DaeyaltCatalog.PickaxeTier.INFERNAL;
			case ItemID._3RD_AGE_PICKAXE:
				return DaeyaltCatalog.PickaxeTier.THIRD_AGE;
			case ItemID.CRYSTAL_PICKAXE:
			case ItemID.CRYSTAL_PICKAXE_23863:
				return DaeyaltCatalog.PickaxeTier.CRYSTAL;
			default:
				return null;
		}
	}

	static final class Interaction
	{
		private final WorldPoint location;
		private final DaeyaltCatalog.PickaxeTier pickaxe;

		private Interaction(WorldPoint location, DaeyaltCatalog.PickaxeTier pickaxe)
		{
			this.location = location;
			this.pickaxe = pickaxe;
		}

		WorldPoint location()
		{
			return location;
		}

		DaeyaltCatalog.PickaxeTier pickaxe()
		{
			return pickaxe;
		}
	}
}

package com.idlefamiliar;

/** Exact fixed-cadence queues whose remaining input count is caller-verified. */
final class FixedProcessingEtaEngine implements EtaEngine
{
	private static final int INTERRUPTION_GRACE_TICKS = 4;

	private FixedProcessingRun run;
	private TaskEtaSnapshot snapshot = TaskEtaSnapshot.inactive();

	boolean update(String label, int remainingUnits, int ticksPerUnit,
		boolean eligible, int tick)
	{
		if (!eligible || label == null || label.trim().isEmpty()
			|| remainingUnits <= 0 || ticksPerUnit <= 0)
		{
			cancel();
			return false;
		}

		if (run == null || !run.matches(label, ticksPerUnit)
			|| remainingUnits > run.remainingUnits)
		{
			run = new FixedProcessingRun(label, remainingUnits, ticksPerUnit, tick);
		}
		else if (remainingUnits < run.remainingUnits)
		{
			run = run.confirm(remainingUnits, tick);
		}
		else
		{
			// Repeated station poses prove the queue is still live, but must not
			// reset its cadence on every game tick.
			run = run.continueAt(tick);
		}
		snapshot = run.snapshotAt(tick);
		return true;
	}

	@Override
	public void onGameTick(int tick)
	{
		if (run == null)
		{
			return;
		}
		if (tick - run.lastEvidenceTick
			> Math.max(INTERRUPTION_GRACE_TICKS, run.ticksPerUnit + 1))
		{
			cancel();
			return;
		}
		snapshot = run.snapshotAt(tick);
	}

	@Override
	public void cancel()
	{
		run = null;
		snapshot = TaskEtaSnapshot.inactive();
	}

	@Override
	public boolean isActive()
	{
		return run != null;
	}

	@Override
	public TaskEtaSnapshot snapshot()
	{
		return snapshot;
	}

	private static final class FixedProcessingRun implements EtaRun
	{
		private final String label;
		private final int initialUnits;
		private final int remainingUnits;
		private final int ticksPerUnit;
		private final int lastConfirmationTick;
		private final int lastEvidenceTick;

		private FixedProcessingRun(String label, int units, int ticksPerUnit, int tick)
		{
			this(label, units, units, ticksPerUnit, tick, tick);
		}

		private FixedProcessingRun(String label, int initialUnits, int remainingUnits,
			int ticksPerUnit, int lastConfirmationTick, int lastEvidenceTick)
		{
			this.label = label;
			this.initialUnits = initialUnits;
			this.remainingUnits = remainingUnits;
			this.ticksPerUnit = ticksPerUnit;
			this.lastConfirmationTick = lastConfirmationTick;
			this.lastEvidenceTick = lastEvidenceTick;
		}

		private boolean matches(String nextLabel, int nextTicksPerUnit)
		{
			return label.equals(nextLabel) && ticksPerUnit == nextTicksPerUnit;
		}

		private FixedProcessingRun confirm(int units, int tick)
		{
			return new FixedProcessingRun(label, initialUnits, units, ticksPerUnit, tick, tick);
		}

		private FixedProcessingRun continueAt(int tick)
		{
			return new FixedProcessingRun(label, initialUnits, remainingUnits, ticksPerUnit,
				lastConfirmationTick, tick);
		}

		@Override
		public TaskEtaSnapshot snapshotAt(int tick)
		{
			int elapsed = Math.max(0, tick - lastConfirmationTick);
			int remainingTicks = saturatedTicks(remainingUnits, ticksPerUnit, elapsed);
			int totalTicks = saturatedTicks(initialUnits, ticksPerUnit, 0);
			return TaskEtaSnapshot.processing(label, initialUnits, remainingUnits,
				remainingTicks, totalTicks);
		}

		private static int saturatedTicks(int units, int ticksPerUnit, int elapsed)
		{
			long ticks = Math.max(0L, (long) units * ticksPerUnit - elapsed);
			return ticks >= Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) ticks;
		}
	}
}

package com.idlefamiliar;

import java.util.Set;

/** Tracks active skilling with a tick-based linger and interaction bridge. */
public class SkillingActivityTracker
{
	/** Passive stat changes do not prove skilling. */
	static final Set<String> PASSIVE_SKILLS = Set.of("prayer", "hitpoints");

	private static final int NO_SIGNAL = Integer.MIN_VALUE;

	static final int NO_TARGET = 0;

	private int lastSignalTick = NO_SIGNAL;
	private String confirmedSkill;

	/** Opaque actor identity keeps this class free of RuneLite types. */
	private int targetToken = NO_TARGET;

	/** Tick when an animation confirmed the current target. */
	private int targetConfirmedTick = NO_SIGNAL;

	public static boolean isPassiveSkill(String skill)
	{
		return skill != null && PASSIVE_SKILLS.contains(skill.toLowerCase());
	}

	/** Records a stat signal unless it is passive. */
	public boolean recordSkillSignal(String skill, int tick)
	{
		if (isPassiveSkill(skill))
		{
			return false;
		}
		return recordConfirmedSkillSignal(skill, tick);
	}

	/** Records a real XP gain, including active Prayer training. */
	public boolean recordXpSkillSignal(String skill, int tick)
	{
		return recordConfirmedSkillSignal(skill, tick);
	}

	private boolean recordConfirmedSkillSignal(String skill, int tick)
	{
		lastSignalTick = tick;
		if (skill != null && !skill.isEmpty())
		{
			confirmedSkill = skill;
		}
		return true;
	}

	/** Refreshes linger without changing the skill label. */
	public void recordActivitySignal(int tick)
	{
		lastSignalTick = tick;
	}

	/** Bridges animation gaps while the same confirmed target remains selected. */
	public boolean recordInteractionTarget(int targetToken, int tick)
	{
		// A changed or cleared target ends the bridge immediately.
		if (targetToken != this.targetToken)
		{
			this.targetToken = targetToken;
			this.targetConfirmedTick = NO_SIGNAL;
		}

		// The one-tick tolerance covers signal ordering within onGameTick.
		if (targetToken != NO_TARGET
			&& lastSignalTick != NO_SIGNAL
			&& (tick - lastSignalTick) <= 1
			&& (tick - lastSignalTick) >= 0)
		{
			this.targetConfirmedTick = tick;
		}

		return isSustainedByTarget();
	}

	/** Returns whether the current target sustains skilling. */
	public boolean isSustainedByTarget()
	{
		return targetToken != NO_TARGET && targetConfirmedTick != NO_SIGNAL;
	}

	public boolean isSkilling(int tick, int lingerTicks)
	{
		if (isSustainedByTarget())
		{
			return true;
		}
		if (lastSignalTick == NO_SIGNAL)
		{
			return false;
		}
		return (tick - lastSignalTick) < lingerTicks;
	}

	public String getConfirmedSkill(int tick, int lingerTicks)
	{
		return isSkilling(tick, lingerTicks) ? confirmedSkill : null;
	}

	/** Cancels linger, target sustain, and the label together. */
	public void cancelLinger()
	{
		lastSignalTick = NO_SIGNAL;
		confirmedSkill = null;
		targetToken = NO_TARGET;
		targetConfirmedTick = NO_SIGNAL;
	}

	public void reset()
	{
		lastSignalTick = NO_SIGNAL;
		confirmedSkill = null;
		targetToken = NO_TARGET;
		targetConfirmedTick = NO_SIGNAL;
	}
}

package com.idlefamiliar;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.function.IntUnaryOperator;

/** Paints and tracks the read-only 4x7 inventory viewer independently of the desktop window shell. */
final class InventoryGridRenderer
{
	static final int BASE_PADDING = 7;
	static final int BASE_HEADER_HEIGHT = 22;
	static final int BASE_SLOT_SIZE = 30;
	private static final long CHANGE_HIGHLIGHT_MS = 900L;

	private InventorySnapshot previousInventory = InventorySnapshot.empty();
	private boolean initialized;
	private final long[] slotChangedAt = new long[InventorySnapshot.SLOT_COUNT];

	/** Shared viewer geometry used by both window layout and painting tests. */
	static Dimension viewerSize(InventoryDensity density, IntUnaryOperator ui)
	{
		if (density == InventoryDensity.OFF)
		{
			return new Dimension(0, 0);
		}
		IntUnaryOperator safeUi = ui == null ? value -> value : ui;
		int padding = safeUi.applyAsInt(BASE_PADDING);
		int headerHeight = safeUi.applyAsInt(BASE_HEADER_HEIGHT);
		int slotSize = safeUi.applyAsInt(BASE_SLOT_SIZE);
		int rows = density == InventoryDensity.STRIP ? 1 : InventorySnapshot.ROWS;
		return new Dimension(padding * 2 + InventorySnapshot.COLUMNS * slotSize,
			headerHeight + padding * 2 + rows * slotSize);
	}

	void recordChanges(InventorySnapshot inventory, long nowMs)
	{
		InventorySnapshot current = inventory == null ? InventorySnapshot.empty() : inventory;
		if (!initialized)
		{
			previousInventory = current;
			initialized = true;
			return;
		}
		if (current == previousInventory)
		{
			return;
		}
		for (int index = 0; index < InventorySnapshot.SLOT_COUNT; index++)
		{
			InventorySnapshot.Slot before = previousInventory.getSlot(index);
			InventorySnapshot.Slot after = current.getSlot(index);
			if (before.getItemId() != after.getItemId()
				|| before.getQuantity() != after.getQuantity())
			{
				slotChangedAt[index] = nowMs;
			}
		}
		previousInventory = current;
	}

	void paint(Graphics2D graphics, InventorySnapshot inventory, int occupiedSlots,
		InventoryDensity density, int x, int y, int width, int height, WidgetTheme theme,
		double scale, IntUnaryOperator ui, long nowMs)
	{
		WidgetTheme safeTheme = theme == null ? WidgetTheme.CLASSIC_RUNESCAPE : theme;
		drawStonePanel(graphics, x, y, width, height, safeTheme, ui);

		Font originalFont = graphics.getFont();
		graphics.setFont(originalFont.deriveFont(Font.BOLD, Math.max(6f, (float) (13f * scale))));
		FontMetrics headerMetrics = graphics.getFontMetrics();
		int padding = ui.applyAsInt(BASE_PADDING);
		int headerHeight = ui.applyAsInt(BASE_HEADER_HEIGHT);
		int slotSize = ui.applyAsInt(BASE_SLOT_SIZE);
		int safeOccupiedSlots = Math.max(0, Math.min(InventorySnapshot.SLOT_COUNT, occupiedSlots));
		String heading = "Inv " + safeOccupiedSlots + "/" + InventorySnapshot.SLOT_COUNT;
		int headingY = y + (headerHeight - headerMetrics.getHeight()) / 2 + headerMetrics.getAscent();
		graphics.setColor(safeTheme.shadow());
		graphics.drawString(heading, x + padding + ui.applyAsInt(1), headingY + ui.applyAsInt(1));
		graphics.setColor(safeTheme.text());
		graphics.drawString(heading, x + padding, headingY);
		graphics.setFont(originalFont);

		InventorySnapshot safeInventory = inventory == null ? InventorySnapshot.empty() : inventory;
		int gridY = y + headerHeight + padding;
		int[] displayedSlots = density == InventoryDensity.STRIP
			? recentSlots(safeInventory) : nativeSlots();
		for (int displayIndex = 0; displayIndex < displayedSlots.length; displayIndex++)
		{
			int slotIndex = displayedSlots[displayIndex];
			int column = displayIndex % InventorySnapshot.COLUMNS;
			int row = displayIndex / InventorySnapshot.COLUMNS;
			int slotX = x + padding + column * slotSize;
			int slotY = gridY + row * slotSize;
			drawSlot(graphics, safeInventory.getSlot(slotIndex), slotX, slotY,
				isHighlighted(slotIndex, nowMs), safeTheme, scale, ui);
		}
	}

	private int[] nativeSlots()
	{
		int[] slots = new int[InventorySnapshot.SLOT_COUNT];
		for (int index = 0; index < slots.length; index++)
		{
			slots[index] = index;
		}
		return slots;
	}

	private int[] recentSlots(InventorySnapshot inventory)
	{
		int[] result = new int[InventorySnapshot.COLUMNS];
		boolean[] selected = new boolean[InventorySnapshot.SLOT_COUNT];
		int resultSize = 0;
		while (resultSize < result.length)
		{
			int newest = -1;
			for (int index = 0; index < slotChangedAt.length; index++)
			{
				if (!selected[index] && slotChangedAt[index] > 0L
					&& (newest < 0 || slotChangedAt[index] > slotChangedAt[newest]))
				{
					newest = index;
				}
			}
			if (newest < 0)
			{
				break;
			}
			result[resultSize++] = newest;
			selected[newest] = true;
		}
		for (int index = 0; resultSize < result.length && index < InventorySnapshot.SLOT_COUNT; index++)
		{
			if (!selected[index] && !inventory.getSlot(index).isEmpty())
			{
				result[resultSize++] = index;
				selected[index] = true;
			}
		}
		for (int index = 0; resultSize < result.length && index < InventorySnapshot.SLOT_COUNT; index++)
		{
			if (!selected[index])
			{
				result[resultSize++] = index;
			}
		}
		return result;
	}

	private void drawSlot(Graphics2D graphics, InventorySnapshot.Slot slot, int x, int y,
		boolean highlighted, WidgetTheme theme, double scale, IntUnaryOperator ui)
	{
		int size = ui.applyAsInt(BASE_SLOT_SIZE);
		int one = ui.applyAsInt(1);
		int radius = ui.applyAsInt(3);
		graphics.setColor(theme.panelDark());
		graphics.fillRoundRect(x, y, size - one, size - one, radius, radius);
		graphics.setColor(highlighted ? theme.text() : theme.border());
		graphics.drawRoundRect(x, y, size - one, size - one, radius, radius);
		if (highlighted)
		{
			graphics.setColor(new Color(theme.text().getRed(), theme.text().getGreen(),
				theme.text().getBlue(), 70));
			graphics.drawRoundRect(x + one, y + one, size - ui.applyAsInt(3),
				size - ui.applyAsInt(3), radius, radius);
		}

		if (slot == null || slot.isEmpty())
		{
			return;
		}
		BufferedImage image = slot.getImage();
		if (image != null)
		{
			int imageSize = size - ui.applyAsInt(5);
			graphics.drawImage(image, x + (size - imageSize) / 2, y + (size - imageSize) / 2,
				imageSize, imageSize, null);
		}
		if (slot.getQuantity() > 1)
		{
			drawQuantity(graphics, WidgetTextFormatter.inventoryQuantity(slot.getQuantity()),
				x, y, size, theme, scale, ui);
		}
	}

	private boolean isHighlighted(int slotIndex, long nowMs)
	{
		long changedAt = slotChangedAt[slotIndex];
		return changedAt > 0L && nowMs - changedAt <= CHANGE_HIGHLIGHT_MS;
	}

	private void drawQuantity(Graphics2D graphics, String quantity, int x, int y, int size,
		WidgetTheme theme, double scale, IntUnaryOperator ui)
	{
		Font originalFont = graphics.getFont();
		Font quantityFont = originalFont.deriveFont(Font.BOLD, Math.max(6f, (float) (10f * scale)));
		FontMetrics metrics = graphics.getFontMetrics(quantityFont);
		while (metrics.stringWidth(quantity) > size - ui.applyAsInt(3) && quantityFont.getSize2D() > 6f)
		{
			quantityFont = originalFont.deriveFont(Font.BOLD, quantityFont.getSize2D() - 1f);
			metrics = graphics.getFontMetrics(quantityFont);
		}
		graphics.setFont(quantityFont);
		int textX = x + size - ui.applyAsInt(2) - metrics.stringWidth(quantity);
		int baseline = y + size - ui.applyAsInt(3);
		graphics.setColor(theme.shadow());
		graphics.drawString(quantity, textX + 1, baseline + 1);
		graphics.setColor(theme.text());
		graphics.drawString(quantity, textX, baseline);
		graphics.setFont(originalFont);
	}

	private void drawStonePanel(Graphics2D graphics, int x, int y, int width, int height,
		WidgetTheme theme, IntUnaryOperator ui)
	{
		int one = ui.applyAsInt(1);
		int two = ui.applyAsInt(2);
		int radius = ui.applyAsInt(5);
		graphics.setColor(theme.panel());
		graphics.fillRoundRect(x, y, width, height, radius, radius);
		graphics.setStroke(new BasicStroke(1f));
		graphics.setColor(theme.borderLight());
		graphics.drawLine(x + one, y + one, x + width - two, y + one);
		graphics.drawLine(x + one, y + one, x + one, y + height - two);
		graphics.setColor(theme.border());
		graphics.drawLine(x + one, y + height - two, x + width - two, y + height - two);
		graphics.drawLine(x + width - two, y + one, x + width - two, y + height - two);
		graphics.setColor(theme.panelDark());
		graphics.drawRoundRect(x, y, width - one, height - one, radius, radius);
	}
}

package com.idlefamiliar;

import java.util.Map;
import java.util.Set;
import net.runelite.api.ItemID;
import net.runelite.api.gameval.AnimationID;

/** Reviewed mechanics and client signals for sorting shipwreck salvage. */
final class SalvageSortingCatalog
{
	static final String LABEL = "Sorting salvage";
	static final String GATHERING_LABEL = "Shipwreck salvaging";
	/** The station processes one salvage item every three game ticks. */
	static final int TICKS_PER_ITEM = 3;

	private static final Set<Integer> SALVAGE_ITEM_IDS = Set.of(
		ItemID.SMALL_SALVAGE,
		ItemID.FISHY_SALVAGE,
		ItemID.BARRACUDA_SALVAGE,
		ItemID.LARGE_SALVAGE,
		ItemID.PLUNDERED_SALVAGE,
		ItemID.MARTIAL_SALVAGE,
		ItemID.FREMENNIK_SALVAGE,
		ItemID.OPULENT_SALVAGE);
	private SalvageSortingCatalog()
	{
	}

	/** Both dock and vessel facilities expose this exact native menu action. */
	static boolean isSortingInteraction(String option, String target)
	{
		boolean sort = "sort-salvage".equals(option) || "sort salvage".equals(option);
		return sort && target != null && target.contains("salvaging station");
	}

	/** The deliberate station interaction, distinct from salvaging-hook animations. */
	static boolean isStartAnimation(int animationId)
	{
		return animationId == AnimationID.HUMAN_SAILING_SALVAGE01_LARGE01_INTERACT01;
	}

	/** Player poses that prove the station queue is still engaged. */
	static boolean isStationAnimation(int animationId)
	{
		return animationId == AnimationID.HUMAN_SAILING_SALVAGE01_LARGE01_DROP01
			|| animationId == AnimationID.HUMAN_SAILING_SALVAGE01_LARGE01_IDLE01
			|| isStartAnimation(animationId)
			|| animationId == AnimationID.HUMAN_SAILING_SALVAGE01_LARGE01_RESET01
			// The onboard station uses this hook-named interaction pose, but it
			// still consumes salvage from the player's ordinary inventory.
			|| animationId
				== AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_INTERACT01;
	}

	/** Player-operated hook poses; crew-only and inactive facility poses are excluded. */
	static boolean isHookAnimation(int animationId)
	{
		return animationId == AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_DROP01
			|| animationId == AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_IDLE01
			|| animationId == AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_RESET01
			|| animationId == AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_2X5_DROP01
			|| animationId == AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_2X5_IDLE01
			|| animationId == AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_2X5_RESET01
			|| animationId == AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_3X8_DROP01
			|| animationId == AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_3X8_IDLE01
			|| animationId == AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_3X8_RESET01
			|| animationId == AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_SALVAGING01
			|| animationId == AnimationID.SAILING_HUMAN_SALVAGE_HOOK_KANDARIN_1X3_PULL01;
	}

	static boolean isSortingStartMessage(String normalizedMessage)
	{
		return normalizedMessage != null
			&& normalizedMessage.startsWith("you begin sorting through your salvage");
	}

	static boolean isSortingResultMessage(String normalizedMessage)
	{
		return normalizedMessage != null
			&& normalizedMessage.startsWith("you sort through the ")
			&& normalizedMessage.contains(" salvage and find:");
	}

	static boolean isSortingEndMessage(String normalizedMessage)
	{
		return normalizedMessage != null
			&& normalizedMessage.startsWith("you have no more salvage to sort");
	}

	static int sortableUnits(Map<Integer, Integer> inventory)
	{
		if (inventory == null || inventory.isEmpty())
		{
			return 0;
		}
		long total = 0L;
		for (Integer itemId : SALVAGE_ITEM_IDS)
		{
			Integer quantity = inventory.get(itemId);
			if (quantity != null && quantity > 0)
			{
				total += quantity;
			}
		}
		return total >= Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) total;
	}
}

