		13596, 13598, 13599, // current 1x3 hook salvage / pull / interact
	};

	private final Map<Integer, String> activityByAnimation;
	private final Set<Integer> teleportAnimations;

	private ActivityAnimationRegistry(Map<Integer, String> activityByAnimation, Set<Integer> teleportAnimations)
	{
		this.activityByAnimation = activityByAnimation;
		this.teleportAnimations = teleportAnimations;
	}

	/**
	 * @return the activity label for {@code animationId}, or {@code null} when
	 *         it is not a recognised skilling animation
	 */
	public String activityForAnimation(int animationId)
	{
		return activityByAnimation.get(animationId);
	}

	/** @return {@code true} if {@code animationId} is a known teleport animation */
	public boolean isTeleportAnimation(int animationId)
	{
		return teleportAnimations.contains(animationId);
	}

	/** Build the immutable registry from the baked whitelists above. */
	public static ActivityAnimationRegistry build()
	{
		Map<Integer, String> byAnimation = new HashMap<>();
		register(byAnimation, WOODCUTTING_ANIMATIONS, "Woodcutting");
		register(byAnimation, MINING_ANIMATIONS, "Mining");
		register(byAnimation, FISHING_ANIMATIONS, "Fishing");
		register(byAnimation, SMITHING_ANIMATIONS, "Smithing");
		register(byAnimation, FLETCHING_ANIMATIONS, "Fletching");
		register(byAnimation, CRAFTING_ANIMATIONS, "Crafting");
		register(byAnimation, JEWELLERY_ENCHANTING_ANIMATIONS, "Magic");
		register(byAnimation, HERBLORE_ANIMATIONS, "Herblore");
		register(byAnimation, COOKING_ANIMATIONS, "Cooking");
		register(byAnimation, RUNECRAFT_ANIMATIONS, "Runecraft");
		register(byAnimation, FARMING_ANIMATIONS, "Farming");
		register(byAnimation, THIEVING_ANIMATIONS, "Thieving");

		// Sailing salvaging wins over any earlier mapping for the same id.
		for (int salvageAnimation : SAILING_SALVAGE_ANIMATIONS)
		{
			byAnimation.put(salvageAnimation, "Sailing");
		}

		Set<Integer> teleports = new HashSet<>();
		for (int teleportAnimation : TELEPORT_ANIMATIONS)
		{
			teleports.add(teleportAnimation);
		}

		return new ActivityAnimationRegistry(
			Collections.unmodifiableMap(byAnimation),
			Collections.unmodifiableSet(teleports));
	}

	/** putIfAbsent each id under {@code label}, preserving any earlier (higher-priority) mapping. */
	private static void register(Map<Integer, String> byAnimation, int[] animations, String label)
	{
		for (int animation : animations)
		{
			byAnimation.putIfAbsent(animation, label);
		}
	}
}

package com.idlefamiliar;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Static source-modelled and locally observed gathering ETA run family. */
final class GatheringEtaEngine implements EtaEngine
{
	static final int INVENTORY_SLOT_CAPACITY = 28;
	static final int NO_GATHERING_HORIZON = -1;

	enum Disposition
	{
		ACTIVE,
		COMPLETED,
		CANCELLED,
		IGNORED
	}

	private ModelledRun modelledRun;
	private ObservedRun observedRun;
	private TaskEtaSnapshot snapshot = TaskEtaSnapshot.inactive();

	Disposition onWoodcuttingLog(WoodcuttingCatalog.Tree tree,
		WoodcuttingCatalog.AxeTier axeTier, int effectiveLevel, int occupiedSlots,
		int producedSlots, boolean eligible, int horizonTicks, int tick)
	{
		if (!eligible || tree == null || axeTier == null || producedSlots <= 0
			|| !validOccupiedSlots(occupiedSlots) || !validHorizon(horizonTicks))
		{
			return cancelUpdate();
		}
		GatheringProfile profile = WoodcuttingCatalog.profile(tree, axeTier);
		int freeSlots = INVENTORY_SLOT_CAPACITY - occupiedSlots;
		if (freeSlots <= 0)
		{
			return completeUpdate();
		}
		if (modelledRun == null)
		{
			int initialFreeSlots = freeSlots + producedSlots;
			if (initialFreeSlots > INVENTORY_SLOT_CAPACITY)
			{
				return cancelUpdate();
			}
			startModelled(new ModelledRun(profile, effectiveLevel, initialFreeSlots,
				freeSlots, horizonTicks, tick));
			return Disposition.ACTIVE;
		}
		if (!modelledRun.matches(profile, effectiveLevel)
			|| freeSlots >= modelledRun.remainingFreeSlots)
		{
			return cancelUpdate();
		}
		modelledRun = modelledRun.confirm(freeSlots, horizonTicks, tick);
		snapshot = modelledRun.snapshotAt(tick);
		return Disposition.ACTIVE;
	}

	Disposition onWoodcuttingStorageStart(WoodcuttingCatalog.Tree tree,
		WoodcuttingCatalog.AxeTier axeTier, int effectiveLevel, int occupiedSlots,
		int storageCapacity, boolean eligible, int horizonTicks, int tick)
	{
		if (!eligible || tree == null || axeTier == null || storageCapacity <= 0
			|| !validOccupiedSlots(occupiedSlots) || !validHorizon(horizonTicks))
		{
			return cancelUpdate();
		}
		int totalFreeSlots = INVENTORY_SLOT_CAPACITY - occupiedSlots + storageCapacity;
		if (totalFreeSlots <= 0)
		{
			return completeUpdate();
		}
		GatheringProfile profile = WoodcuttingCatalog.profile(tree, axeTier);
		if (modelledRun != null && modelledRun.matches(profile, effectiveLevel)
			&& modelledRun.remainingFreeSlots == totalFreeSlots)
		{
			snapshot = modelledRun.snapshotAt(tick);
			return Disposition.ACTIVE;
		}
		startModelled(new ModelledRun(profile, effectiveLevel, totalFreeSlots,
			totalFreeSlots, horizonTicks, tick));
		return Disposition.ACTIVE;
	}

	Disposition onConventionalFishingBarrelStart(GatheringProfile profile,
		int effectiveLevel, int ordinaryFreeSlots, double yieldMultiplier,
		boolean eligible, int horizonTicks, int tick)
	{
		if (!eligible || !FishingCatalog.isConventionalV1Profile(profile)
			|| effectiveLevel < profile.getRequiredLevel()
			|| ordinaryFreeSlots < 0 || ordinaryFreeSlots > INVENTORY_SLOT_CAPACITY
			|| !validYieldMultiplier(yieldMultiplier)
			|| !validFishingHorizon(horizonTicks))
		{
			return cancelUpdate();
		}
		int totalFreeSlots = ordinaryFreeSlots + INVENTORY_SLOT_CAPACITY;
		if (modelledRun != null
			&& modelledRun.matches(profile, effectiveLevel, yieldMultiplier)
			&& modelledRun.initialFreeSlots == totalFreeSlots)
		{
			snapshot = modelledRun.snapshotAt(tick);
			return Disposition.ACTIVE;
		}
		startModelled(new ModelledRun(profile, effectiveLevel, totalFreeSlots,
			totalFreeSlots, horizonTicks, tick, yieldMultiplier));
		return Disposition.ACTIVE;
	}

	Disposition onConventionalFishingCatch(GatheringProfile profile, int effectiveLevel,
		int occupiedSlots, int producedSlots, double yieldMultiplier,
		boolean eligible, int horizonTicks, int tick)
	{
		if (!eligible || !FishingCatalog.isConventionalV1Profile(profile)
			|| effectiveLevel < profile.getRequiredLevel() || !validOccupiedSlots(occupiedSlots)
			|| producedSlots < 1 || producedSlots > 2 || !validYieldMultiplier(yieldMultiplier)
			|| (producedSlots > 1 && yieldMultiplier <= 1d)
			|| !validFishingHorizon(horizonTicks))
		{
			return cancelUpdate();
		}
		int freeSlots = INVENTORY_SLOT_CAPACITY - occupiedSlots;
		if (freeSlots <= 0)
		{
			return completeUpdate();
		}
		if (modelledRun == null)
		{
			int initialFreeSlots = freeSlots + producedSlots;
			if (initialFreeSlots > INVENTORY_SLOT_CAPACITY)
			{
				return cancelUpdate();
			}
			startModelled(new ModelledRun(profile, effectiveLevel, initialFreeSlots,
				freeSlots, horizonTicks, tick, yieldMultiplier));
			return Disposition.ACTIVE;
		}
		if (!modelledRun.matches(profile, effectiveLevel, yieldMultiplier)
			|| freeSlots >= modelledRun.remainingFreeSlots)
		{
			return cancelUpdate();
		}
		modelledRun = modelledRun.confirm(freeSlots, horizonTicks, tick);
		snapshot = modelledRun.snapshotAt(tick);
		return Disposition.ACTIVE;
	}

	Disposition onKarambwanAttempt(int effectiveLevel, int occupiedSlots,
		int remainingAttempts, boolean caught, boolean eligible, int tick)
	{
		if (!eligible || !validOccupiedSlots(occupiedSlots) || remainingAttempts < 0)
		{
			return cancelUpdate();
		}
		int freeSlots = INVENTORY_SLOT_CAPACITY - occupiedSlots;
		if (freeSlots <= 0)
		{
			return completeUpdate();
		}
		GatheringProfile profile = FishingCatalog.karambwanVesselProfile();
		int horizonTicks = baitHorizonTicks(remainingAttempts);
		if (modelledRun == null)
		{
			int initialFreeSlots = freeSlots + (caught ? 1 : 0);
			if (initialFreeSlots > INVENTORY_SLOT_CAPACITY)
			{
				return cancelUpdate();
			}
			startModelled(new ModelledRun(profile, effectiveLevel, initialFreeSlots,
				freeSlots, horizonTicks, tick));
			return Disposition.ACTIVE;
		}
		if (!modelledRun.matches(profile, effectiveLevel)
			|| freeSlots > modelledRun.remainingFreeSlots)
		{
			return cancelUpdate();
		}
		modelledRun = modelledRun.confirm(freeSlots, horizonTicks, tick);
		snapshot = modelledRun.snapshotAt(tick);
		return Disposition.ACTIVE;
	}

	Disposition onKarambwanBarrelAttempt(int effectiveLevel, int ordinaryFreeSlots,
		int remainingAttempts, double yieldMultiplier, boolean eligible, int tick)
	{
		if (!eligible || ordinaryFreeSlots < 0 || ordinaryFreeSlots > INVENTORY_SLOT_CAPACITY
			|| remainingAttempts < 0 || !validYieldMultiplier(yieldMultiplier))
		{
			return cancelUpdate();
		}
		int totalFreeSlots = ordinaryFreeSlots + INVENTORY_SLOT_CAPACITY;
		GatheringProfile profile = FishingCatalog.karambwanVesselProfile();
		if (modelledRun != null
			&& modelledRun.matches(profile, effectiveLevel, yieldMultiplier)
			&& modelledRun.initialFreeSlots == totalFreeSlots)
		{
			snapshot = modelledRun.snapshotAt(tick);
			return Disposition.ACTIVE;
		}
		startModelled(new ModelledRun(profile, effectiveLevel, totalFreeSlots,
			totalFreeSlots, baitHorizonTicks(remainingAttempts), tick, yieldMultiplier));
		return Disposition.ACTIVE;
	}

	Disposition startObserved(String label, int occupiedSlots, boolean eligible, int tick)
	{
		if (!eligible || label == null || label.trim().isEmpty()
			|| occupiedSlots < 0 || occupiedSlots >= INVENTORY_SLOT_CAPACITY)
		{
			return Disposition.IGNORED;
		}
		int freeSlots = INVENTORY_SLOT_CAPACITY - occupiedSlots;
		if (observedRun != null && observedRun.matches(label))
		{
			snapshot = observedRun.snapshotAt(tick);
			return Disposition.ACTIVE;
		}
		modelledRun = null;
		observedRun = new ObservedRun(label.trim(), freeSlots, tick);
		snapshot = observedRun.snapshotAt(tick);
		return Disposition.ACTIVE;
	}

	Disposition onObservedYield(String label, int occupiedSlots, int producedSlots,
		boolean eligible, int tick)
	{
		if (!eligible || label == null || label.trim().isEmpty()
			|| !validOccupiedSlots(occupiedSlots) || producedSlots <= 0)
		{
			return cancelUpdate();
		}
		int freeSlots = INVENTORY_SLOT_CAPACITY - occupiedSlots;
		if (freeSlots <= 0)
		{
			return completeUpdate();
		}
		if (observedRun == null)
		{
			int initialFreeSlots = freeSlots + producedSlots;
			if (initialFreeSlots > INVENTORY_SLOT_CAPACITY)
			{
				return cancelUpdate();
			}
			modelledRun = null;
			observedRun = new ObservedRun(label.trim(), initialFreeSlots, tick)
				.withRemaining(freeSlots);
			snapshot = observedRun.snapshotAt(tick);
			return Disposition.ACTIVE;
		}
		if (!observedRun.matches(label)
			|| observedRun.remainingFreeSlots - freeSlots != producedSlots)
		{
			return cancelUpdate();
		}
		observedRun = observedRun.confirm(freeSlots, producedSlots, tick);
		snapshot = observedRun.snapshotAt(tick);
		return Disposition.ACTIVE;
	}

	@Override
	public void onGameTick(int tick)
	{
		if (modelledRun != null)
		{
			snapshot = modelledRun.snapshotAt(tick);
		}
		else if (observedRun != null)
		{
			snapshot = observedRun.snapshotAt(tick);
		}
	}

	@Override
	public void cancel()
	{
		modelledRun = null;
		observedRun = null;
		snapshot = TaskEtaSnapshot.inactive();
	}

	@Override
	public boolean isActive()
	{
		return modelledRun != null || observedRun != null;
	}

	@Override
	public TaskEtaSnapshot snapshot()
	{
		return snapshot;
	}

	private void startModelled(ModelledRun run)
	{
		modelledRun = run;
		observedRun = null;
		snapshot = run.snapshotAt(run.lastConfirmationTick);
	}

	private Disposition cancelUpdate()
	{
		cancel();
		return Disposition.CANCELLED;
	}

	private Disposition completeUpdate()
	{
		cancel();
		return Disposition.COMPLETED;
	}

	private static boolean validOccupiedSlots(int occupiedSlots)
	{
		return occupiedSlots >= 0 && occupiedSlots <= INVENTORY_SLOT_CAPACITY;
	}

	private static boolean validHorizon(int ticks)
	{
		return ticks == NO_GATHERING_HORIZON || ticks >= 0;
	}

	private static boolean validFishingHorizon(int ticks)
	{
		return ticks == FishingCatalog.NO_SPOT_MOVEMENT_HORIZON
			|| (ticks >= 0 && ticks <= FishingCatalog.ORDINARY_SPOT_EARLIEST_MOVE_TICKS);
	}

	private static boolean validYieldMultiplier(double multiplier)
	{
		return Double.isFinite(multiplier) && multiplier >= 1d;
	}

	private static int baitHorizonTicks(int remainingAttempts)
	{
		long ticks = (long) remainingAttempts * FishingCatalog.KARAMBWAN_ROLL_TICKS;
		return ticks >= Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) ticks;
	}

	private static final class ObservedRun implements EtaRun
	{
		private static final int REQUIRED_INTERVALS = 3;
		private static final int MAX_INTERVALS = 7;
		private final String label;
		private final int initialFreeSlots;
		private final int remainingFreeSlots;
		private final int lastConfirmationTick;
		private final List<Double> observedTicksPerSlot;

		private ObservedRun(String label, int initialFreeSlots, int tick)
		{
			this(label, initialFreeSlots, initialFreeSlots, tick, Collections.emptyList());
		}

		private ObservedRun(String label, int initialFreeSlots, int remainingFreeSlots,
			int lastConfirmationTick, List<Double> observedTicksPerSlot)
		{
			this.label = label;
			this.initialFreeSlots = initialFreeSlots;
			this.remainingFreeSlots = remainingFreeSlots;
			this.lastConfirmationTick = lastConfirmationTick;
			this.observedTicksPerSlot = Collections.unmodifiableList(
				new ArrayList<>(observedTicksPerSlot));
		}

		private boolean matches(String otherLabel)
		{
			return otherLabel != null && label.equals(otherLabel.trim());
		}

		private ObservedRun withRemaining(int freeSlots)
		{
			return new ObservedRun(label, initialFreeSlots, freeSlots,
				lastConfirmationTick, observedTicksPerSlot);
		}

		private ObservedRun confirm(int freeSlots, int producedSlots, int tick)
		{
			List<Double> nextObserved = new ArrayList<>(observedTicksPerSlot);
			int intervalTicks = tick - lastConfirmationTick;
			if (intervalTicks > 0)
			{
				nextObserved.add(intervalTicks / (double) producedSlots);
				if (nextObserved.size() > MAX_INTERVALS)
				{
					nextObserved.remove(0);
				}
			}
			return new ObservedRun(label, initialFreeSlots, freeSlots, tick, nextObserved);
		}

		@Override
		public TaskEtaSnapshot snapshotAt(int tick)
		{
			if (observedTicksPerSlot.size() < REQUIRED_INTERVALS)
			{
				return TaskEtaSnapshot.calibratingGathering(label, initialFreeSlots,
					remainingFreeSlots, observedTicksPerSlot.size(), REQUIRED_INTERVALS);
			}
			List<Double> sorted = new ArrayList<>(observedTicksPerSlot);
			Collections.sort(sorted);
			double median = median(sorted);
			int elapsed = Math.max(0, tick - lastConfirmationTick);
			int remainingTicks = Math.max(0,
				boundedCeil(remainingFreeSlots * median) - elapsed);
			int lowerTicks = Math.max(0,
				boundedCeil(remainingFreeSlots * sorted.get(0)) - elapsed);
			int upperTicks = Math.max(lowerTicks,
				boundedCeil(remainingFreeSlots * sorted.get(sorted.size() - 1)) - elapsed);
			int totalTicks = boundedCeil(initialFreeSlots * median);
			return TaskEtaSnapshot.gathering(label, initialFreeSlots, remainingFreeSlots,
				remainingTicks, totalTicks, lowerTicks, upperTicks, TaskEtaSnapshot.Confidence.HIGH);
		}

		private static double median(List<Double> sorted)
		{
			int middle = sorted.size() / 2;
			return sorted.size() % 2 == 1 ? sorted.get(middle)
				: (sorted.get(middle - 1) + sorted.get(middle)) / 2d;
		}
	}

	private static final class ModelledRun implements EtaRun
	{
		private static final int REQUIRED_LOCAL_INTERVALS = 3;
		private static final int MAX_LOCAL_INTERVALS = 7;
		private final GatheringProfile profile;
		private final int effectiveLevel;
		private final int initialFreeSlots;
		private final int remainingFreeSlots;
		private final int horizonDeadlineTick;
		private final int lastConfirmationTick;
		private final int initialTotalTicks;
		private final double capacityYieldMultiplier;
		private final List<Double> observedTicksPerSlot;

		private ModelledRun(GatheringProfile profile, int effectiveLevel, int initialFreeSlots,
			int remainingFreeSlots, int remainingHorizonTicks, int tick)
		{
			this(profile, effectiveLevel, initialFreeSlots, remainingFreeSlots,
				remainingHorizonTicks, tick, NO_GATHERING_HORIZON, 1d, Collections.emptyList());
		}

		private ModelledRun(GatheringProfile profile, int effectiveLevel, int initialFreeSlots,
			int remainingFreeSlots, int remainingHorizonTicks, int tick, double yieldMultiplier)
		{
			this(profile, effectiveLevel, initialFreeSlots, remainingFreeSlots,
				remainingHorizonTicks, tick, NO_GATHERING_HORIZON, yieldMultiplier,
				Collections.emptyList());
		}

		private ModelledRun(GatheringProfile profile, int effectiveLevel, int initialFreeSlots,
			int remainingFreeSlots, int remainingHorizonTicks, int tick,
			int preservedInitialTotalTicks, double yieldMultiplier,
			List<Double> observedTicksPerSlot)
		{
			this.profile = profile;
			this.effectiveLevel = effectiveLevel;
			this.initialFreeSlots = initialFreeSlots;
			this.remainingFreeSlots = remainingFreeSlots;
			this.horizonDeadlineTick = deadline(tick, remainingHorizonTicks);
			this.lastConfirmationTick = tick;
			this.capacityYieldMultiplier = yieldMultiplier;
			this.observedTicksPerSlot = Collections.unmodifiableList(
				new ArrayList<>(observedTicksPerSlot));
			this.initialTotalTicks = preservedInitialTotalTicks == NO_GATHERING_HORIZON
				? Math.min(expectedTicks(initialFreeSlots), initialHorizonTicks())
				: preservedInitialTotalTicks;
		}

		private boolean matches(GatheringProfile otherProfile, int otherLevel)
		{
			return profile == otherProfile && effectiveLevel == otherLevel;
		}

		private boolean matches(GatheringProfile otherProfile, int otherLevel,
			double otherYieldMultiplier)
		{
			return matches(otherProfile, otherLevel)
				&& Double.compare(capacityYieldMultiplier, otherYieldMultiplier) == 0;
		}

		private ModelledRun confirm(int freeSlots, int remainingHorizonTicks, int tick)
		{
			List<Double> nextObserved = new ArrayList<>(observedTicksPerSlot);
			int producedSlots = remainingFreeSlots - freeSlots;
			int intervalTicks = tick - lastConfirmationTick;
			if (producedSlots > 0 && intervalTicks > 0)
			{
				nextObserved.add(intervalTicks / (double) producedSlots);
				if (nextObserved.size() > MAX_LOCAL_INTERVALS)
				{
					nextObserved.remove(0);
				}
			}
			return new ModelledRun(profile, effectiveLevel, initialFreeSlots, freeSlots,
				mergeRemainingHorizon(remainingHorizonTicks, tick), tick, initialTotalTicks,
				capacityYieldMultiplier, nextObserved);
		}

		@Override
		public TaskEtaSnapshot snapshotAt(int tick)
		{
			int elapsed = Math.max(0, tick - lastConfirmationTick);
			int inventoryTicks = Math.max(0, expectedTicks(remainingFreeSlots) - elapsed);
			int[] inventoryRange = expectedTickRange(remainingFreeSlots);
			int lowerInventoryTicks = Math.max(0, inventoryRange[0] - elapsed);
			int upperInventoryTicks = Math.max(lowerInventoryTicks, inventoryRange[1] - elapsed);
			int horizonTicks = remainingHorizonAt(tick);
			return TaskEtaSnapshot.gathering(profile.getLabel(), initialFreeSlots,
				remainingFreeSlots, Math.min(inventoryTicks, horizonTicks), initialTotalTicks,
				Math.min(lowerInventoryTicks, horizonTicks),
				Math.min(upperInventoryTicks, horizonTicks),
				hasLocalRate() ? TaskEtaSnapshot.Confidence.HIGH : TaskEtaSnapshot.Confidence.MEDIUM);
		}

		private int expectedTicks(int freeSlots)
		{
			double expected = hasLocalRate() ? freeSlots * localMedianTicksPerSlot()
				: profile.expectedTicksToFill(freeSlots, effectiveLevel) / capacityYieldMultiplier;
			return expected >= Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) Math.ceil(expected);
		}

		private int[] expectedTickRange(int freeSlots)
		{
			if (hasLocalRate())
			{
				List<Double> sorted = new ArrayList<>(observedTicksPerSlot);
				Collections.sort(sorted);
				return new int[]{boundedCeil(freeSlots * sorted.get(0)),
					boundedCeil(freeSlots * sorted.get(sorted.size() - 1))};
			}
			double[] range = profile.expectedTickRangeToFill(freeSlots, effectiveLevel);
			return new int[]{boundedCeil(range[0] / capacityYieldMultiplier),
				boundedCeil(range[1] / capacityYieldMultiplier)};
		}

		private boolean hasLocalRate()
		{
			return observedTicksPerSlot.size() >= REQUIRED_LOCAL_INTERVALS;
		}

		private double localMedianTicksPerSlot()
		{
			List<Double> sorted = new ArrayList<>(observedTicksPerSlot);
			Collections.sort(sorted);
			int middle = sorted.size() / 2;
			return sorted.size() % 2 == 1 ? sorted.get(middle)
				: (sorted.get(middle - 1) + sorted.get(middle)) / 2d;
		}

		private int remainingHorizonAt(int tick)
		{
			return horizonDeadlineTick == Integer.MAX_VALUE ? Integer.MAX_VALUE
				: Math.max(0, horizonDeadlineTick - tick);
		}

		private int initialHorizonTicks()
		{
			return horizonDeadlineTick == Integer.MAX_VALUE ? Integer.MAX_VALUE
				: Math.max(0, horizonDeadlineTick - lastConfirmationTick);
		}

		private int mergeRemainingHorizon(int callerTicks, int tick)
		{
			int existing = remainingHorizonAt(tick);
			if (callerTicks == NO_GATHERING_HORIZON)
			{
				return existing == Integer.MAX_VALUE ? NO_GATHERING_HORIZON : existing;
			}
			return Math.min(existing, callerTicks);
		}

		private static int deadline(int tick, int remainingTicks)
		{
			if (remainingTicks == NO_GATHERING_HORIZON)
			{
				return Integer.MAX_VALUE;
			}
			long deadline = (long) tick + remainingTicks;
			return deadline >= Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) deadline;
		}
	}

	private static int boundedCeil(double value)
	{
		return !Double.isFinite(value) || value >= Integer.MAX_VALUE
			? Integer.MAX_VALUE : (int) Math.ceil(Math.max(0d, value));
	}
}

package com.idlefamiliar;

import java.awt.image.BufferedImage;
import java.util.Arrays;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;

/** Immutable inventory copy built on the client thread and painted by Swing. */
public final class InventorySnapshot
{
	public static final int COLUMNS = 4;
	public static final int ROWS = 7;
	public static final int SLOT_COUNT = COLUMNS * ROWS;

	private static final InventorySnapshot EMPTY = new InventorySnapshot(emptySlots());

	private final Slot[] slots;

	private InventorySnapshot(Slot[] slots)
	{
		this.slots = slots;
	}

	public static InventorySnapshot empty()
	{
		return EMPTY;
	}

	/**
	 * Capture the native 4x7 inventory layout on the client thread. Existing
	 * item-icon references are retained for unchanged item ids, avoiding 28 icon
	 * lookups on every game tick.
	 */
	static InventorySnapshot capture(ItemContainer inventory, InventorySnapshot previous,
		ItemManager itemManager)
	{
		InventorySnapshot prior = previous == null ? EMPTY : previous;
		Slot[] next = new Slot[SLOT_COUNT];
		Item[] items = inventory == null ? null : inventory.getItems();
		boolean unchanged = true;
		for (int index = 0; index < SLOT_COUNT; index++)
		{
			Item item = items != null && index < items.length ? items[index] : null;
			int itemId = item == null ? -1 : item.getId();
			int quantity = item == null || itemId < 0 ? 0 : Math.max(0, item.getQuantity());
			if (itemId < 0 || quantity <= 0)
			{
				itemId = -1;
				quantity = 0;
			}

			Slot before = prior.slots[index];
			if (before.itemId == itemId && before.quantity == quantity)
			{
				next[index] = before;
				continue;
			}

			unchanged = false;
			// Quantity-only changes are common for stackable items. The icon is tied
			// to the item id, so retain it instead of asking ItemManager to resolve the
			// same image again on every quantity update.
			BufferedImage image = itemId < 0 ? null
				: before.itemId == itemId && before.image != null ? before.image
				: itemManager == null ? null : itemManager.getImage(itemId);
			next[index] = new Slot(itemId, quantity, image);
		}
		return unchanged ? prior : new InventorySnapshot(next);
	}

	public Slot getSlot(int index)
	{
		if (index < 0 || index >= SLOT_COUNT)
		{
			throw new IndexOutOfBoundsException("Inventory slot " + index);
		}
		return slots[index];
	}

	private static Slot[] emptySlots()
	{
		Slot[] empty = new Slot[SLOT_COUNT];
		Arrays.fill(empty, Slot.EMPTY);
		return empty;
	}

	/** One visible inventory slot; item images are read-only after lookup. */
	public static final class Slot
	{
		private static final Slot EMPTY = new Slot(-1, 0, null);

		private final int itemId;
		private final int quantity;
		private final BufferedImage image;

		private Slot(int itemId, int quantity, BufferedImage image)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.image = image;
		}

		public boolean isEmpty()
		{
			return itemId < 0 || quantity <= 0;
		}

		public int getItemId()
		{
			return itemId;
		}

		public int getQuantity()
		{
			return quantity;
		}

		public BufferedImage getImage()
		{
			return image;
		}
	}
}

package com.idlefamiliar;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

/**
 * Owns the detached window, RuneLite sidebar and toolbar-button lifecycle.
 * Gameplay and EventBus concerns stay in {@link IdleFamiliarPlugin}; this class
 * only translates presentation configuration into Swing view operations.
 */
final class DesktopUiCoordinator
{
	private final WidgetContentSource contentSource;
	private final IdleFamiliarConfig config;
	private final ConfigManager configManager;
	private final ClientToolbar clientToolbar;

	private DesktopPetWindow desktopWindow;
	private IdleFamiliarPanel sidebarPanel;
	private NavigationButton navigationButton;

	DesktopUiCoordinator(WidgetContentSource contentSource, IdleFamiliarConfig config,
		ConfigManager configManager, ClientToolbar clientToolbar)
	{
		this.contentSource = contentSource;
		this.config = config;
		this.configManager = configManager;
		this.clientToolbar = clientToolbar;
	}

	/** Construct and register both views. Visibility is enabled after session state is reset. */
	void start()
	{
		if (navigationButton != null)
		{
			return;
		}

		desktopWindow = new DesktopPetWindow(contentSource, config, configManager);
		sidebarPanel = new IdleFamiliarPanel(contentSource, config, configManager);
		navigationButton = NavigationButton.builder()
			.tooltip("Idle Familiar")
			.icon(ImageUtil.loadImageResource(IdleFamiliarPlugin.class, "/icon.png"))
			.priority(6)
			.panel(sidebarPanel)
			.build();
		clientToolbar.addNavigation(navigationButton);
	}

	void stop()
	{
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
			navigationButton = null;
		}
		if (sidebarPanel != null)
		{
			sidebarPanel.shutDown();
			sidebarPanel = null;
		}
		if (desktopWindow != null)
		{
			desktopWindow.hide();
			desktopWindow = null;
		}
	}

	void refreshVisibility()
	{
		if (desktopWindow != null)
		{
			desktopWindow.refreshVisibility();
		}
	}

	void resetPosition()
	{
		if (desktopWindow != null)
		{
			desktopWindow.resetPosition();
		}
	}

	void moveToPointerDisplay()
	{
		if (desktopWindow != null)
		{
			desktopWindow.moveToPointerDisplay();
		}
	}

	/** Apply one ordinary presentation config event, preserving the existing event order. */
	void onConfigChanged(String key, String newValue)
	{
		if (desktopWindow != null)
		{
			if ("widgetTheme".equals(key))
			{
				desktopWindow.applyTheme(newValue);
			}
			else if ("avatarScale".equals(key))
			{
				desktopWindow.applyScale(newValue);
			}
			else if ("widgetCollapsed".equals(key))
			{
				desktopWindow.applyCollapsed(newValue);
				if (sidebarPanel != null)
				{
					sidebarPanel.applyCollapsed(newValue);
				}
			}
			else if (("widgetAnchor".equals(key) || "widgetSafeMargin".equals(key))
				&& !desktopWindow.isWritingPositionConfiguration())
			{
				desktopWindow.applySelectedAnchor();
			}
			desktopWindow.refreshVisibility();
		}
		if (sidebarPanel != null)
		{
			sidebarPanel.scheduleRefresh();
		}
	}

	/** Apply view state that must be synchronized after a preset's bulk writes. */
	void refreshAfterPreset(DisplayPreset preset)
	{
		if (desktopWindow == null || preset == null)
		{
			return;
		}
		Object presetTheme = preset.settings().get("widgetTheme");
		if (presetTheme instanceof WidgetTheme)
		{
			desktopWindow.applyTheme(((WidgetTheme) presetTheme).name());
		}
		Object collapsed = preset.settings().get("widgetCollapsed");
		if (collapsed != null)
		{
			desktopWindow.applyCollapsed(String.valueOf(collapsed));
		}
		Object scale = preset.settings().get("avatarScale");
		if (scale instanceof AvatarScale)
		{
			desktopWindow.applyScale(((AvatarScale) scale).name());
		}
		desktopWindow.refreshVisibility();
		if (sidebarPanel != null)
		{
			sidebarPanel.scheduleRefresh();
		}
	}
}

package com.idlefamiliar;

import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import java.util.Objects;

/**
 * Prevents a semantic game-event cue and the immediately-following animation
 * start cue from double-playing for the same action.
 */
public class SoundCueGate
{
	private final Map<String, Integer> suppressedAnimationStarts = new HashMap<>();
	private String lastAnimationKey;

	/** Claim a semantic animation transition exactly once per resolved asset key. */
	public boolean claimAnimationStart(String animationKey)
	{
		if (Objects.equals(animationKey, lastAnimationKey))
		{
			return false;
		}
		lastAnimationKey = animationKey;
		return true;
	}

	public void suppressAnimationStart(String animationKey, int currentTick, int ttlTicks)
	{
		if (animationKey == null || animationKey.isEmpty())
		{
			return;
		}
		suppressedAnimationStarts.put(animationKey, currentTick + Math.max(0, ttlTicks));
	}

	public boolean consumeSuppressedAnimationStart(String animationKey, int currentTick)
	{
		pruneExpired(currentTick);
		Integer suppressUntilTick = suppressedAnimationStarts.get(animationKey);
		if (suppressUntilTick == null)
		{
			return false;
		}
		suppressedAnimationStarts.remove(animationKey);
		return true;
	}

	public void reset()
	{
		suppressedAnimationStarts.clear();
		lastAnimationKey = null;
	}

	private void pruneExpired(int currentTick)
	{
		Iterator<Map.Entry<String, Integer>> iterator = suppressedAnimationStarts.entrySet().iterator();
		while (iterator.hasNext())
		{
			if (currentTick > iterator.next().getValue())
			{
				iterator.remove();
			}
		}
	}
}

