package com.idlefamiliar;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Immutable client-free mechanics for one gathering target and tool. */
final class GatheringProfile
{
	enum YieldMode
	{
		/** One output roll, yielding at most one inventory slot. */
		SINGLE,
		/** Ordered rolls stop at the first success, yielding at most one slot. */
		CASCADE,
		/** Every roll is independent and may fill more than one slot. */
		INDEPENDENT
	}

	private final String key;
	private final String label;
	private final int requiredLevel;
	private final int rollTicks;
	private final int activeSpotTicks;
	private final int respawnTicks;
	private final YieldMode yieldMode;
	private final List<OutcomeRoll> outcomeRolls;

	GatheringProfile(String key, String label, int requiredLevel, int rollTicks,
		int activeSpotTicks, int respawnTicks, YieldMode yieldMode,
		List<OutcomeRoll> outcomeRolls)
	{
		if (key == null || key.isEmpty() || label == null || label.isEmpty())
		{
			throw new IllegalArgumentException("A gathering profile needs a key and label");
		}
		if (requiredLevel < GatheringSuccessChance.MIN_LEVEL || rollTicks <= 0
			|| activeSpotTicks < 0 || respawnTicks < 0 || yieldMode == null
			|| outcomeRolls == null || outcomeRolls.isEmpty())
		{
			throw new IllegalArgumentException("Invalid gathering profile mechanics");
		}

		this.key = key;
		this.label = label;
		this.requiredLevel = requiredLevel;
		this.rollTicks = rollTicks;
		this.activeSpotTicks = activeSpotTicks;
		this.respawnTicks = respawnTicks;
		this.yieldMode = yieldMode;
		this.outcomeRolls = Collections.unmodifiableList(new ArrayList<>(outcomeRolls));
	}

	String getKey()
	{
		return key;
	}

	String getLabel()
	{
		return label;
	}

	int getRequiredLevel()
	{
		return requiredLevel;
	}

	int getRollTicks()
	{
		return rollTicks;
	}

	int getActiveSpotTicks()
	{
		return activeSpotTicks;
	}

	int getRespawnTicks()
	{
		return respawnTicks;
	}

	YieldMode getYieldMode()
	{
		return yieldMode;
	}

	List<OutcomeRoll> getOutcomeRolls()
	{
		return outcomeRolls;
	}

	/** Expected inventory slots produced by one native action roll. */
	double expectedSlotsPerRollAt(int effectiveLevel)
	{
		switch (yieldMode)
		{
			case SINGLE:
				return outcomeRolls.get(0).successChanceAt(effectiveLevel);
			case CASCADE:
				double allFailed = 1d;
				for (OutcomeRoll outcomeRoll : outcomeRolls)
				{
					allFailed *= 1d - outcomeRoll.successChanceAt(effectiveLevel);
				}
				return 1d - allFailed;
			case INDEPENDENT:
				double expectedSlots = 0d;
				for (OutcomeRoll outcomeRoll : outcomeRolls)
				{
					expectedSlots += outcomeRoll.successChanceAt(effectiveLevel);
				}
				return expectedSlots;
			default:
				throw new IllegalStateException("Unhandled yield mode: " + yieldMode);
		}
	}

	/** Expected native game ticks until the supplied inventory capacity is filled. */
	double expectedTicksToFill(int freeInventorySlots, int effectiveLevel)
	{
		if (freeInventorySlots < 0)
		{
			throw new IllegalArgumentException("Free inventory slots cannot be negative");
		}
		if (freeInventorySlots == 0)
		{
			return 0d;
		}

		double slotsPerRoll = expectedSlotsPerRollAt(effectiveLevel);
		return slotsPerRoll == 0d ? Double.POSITIVE_INFINITY
			: freeInventorySlots * rollTicks / slotsPerRoll;
	}

	/**
	 * Approximate 90% completion interval from the reviewed per-roll outcome
	 * probabilities. This is presentation uncertainty, not a guarantee: local
	 * samples may still be interrupted by movement or resource depletion.
	 */
	double[] expectedTickRangeToFill(int freeInventorySlots, int effectiveLevel)
	{
		if (freeInventorySlots < 0)
		{
			throw new IllegalArgumentException("Free inventory slots cannot be negative");
		}
		if (freeInventorySlots == 0)
		{
			return new double[]{0d, 0d};
		}

		double meanSlots = expectedSlotsPerRollAt(effectiveLevel);
		if (meanSlots <= 0d)
		{
			return new double[]{Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY};
		}
		double varianceSlots;
		if (yieldMode == YieldMode.INDEPENDENT)
		{
			varianceSlots = 0d;
			for (OutcomeRoll outcomeRoll : outcomeRolls)
			{
				double probability = outcomeRoll.successChanceAt(effectiveLevel);
				varianceSlots += probability * (1d - probability);
			}
		}
		else
		{
			varianceSlots = meanSlots * (1d - meanSlots);
		}

		double meanRolls = freeInventorySlots / meanSlots;
		// Renewal-process approximation. For a Bernoulli yield this reduces to
		// the exact negative-binomial standard deviation sqrt(n(1-p))/p.
		double standardDeviationRolls = Math.sqrt(
			freeInventorySlots * varianceSlots / (meanSlots * meanSlots * meanSlots));
		double z90 = 1.645d;
		double lowerRolls = Math.max(1d, meanRolls - z90 * standardDeviationRolls);
		double upperRolls = Math.max(lowerRolls, meanRolls + z90 * standardDeviationRolls);
		return new double[]{lowerRolls * rollTicks, upperRolls * rollTicks};
	}
}

package com.idlefamiliar;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Random;

/** Picks sprite variants by positive integer weight. */
public class WeightedVariantPicker
{
	private final List<String> names;
	private final int[] cumulativeWeights;
	private final int totalWeight;
	private final Random random;

	/**
	 * @param weightMap insertion-ordered map of variant name &rarr; weight
	 * @param random    random source (injectable for deterministic tests)
	 */
	public WeightedVariantPicker(Map<String, Integer> weightMap, Random random)
	{
		if (weightMap == null || weightMap.isEmpty())
		{
			throw new IllegalArgumentException("weightMap must contain at least one variant");
		}
		this.random = random;
		this.names = new ArrayList<>(weightMap.size());
		this.cumulativeWeights = new int[weightMap.size()];

		int cumulative = 0;
		int index = 0;
		for (Map.Entry<String, Integer> entry : weightMap.entrySet())
		{
			int weight = Math.max(0, entry.getValue() == null ? 0 : entry.getValue());
			cumulative += weight;
			names.add(entry.getKey());
			cumulativeWeights[index++] = cumulative;
		}
		this.totalWeight = cumulative;
	}

	/** @return a variant name chosen proportionally to its weight. */
	public String pick()
	{
		if (names.size() == 1 || totalWeight <= 0)
		{
			return names.get(0);
		}

		int roll = random.nextInt(totalWeight);
		for (int i = 0; i < cumulativeWeights.length; i++)
		{
			if (roll < cumulativeWeights[i])
			{
				return names.get(i);
			}
		}
		return names.get(names.size() - 1); // unreachable in practice
	}

	/** @return the number of variants this picker chooses among. */
	public int variantCount()
	{
		return names.size();
	}

	/** @return the variant names this picker can choose from, in discovery order. */
	List<String> variantNames()
	{
		return Collections.unmodifiableList(names);
	}
}

package com.idlefamiliar;

import java.util.EnumSet;

/**
 * One-shot gate for the optional RuneLite notifier bridge. A reason is routed
 * at most once until every attention latch clears, and enabling the option
 * while a reason is already active never emits a delayed surprise alert.
 */
final class AttentionNotificationGate
{
	private final EnumSet<AttentionReason> observed = EnumSet.noneOf(AttentionReason.class);

	String update(AttentionReason reason, boolean enabled)
	{
		AttentionReason safeReason = reason == null ? AttentionReason.NONE : reason;
		if (!safeReason.isActive())
		{
			observed.clear();
			return null;
		}

		boolean firstObservation = observed.add(safeReason);
		return enabled && firstObservation
			? "Idle Familiar: " + safeReason.getDisplayText() : null;
	}

	void reset()
	{
		observed.clear();
	}
}

package com.idlefamiliar;

final class SoundActivation
{
	private SoundActivation()
	{
	}

	static boolean chatMessage(IdleFamiliarConfig config)
	{
		return config.chatMessageSounds();
	}

	static boolean animationStart(IdleFamiliarConfig config, AvatarState state)
	{
		return avatarTrigger(config, state);
	}

	static boolean gameEvent(IdleFamiliarConfig config, GameSoundEvent event)
	{
		switch (event)
		{
			case INVENTORY_FULL:
				return config.inventoryFullSounds();
			case LOW_HEALTH:
				return config.lowHpSounds();
			case LOW_PRAYER:
				return config.lowPrayerSounds();
			case ETA_COMPLETE:
				return config.etaCompleteSounds();
			default:
				// No dedicated toggle for this event (e.g. combat / level-up / death):
				// sounds are opt-in, so an unconfigured event stays silent.
				return false;
		}
	}

	private static boolean avatarTrigger(IdleFamiliarConfig config, AvatarState state)
	{
		switch (state)
		{
			case PLAYER_IDLE:
				return config.idleSounds();
			case AFK_WARNING:
				return config.afkSounds();
			case INVENTORY_FULL:
				return config.inventoryFullSounds();
			case LOW_HEALTH:
				return config.lowHpSounds();
			case LOW_PRAYER:
				return config.lowPrayerSounds();
			case CUSTOM_EVENT:
				return config.chatMessageSounds();
			default:
				// No dedicated toggle for this state (e.g. combat / banking / level-up /
				// death / locomotion / teleport): sounds are opt-in, so it stays silent.
				return false;
		}
	}
}

package com.idlefamiliar;

/** Captured interaction or equipment evidence for resolving one queue. */
final class ProcessingContext
{
	enum Kind
	{
		NONE,
		FLETCHING_KNIFE,
		FORESTERS_CAMPFIRE,
		COOKING,
		ANVIL_SMITHING,
		FURNACE_SMELTING,
		FINISHED_POTION
	}

	private static final ProcessingContext NONE = new ProcessingContext(Kind.NONE, false, false);
	private final Kind kind;
	private final boolean offhandHammer;
	private final boolean fullSmithsUniform;

	private ProcessingContext(Kind kind, boolean offhandHammer, boolean fullSmithsUniform)
	{
		this.kind = kind == null ? Kind.NONE : kind;
		this.offhandHammer = offhandHammer;
		this.fullSmithsUniform = fullSmithsUniform;
	}

	static ProcessingContext none()
	{
		return NONE;
	}

	static ProcessingContext fletchingKnife()
	{
		return new ProcessingContext(Kind.FLETCHING_KNIFE, false, false);
	}

	static ProcessingContext forestersCampfire()
	{
		return new ProcessingContext(Kind.FORESTERS_CAMPFIRE, false, false);
	}

	static ProcessingContext cooking()
	{
		return new ProcessingContext(Kind.COOKING, false, false);
	}

	static ProcessingContext anvilSmithing(boolean offhandHammer, boolean fullSmithsUniform)
	{
		return new ProcessingContext(Kind.ANVIL_SMITHING, offhandHammer, fullSmithsUniform);
	}

	static ProcessingContext furnaceSmelting()
	{
		return new ProcessingContext(Kind.FURNACE_SMELTING, false, false);
	}

	/** Only use after equipment inspection has ruled out secondary-saving effects. */
	static ProcessingContext finishedPotionWithoutSavingEffect()
	{
		return new ProcessingContext(Kind.FINISHED_POTION, false, false);
	}

	Kind kind()
	{
		return kind;
	}

	boolean hasOffhandHammer()
	{
		return offhandHammer;
	}

	boolean hasFullSmithsUniform()
	{
		return fullSmithsUniform;
	}

	boolean sameAs(ProcessingContext other)
	{
		return other != null && kind == other.kind
			&& offhandHammer == other.offhandHammer
			&& fullSmithsUniform == other.fullSmithsUniform;
	}
}

