import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** Owns external avatar-folder setup, runtime reloads and asset validation. */
final class AvatarAssetManager
{
	private static final Logger log = LoggerFactory.getLogger(AvatarAssetManager.class);

	private final AnimationController animationController;
	private final File externalAvatarDirectory;
	private final Consumer<String> announcer;

	AvatarAssetManager(AnimationController animationController,
		File externalAvatarDirectory, Consumer<String> announcer)
	{
		this.animationController = animationController;
		this.externalAvatarDirectory = externalAvatarDirectory;
		this.announcer = announcer;
	}

	void initialize()
	{
		if (externalAvatarDirectory != null)
		{
			//noinspection ResultOfMethodCallIgnored
			externalAvatarDirectory.mkdirs();
		}
		animationController.setExternalAssetDir(externalAvatarDirectory);
		animationController.loadDefaultAnimations();
	}

	/** Reload every sheet and weights file, including external overrides. */
	void reload()
	{
		animationController.reloadAnimations();
		log.debug("Idle Familiar animations reloaded");
		announcer.accept("Idle Familiar: animations reloaded.");
	}

	/** Validate the external folder and announce one concise result in game chat. */
	List<String> validate()
	{
		List<String> issues = AvatarAssetValidator.validate(
			externalAvatarDirectory, knownAssetBases());
		if (issues.isEmpty())
		{
			log.debug("Idle Familiar animation validation: no issues");
			announcer.accept("Idle Familiar: animation validation found no issues.");
			return issues;
		}

		log.warn("Idle Familiar animation validation found {} issue(s):", issues.size());
		for (String issue : issues)
		{
			log.warn("  {}", issue);
		}
		announcer.accept("Idle Familiar: animation validation found "
			+ issues.size() + " issue(s) (see client log).");
		return issues;
	}

	Set<String> knownAssetBases()
	{
		Set<String> bases = new HashSet<>();
		for (AvatarState state : AvatarState.values())
		{
			addBase(bases, animationController.resolveAssetName(state, ""));
		}
		for (String style : new String[]{"melee", "ranged", "magic"})
		{
			addBase(bases, "combat_" + style);
		}
		for (Skill skill : Skill.values())
		{
			addBase(bases, skill.name().toLowerCase(Locale.ROOT).replace(' ', '_'));
		}
		return bases;
	}

	private static void addBase(Set<String> bases, String key)
	{
		bases.add(key);
		bases.add(key + "_loop");
	}
}

