package com.idlefamiliar;

import java.util.IdentityHashMap;
import java.util.Map;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.client.game.FishingSpot;

/** Tracks observed spot age; pre-login spots have no movement horizon. */
final class FishingSpotMovementTracker
{
	private static final int INFERNAL_EEL_EARLIEST_MOVE_TICKS = 100;
	private final Map<NPC, SpawnObservation> observations = new IdentityHashMap<>();

	void onSpawned(NPC npc, int tick)
	{
		if (npc == null)
		{
			return;
		}
		FishingSpot spot = FishingSpot.findSpot(npc.getId());
		if (spot != null)
		{
			observations.put(npc, new SpawnObservation(spot, tick));
		}
	}

	void onDespawned(NPC npc)
	{
		if (npc != null)
		{
			observations.remove(npc);
		}
	}

	int earliestMoveRemainingTicks(Actor interacting, GatheringProfile profile, int tick)
	{
		if (!(interacting instanceof NPC) || !FishingCatalog.isConventionalV1Profile(profile))
		{
			return FishingCatalog.NO_SPOT_MOVEMENT_HORIZON;
		}
		SpawnObservation observation = observations.get((NPC) interacting);
		if (observation == null)
		{
			return FishingCatalog.NO_SPOT_MOVEMENT_HORIZON;
		}

		int earliestMoveTicks = earliestMoveTicks(observation.spot);
		if (earliestMoveTicks < 0)
		{
			return FishingCatalog.NO_SPOT_MOVEMENT_HORIZON;
		}
		return Math.max(0, earliestMoveTicks - Math.max(0, tick - observation.spawnTick));
	}

	private static int earliestMoveTicks(FishingSpot spot)
	{
		switch (spot)
		{
			case KARAMBWAN:
			case KARAMBWANJI:
			case DARK_CRAB:
			case CIVITAS_ILLA_FORTIS_PARK:
				return FishingCatalog.NO_SPOT_MOVEMENT_HORIZON;
			case ANGLERFISH:
				// The reviewed catalogue explicitly holds this spot-life timer
				// because the available source presentation conflicts.
				return FishingCatalog.NO_SPOT_MOVEMENT_HORIZON;
			case INFERNAL_EEL:
				return INFERNAL_EEL_EARLIEST_MOVE_TICKS;
			default:
				return FishingCatalog.ORDINARY_SPOT_EARLIEST_MOVE_TICKS;
		}
	}

	void reset()
	{
		observations.clear();
	}

	private static final class SpawnObservation
	{
		private final FishingSpot spot;
		private final int spawnTick;

		private SpawnObservation(FishingSpot spot, int spawnTick)
		{
			this.spot = spot;
			this.spawnTick = spawnTick;
		}
	}
}

package com.idlefamiliar;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;

/** Stores observed world-object evidence for gathering attention horizons. */
final class GatheringResourceTracker
{
	static final int NO_HORIZON = -1;
	private static final int DAEYALT_INACTIVE_OBJECT_ID = 39094;
	private static final int DAEYALT_ACTIVE_OBJECT_ID = 39095;
	private static final int OBJECT_TRANSITION_TICK_TOLERANCE = 1;

	private WoodcuttingTarget woodcuttingTarget;
	private final Map<WorldPoint, Integer> daeyaltInactiveDespawnTicks = new HashMap<>();
	private final Map<WorldPoint, Integer> daeyaltActiveSpawnTicks = new HashMap<>();
	private final Map<WorldPoint, Integer> daeyaltActiveSinceTicks = new HashMap<>();
	private PendingDaeyalt pendingDaeyalt;

	void reset()
	{
		woodcuttingTarget = null;
		daeyaltInactiveDespawnTicks.clear();
		daeyaltActiveSpawnTicks.clear();
		daeyaltActiveSinceTicks.clear();
		pendingDaeyalt = null;
	}

	void recordWoodcuttingInteraction(WoodcuttingCatalog.Tree tree, int objectId,
		WorldPoint location, int tick)
	{
		if (tree == null || location == null)
		{
			woodcuttingTarget = null;
			return;
		}
		woodcuttingTarget = new WoodcuttingTarget(tree, objectId, location, tick);
	}

	/** Returns a known natural-tree horizon measured from the actual chop click. */
	int remainingWoodcuttingHorizon(WoodcuttingCatalog.Tree tree, int tick)
	{
		if (woodcuttingTarget == null || woodcuttingTarget.tree != tree)
		{
			return NO_HORIZON;
		}
		int elapsed = tick - woodcuttingTarget.interactionTick;
		if (elapsed < 0)
		{
			return NO_HORIZON;
		}
		return Math.max(0, WoodcuttingCatalog.activeSpotTicks(tree) - elapsed);
	}

	void onGameObjectSpawned(int objectId, WorldPoint location, int tick)
	{
		if (objectId != DAEYALT_ACTIVE_OBJECT_ID || location == null)
		{
			return;
		}
		daeyaltActiveSpawnTicks.put(location, tick);
		confirmDaeyaltActivation(location);
	}

	/**
	 * Returns which tracked resource ended. A Daeyalt activation is accepted
	 * only when the client observed its inactive counterpart disappear at the
	 * same location during the object transition.
	 */
	ResourceDespawn onGameObjectDespawned(int objectId, WorldPoint location, int tick)
	{
		if (location == null)
		{
			return ResourceDespawn.NONE;
		}

		boolean woodcutting = woodcuttingTarget != null
			&& woodcuttingTarget.objectId == objectId
			&& woodcuttingTarget.location.equals(location);
		if (woodcutting)
		{
			woodcuttingTarget = null;
		}

		boolean daeyalt = false;
		if (objectId == DAEYALT_INACTIVE_OBJECT_ID)
		{
			daeyaltInactiveDespawnTicks.put(location, tick);
			confirmDaeyaltActivation(location);
		}
		else if (objectId == DAEYALT_ACTIVE_OBJECT_ID)
		{
			daeyaltActiveSinceTicks.remove(location);
			daeyaltActiveSpawnTicks.remove(location);
			daeyaltInactiveDespawnTicks.remove(location);
			if (pendingDaeyalt != null && pendingDaeyalt.location.equals(location))
			{
				pendingDaeyalt = null;
			}
			daeyalt = true;
		}
		return woodcutting || daeyalt ? new ResourceDespawn(woodcutting, daeyalt) : ResourceDespawn.NONE;
	}

	boolean armDaeyalt(WorldPoint location, DaeyaltCatalog.PickaxeTier pickaxe, int tick)
	{
		Map.Entry<WorldPoint, Integer> activeRock = resolveDaeyaltActiveRock(location);
		Integer activeSince = activeRock == null ? null : activeRock.getValue();
		if (pickaxe == null || activeSince == null || tick < activeSince
			|| tick - activeSince > DaeyaltCatalog.MAX_ACTIVE_TICKS)
		{
			pendingDaeyalt = null;
			return false;
		}
		pendingDaeyalt = new PendingDaeyalt(activeRock.getKey(), pickaxe, tick);
		return true;
	}

	/** Matches exact anchors, or the sole observed active Daeyalt cycle. */
	private Map.Entry<WorldPoint, Integer> resolveDaeyaltActiveRock(WorldPoint clickedLocation)
	{
		if (clickedLocation != null)
		{
			Integer exact = daeyaltActiveSinceTicks.get(clickedLocation);
			if (exact != null)
			{
				return Map.entry(clickedLocation, exact);
			}
		}
		return daeyaltActiveSinceTicks.size() == 1
			? daeyaltActiveSinceTicks.entrySet().iterator().next() : null;
	}

	DaeyaltStart consumePendingDaeyalt(int tick, int interactionGraceTicks)
	{
		if (pendingDaeyalt == null || tick - pendingDaeyalt.interactionTick < 0
			|| tick - pendingDaeyalt.interactionTick > interactionGraceTicks)
		{
			pendingDaeyalt = null;
			return null;
		}

		Integer activeSince = daeyaltActiveSinceTicks.get(pendingDaeyalt.location);
		if (activeSince == null || tick < activeSince || tick - activeSince > DaeyaltCatalog.MAX_ACTIVE_TICKS)
		{
			pendingDaeyalt = null;
			return null;
		}

		DaeyaltStart start = new DaeyaltStart(pendingDaeyalt.pickaxe,
			Math.max(0, DaeyaltCatalog.MIN_ACTIVE_TICKS - (tick - activeSince)));
		pendingDaeyalt = null;
		return start;
	}

	void clearPendingDaeyalt()
	{
		pendingDaeyalt = null;
	}

	private void confirmDaeyaltActivation(WorldPoint location)
	{
		Integer inactiveDespawn = daeyaltInactiveDespawnTicks.get(location);
		Integer activeSpawn = daeyaltActiveSpawnTicks.get(location);
		if (inactiveDespawn == null || activeSpawn == null)
		{
			return;
		}

		if (Math.abs(activeSpawn - inactiveDespawn) <= OBJECT_TRANSITION_TICK_TOLERANCE)
		{
			daeyaltActiveSinceTicks.put(location, Math.max(activeSpawn, inactiveDespawn));
			daeyaltInactiveDespawnTicks.remove(location);
			daeyaltActiveSpawnTicks.remove(location);
			return;
		}

		// Scene-load callbacks can leave an old unmatched active spawn in the
		// tracker. Discard only the older observation: the newer half may still
		// pair with the next transition callback in this same game tick.
		if (activeSpawn < inactiveDespawn)
		{
			daeyaltActiveSpawnTicks.remove(location);
		}
		else
		{
			daeyaltInactiveDespawnTicks.remove(location);
		}
	}

	static final class ResourceDespawn
	{
		private static final ResourceDespawn NONE = new ResourceDespawn(false, false);
		private final boolean woodcutting;
		private final boolean daeyalt;

		private ResourceDespawn(boolean woodcutting, boolean daeyalt)
		{
			this.woodcutting = woodcutting;
			this.daeyalt = daeyalt;
		}

		boolean endedWoodcuttingTarget()
		{
			return woodcutting;
		}

		boolean endedDaeyaltActiveRock()
		{
			return daeyalt;
		}
	}

	static final class DaeyaltStart
	{
		private final DaeyaltCatalog.PickaxeTier pickaxe;
		private final int earliestMoveRemainingTicks;

		private DaeyaltStart(DaeyaltCatalog.PickaxeTier pickaxe, int earliestMoveRemainingTicks)
		{
			this.pickaxe = pickaxe;
			this.earliestMoveRemainingTicks = earliestMoveRemainingTicks;
		}

		DaeyaltCatalog.PickaxeTier pickaxe()
		{
			return pickaxe;
		}

		int earliestMoveRemainingTicks()
		{
			return earliestMoveRemainingTicks;
		}
	}

	private static final class WoodcuttingTarget
	{
		private final WoodcuttingCatalog.Tree tree;
		private final int objectId;
		private final WorldPoint location;
		private final int interactionTick;

		private WoodcuttingTarget(WoodcuttingCatalog.Tree tree, int objectId, WorldPoint location,
			int interactionTick)
		{
			this.tree = tree;
			this.objectId = objectId;
			this.location = location;
			this.interactionTick = interactionTick;
		}
	}

	private static final class PendingDaeyalt
	{
		private final WorldPoint location;
		private final DaeyaltCatalog.PickaxeTier pickaxe;
		private final int interactionTick;

		private PendingDaeyalt(WorldPoint location, DaeyaltCatalog.PickaxeTier pickaxe,
			int interactionTick)
		{
			this.location = location;
			this.pickaxe = pickaxe;
			this.interactionTick = interactionTick;
		}
	}
}

package com.idlefamiliar;

import java.util.Map;
import net.runelite.api.ItemID;
import net.runelite.client.game.FishingSpot;

/** Emits verified fishing evidence without mutating ETA state. */
final class FishingActivityDetector
{
	private static final int[] UNSUPPORTED_MODIFIER_ITEMS = {
		ItemID.SPIRIT_FLAKES,
		ItemID.INFERNAL_HARPOON, ItemID.INFERNAL_HARPOON_UNCHARGED,
		ItemID.INFERNAL_HARPOON_OR, ItemID.INFERNAL_HARPOON_OR_30342,
		ItemID.INFERNAL_HARPOON_UNCHARGED_30343
	};

	static int clampResultGraceTicks(int configuredTicks)
	{
		return Math.max(5, Math.min(8, configuredTicks));
	}

	interface Detection
	{
	}

	private final ActivityAnimationRegistry animationRegistry;
	private final ActivityEvidenceTracker evidence;
	private final ExtendedInventoryTracker extendedInventory;

	FishingActivityDetector(ActivityAnimationRegistry animationRegistry,
		ActivityEvidenceTracker evidence, ExtendedInventoryTracker extendedInventory)
	{
		this.animationRegistry = animationRegistry;
		this.evidence = evidence;
		this.extendedInventory = extendedInventory;
	}

	Detection detect(InventoryChange change, InventoryState inventory,
		InventoryState equipment, int animationId, int tick, int effectiveLevel,
		int fishingGraceTicks)
	{
		if (change == null || !change.hasBaseline() || inventory == null
			|| !isFishingRecent(animationId, tick, fishingGraceTicks))
		{
			return null;
		}

		ConventionalCatch conventional = detectConventional(change, inventory,
			equipment, tick, effectiveLevel);
		return conventional != null ? conventional
			: detectKarambwan(change, inventory, equipment, tick, effectiveLevel);
	}

	BarrelStart detectBarrelStart(FishingSpot spot, InventoryState inventory,
		InventoryState equipment, int animationId, int effectiveLevel)
	{
		boolean openBarrel = extendedInventory.hasOpenFishBarrel(inventory, equipment);
		if (!openBarrel)
		{
			extendedInventory.markEmptyOrUnknown(
				ExtendedInventoryTracker.Container.FISH_BARREL);
			return null;
		}
		if (extendedInventory.isKnownFull(ExtendedInventoryTracker.Container.FISH_BARREL))
		{
			return null;
		}

		FishingCatalog.HarpoonTier harpoonTier = resolveHarpoonTier(inventory, equipment);
		GatheringProfile profile = barrelProfileForSpot(spot, inventory, equipment,
			harpoonTier, animationId);
		if (!FishingCatalog.isFishBarrelCompatible(profile))
		{
			return null;
		}
		int totalFreeSlots = extendedInventory.effectiveFreeSlots(
			ExtendedInventoryTracker.Container.FISH_BARREL, true, inventory.freeSlots());
		boolean eligible = hasMatchingTool(profile, harpoonTier, inventory, equipment)
			&& !hasUnsupportedModifier(inventory, equipment)
			&& remainingFishingInput(profile, inventory.itemCounts()) >= totalFreeSlots;
		return new BarrelStart(profile, effectiveLevel, inventory.freeSlots(),
			capacityYieldMultiplier(equipment), eligible);
	}

	boolean isFishingAnimation(int animationId)
	{
		return "Fishing".equals(
			animationRegistry.activityForAnimation(animationId));
	}

	private boolean isFishingRecent(int animationId, int tick, int graceTicks)
	{
		return isFishingAnimation(animationId)
			|| evidence.isRecent(ActivityEvidenceTracker.Signal.FISHING, tick, graceTicks);
	}

	private ConventionalCatch detectConventional(InventoryChange change,
		InventoryState inventory, InventoryState equipment, int tick, int effectiveLevel)
	{
		Integer caughtFishId = null;
		int caughtFishSlots = 0;
		Integer consumedInputId = null;
		for (Integer itemId : change.delta().itemIds())
		{
			int before = change.before().quantity(itemId);
			int after = change.after().quantity(itemId);
			if (before == after)
			{
				continue;
			}
			int quantityDelta = after - before;
			if ((quantityDelta == 1 || quantityDelta == 2)
				&& isSupportedConventionalCatch(itemId) && caughtFishId == null)
			{
				caughtFishId = itemId;
				caughtFishSlots = quantityDelta;
				continue;
			}
			if (quantityDelta == -1 && isFishingInput(itemId) && consumedInputId == null)
			{
				consumedInputId = itemId;
				continue;
			}
			return null;
		}

		if (caughtFishId == null)
		{
			return null;
		}

		FishingCatalog.HarpoonTier harpoonTier = resolveHarpoonTier(inventory, equipment);
		GatheringProfile profile = profileForCatch(caughtFishId, harpoonTier, consumedInputId);
		int remainingRequiredInput = remainingFishingInput(
			profile, change.after().itemCounts());
		double capacityMultiplier = capacityYieldMultiplier(equipment);
		boolean openBarrel = extendedInventory.hasOpenFishBarrel(inventory, equipment);
		boolean barrelEligibleCatch = FishingCatalog.isFishBarrelCompatible(profile);
		if (openBarrel && barrelEligibleCatch)
		{
			extendedInventory.markFull(ExtendedInventoryTracker.Container.FISH_BARREL);
		}
		boolean eligible = fishingInputDeltaMatches(profile, consumedInputId)
			&& profile != null
			&& hasMatchingTool(profile, harpoonTier, inventory, equipment)
			&& !hasUnsupportedModifier(inventory, equipment)
			&& (!openBarrel || !barrelEligibleCatch
				|| extendedInventory.isKnownFull(ExtendedInventoryTracker.Container.FISH_BARREL))
			&& (caughtFishSlots == 1 || capacityMultiplier > 1d)
			&& remainingRequiredInput >= inventory.freeSlots();

		evidence.mark(ActivityEvidenceTracker.Signal.FISHING, tick);
		return new ConventionalCatch(profile, effectiveLevel, inventory.occupiedSlots(),
			caughtFishSlots, capacityMultiplier, eligible);
	}

	private KarambwanAttempt detectKarambwan(InventoryChange change,
		InventoryState inventory, InventoryState equipment, int tick, int effectiveLevel)
	{
		boolean baitConsumed = false;
		boolean caught = false;
		boolean baitedVesselSpent = false;
		boolean emptyVesselRestored = false;
		for (Integer itemId : change.delta().itemIds())
		{
			int before = change.before().quantity(itemId);
			int after = change.after().quantity(itemId);
			if (before == after)
			{
				continue;
			}
			if (itemId == ItemID.RAW_KARAMBWANJI && after - before == -1 && !baitConsumed)
			{
				baitConsumed = true;
				continue;
			}
			if (itemId == ItemID.RAW_KARAMBWAN && after - before == 1 && !caught)
			{
				caught = true;
				continue;
			}
			if (itemId == ItemID.KARAMBWAN_VESSEL_3159 && after - before == -1
				&& !baitedVesselSpent)
			{
				baitedVesselSpent = true;
				continue;
			}
			if (itemId == ItemID.KARAMBWAN_VESSEL && after - before == 1
				&& !emptyVesselRestored)
			{
				emptyVesselRestored = true;
				continue;
			}
			return null;
		}

		boolean vesselPresent = hasKarambwanVessel(change.before())
			|| hasKarambwanVessel(change.after());
		if (!vesselPresent || (!baitConsumed && !caught
			&& !(baitedVesselSpent && emptyVesselRestored)))
		{
			return null;
		}

		evidence.mark(ActivityEvidenceTracker.Signal.FISHING, tick);
		boolean openBarrel = extendedInventory.hasOpenFishBarrel(inventory, equipment);
		if (!openBarrel)
		{
			extendedInventory.markEmptyOrUnknown(
				ExtendedInventoryTracker.Container.FISH_BARREL);
		}
		else if (caught)
		{
			extendedInventory.markFull(ExtendedInventoryTracker.Container.FISH_BARREL);
		}
		boolean usesBarrel = openBarrel
			&& !extendedInventory.isKnownFull(ExtendedInventoryTracker.Container.FISH_BARREL);
		return new KarambwanAttempt(effectiveLevel, inventory.occupiedSlots(),
			remainingKarambwanAttempts(change.after()), caught, usesBarrel,
			capacityYieldMultiplier(equipment), !hasUnsupportedModifier(inventory, equipment));
	}

	private static GatheringProfile barrelProfileForSpot(FishingSpot spot,
		InventoryState inventory, InventoryState equipment,
		FishingCatalog.HarpoonTier harpoonTier, int animationId)
	{
		if (spot == null)
		{
			return null;
		}
		switch (spot)
		{
			case SHRIMP:
				return exactlyOne(
					hasSmallNet(inventory, equipment)
						? FishingCatalog.smallNetShrimpAnchovyProfile() : null,
					hasFishingRod(inventory, equipment)
						&& inventory.quantity(ItemID.FISHING_BAIT) > 0
						? FishingCatalog.rodSardineHerringProfile() : null);
			case LOBSTER:
				if (isBarehandedAnimation(animationId))
				{
					return FishingCatalog.barehandedTunaSwordfishProfile();
				}
				return exactlyOne(
					hasLobsterPot(inventory, equipment)
						? FishingCatalog.cageLobsterProfile() : null,
					harpoonTier != null
						? FishingCatalog.harpoonTunaSwordfishProfile(harpoonTier) : null);
			case SHARK:
				if (isBarehandedAnimation(animationId))
				{
					return FishingCatalog.barehandedSharkProfile();
				}
				return harpoonTier == null ? null
					: FishingCatalog.harpoonSharkProfile(harpoonTier);
			case MONKFISH:
				return FishingCatalog.smallNetMonkfishProfile();
			case SALMON:
				GatheringProfile flyProfile = flyProfile(inventory, equipment);
				GatheringProfile pikeProfile = hasFishingRod(inventory, equipment)
					&& inventory.quantity(ItemID.FISHING_BAIT) > 0
					? FishingCatalog.rodPikeProfile() : null;
				return exactlyOne(flyProfile, pikeProfile);
			case BARB_FISH:
				return hasBarbarianRod(inventory, equipment)
					&& totalBarbarianBait(inventory.itemCounts()) > 0
					? FishingCatalog.barbarianRodProfile() : null;
			case ANGLERFISH:
				boolean sandworms = inventory.quantity(ItemID.SANDWORMS) > 0;
				boolean diabolicWorms = inventory.quantity(ItemID.DIABOLIC_WORMS) > 0;
				return sandworms == diabolicWorms ? null
					: FishingCatalog.rodAnglerfishProfile(diabolicWorms);
			case LAVA_EEL:
				return FishingCatalog.oilyRodLavaEelProfile();
			case CAVE_EEL:
			case SLIMY_EEL:
				return FishingCatalog.rodSlimyCaveEelProfile();
			default:
				return null;
		}
	}

	private static GatheringProfile flyProfile(InventoryState inventory,
		InventoryState equipment)
	{
		if (!hasFlyRod(inventory, equipment))
		{
			return null;
		}
		boolean feathers = inventory.quantity(ItemID.FEATHER) > 0;
		boolean stripyFeathers = inventory.quantity(ItemID.STRIPY_FEATHER) > 0;
		if (feathers == stripyFeathers)
		{
			return null;
		}
		return stripyFeathers ? FishingCatalog.flyRainbowFishProfile()
			: FishingCatalog.flyTroutSalmonProfile();
	}

	private static GatheringProfile exactlyOne(GatheringProfile first,
		GatheringProfile second)
	{
		return (first == null) == (second == null) ? null
			: first != null ? first : second;
	}

	private static boolean hasSmallNet(InventoryState inventory,
		InventoryState equipment)
	{
		return inventory.containsAny(ItemID.SMALL_FISHING_NET)
			|| equipment.containsAny(ItemID.SMALL_FISHING_NET);
	}

	private static boolean hasLobsterPot(InventoryState inventory,
		InventoryState equipment)
	{
		return inventory.containsAny(ItemID.LOBSTER_POT)
			|| equipment.containsAny(ItemID.LOBSTER_POT);
	}

	private static boolean hasFishingRod(InventoryState inventory,
		InventoryState equipment)
	{
		return inventory.containsAny(ItemID.FISHING_ROD, ItemID.PEARL_FISHING_ROD)
			|| equipment.containsAny(ItemID.FISHING_ROD, ItemID.PEARL_FISHING_ROD);
	}

	private static boolean hasFlyRod(InventoryState inventory,
		InventoryState equipment)
	{
		return inventory.containsAny(ItemID.FLY_FISHING_ROD, ItemID.PEARL_FLY_FISHING_ROD)
			|| equipment.containsAny(ItemID.FLY_FISHING_ROD, ItemID.PEARL_FLY_FISHING_ROD);
	}

	private static boolean hasBarbarianRod(InventoryState inventory,
		InventoryState equipment)
	{
		return inventory.containsAny(ItemID.BARBARIAN_ROD, ItemID.PEARL_BARBARIAN_ROD)
			|| equipment.containsAny(ItemID.BARBARIAN_ROD, ItemID.PEARL_BARBARIAN_ROD);
	}

	private static boolean isBarehandedAnimation(int animationId)
	{
		return animationId >= 6703 && animationId <= 6711;
	}

	private static boolean hasKarambwanVessel(InventoryState inventory)
	{
		return inventory.quantity(ItemID.KARAMBWAN_VESSEL) > 0
			|| inventory.quantity(ItemID.KARAMBWAN_VESSEL_3159) > 0;
	}

	private static int remainingKarambwanAttempts(InventoryState inventory)
	{
		long attempts = (long) inventory.quantity(ItemID.RAW_KARAMBWANJI)
			+ inventory.quantity(ItemID.KARAMBWAN_VESSEL_3159);
		return attempts >= Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) attempts;
	}

	private static double capacityYieldMultiplier(InventoryState equipment)
	{
		double chance = equipment.containsAny(ItemID.RADAS_BLESSING_4) ? 0.08d
			: equipment.containsAny(ItemID.RADAS_BLESSING_3) ? 0.06d
			: equipment.containsAny(ItemID.RADAS_BLESSING_2) ? 0.04d
			: equipment.containsAny(ItemID.RADAS_BLESSING, ItemID.RADAS_BLESSING_1)
				? 0.02d : 0d;
		return 1d + chance;
	}

	private static boolean hasUnsupportedModifier(InventoryState inventory,
		InventoryState equipment)
	{
		return inventory.containsAny(UNSUPPORTED_MODIFIER_ITEMS)
			|| equipment.containsAny(UNSUPPORTED_MODIFIER_ITEMS);
	}

	private static FishingCatalog.HarpoonTier resolveHarpoonTier(InventoryState inventory,
		InventoryState equipment)
	{
		if (inventory.containsAny(ItemID.CRYSTAL_HARPOON, ItemID.CRYSTAL_HARPOON_23864)
			|| equipment.containsAny(ItemID.CRYSTAL_HARPOON, ItemID.CRYSTAL_HARPOON_23864))
		{
			return FishingCatalog.HarpoonTier.CRYSTAL;
		}
		if (inventory.containsAny(ItemID.DRAGON_HARPOON, ItemID.DRAGON_HARPOON_OR,
			ItemID.DRAGON_HARPOON_OR_30349, ItemID.CRYSTAL_HARPOON_INACTIVE)
			|| equipment.containsAny(ItemID.DRAGON_HARPOON, ItemID.DRAGON_HARPOON_OR,
				ItemID.DRAGON_HARPOON_OR_30349, ItemID.CRYSTAL_HARPOON_INACTIVE))
		{
			return FishingCatalog.HarpoonTier.DRAGON;
		}
		return inventory.containsAny(ItemID.HARPOON, ItemID.BARBTAIL_HARPOON)
			|| equipment.containsAny(ItemID.HARPOON, ItemID.BARBTAIL_HARPOON)
			? FishingCatalog.HarpoonTier.NORMAL : null;
	}

	private static boolean hasMatchingTool(GatheringProfile profile,
		FishingCatalog.HarpoonTier harpoonTier, InventoryState inventory,
		InventoryState equipment)
	{
		if (profile == FishingCatalog.smallNetShrimpAnchovyProfile()
			|| profile == FishingCatalog.smallNetMonkfishProfile())
		{
			return inventory.containsAny(ItemID.SMALL_FISHING_NET)
				|| equipment.containsAny(ItemID.SMALL_FISHING_NET);
		}
		if (profile == FishingCatalog.cageLobsterProfile())
		{
			return inventory.containsAny(ItemID.LOBSTER_POT)
				|| equipment.containsAny(ItemID.LOBSTER_POT);
		}
		if (profile == FishingCatalog.harpoonTunaSwordfishProfile(harpoonTier)
			|| profile == FishingCatalog.harpoonSharkProfile(harpoonTier))
		{
			return harpoonTier != null;
		}
		if (profile == FishingCatalog.barehandedTunaSwordfishProfile()
			|| profile == FishingCatalog.barehandedSharkProfile())
		{
			return harpoonTier == null;
		}
		if (profile == FishingCatalog.flyTroutSalmonProfile()
			|| profile == FishingCatalog.flyRainbowFishProfile())
		{
			return inventory.containsAny(ItemID.FLY_FISHING_ROD, ItemID.PEARL_FLY_FISHING_ROD)
				|| equipment.containsAny(ItemID.FLY_FISHING_ROD, ItemID.PEARL_FLY_FISHING_ROD);
		}
		if (profile == FishingCatalog.rodSardineHerringProfile()
			|| profile == FishingCatalog.rodPikeProfile()
			|| profile == FishingCatalog.rodSlimyCaveEelProfile()
			|| profile == FishingCatalog.rodAnglerfishProfile(false)
			|| profile == FishingCatalog.rodAnglerfishProfile(true))
		{
			return inventory.containsAny(ItemID.FISHING_ROD, ItemID.PEARL_FISHING_ROD)
				|| equipment.containsAny(ItemID.FISHING_ROD, ItemID.PEARL_FISHING_ROD);
		}
		if (profile == FishingCatalog.oilyRodLavaEelProfile()
			|| profile == FishingCatalog.oilyRodInfernalEelProfile())
		{
			boolean oilyRod = inventory.containsAny(ItemID.OILY_FISHING_ROD,
				ItemID.OILY_PEARL_FISHING_ROD)
				|| equipment.containsAny(ItemID.OILY_FISHING_ROD, ItemID.OILY_PEARL_FISHING_ROD);
			return oilyRod && (profile != FishingCatalog.oilyRodInfernalEelProfile()
				|| equipment.containsAny(ItemID.ICE_GLOVES));
		}
		if (profile == FishingCatalog.barbarianRodProfile())
		{
			return inventory.containsAny(ItemID.BARBARIAN_ROD, ItemID.PEARL_BARBARIAN_ROD)
				|| equipment.containsAny(ItemID.BARBARIAN_ROD, ItemID.PEARL_BARBARIAN_ROD);
		}
		return false;
	}

	private static boolean isSupportedConventionalCatch(int itemId)
	{
		return itemId == ItemID.RAW_SHRIMPS || itemId == ItemID.RAW_ANCHOVIES
			|| itemId == ItemID.RAW_LOBSTER || itemId == ItemID.RAW_TUNA
			|| itemId == ItemID.RAW_SWORDFISH || itemId == ItemID.RAW_SHARK
			|| itemId == ItemID.RAW_TROUT || itemId == ItemID.RAW_SALMON
			|| itemId == ItemID.RAW_SARDINE || itemId == ItemID.RAW_HERRING
			|| itemId == ItemID.RAW_PIKE || itemId == ItemID.RAW_MONKFISH
			|| itemId == ItemID.RAW_RAINBOW_FISH || itemId == ItemID.RAW_SLIMY_EEL
			|| itemId == ItemID.RAW_CAVE_EEL || itemId == ItemID.RAW_LAVA_EEL
			|| itemId == ItemID.INFERNAL_EEL || itemId == ItemID.RAW_ANGLERFISH
			|| itemId == ItemID.LEAPING_TROUT || itemId == ItemID.LEAPING_SALMON
			|| itemId == ItemID.LEAPING_STURGEON;
	}

	private static GatheringProfile profileForCatch(int itemId,
		FishingCatalog.HarpoonTier harpoonTier, Integer consumedInputId)
	{
		switch (itemId)
		{
			case ItemID.RAW_SHRIMPS:
			case ItemID.RAW_ANCHOVIES:
				return FishingCatalog.smallNetShrimpAnchovyProfile();
			case ItemID.RAW_MONKFISH:
				return FishingCatalog.smallNetMonkfishProfile();
			case ItemID.RAW_LOBSTER:
				return FishingCatalog.cageLobsterProfile();
			case ItemID.RAW_TUNA:
			case ItemID.RAW_SWORDFISH:
				return harpoonTier == null ? FishingCatalog.barehandedTunaSwordfishProfile()
					: FishingCatalog.harpoonTunaSwordfishProfile(harpoonTier);
			case ItemID.RAW_SHARK:
				return harpoonTier == null ? FishingCatalog.barehandedSharkProfile()
					: FishingCatalog.harpoonSharkProfile(harpoonTier);
			case ItemID.RAW_TROUT:
			case ItemID.RAW_SALMON:
				return FishingCatalog.flyTroutSalmonProfile();
			case ItemID.RAW_RAINBOW_FISH:
				return FishingCatalog.flyRainbowFishProfile();
			case ItemID.RAW_SARDINE:
			case ItemID.RAW_HERRING:
				return FishingCatalog.rodSardineHerringProfile();
			case ItemID.RAW_PIKE:
				return FishingCatalog.rodPikeProfile();
			case ItemID.RAW_SLIMY_EEL:
			case ItemID.RAW_CAVE_EEL:
				return FishingCatalog.rodSlimyCaveEelProfile();
			case ItemID.RAW_LAVA_EEL:
				return FishingCatalog.oilyRodLavaEelProfile();
			case ItemID.INFERNAL_EEL:
				return FishingCatalog.oilyRodInfernalEelProfile();
			case ItemID.RAW_ANGLERFISH:
				return consumedInputId != null && consumedInputId == ItemID.DIABOLIC_WORMS
					? FishingCatalog.rodAnglerfishProfile(true)
					: consumedInputId != null && consumedInputId == ItemID.SANDWORMS
						? FishingCatalog.rodAnglerfishProfile(false) : null;
			case ItemID.LEAPING_TROUT:
			case ItemID.LEAPING_SALMON:
			case ItemID.LEAPING_STURGEON:
				return FishingCatalog.barbarianRodProfile();
			default:
				return null;
		}
	}

	private static boolean isFishingInput(int itemId)
	{
		return itemId == ItemID.FISHING_BAIT || itemId == ItemID.FEATHER
			|| itemId == ItemID.STRIPY_FEATHER || itemId == ItemID.SANDWORMS
			|| itemId == ItemID.DIABOLIC_WORMS || isBarbarianBait(itemId);
	}

	private static boolean fishingInputDeltaMatches(GatheringProfile profile,
		Integer consumedInputId)
	{
		if (profile == null)
		{
			return false;
		}
		if (profile == FishingCatalog.flyTroutSalmonProfile())
		{
			return consumedInputId != null && consumedInputId == ItemID.FEATHER;
		}
		if (profile == FishingCatalog.flyRainbowFishProfile())
		{
			return consumedInputId != null && consumedInputId == ItemID.STRIPY_FEATHER;
		}
		if (profile == FishingCatalog.rodSardineHerringProfile()
			|| profile == FishingCatalog.rodPikeProfile()
			|| profile == FishingCatalog.rodSlimyCaveEelProfile()
			|| profile == FishingCatalog.oilyRodLavaEelProfile()
			|| profile == FishingCatalog.oilyRodInfernalEelProfile())
		{
			return consumedInputId != null && consumedInputId == ItemID.FISHING_BAIT;
		}
		if (profile == FishingCatalog.rodAnglerfishProfile(false))
		{
			return consumedInputId != null && consumedInputId == ItemID.SANDWORMS;
		}
		if (profile == FishingCatalog.rodAnglerfishProfile(true))
		{
			return consumedInputId != null && consumedInputId == ItemID.DIABOLIC_WORMS;
		}
		return profile == FishingCatalog.barbarianRodProfile()
			? consumedInputId != null && isBarbarianBait(consumedInputId)
			: consumedInputId == null;
	}

	private static int remainingFishingInput(GatheringProfile profile,
		Map<Integer, Integer> inventory)
	{
		if (profile == FishingCatalog.flyTroutSalmonProfile())
		{
			return quantity(inventory, ItemID.FEATHER);
		}
		if (profile == FishingCatalog.flyRainbowFishProfile())
		{
			return quantity(inventory, ItemID.STRIPY_FEATHER);
		}
		if (profile == FishingCatalog.rodSardineHerringProfile()
			|| profile == FishingCatalog.rodPikeProfile()
			|| profile == FishingCatalog.rodSlimyCaveEelProfile()
			|| profile == FishingCatalog.oilyRodLavaEelProfile()
			|| profile == FishingCatalog.oilyRodInfernalEelProfile())
		{
			return quantity(inventory, ItemID.FISHING_BAIT);
		}
		if (profile == FishingCatalog.rodAnglerfishProfile(false))
		{
			return quantity(inventory, ItemID.SANDWORMS);
		}
		if (profile == FishingCatalog.rodAnglerfishProfile(true))
		{
			return quantity(inventory, ItemID.DIABOLIC_WORMS);
		}
		return profile == FishingCatalog.barbarianRodProfile()
			? totalBarbarianBait(inventory) : Integer.MAX_VALUE;
	}

	private static boolean isBarbarianBait(int itemId)
	{
		return itemId == ItemID.FISHING_BAIT || itemId == ItemID.FEATHER
			|| itemId == ItemID.FISH_OFFCUTS || itemId == ItemID.ROE
			|| itemId == ItemID.CAVIAR;
	}

	private static int totalBarbarianBait(Map<Integer, Integer> inventory)
	{
		long total = (long) quantity(inventory, ItemID.FISHING_BAIT)
			+ quantity(inventory, ItemID.FEATHER) + quantity(inventory, ItemID.FISH_OFFCUTS)
			+ quantity(inventory, ItemID.ROE) + quantity(inventory, ItemID.CAVIAR);
		return total >= Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) total;
	}

	private static int quantity(Map<Integer, Integer> inventory, int itemId)
	{
		Integer value = inventory.get(itemId);
		return value == null ? 0 : value;
	}

	static final class ConventionalCatch implements Detection
	{
		final GatheringProfile profile;
		final int effectiveLevel;
		final int occupiedSlots;
		final int producedSlots;
		final double capacityYieldMultiplier;
		final boolean eligible;

		private ConventionalCatch(GatheringProfile profile, int effectiveLevel,
			int occupiedSlots, int producedSlots, double capacityYieldMultiplier,
			boolean eligible)
		{
			this.profile = profile;
			this.effectiveLevel = effectiveLevel;
			this.occupiedSlots = occupiedSlots;
			this.producedSlots = producedSlots;
			this.capacityYieldMultiplier = capacityYieldMultiplier;
			this.eligible = eligible;
		}
	}

	static final class KarambwanAttempt implements Detection
	{
		final int effectiveLevel;
		final int occupiedSlots;
		final int remainingKarambwanji;
		final boolean caught;
		final boolean usesFishBarrel;
		final double capacityYieldMultiplier;
		final boolean eligible;

		private KarambwanAttempt(int effectiveLevel, int occupiedSlots,
			int remainingKarambwanji, boolean caught, boolean usesFishBarrel,
			double capacityYieldMultiplier, boolean eligible)
		{
			this.effectiveLevel = effectiveLevel;
			this.occupiedSlots = occupiedSlots;
			this.remainingKarambwanji = remainingKarambwanji;
			this.caught = caught;
			this.usesFishBarrel = usesFishBarrel;
			this.capacityYieldMultiplier = capacityYieldMultiplier;
			this.eligible = eligible;
		}
	}

	static final class BarrelStart
	{
		final GatheringProfile profile;
		final int effectiveLevel;
		final int ordinaryFreeSlots;
		final double capacityYieldMultiplier;
		final boolean eligible;

		private BarrelStart(GatheringProfile profile, int effectiveLevel,
			int ordinaryFreeSlots, double capacityYieldMultiplier, boolean eligible)
		{
			this.profile = profile;
			this.effectiveLevel = effectiveLevel;
			this.ordinaryFreeSlots = ordinaryFreeSlots;
			this.capacityYieldMultiplier = capacityYieldMultiplier;
			this.eligible = eligible;
		}
	}
